INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimar vasos de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Estimar cantidades usando una barra deslizante", "Relacionar la estimación con el conteo exacto"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-slider", "xp": 0, "type": "estimate_slider", "hints": ["Piensa: si la jarra es grande, ¿saldrán 1 vaso o 100? ¡Ninguno! Algo como 8 está bien."], "title": "¿Cuántos vasos salen de la jarra?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Recordemos que Liruf vendió 4 vasos de limonada. Ahora Zara quiere preparar más, pero primero necesita saber cuántos vasos salen de una jarra. Zara preparó una jarra grande de limonada. Sin contar, desliza la barra para estimar: ¿como cuántos vasos crees que salgan de esta jarra?", "difficulty": 1, "explanation_md": "¡Bien! Una jarra grande da aproximadamente 8 vasos. Zara está contenta con tu estimación. Recuerda que una jarra tiene espacio para unos 8 vasos pequeños, así que 8 es una estimación razonable.", "audio_segment_id": "s1-estimate-slider.prompt"}], "schema_version": 1}', '{"s1-estimate-slider": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-slider.prompt": {"url": "http://localhost:4006/files/lesson-audio/57b614198edcd0c7687f2ce4a4c1e70589dd3688a46a31b8fb0188e202c36e94.mp3", "hash": "964d6b12b8c11b4cb04785dd4b30acecdc9d0b8a36da0cb06b46e6242a56d27a", "bytes": 103536, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/57b614198edcd0c7687f2ce4a4c1e70589dd3688a46a31b8fb0188e202c36e94.mp3", "duration_ms": 17200}, "s1-estimate-slider.explanation": {"url": "http://localhost:4006/files/lesson-audio/38294d7bb1b1fef0d742185beec866cba093cfb2d058e012129badc053bd337c.mp3", "hash": "cc3414cb2506d7a5635307d00d5b484cd18e85860131b7296e5dccb17a55147e", "bytes": 76608, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/38294d7bb1b1fef0d742185beec866cba093cfb2d058e012129badc053bd337c.mp3", "duration_ms": 12720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "repaso-quiz-mcq", "title": "Revisão: Quanto você ganha por copo?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Responder de memória, sem ajuda, as ideias centrais da barraca: o preço justo do copo e como a poupança cresce."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-repaso-ganancia", "xp": 5, "type": "quiz_mcq", "hints": ["O lucro é o que sobra depois de subtrair os gastos do preço."], "title": "Quanto você ganha por copo?", "payload": {"options": [{"id": "a", "text_md": "3 reais", "rationale_md": "Correto. 5 - 2 = 3."}, {"id": "b", "text_md": "7 reais", "rationale_md": "Quase, mas você somou o preço e os ingredientes. O lucro é calculado subtraindo os custos do preço, não somando."}, {"id": "c", "text_md": "2 reais", "rationale_md": "Esse é o custo dos ingredientes, não o lucro. Lembre-se de subtrair: preço - custo = lucro."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você já deixou tudo pronto para amanhã, Dina faz uma pergunta rápida sobre ontem. Enquanto guardam a barraca juntos, Dina sorri e pergunta: **''Sem olhar o caderno… quanto você ganha por copo?''**\\n\\nLembre-se da sua barraca: você vendeu copos a **5** reais cada, e os ingredientes custaram **2** reais por copo. Então, para cada copo, quanto sobra de lucro?", "difficulty": 1, "explanation_md": "Exato! Se você vende o copo por **5** reais e os ingredientes custam **2**, o lucro é **3** reais por copo. Muito bem, Liruf!", "audio_segment_id": "s1-repaso-ganancia.prompt"}], "schema_version": 1}', '{"s1-repaso-ganancia": {"correct_option_id": "a"}}', '{"units": {"s1-repaso-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/473bc0ddcafd93c3d60243f83c2eaf8706e329c6bba3c16d56084909ae972921.mp3", "hash": "52145de86a95704a4aaf2a119457fafb055d5fc29cd9a9c3ec4a879f2e7a5deb", "bytes": 140976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/473bc0ddcafd93c3d60243f83c2eaf8706e329c6bba3c16d56084909ae972921.mp3", "duration_ms": 23440}, "s1-repaso-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/55162a5585e3af70ba2fc31dda9bd66cfa0c89a2ef116fad5a6cde57c04581bd.mp3", "hash": "6d5b5ef50fdaf9291aae07aa67d384758d7c4ab6ae4ad4486c904051d4559e18", "bytes": 55008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/55162a5585e3af70ba2fc31dda9bd66cfa0c89a2ef116fad5a6cde57c04581bd.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Inventário noturno: quantos limões sobraram?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar objetos até 20", "Escrever o número exato de limões na cesta"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cuenta-limones", "xp": 10, "type": "count_objects", "hints": ["Olhe bem para cada limão na cesta. Aponte com o dedo enquanto conta: um, dois, três…", "Se você se perder, comece de novo. Os limões não se movem."], "title": "Quantos limões há?", "payload": {"scene": [{"icon": "lemon", "tint": "primary", "count": 12}], "ask_icon": "lemon"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Ontem você estimou quantos copos saem de uma jarra... Hoje vamos contar limões um por um para saber o número exato! Liruf acende sua lanterninha e olha a cesta de limões. Ajude-o a contar quantos limões sobraram. Escreva o número exato.", "difficulty": 1, "explanation_md": "Correto! Liruf contou 12 limões na cesta. 12 é o número exato.", "audio_segment_id": "s1-cuenta-limones.prompt"}], "schema_version": 1}', '{"s1-cuenta-limones": {"value": 12}}', '{"units": {"s1-cuenta-limones.prompt": {"url": "http://localhost:4006/files/lesson-audio/8de46e310608ca3982a8e85e9d863098d0a7ee46a2881efb5f54bfb292359238.mp3", "hash": "0f974074f6e5f4d56f7e21af652340b30da8bfab587e51c2c7f730964b5c1701", "bytes": 104976, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8de46e310608ca3982a8e85e9d863098d0a7ee46a2881efb5f54bfb292359238.mp3", "duration_ms": 17440}, "s1-cuenta-limones.explanation": {"url": "http://localhost:4006/files/lesson-audio/117dd199e7d46a4d0d017584be43d2bb2688c55724bdd0025d986f9bb20f5d84.mp3", "hash": "8832e7062a55cc7529220f79eb4da60919671c9e63d2e445d1bec41938791892", "bytes": 36864, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/117dd199e7d46a4d0d017584be43d2bb2688c55724bdd0025d986f9bb20f5d84.mp3", "duration_ms": 6080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "The delivery cart''s route", "locale": "en-US", "subject": "mixed", "objectives": ["Guide the delivery cart through the neighborhood grid to the customer''s house using the fewest steps."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 15, "type": "robot_path", "hints": ["Think about the shortest route avoiding the walls. How many steps up and to the right do you need?", "You can draw the grid on paper to visualize the movements."], "title": "The delivery cart''s route", "payload": {"goal": {"x": 3, "y": 3}, "grid": {"h": 4, "w": 4}, "start": {"x": 1, "y": 1, "dir": "up"}, "walls": [{"x": 2, "y": 1}, {"x": 2, "y": 2}], "commands": ["forward", "left", "right"], "max_commands": 6}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you know how to order the cash register steps, let''s order the delivery cart steps! After recording the sale, Dina and Zara need to deliver the order. The delivery cart is at position (1,1) facing up. The customer''s house is at (3,3). There are walls at (2,1) and (2,2). The cart can only move forward, turn left, or turn right. Help Zara program the cart to reach the house in the fewest steps (maximum 6). Remember: first turn to face the right direction, then move forward. Just like when you count steps on the floor!", "difficulty": 2, "explanation_md": "Excellent! You used 5 commands: turn right, move forward, turn left, move forward, and move forward. The cart reached the customer''s house in just 5 steps! Dina and Zara are happy because the order arrived on time.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/8b14562a883a5d64eda176e1f0db74ac316c70c0f3e7750a6aeb55b18bb51dc4.mp3", "hash": "ade5f2fd43ad5bc2095ac1c5ede2355c82393a18a1d38462d3efdd110654dc64", "bytes": 171648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8b14562a883a5d64eda176e1f0db74ac316c70c0f3e7750a6aeb55b18bb51dc4.mp3", "duration_ms": 28560}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/e47ed885c4bae30335a15384ab5d326c66ef07b54603daf59d8094c5a4fb2721.mp3", "hash": "04f789f8175fb1763506fedc5864cbedcecc48e30bfdfc820401a77cc524ef42", "bytes": 78624, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e47ed885c4bae30335a15384ab5d326c66ef07b54603daf59d8094c5a4fb2721.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "Liruf and the Path Decision", "locale": "en-US", "subject": "mixed", "objectives": ["Distinguish between a fact and an opinion when making a decision in a branching story."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-branch", "xp": 0, "type": "story_branch", "hints": ["Think: does the shiny path look safe? That''s an opinion. Are there flowers in the field? That''s a fact."], "title": "Liruf and the Path Decision", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "brillante", "next": "brillante", "text_md": "Shiny path (looks safe, but it''s an opinion)"}, {"id": "sombreado", "next": "sombreado", "text_md": "Shady path (looks mysterious, but it could be a fact)"}], "emotion": "thinking", "text_md": "Liruf is in a forest and finds two paths: one shiny and one shady. Dina says: ''The shiny path looks safer, but is that a fact or an opinion?'' Which one does Liruf choose?", "character": "liruf"}, {"id": "brillante", "choices": [{"id": "fin-brillante", "next": null, "text_md": "End of story"}], "emotion": "happy", "text_md": "The shiny path leads to a field with 20 flowers! That''s a fact: there are flowers. Liruf is happy, but remembers that the appearance of safety was just an opinion. Question: Why is it important to distinguish facts from opinions when deciding? Reflect: if you only follow opinions, you might be wrong.", "character": "liruf"}, {"id": "sombreado", "choices": [{"id": "fin-sombreado", "next": null, "text_md": "End of story"}], "emotion": "surprised", "text_md": "The shady path leads to a quiet cave where there is an ancient map. The map shows real facts about the forest! Liruf is curious and learns that mysterious isn''t always bad. Question: How did distinguishing facts from opinions help you in this decision? Reflect: basing yourself on facts lets you discover new things.", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you''ve practiced identifying facts and opinions separately, let''s use that to help Liruf decide! Help Liruf choose a path. Remember: a fact can be proven, an opinion is what someone thinks.", "difficulty": 1, "explanation_md": "Liruf learned that appearances can be opinions, not facts. Always check!", "audio_segment_id": "s1-branch.prompt"}], "schema_version": 1}', '{"s1-branch": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "brillante"}, {"score": 100, "node_id": "inicio", "choice_id": "sombreado"}]}}', '{"units": {"s1-branch.prompt": {"url": "http://localhost:4006/files/lesson-audio/169ec7fcd3cfe404968d7412b66200de8810a5dca46e02870a2d80da7afa7405.mp3", "hash": "04363403deaeb81d3cd9198050da48bb41dcd69e102c974df55bea7778c76100", "bytes": 66528, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/169ec7fcd3cfe404968d7412b66200de8810a5dca46e02870a2d80da7afa7405.mp3", "duration_ms": 11040}, "s1-branch.explanation": {"url": "http://localhost:4006/files/lesson-audio/506465433b6261c07554ecaffa49c51b8efc67ba38ee6a5739f565e1223d81a7.mp3", "hash": "af5de39014397c4dc496f5ffced1fb3e4b0f1a492eb298d366ddd630dc3f02b6", "bytes": 24768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/506465433b6261c07554ecaffa49c51b8efc67ba38ee6a5739f565e1223d81a7.mp3", "duration_ms": 4080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dinero", "title": "Combo Dinero: Cierre de Caja", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas para cerrar la caja del día.", "Calcular el cambio correcto al recibir un billete de 20 MXN.", "Determinar cuántas semanas se necesitan para ahorrar 80 MXN para la guitarra."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 10, "type": "coin_count", "hints": ["Suma primero las monedas más grandes: 10+10=20, luego 20+5=25, luego 25+2+2=29, luego 29+1+1+1=32."], "title": "Cerrar la caja", "payload": {"target": 32, "currency": "MXN", "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Recuerda que ayer escuchaste a dos clientes hablar sobre la limonada y respondiste preguntas de verdadero/falso con imágenes. ¡Hoy usamos lo que aprendiste para cerrar la caja! Liruf dice: **''¡Hora de cerrar la caja! Cuenta todas las monedas que tenemos hoy.''** En la caja hay: 3 monedas de 1 MXN, 2 monedas de 2 MXN, 1 moneda de 5 MXN, y 2 monedas de 10 MXN. ¿Cuánto dinero hay en total?", "difficulty": 1, "explanation_md": "¡Correcto! Sumaste 10+10+5+2+2+1+1+1 = **32 MXN**. ¡Buen conteo, como Liruf! Reflexiona: ¿cómo te ayudó lo de ayer a contar hoy?", "audio_segment_id": "s1-coin-count.prompt"}, {"id": "s2-make-change", "xp": 10, "type": "make_change", "hints": ["Resta el precio de lo que pagó: 20 - 5 = ?"], "title": "Dar cambio de 20", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10, 20]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Un cliente compra un vaso de limonada de **5 MXN** y paga con un billete de **20 MXN**. Rho pregunta: **''¿Cuánto cambio debe darle Dina?''**", "difficulty": 1, "explanation_md": "¡Muy bien! 20 - 5 = **15 MXN** de cambio. Rho te felicita. Piensa: ¿qué pasaría si pagara con 10 MXN?", "audio_segment_id": "s2-make-change.prompt"}, {"id": "s3-savings-goal", "xp": 10, "type": "savings_goal", "hints": ["Divide la meta entre lo que ahorra cada semana: 80 ÷ 20 = ?"], "title": "Semanas para la guitarra", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quiere ahorrar **80 MXN** para una guitarra. Zara dice: **''Si cada semana guardas 20 MXN de tus ganancias, ¿cuántas semanas necesitas?''**", "difficulty": 1, "explanation_md": "¡Exacto! 80 ÷ 20 = **4 semanas**. ¡Zara estará orgullosa! Reflexiona: ¿y si ahorraras 10 MXN por semana?", "audio_segment_id": "s3-savings-goal.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}, "s2-make-change": {}, "s3-savings-goal": {"correct": {"20": 4}}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/0d2f838f862698786086ebba59a6f23aae4e9bc1d38383a1ca3e52aa7a2f176f.mp3", "hash": "62b4091791f4a98ca86e64093f7ab5c2dfe4181ed52fe32194acb570150a260e", "bytes": 164448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0d2f838f862698786086ebba59a6f23aae4e9bc1d38383a1ca3e52aa7a2f176f.mp3", "duration_ms": 27360}, "s2-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/4efff143c2f2cb443bb887feb37b309f0b8885d8a9a0eb46882614842dc23b3d.mp3", "hash": "ee21aca9a90a1dd440ece8f7c6f81ec997cc8f5a5d445b59bb4f89f77b0e3e0d", "bytes": 57456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4efff143c2f2cb443bb887feb37b309f0b8885d8a9a0eb46882614842dc23b3d.mp3", "duration_ms": 9520}, "s3-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/4b19b9c537d7effc19722703dd8eaf04ea5ce9fc37dd13b0163d30e4a72b663a.mp3", "hash": "7aba5865a8aa5e392931e948d2fffedf66c3e5bb4ed4fa7f6487a5572978655e", "bytes": 67104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4b19b9c537d7effc19722703dd8eaf04ea5ce9fc37dd13b0163d30e4a72b663a.mp3", "duration_ms": 11120}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/86c8d34cf887afdcadc419e5263bf0ef4f24eda589fc31afc12385d87c498579.mp3", "hash": "b0bc57e469a1ab8bb1a02ea73b905c0db73ae23746575422f2e6f90d5aab4803", "bytes": 82944, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/86c8d34cf887afdcadc419e5263bf0ef4f24eda589fc31afc12385d87c498579.mp3", "duration_ms": 13760}, "s2-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/a51fb6d6fc0931a7c731089f005bc80ce0784996cf03adbdf600b629c0f1e099.mp3", "hash": "be5b8178a00d0ac9fea7b9afc0f2bfba71f7d7d349e4fca549de63d3e27734ab", "bytes": 56016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a51fb6d6fc0931a7c731089f005bc80ce0784996cf03adbdf600b629c0f1e099.mp3", "duration_ms": 9280}, "s3-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/5e699e2f6244333cb803be0b50f9a72838219ee4c38cd912a6ccef00f1a4332e.mp3", "hash": "d47426094470e96e975a88b8ddabbea55108e8c89c894ef9670b4204dfc58921", "bytes": 62784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5e699e2f6244333cb803be0b50f9a72838219ee4c38cd912a6ccef00f1a4332e.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Elige el precio justo", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 5, "type": "quiz_mcq", "hints": ["Piensa: si pones un precio muy alto, los clientes se irán; si es muy bajo, no ganarás nada."], "title": "Precio justo", "payload": {"options": [{"id": "opt-50", "text_md": "50 pesos", "rationale_md": "50 pesos es demasiado caro para un vaso de limonada. Los clientes no pagarán tanto y te quedarás sin vender."}, {"id": "opt-5", "text_md": "5 pesos", "rationale_md": "5 pesos es el precio justo: cubre el costo de 3 pesos de los ingredientes y te da una ganancia de 2 pesos por vaso. Es un precio que los clientes están dispuestos a pagar."}, {"id": "opt-1", "text_md": "1 peso", "rationale_md": "1 peso es muy poco: no cubre ni el costo de los ingredientes (3 pesos). Venderías, pero perderías dinero en cada vaso."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Hola! Ya decidiste abrir tu puesto de limonada con una meta de 80 pesos. Recuerda que en la lección pasada te preguntaste cómo te sentías al abrir el puesto. Ahora, Liruf también tiene su puesto de limonada. A Liruf le cuesta 3 pesos hacer cada vaso (ingredientes). Él piensa vender cada vaso a 5 pesos. Así, por cada vaso, gana 2 pesos (5 - 3 = 2). ¿Cuál es el mejor precio para vender cada vaso?", "difficulty": 1, "explanation_md": "¡Excelente! 5 pesos es el precio justo: cubre el costo de 3 pesos y te da una ganancia de 2 pesos, además es atractivo para los clientes.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "opt-5"}}', '{"units": {"s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/df1701fb4901217b268c4d6e93b53b7d35aa7de1370d221d66410189b47f4d54.mp3", "hash": "93f39be289bc41a45b6cd8e4192d046a51d7dc810531526e0d14003d34ff5a7a", "bytes": 150048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/df1701fb4901217b268c4d6e93b53b7d35aa7de1370d221d66410189b47f4d54.mp3", "duration_ms": 24960}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/3241665b226ea919936dd6c9aed3c9a0daf29e70eadb8a48284ac93e1f307fff.mp3", "hash": "c7f3e81b7cb95426afaae91c988aa3539c1dd07c359590a36e34a1586d59dd14", "bytes": 60768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3241665b226ea919936dd6c9aed3c9a0daf29e70eadb8a48284ac93e1f307fff.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Agrupa o dinheiro do caixa", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar passos, emparelhar produtos com preços e classificar compras entre necessidades do posto e gostos que podem esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-sets", "xp": 10, "type": "group_sets", "hints": ["Observe se o objeto é redondo (moeda) ou retangular (cédula).", "As moedas são de metal e as cédulas de papel."], "title": "Agrupa o dinheiro do caixa", "payload": {"items": [{"id": "item1", "text_md": "Moeda de 5 MXN"}, {"id": "item2", "text_md": "Moeda de 5 MXN"}, {"id": "item3", "text_md": "Moeda de 5 MXN"}, {"id": "item4", "text_md": "Cédula de 20 MXN"}, {"id": "item5", "text_md": "Cédula de 20 MXN"}], "set_a": "moedas", "set_b": "cédulas"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Completar o padrão da fileira de copos do balcão (pequeno, grande, pequeno, grande…): descobrir o que vem a seguir. Agora, Liruf precisa separar o dinheiro do caixa para contar mais fácil. Arraste cada moeda ou cédula para a zona correta: moedas com moedas, cédulas com cédulas.", "difficulty": 1, "explanation_md": "Bom! Você separou 3 moedas e 2 cédulas. Assim é mais fácil contar: 3 moedas de 5 MXN somam 15 MXN e 2 cédulas de 20 MXN somam 40 MXN. Liruf pode manter o controle rápido!", "audio_segment_id": "s1-group-sets.prompt"}], "schema_version": 1}', '{"s1-group-sets": {"zones": {"item1": "a", "item2": "a", "item3": "a", "item4": "b", "item5": "b"}}}', '{"units": {"s1-group-sets.prompt": {"url": "http://localhost:4006/files/lesson-audio/e6aad4f2819d7196ea8926b9e635ed97f3a83c49aafb5b9eeaeea9817dab7b08.mp3", "hash": "a2f1ee1bd53759bf568a370209118eb5c57e01a54b70cf36c168a491e1aeac2e", "bytes": 121248, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e6aad4f2819d7196ea8926b9e635ed97f3a83c49aafb5b9eeaeea9817dab7b08.mp3", "duration_ms": 20160}, "s1-group-sets.explanation": {"url": "http://localhost:4006/files/lesson-audio/b9f30dd22dd41a438f85a06e146d2d0bf5f9319c7a8bdd56da9e05080e12fa87.mp3", "hash": "e0e3c6b5b1a4f377a5296cba5709953d278e901840a18ae5a30721f3473a910c", "bytes": 102528, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b9f30dd22dd41a438f85a06e146d2d0bf5f9319c7a8bdd56da9e05080e12fa87.mp3", "duration_ms": 17040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "true-false", "title": "Certo ou falso? A poupança que cresce", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões simples de dinheiro comparando opções: preço justo, lugar seguro para guardar e distinguir um bom negócio de um mau.", "Decidir se é certo ou falso: ''Se eu guardar 5 reais de cada venda, minha poupança CRESCE a cada dia''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 0, "type": "true_false", "hints": ["Pense: se a cada dia você guarda 5 reais, a quantidade total aumenta ou fica igual?", "Imagine que hoje você guarda 5, amanhã mais 5… o total soma."], "title": "A poupança que cresce", "payload": {"statement_md": "Se eu guardar 5 reais de cada venda, minha poupança CRESCE a cada dia.", "justifications": [{"id": "j-crece", "text_md": "É certo, porque a cada dia você soma mais 5 reais, então o total aumenta."}, {"id": "j-no-crece", "text_md": "É falso, porque guardar sempre a mesma quantia não faz a poupança crescer."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você já sabe que 5 reais é um preço justo para sua limonada, o que acontece se você guardar esses 5 reais todo dia? Dina e Liruf ajudam você a pensar. Dina diz: ''Se você guardar 5 reais de cada venda, a cada dia você soma mais 5. Olha: Dia 1: 5 reais, Dia 2: 10 reais, Dia 3: 15 reais... a poupança cresce!'' Liruf precisa decidir se é certo ou falso. O que você acha?", "difficulty": 1, "explanation_md": "Correto! É **certo**: se você guarda 5 reais todo dia, a poupança total cresce. Por exemplo, em 3 dias você teria 15 reais.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j-crece"}}', '{"units": {"s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/8cbe964ec9df60b3a5c5a633a8c47293fcff8ae6887df2996e7e1aba8a361b83.mp3", "hash": "870f6087dc2a3a1ebf31d5f3aef6dd37d1dafd048d4e92f52dd6b49b4cc83678", "bytes": 188064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8cbe964ec9df60b3a5c5a633a8c47293fcff8ae6887df2996e7e1aba8a361b83.mp3", "duration_ms": 31280}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/ca2122a112b96832f2954e18282db59b547af14dff63b3d6f61a1bfc366465e4.mp3", "hash": "57bc602fb0496954fa5f065e03eb7141f784f7bf642c2727766f437b22c49de6", "bytes": 60768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ca2122a112b96832f2954e18282db59b547af14dff63b3d6f61a1bfc366465e4.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "memory-flip", "title": "Juego de memoria con monedas", "locale": "es-MX", "subject": "mixed", "objectives": ["Encontrar los pares escondidos de monedas iguales (1 con 1, 5 con 5, 10 con 10): reconocer las monedas de México."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 0, "type": "memory_flip", "hints": ["Recuerda: las monedas de 1 son las más chiquitas, las de 5 son plateadas y las de 10 tienen el centro dorado."], "title": "Encuentra los pares", "payload": {"pairs": [{"a_md": "Moneda de 1 peso", "b_md": "1"}, {"a_md": "Moneda de 5 pesos", "b_md": "5"}, {"a_md": "Moneda de 10 pesos", "b_md": "10"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que ya sabes los precios del puesto (vaso chico: 5, jarra: 20, galleta: 3), Zara quiere ayudarte a reconocer las monedas para cobrar bien. Ella inventó un juego de memoria con las monedas de la caja. Voltea las tarjetas para encontrar pares de monedas iguales. ¡Empareja 1 con 1, 5 con 5 y 10 con 10! Por ejemplo, Zara necesita una moneda de 5 pesos para comprar una galleta.", "difficulty": 1, "explanation_md": "¡Muy bien! Emparejaste las monedas de 1, 5 y 10. Así reconoces las monedas de México. Por ejemplo, la moneda de 5 pesos sirve para pagar un vaso chico, la de 10 para dos galletas, y la de 1 para completar el cambio.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/708669bd8aa71cedd3c9da94c595e39d65debd88197278b85c0598948d0ad6fe.mp3", "hash": "b550c29ab11e052268abee8984360da88df18ba548320732dbb3ad3522f4aecb", "bytes": 163008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/708669bd8aa71cedd3c9da94c595e39d65debd88197278b85c0598948d0ad6fe.mp3", "duration_ms": 27120}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/ccb13d110a1e560d747856bfa51056d4ae7c80055bb9139cde05ebf5941104cd.mp3", "hash": "400b77a6e5869844ddc124bc4878525b2d5adcf777e5e15a00a30532174024ef", "bytes": 91584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ccb13d110a1e560d747856bfa51056d4ae7c80055bb9139cde05ebf5941104cd.mp3", "duration_ms": 15200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Cause and effect at the lemonade stand", "locale": "en-US", "subject": "mixed", "objectives": ["Spot an error in a sales sum", "Read a simple graph of cups sold per day", "Recognize signs of a bad deal"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-causa-efecto", "xp": 0, "type": "cause_effect", "hints": ["Think: if it''s hot, people are thirstier."], "title": "Match causes and effects", "payload": {"slots": 3, "events": [{"id": "e1", "text_md": "Sunny and hot day"}, {"id": "e2", "text_md": "Raise the price from 5 MXN to 10 MXN"}, {"id": "e3", "text_md": "Liruf plays cheerful music at the stand"}, {"id": "e4", "text_md": "A customer says the lemonade is too sweet"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember that yesterday we discovered Liruf added up his sales wrong: he said he sold 20 cups, but it was actually 5+5+5=15. Today we''ll practice spotting errors in sales sums. First, help Liruf understand what happened with his sales. Match each cause with its effect.", "difficulty": 1, "explanation_md": "Excellent! A sunny day causes more thirst, which leads to more cups sold. Doubling the price causes fewer customers. Now, check this calculation: Liruf wrote that on Monday he sold 6 cups, Tuesday 7, Wednesday 8, and said the total was 25. Is that correct? 6+7+8=21, not 25. Find the error!", "audio_segment_id": "s1-causa-efecto.prompt"}], "schema_version": 1}', '{"s1-causa-efecto": {"chain": ["e1", "e2", "e3"]}}', '{"units": {"s1-causa-efecto.prompt": {"url": "http://localhost:4006/files/lesson-audio/95ab787522e6437cb27cd64775d083bd272b66cccfc297c543a209647c3f8670.mp3", "hash": "bea04702a57d115b8687e31233d7d7b4ec3764da2e3634bec54dcbe156fdb528", "bytes": 98784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/95ab787522e6437cb27cd64775d083bd272b66cccfc297c543a209647c3f8670.mp3", "duration_ms": 16400}, "s1-causa-efecto.explanation": {"url": "http://localhost:4006/files/lesson-audio/581e9b432fbee34d2a24cf6541cdad6da5e420c5ba02801949fb4857fc579d85.mp3", "hash": "a89aa82592eba81628e0e3d37dae02d1afcf5f596f27ff08d4c312f01f10ccc4", "bytes": 112176, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/581e9b432fbee34d2a24cf6541cdad6da5e420c5ba02801949fb4857fc579d85.mp3", "duration_ms": 18640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-narrativa-choice", "title": "A Saturday at the lemonade stand", "locale": "en-US", "subject": "mixed", "objectives": ["Chain several skills in one lesson: listen to the situation, decide, calculate, and charge."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura-sabado", "xp": 0, "type": "story_scene", "hints": [], "title": "Customers arrive!", "payload": {"art": {"icon": "lemonade_stand", "tint": "primary"}, "action": "idle", "body_md": "—Good morning! —says Dina—. Just like yesterday with the tip machine that doubled (if 1 went in, 2 came out), today we will also use rules to decide the price. Today is Saturday and we have lots of customers. Liruf, how much should we charge per cup? The normal price is 5 pesos, but we can change it. For example, if there are 10 customers and each buys one cup, we would earn 50 pesos at the normal price. You decide!\\n\\nLiruf looks at the line: —We could raise it a little, but without scaring anyone. What do you think?\\n\\nRho, from the counter, suggests: —We can set it at 6 pesos, or 7, or even 8. You decide!", "emotion": "happy", "backdrop": "band", "character": "dina"}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "Dina and Liruf open the stand on a sunny Saturday. There is already a line of customers.", "difficulty": 1, "explanation_md": "Dina remembers that the tip machine doubled: if 1 went in, 2 came out. Today they have to decide the price.", "audio_segment_id": "s1-apertura-sabado.prompt"}, {"id": "s2-decision-precio", "xp": 15, "type": "quiz_mcq", "hints": ["Think: if you raise the price too much, some customers might not buy."], "title": "Choose the price of the day", "payload": {"options": [{"id": "opt-6", "text_md": "6 pesos", "rationale_md": "A small increase, just enough to earn a little more without losing customers."}, {"id": "opt-7", "text_md": "7 pesos", "rationale_md": "It might be too much for some; you might sell fewer cups."}, {"id": "opt-8", "text_md": "8 pesos", "rationale_md": "A big jump from 5 pesos; many customers might leave."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "What price will you set for a cup of lemonade today?", "difficulty": 2, "explanation_md": "You chose 6 pesos, a fair price that encourages customers. Dina smiles.", "audio_segment_id": "s2-decision-precio.prompt"}], "schema_version": 1}', '{"s2-decision-precio": {"correct_option_id": "opt-6"}}', '{"units": {"s1-apertura-sabado.body": {"url": "http://localhost:4006/files/lesson-audio/ea5d7adfeb6b31a5d1ca821b9b113e5484feccb5d42c26f97919c46709aa6657.mp3", "hash": "f3d97a75448f9678207037374c0a78b3c4de1ea1627ac6fd76ac2b5bbe51d830", "bytes": 185616, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ea5d7adfeb6b31a5d1ca821b9b113e5484feccb5d42c26f97919c46709aa6657.mp3", "duration_ms": 30880}, "s1-apertura-sabado.prompt": {"url": "http://localhost:4006/files/lesson-audio/3d26a43e669807ac2772b1bbaef20f94d450673988eeb31f6808ecd9620c0abc.mp3", "hash": "66c4da2308c8050241060c0f0058e8f818cc90780a777da17e8ab00032d5aa8c", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3d26a43e669807ac2772b1bbaef20f94d450673988eeb31f6808ecd9620c0abc.mp3", "duration_ms": 5280}, "s2-decision-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/9715ad2bdc1b4404ad2192f75d8d9603770bd771868acf882bf20252d0eaef23.mp3", "hash": "5b3a585150243c49d779e57850036d4c4133d16c3463d175faa620408016101f", "bytes": 15264, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9715ad2bdc1b4404ad2192f75d8d9603770bd771868acf882bf20252d0eaef23.mp3", "duration_ms": 2480}, "s1-apertura-sabado.explanation": {"url": "http://localhost:4006/files/lesson-audio/401c8f90ae8ad00d0926bddb87007e35b5fc6c8a4bb80a87d4631e59f26c4475.mp3", "hash": "77368900640058c4d1dacf1c6ad4e58d59952db332e290d4494843980b97cf27", "bytes": 39168, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/401c8f90ae8ad00d0926bddb87007e35b5fc6c8a4bb80a87d4631e59f26c4475.mp3", "duration_ms": 6480}, "s2-decision-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/316f2cc3d7b323e867bfec2fc7289c66b5cd4c0306221d409de3f3ba253b0d89.mp3", "hash": "6e045bc92e464ec483b541cd6a8fe774644ea7bca6fbf9a61b000eda5860b152", "bytes": 31104, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/316f2cc3d7b323e867bfec2fc7289c66b5cd4c0306221d409de3f3ba253b0d89.mp3", "duration_ms": 5120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "memory-flip", "title": "Memory game with coins", "locale": "en-US", "subject": "mixed", "objectives": ["Find the hidden pairs of matching coins (1 with 1, 5 with 5, 10 with 10): recognize Mexican coins."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 0, "type": "memory_flip", "hints": ["Remember: 1-peso coins are the smallest, 5-peso coins are silver, and 10-peso coins have a gold center."], "title": "Find the pairs", "payload": {"pairs": [{"a_md": "1-peso coin", "b_md": "1"}, {"a_md": "5-peso coin", "b_md": "5"}, {"a_md": "10-peso coin", "b_md": "10"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you know the stand prices (small cup: 5, pitcher: 20, cookie: 3), Zara wants to help you recognize coins so you can charge correctly. She invented a memory game with the coins from the cash box. Flip the cards to find matching pairs of coins. Match 1 with 1, 5 with 5, and 10 with 10! For example, Zara needs a 5-peso coin to buy a cookie.", "difficulty": 1, "explanation_md": "Great job! You matched the 1, 5, and 10 peso coins. Now you can recognize Mexican coins. For example, a 5-peso coin can pay for a small cup, a 10-peso coin for two cookies, and a 1-peso coin to make change.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/3afb0a7bdc6c25c75c20ca025e9e7f7d3a56bbfaded46bd05f9a601db2132256.mp3", "hash": "e6ac9a761ee2532d598428037a802c2cf4fef541094ec2035a4a61364c76089a", "bytes": 116928, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3afb0a7bdc6c25c75c20ca025e9e7f7d3a56bbfaded46bd05f9a601db2132256.mp3", "duration_ms": 19440}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/3e6407258c27317dc0c3fe35750ab9b84e2a2b9fce8100da6a60b2dd628a936d.mp3", "hash": "a6ee81e225871bfa9dec8a4eb16e40e64ecb390d0c72d1ec339276db5ba57921", "bytes": 80496, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3e6407258c27317dc0c3fe35750ab9b84e2a2b9fce8100da6a60b2dd628a936d.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compara fornecedores de limões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Leia a tabela de dois fornecedores de limões (preço e quantidade) e escolha o que dá mais por menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 0, "type": "compare_table", "hints": ["Observe o preço e a quantidade: procure qual te dá mais limões por cada real."], "title": "Compara fornecedores de limões", "payload": {"cols": [{"id": "precio", "label": "Preço"}, {"id": "cantidad", "label": "Quantidade de limões"}], "rows": [{"id": "proveedor-a", "label": "Fornecedor A"}, {"id": "proveedor-b", "label": "Fornecedor B"}], "tokens": [{"id": "t1", "text_md": "5 MXN"}, {"id": "t2", "text_md": "10 limões"}, {"id": "t3", "text_md": "5 MXN"}, {"id": "t4", "text_md": "8 limões"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Depois de ver como o preço afeta as vendas, agora Dina busca a melhor oferta para seus limões. Ela quer comprar limões para sua barraca de limonada e anotou em seu caderno uma tabela com dois fornecedores. Ajude Dina a escolher o que dá mais limões por menos dinheiro. Pense: qual é mais vantajoso para ela?", "difficulty": 1, "explanation_md": "Correto! O fornecedor A dá 10 limões por 5 MXN, ou seja, 2 limões por real. O fornecedor B dá 8 limões por 5 MXN, apenas 1,6 limões por real. O A é o melhor negócio!", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a_precio": "t1", "proveedor-b_precio": "t3", "proveedor-a_cantidad": "t2", "proveedor-b_cantidad": "t4"}}}', '{"units": {"s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/54b7f37adeee02f1f009161379e7a497d611b9f91123f340a0cbd2d18b33420b.mp3", "hash": "92167a30b4d61a6308840ca2a2b1c70e1992ff0aa7349875a195c14360e7370e", "bytes": 127008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/54b7f37adeee02f1f009161379e7a497d611b9f91123f340a0cbd2d18b33420b.mp3", "duration_ms": 21120}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/cac7720020a9e6d2ce5d30e15898678ddd3054575d5e681f47e6a5f1a7779850.mp3", "hash": "7fef5eb25b2d80b0e19b3ffcd62a02a5c440631873fe3b46b52af39737fe3378", "bytes": 103968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cac7720020a9e6d2ce5d30e15898678ddd3054575d5e681f47e6a5f1a7779850.mp3", "duration_ms": 17280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "pattern-complete", "title": "Complete the cup pattern", "locale": "en-US", "subject": "mixed", "objectives": ["Complete the pattern of the cup row on the counter (small, large, small, large…): figure out what comes next."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-pattern-vasos", "xp": 0, "type": "pattern_complete", "hints": ["The pattern alternates between small and large. What was the last cup you saw?"], "title": "Cup pattern", "payload": {"options": [{"id": "opt1", "icon": "cup_small", "tint": "primary"}, {"id": "opt2", "icon": "cup_large", "tint": "primary"}, {"id": "opt3", "icon": "cup_medium", "tint": "primary"}], "sequence": [{"icon": "cup_small", "tint": "primary"}, {"icon": "cup_large", "tint": "primary"}, {"icon": "cup_small", "tint": "primary"}, {"icon": "cup_large", "tint": "primary"}], "missing_slots": 1}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Now that we''ve organized the sale day, let''s see how Zara arranges the cups for her customers at noon! Zara is placing cups on the counter. Observe the pattern: **small**, **large**, **small**, **large**... Which cup comes next?", "difficulty": 1, "explanation_md": "Correct! The pattern is small, large, small, large... The last one was large, so the next one is small. Well done, Zara!", "audio_segment_id": "s1-pattern-vasos.prompt"}], "schema_version": 1}', '{"s1-pattern-vasos": {"correct": {"0": "opt1"}}}', '{"units": {"s1-pattern-vasos.prompt": {"url": "http://localhost:4006/files/lesson-audio/4e98a813cb4b12575cb5d66d6685ac1666800fc640bcd91e56f35b8946fc1416.mp3", "hash": "9ef9049ac3e010ee5ba1552760669161acf3d35d6d5f89e3028e6a9540489e2e", "bytes": 78624, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/4e98a813cb4b12575cb5d66d6685ac1666800fc640bcd91e56f35b8946fc1416.mp3", "duration_ms": 13040}, "s1-pattern-vasos.explanation": {"url": "http://localhost:4006/files/lesson-audio/56e2780f78b26f2807fa55ace75d96001b382c1c2e872500643fa993e0af9502.mp3", "hash": "161ecff5d04090b26906bc12c33eff9e7a3e76fab529a2065c2294a3f3f9fbeb", "bytes": 58896, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/56e2780f78b26f2807fa55ace75d96001b382c1c2e872500643fa993e0af9502.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Fair trade: trading lemonade for lemons?", "locale": "en-US", "subject": "mixed", "objectives": ["Decide if a trade is fair by comparing the values of two offers using coins of 1, 2, 5, and 10."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 0, "type": "fair_trade", "hints": ["Each glass of lemonade costs 5 pesos. How much are 2 glasses worth?", "Compare the total value of the glasses with the value of the bag of lemons."], "title": "Fair trade: trading lemonade for lemons?", "payload": {"offer_a": {"qty": 2, "icon": "cup", "label": "Glasses of lemonade"}, "offer_b": {"qty": 1, "icon": "lemon", "label": "Bag of lemons"}, "rate_md": "Each glass of lemonade costs **5 pesos**."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf keeps saving for his 80-peso guitar. He already knows he needs 4 weeks saving 20 pesos each week. Today, while preparing lemonade to sell, the fruit seller makes him an offer: swap 2 glasses of lemonade for a bag of lemons worth 10 pesos. Is the exchange fair?", "difficulty": 1, "explanation_md": "Correct! 2 glasses of lemonade are worth 10 pesos (2 × 5 = 10), same as the bag of lemons. It''s a fair trade!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/2aa8981404f985ca3eff83137910c6b143a6d1ee0b26afbad53476e34517ba8f.mp3", "hash": "e9a12ab3c814441e2bbbeb90602836460f809b88e6822f35e326c501d3fd469f", "bytes": 91584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2aa8981404f985ca3eff83137910c6b143a6d1ee0b26afbad53476e34517ba8f.mp3", "duration_ms": 15200}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/bf8dc62e58d401037c20690a2b48a10594b0e15417c43e925acbb635e432246d.mp3", "hash": "60f8c7b553877a7a0c31362bb9c622145d21a4ee58d14875362e09deb32b0ac7", "bytes": 46368, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bf8dc62e58d401037c20690a2b48a10594b0e15417c43e925acbb635e432246d.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "speed-tap", "title": "¡Atrapa las monedas!", "locale": "es-MX", "subject": "mixed", "objectives": ["Reconocer monedas de un vistazo entre otros objetos.", "Practicar la toma rápida de decisiones sobre qué es dinero."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 0, "type": "speed_tap", "hints": ["Las monedas de México son de 1, 2, 5, 10 y 20 pesos. ¡Busca esos números!", "Si tiene forma redonda y dice ''MXN'' o el número, es moneda."], "title": "¡Atrapa las monedas!", "payload": {"items": [{"id": "moneda1", "text_md": "Moneda de 1 peso"}, {"id": "boton1", "text_md": "Botón rojo"}, {"id": "moneda2", "text_md": "Moneda de 2 pesos"}, {"id": "tapa1", "text_md": "Tapa de jugo"}, {"id": "moneda5", "text_md": "Moneda de 5 pesos"}, {"id": "moneda10", "text_md": "Moneda de 10 pesos"}, {"id": "boton2", "text_md": "Botón azul"}, {"id": "moneda20", "text_md": "Moneda de 20 pesos"}, {"id": "tapa2", "text_md": "Tapa de jugo"}], "seconds": 10, "instruction_md": "Toca solo las MONEDAS. ¡Ignora botones y tapas de jugo!"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Recuerda que ayer decidiste qué gastos ayudan a tu puesto. Hoy, necesitas monedas reales para comprar esos limones. Dina y Liruf están contando las monedas que tienen. ¿Puedes ayudar a Liruf a encontrar solo las monedas entre estos objetos?", "difficulty": 1, "explanation_md": "¡Bien! Atrapaste monedas de 1, 2, 5, 10 y 20 pesos. Liruf necesita esas para su puesto. Las tapas de jugo no son dinero, así que no las toques. Si tocaste una tapa, recuerda: solo las monedas sirven para comprar limones.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["moneda1", "moneda2", "moneda5", "moneda10", "moneda20"]}}', '{"units": {"s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/cc72cfd9cf99ab476ff4d6aa842df40103b2091256623e152f84fc0f43fb88d6.mp3", "hash": "aa20b263667ac22003c6bda0454bc7569d46a41bb28c992340e71a906170f1c9", "bytes": 93888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cc72cfd9cf99ab476ff4d6aa842df40103b2091256623e152f84fc0f43fb88d6.mp3", "duration_ms": 15600}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/2287cf795459aa5a591cfa0b7783db69df1f23873c7bb88b843f82366fc13501.mp3", "hash": "e418e9a35513ab4e69b6c53e921ebf42ea83b31174ed8aae7947598907c025ff", "bytes": 100656, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2287cf795459aa5a591cfa0b7783db69df1f23873c7bb88b843f82366fc13501.mp3", "duration_ms": 16720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "make-change", "title": "Giving the correct change", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the change when paying with a 20-peso bill for a 5-peso item using 10 and 5 peso coins.", "Identify Mexican coins of 1, 2, 5, and 10 pesos.", "Plan weeks to reach a savings goal of 80 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 15, "type": "make_change", "hints": ["Think: 20 - 5 = 15. Which coins add up to 15?", "You can use a 10 peso coin and a 5 peso coin."], "title": "The lady with the dog''s change", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember how we made 5 pesos with 1 and 2 peso coins? Now we''ll use that total as the price of lemonade. The lady with the dog gives you a **20** peso bill for a glass of lemonade that costs **5** pesos. How much change should you give back? Choose the correct combination of coins.", "difficulty": 2, "explanation_md": "Correct! 20 - 5 = 15, and 10 + 5 = 15. You should give back a 10 peso coin and a 5 peso coin.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/4de15d6949b92c3b2ff39f0c7a4c64acc9dc59722ad286a84bec0e7c1119d418.mp3", "hash": "6b01ce0a181dca42b97780cb834c9ae2a342186136d3b2a3bf0befe040963959", "bytes": 89136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4de15d6949b92c3b2ff39f0c7a4c64acc9dc59722ad286a84bec0e7c1119d418.mp3", "duration_ms": 14800}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/7684eedf3d91188a64a123398f435d230e70f24a40bcc32495595a29d9b81bbe.mp3", "hash": "86018e6b0abbb2d41aaf9bb7e03c7399fb7ee9bac6ef33323f7d5ade03b65807", "bytes": 55584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7684eedf3d91188a64a123398f435d230e70f24a40bcc32495595a29d9b81bbe.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classify the stand''s purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Sort the day''s purchases into two buckets: STAND NEED (lemons, cups) or WANT that can wait (stickers, balloons)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 0, "type": "sort_buckets", "hints": ["Think: without this, can the stand still sell lemonade?", "Wants are things that make you happy, but the stand works without them."], "title": "Classify the stand''s purchases", "payload": {"items": [{"id": "limones", "text_md": "Lemons (for lemonade)"}, {"id": "vasos", "text_md": "Cups (to serve lemonade)"}, {"id": "stickers", "text_md": "Star stickers"}, {"id": "globos", "text_md": "Colorful balloons"}], "buckets": [{"id": "necesidad", "label": "STAND NEED"}, {"id": "gusto", "label": "WANT that can wait"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Yesterday you helped Dina and Liruf recognize matching coins. Today they''ll use that money to decide what to buy. They have 20 pesos in 10-peso coins. Help Dina and Liruf sort the shopping list. Drag each item to the correct bucket: **STAND NEED** (things they absolutely must buy) or **WANT that can wait** (things they like but aren''t urgent).", "difficulty": 1, "explanation_md": "Great job! Lemons and cups are NEEDS because without them Liruf can''t make or sell lemonade. Stickers and balloons are WANTS that can wait for another day.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/db1ac0f277bcbad496fe9069b1b3960af4ccfaecaad3069041c5485e6e660967.mp3", "hash": "7c227f333c92ae3e37e054fbe3f0105622798bbeed3dfb20a1ebadd4190c4546", "bytes": 112176, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/db1ac0f277bcbad496fe9069b1b3960af4ccfaecaad3069041c5485e6e660967.mp3", "duration_ms": 18640}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/bdede8739895226dd4212e3b9f9518ff39e09644975de3f0c3cc6365892d1c40.mp3", "hash": "840cf8c9502fb280b160dbab96ee156d889dd52384ba27afcdd40a2f11ac3bb6", "bytes": 47808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bdede8739895226dd4212e3b9f9518ff39e09644975de3f0c3cc6365892d1c40.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Trueque justo: ¿cambiar limonada por limones?", "locale": "es-MX", "subject": "mixed", "objectives": ["Decidir si un trueque es justo comparando valores de dos ofertas usando monedas de 1, 2, 5 y 10."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 0, "type": "fair_trade", "hints": ["Cada vaso de limonada cuesta 5 pesos. ¿Cuánto valen 2 vasos?", "Compara el valor total de los vasos con el valor de la bolsa de limones."], "title": "Trueque justo: ¿cambiar limonada por limones?", "payload": {"offer_a": {"qty": 2, "icon": "cup", "label": "Vasos de limonada"}, "offer_b": {"qty": 1, "icon": "lemon", "label": "Bolsa de limones"}, "rate_md": "Cada vaso de limonada cuesta **5 pesos**."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf sigue ahorrando para su guitarra de 80 pesos. Ya sabe que necesita 4 semanas ahorrando 20 pesos cada semana. Hoy, mientras prepara limonada para vender, el frutero le hace una oferta: cambiar 2 vasos de limonada por una bolsa de limones que vale 10 pesos. ¿Es justo el intercambio?", "difficulty": 1, "explanation_md": "¡Correcto! 2 vasos de limonada valen 10 pesos (2 × 5 = 10), igual que la bolsa de limones. ¡Es un trueque justo!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/6799de68d0a4b00f5f52ba92fbcb4b77ea29f79696a07344b22cff29aab3b601.mp3", "hash": "683ce558b4931c357803f933137ea549ac2ad547dfe6e0466365487b0896aac6", "bytes": 119808, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6799de68d0a4b00f5f52ba92fbcb4b77ea29f79696a07344b22cff29aab3b601.mp3", "duration_ms": 19920}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/51f797b7f5e1cc7cd1e36d475050e8dc566d3640852e5bc9e5fdfdca64109032.mp3", "hash": "f5d9fbb2d1d9d5a68bc98c2a068a63980757e86f2222c1809894d5ce7101fcd5", "bytes": 59328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/51f797b7f5e1cc7cd1e36d475050e8dc566d3640852e5bc9e5fdfdca64109032.mp3", "duration_ms": 9840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "order-steps", "title": "Ordena los pasos de la limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar pasos, emparejar productos con precios y clasificar compras entre necesidades del puesto y gustos que pueden esperar."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-order-steps", "xp": 0, "type": "order_steps", "hints": ["Piensa: ¿qué haces primero con los limones?", "Después de exprimir, ¿qué líquido agregas?"], "title": "Receta revuelta", "payload": {"items": [{"id": "step1", "text_md": "Exprimir limones"}, {"id": "step2", "text_md": "Agregar agua"}, {"id": "step3", "text_md": "Endulzar"}, {"id": "step4", "text_md": "Probar"}, {"id": "step5", "text_md": "Servir"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Recordemos: ayer ayudamos a Liruf a decidir qué comprar para su puesto. Recuerda que los limones eran una NECESIDAD para el puesto, ¡así que hoy los usamos para hacer limonada! Compramos 3 limones que costaron $6 en total. Ahora, ayuda a Liruf a ordenar los pasos para hacer limonada. Arrastra las tarjetas al orden correcto: primero exprimir limones, luego agregar agua, endulzar, probar y servir.", "difficulty": 1, "explanation_md": "¡Bien hecho! El orden correcto es: exprimir limones, agregar agua, endulzar, probar y servir. Liruf ya puede preparar la limonada.", "audio_segment_id": "s1-order-steps.prompt"}], "schema_version": 1}', '{"s1-order-steps": {"order": ["step1", "step2", "step3", "step4", "step5"]}}', '{"units": {"s1-order-steps.prompt": {"url": "http://localhost:4006/files/lesson-audio/68e61ca6632043109a172f412a72a274c57b1840e3ee1d250a618b13be1fc3b0.mp3", "hash": "53cb52949971dee0f723b5a9bc7a789029a89f131b6cf976e63bf44cb80c193d", "bytes": 165024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/68e61ca6632043109a172f412a72a274c57b1840e3ee1d250a618b13be1fc3b0.mp3", "duration_ms": 27440}, "s1-order-steps.explanation": {"url": "http://localhost:4006/files/lesson-audio/4f81d9134bec01a22c5051934c38a62462a494cc9327f03cab6f07b9454ed432.mp3", "hash": "c641b1eb592edf028f80c55e8af3c574ef5425cb710328c884643330f6d2eec5", "bytes": 60768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4f81d9134bec01a22c5051934c38a62462a494cc9327f03cab6f07b9454ed432.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'en-US', '1', E'{"meta": {"cast": ["rho", "liruf"], "slug": "rank-choices", "title": "Prioritize Your Purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Sort from most to least urgent what to spend today''s profit on: restock lemons first, then cups, and finally decorations."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank-choices", "xp": 15, "type": "rank_choices", "hints": ["Think: what do you need to keep selling lemonade tomorrow?", "Lemons are the base of the recipe; without them, there is no lemonade."], "title": "What to buy first?", "payload": {"items": [{"id": "limones", "text_md": "Restock lemons"}, {"id": "vasos", "text_md": "Buy new cups"}, {"id": "adornos", "text_md": "Decorations for the stand"}], "criterion_md": "Order from **most urgent** to **least urgent** for the lemonade stand."}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Yesterday you ordered the steps to make lemonade. Today you''ll order what to buy first with the profits!\\n\\nRho earned **20 pesos** at their lemonade stand. Help Rho order the purchases from most urgent to least urgent.", "difficulty": 2, "explanation_md": "Excellent! First restock lemons because they are the base of the recipe. Then cups to serve, and finally decorations that can wait.", "audio_segment_id": "s1-rank-choices.prompt"}], "schema_version": 1}', '{"s1-rank-choices": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-rank-choices.prompt": {"url": "http://localhost:4006/files/lesson-audio/5080b006e5cc6febd88d3ae1b3f2b33f8cb8753fd9e818509f55c5809d56399e.mp3", "hash": "a8e99c91145a42e3f88bf8a7534947c69afb522fc2a37c2820fafa0e81a19ab3", "bytes": 92016, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/5080b006e5cc6febd88d3ae1b3f2b33f8cb8753fd9e818509f55c5809d56399e.mp3", "duration_ms": 15280}, "s1-rank-choices.explanation": {"url": "http://localhost:4006/files/lesson-audio/39ce648bd038b3c415ddc965e8d9c17fca40880bc9b306a6104d9db656d22831.mp3", "hash": "bf2a11ac02418082829159f855bb6ea70d2a329ed8124fe159abc21f5f008aaf", "bytes": 60336, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/39ce648bd038b3c415ddc965e8d9c17fca40880bc9b306a6104d9db656d22831.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'pt-BR', '1', E'{"meta": {"cast": ["rho", "liruf"], "slug": "rank-choices", "title": "Priorize suas compras", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar do mais ao menos urgente em que gastar o lucro de hoje: repor limões primeiro, depois copos, e por último enfeites."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank-choices", "xp": 15, "type": "rank_choices", "hints": ["Pense: o que você precisa para continuar vendendo limonada amanhã?", "Os limões são a base da receita, sem eles não há limonada."], "title": "O que comprar primeiro?", "payload": {"items": [{"id": "limones", "text_md": "Repor limões"}, {"id": "vasos", "text_md": "Comprar copos novos"}, {"id": "adornos", "text_md": "Enfeites para a barraca"}], "criterion_md": "Ordene de **mais urgente** a **menos urgente** para a barraca de limonada."}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Ontem você ordenou os passos para fazer limonada. Hoje você vai ordenar o que comprar primeiro com os lucros!\\n\\nRho ganhou **20 reais** em sua barraca de limonada. Ajude Rho a ordenar as compras da mais urgente para a menos urgente.", "difficulty": 2, "explanation_md": "Excelente! Primeiro repor limões porque são a base da receita. Depois copos para servir, e por último enfeites que podem esperar.", "audio_segment_id": "s1-rank-choices.prompt"}], "schema_version": 1}', '{"s1-rank-choices": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-rank-choices.prompt": {"url": "http://localhost:4006/files/lesson-audio/73d88593eda13daf15fa460d517879e85d673ad79da4682634a045fcdd11c2ee.mp3", "hash": "5fa7a3741568b18e030d5fd485f78eda545ca086f77243b0a029bcc953ab91ad", "bytes": 93024, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/73d88593eda13daf15fa460d517879e85d673ad79da4682634a045fcdd11c2ee.mp3", "duration_ms": 15440}, "s1-rank-choices.explanation": {"url": "http://localhost:4006/files/lesson-audio/21f0ec6f2eef9894028c122b6ac4bd83a09c545643778448f691244d92bf9a3b.mp3", "hash": "23d0335ba4ef0d82e3ee75c0dac68df117ca4fbf01f146c4da1e6e5e8cdc625e", "bytes": 58896, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/21f0ec6f2eef9894028c122b6ac4bd83a09c545643778448f691244d92bf9a3b.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "interest-peek", "title": "A peek at interest", "locale": "en-US", "subject": "mixed", "objectives": ["Check the ''interest_peek'' exercise in isolation (prediction flow)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 0, "type": "interest_peek", "hints": ["The first month, he earns 10% of 80, which is 8 MXN. So after one month he has 88 MXN.", "The second month, he again earns 10% of the initial 80 MXN, which is another 8 MXN."], "title": "Predict Liruf''s savings", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 80, "prediction": {"kind": "choice", "options": [{"id": "opt-a", "text_md": "96 MXN"}, {"id": "opt-b", "text_md": "88 MXN"}, {"id": "opt-c", "text_md": "90 MXN"}]}}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf saved **80 MXN** in his piggy bank. Each month, his money grows by **10%** (simple interest). How much will he have after **2 months**?", "difficulty": 1, "explanation_md": "Correct! Liruf will have **96 MXN** after 2 months. Each month he earns 8 MXN (10% of 80), so in total he earns 16 MXN. His money grows!", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 96, "tolerance": 0.01, "correct_option_id": "opt-a"}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escrever a palavra ''poupança''", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escrever a palavra que nomeia o dinheiro que você guarda para depois: ''poupança''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Começa com a letra P e tem 8 letras.", "É o contrário de gastar: guardar para depois."], "title": "Escreva a palavra secreta", "payload": {"max_chars": 10, "placeholder": "Escreva aqui..."}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Dina e Rho contam: Rho guardou 3 reais da venda de limonada. Isso é uma poupança. Lembra como você somou 5+5 e se sentiu seguro? Agora, escreva a palavra que nomeia o dinheiro que você guarda para depois: ''poupança''. Dica: começa com P e tem 8 letras.", "difficulty": 1, "explanation_md": "Muito bem! A palavra ''poupança'' tem 8 letras e é o dinheiro que você guarda para depois, como Rho te ensinou. Assim como você somou 5+5 com confiança, agora sabe que poupar é guardar para mais tarde.", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["ahorro"], "keywords": ["ahorro"], "case_sensitive": false}}', '{"units": {"s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/315b7dd7bcfb2e7857aca2434a90a7cf8aacb7e809dd9440e04435408a897c34.mp3", "hash": "1c2a2140cd18b78da4f72cbf7bc121b1e1f59184f7ef48d192f1ec96aa065203", "bytes": 122688, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/315b7dd7bcfb2e7857aca2434a90a7cf8aacb7e809dd9440e04435408a897c34.mp3", "duration_ms": 20400}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/d69165682b150147e1f8851354c0ba0bc99706ee1f7bbeccc6cc96f7ed3d7831.mp3", "hash": "cfb364763b56b8e8eeb0bedbc9226d69089022e23cffc42bc883768b2e5801e8", "bytes": 89136, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d69165682b150147e1f8851354c0ba0bc99706ee1f7bbeccc6cc96f7ed3d7831.mp3", "duration_ms": 14800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Montar a compra do dia com 20 reais", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar dinheiro com moedas de 1, 2, 5 e 10", "Calcular troco de uma nota de 20", "Planejar quantas semanas faltam para a meta de 80 reais"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 0, "type": "budget_fit", "hints": ["Some os preços dos ingredientes que você escolher e certifique-se de que não passem de 20 reais."], "title": "Compra no mercado", "payload": {"items": [{"id": "limones", "icon": "lemon", "need": true, "label": "Limões (5 reais)", "price": 5}, {"id": "azucar", "icon": "sugar", "need": false, "label": "Açúcar (3 reais)", "price": 3}, {"id": "hielo", "icon": "ice", "need": false, "label": "Gelo (2 reais)", "price": 2}, {"id": "vasos", "icon": "cup", "need": true, "label": "Copos (4 reais)", "price": 4}, {"id": "agua", "icon": "water", "need": false, "label": "Água (1 real)", "price": 1}, {"id": "menta", "icon": "mint", "need": false, "label": "Hortelã (6 reais)", "price": 6}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf tem uma nota de **20 reais** e quer comprar ingredientes para sua barraca de limonada. Ajude-o a escolher quais cabem no seu orçamento. Lembre-se de que antes você comparou preços de limões para gastar menos; agora é hora de montar a compra.", "difficulty": 1, "explanation_md": "Muito bem! Você escolheu uma combinação que soma exatamente 20 reais ou menos, então Liruf pode comprar sem estourar o orçamento.", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/2f0abcb3625e8f76c2019a35d9a0bdff8ce6b0d20a3e4e35685677a6fbc8af00.mp3", "hash": "e56631193655824704d88944c7578334af4196663aa5ee3257406bc67b66d63d", "bytes": 95904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2f0abcb3625e8f76c2019a35d9a0bdff8ce6b0d20a3e4e35685677a6fbc8af00.mp3", "duration_ms": 15920}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/ea75c8ff4c1cae1e0db2470936671f1f0fccf299d55088854a2e7a327650c17e.mp3", "hash": "d9921fc25b60bc7448b2b17dd35b15ccfaee7e94d09025f4c12777d8d5335bc1", "bytes": 60336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ea75c8ff4c1cae1e0db2470936671f1f0fccf299d55088854a2e7a327650c17e.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "interest-peek", "title": "Um olhar sobre os juros", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''interest_peek'' de forma isolada (fluxo de previsão)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 0, "type": "interest_peek", "hints": ["No primeiro mês, ele ganha 10% de 80, que são 8 MXN. Então, depois de um mês, ele tem 88 MXN.", "No segundo mês, ele ganha novamente 10% dos 80 MXN iniciais, que são outros 8 MXN."], "title": "Preveja a economia de Liruf", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 80, "prediction": {"kind": "choice", "options": [{"id": "opt-a", "text_md": "96 MXN"}, {"id": "opt-b", "text_md": "88 MXN"}, {"id": "opt-c", "text_md": "90 MXN"}]}}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf guardou **80 MXN** no seu cofrinho. A cada mês, seu dinheiro cresce **10%** (juros simples). Quanto ele terá depois de **2 meses**?", "difficulty": 1, "explanation_md": "Correto! Liruf terá **96 MXN** depois de 2 meses. A cada mês ele ganha 8 MXN (10% de 80), então no total ganha 16 MXN. O dinheiro dele está crescendo!", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 96, "tolerance": 0.01, "correct_option_id": "opt-a"}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "measure-read", "title": "The measuring pitcher: serving equal glasses", "locale": "en-US", "subject": "mixed", "objectives": ["Read the mark on the measuring pitcher to serve equal glasses: each glass exactly up to the line, neither more nor less."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 10, "type": "measure_read", "hints": ["Look at the line where the needle points. Each big line is worth 100 ml."], "title": "The measuring pitcher", "payload": {"max": 1000, "min": 0, "unit": "ml", "ticks": 10, "instrument": "beaker", "pointer_value": 500}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that we know how to balance values, let''s see how to measure equal amounts to share fairly! Liruf has a measuring pitcher with marks every 100 ml. The pitcher goes from 0 ml to 1000 ml. The needle points to 500 ml. How many ml are in the pitcher?", "difficulty": 1, "explanation_md": "Correct! The needle is exactly at the 500 ml mark, which is half of the pitcher.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 500, "tolerance": 0}}', '{"units": {"s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/ba8b68fc9cdf7c5d5b5440a6d75b2904ac6abee82ace1b4dd1bc8e54fe2c4ed1.mp3", "hash": "eeed03bdd3abccc02073004026fddc0970f5626d76e281c7e6e4cfb0d78db63c", "bytes": 88128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ba8b68fc9cdf7c5d5b5440a6d75b2904ac6abee82ace1b4dd1bc8e54fe2c4ed1.mp3", "duration_ms": 14640}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/9a4fa4248b586bc4c4aca8a0dd95e6280a53c66cdfbd9aa9e86ee0d96a0ce4ed.mp3", "hash": "40c15f2eee93de273539dc93780c134991d801119438516fa13a9f6cd70ff4b7", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9a4fa4248b586bc4c4aca8a0dd95e6280a53c66cdfbd9aa9e86ee0d96a0ce4ed.mp3", "duration_ms": 4960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "build-sentence", "title": "Assemble the stand sign", "locale": "en-US", "subject": "mixed", "objectives": ["Order words to form a lemonade sign with price"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-arma-letrero", "xp": 0, "type": "build_sentence", "hints": ["Start with the name of the drink: ''Lemonade''.", "After ''for'' comes the price number."], "title": "Assemble the stand sign", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "Lemonade"}, {"id": "t2", "text_md": "cold"}, {"id": "t3", "text_md": "for"}, {"id": "t4", "text_md": "5"}, {"id": "t5", "text_md": "pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "After restocking lemons and cups with yesterday''s earnings, Liruf is ready to sell today! He needs to put up his sign. The words are scrambled. Put them in the correct order so it reads: **Cold lemonade for 5 pesos**.", "difficulty": 1, "explanation_md": "Excellent! Liruf now has his sign: ''Cold lemonade for 5 pesos''. The 5 is the price per cup.", "audio_segment_id": "s1-arma-letrero.prompt"}], "schema_version": 1}', '{"s1-arma-letrero": {"order": ["t1", "t2", "t3", "t4", "t5"]}}', '{"units": {"s1-arma-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/3170c44015b1cf750489583846252b6f19ebd630c1cf23f75d9d2057e69f01df.mp3", "hash": "fb36f43f97e7c6e69d3a57348e9e45f3bb5eee8624d4ff988666c83c69a52106", "bytes": 69984, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3170c44015b1cf750489583846252b6f19ebd630c1cf23f75d9d2057e69f01df.mp3", "duration_ms": 11600}, "s1-arma-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/2897983e101963ac4f38107465adc8c3b9a4ff716b6042ee45fccccf690875b1.mp3", "hash": "9ec5f744fe1dd7ac7ec562b00053cd0ee63bd8eaced89ea6ed8112414f411534", "bytes": 38304, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2897983e101963ac4f38107465adc8c3b9a4ff716b6042ee45fccccf690875b1.mp3", "duration_ms": 6320}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Find the error in Liruf''s account", "locale": "en-US", "subject": "mixed", "objectives": ["Detect an error in a sales sum", "Read a simple graph of cups sold per day", "Recognize signs of a bad deal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 0, "type": "spot_error", "hints": ["Check each step of the sum. Does any number seem too big?", "If he sold 3 cups at 5 MXN each, the total should be 15, not 20."], "title": "The account that doesn''t add up", "payload": {"steps": [{"id": "step1", "text_md": "He sold 3 cups of lemonade at 5 MXN each."}, {"id": "step2", "text_md": "He wrote: 5 + 5 + 5 = 20"}, {"id": "step3", "text_md": "He wrote the total: 20 MXN"}], "context_md": "Peek into a savings secret: if the bank piggy bank ''thanks'' you with extra coins for waiting, the saved money grows by itself over time. But today Liruf has a problem: when closing his lemonade stand, his account doesn''t add up. Help him find the wrong step."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Help Liruf find the error in his account.", "difficulty": 1, "explanation_md": "Exactly! Liruf added 5 + 5 + 5 and got 20, but 5+5+5 is 15. The error is in step 3, where he wrote 20 instead of 15.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step2"], "correction_md": "El error está en el paso 2: 5 + 5 + 5 = 15, no 20. Liruf debe corregir el total a 15 MXN."}}', '{"units": {"s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/e2f5d7e2c3f8e6269cd19dfd1cb4472d0a7156fbbc62cfcd0ac4d174f7ac38a4.mp3", "hash": "5ec24c935e05c7e82bfd704de7ab661594d28be4f584b9e27bd8d1d0e62f7449", "bytes": 15696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e2f5d7e2c3f8e6269cd19dfd1cb4472d0a7156fbbc62cfcd0ac4d174f7ac38a4.mp3", "duration_ms": 2560}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/af2641a5dd6045a3f28586af138b98bd9a5058756f49c5008e0c8148f4168769.mp3", "hash": "1e7367576d8e96be54f54feb42a6eaea0bf48bbf4ebfadea949b9d80fc2239e5", "bytes": 64656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/af2641a5dd6045a3f28586af138b98bd9a5058756f49c5008e0c8148f4168769.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "equation-builder", "title": "Arma la suma de la tarde", "locale": "es-MX", "subject": "mixed", "objectives": ["Armar con fichas la suma de la tarde: 5 + 5 + 5 = 15 pesos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ecuacion", "xp": 0, "type": "equation_builder", "hints": ["Empieza con el número 5, luego el signo +, otro 5, otro +, y otro 5."], "title": "Arma la suma de la tarde", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}], "target_result": 15}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Ayer contaste los limones que quedaban; hoy usaremos esos limones para vender limonada y sumar lo ganado. Rho te da tarjetas con números y signos (+). Arma tú mismo la suma de la tarde: tres vasos de limonada a 5 pesos cada uno. ¿Cuánto es el total?", "difficulty": 1, "explanation_md": "¡Correcto! 5 + 5 + 5 = 15 pesos, el total de la tarde. Si pusiste otra combinación, revisa que los números y signos estén en orden.", "audio_segment_id": "s1-ecuacion.prompt"}], "schema_version": 1}', '{"s1-ecuacion": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-ecuacion.prompt": {"url": "http://localhost:4006/files/lesson-audio/96b58bb641c8bcd41b05fcac2878d7297fb0c4a75d43c9ebc086eb867c6794fa.mp3", "hash": "1e54b18f6a0e0cf91bf60f8c2d918aa8b2abc921de83cc522bac45a9039539a5", "bytes": 106848, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/96b58bb641c8bcd41b05fcac2878d7297fb0c4a75d43c9ebc086eb867c6794fa.mp3", "duration_ms": 17760}, "s1-ecuacion.explanation": {"url": "http://localhost:4006/files/lesson-audio/5168159423cb071afd6031d430461dc8f0a9936b6d4f0d89c4b8683f3d48e43a.mp3", "hash": "7df5b7c77443bcd7e693aea88ff5d60abf7a2c2c3d58dfed7641d5a0bb530411", "bytes": 74736, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5168159423cb071afd6031d430461dc8f0a9936b6d4f0d89c4b8683f3d48e43a.mp3", "duration_ms": 12400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'es-MX', '1', E'{"meta": {"cast": ["dina", "rho"], "slug": "fact-opinion", "title": "Hechos y opiniones en el puesto de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Separar hechos de opiniones en frases del puesto de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 0, "type": "fact_opinion", "hints": ["Un hecho se puede medir o verificar, como ''el vaso cuesta 5 pesos''. Una opinión expresa un gusto personal."], "title": "Hecho u opinión", "payload": {"statements": [{"id": "s1", "text_md": "El vaso cuesta 5 pesos."}, {"id": "s2", "text_md": "Mi limonada es la más rica del mundo."}, {"id": "s3", "text_md": "Hoy vendí 12 vasos de limonada."}, {"id": "s4", "text_md": "La limonada de Liruf sabe mejor que la de Dina."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Ayer aprendimos que las promesas como \\"te doy 100 pesos mañana\\" suenan sospechosas. Hoy veremos cómo distinguir entre lo que es real (hecho) y lo que es solo una opinión, para no dejarnos engañar. Rho leyó estas frases del día. ¿Cuáles son hechos que se pueden comprobar y cuáles son solo opiniones?", "difficulty": 1, "explanation_md": "¡Muy bien! Las frases que se pueden comprobar son hechos. Por ejemplo, ''el vaso cuesta 5 pesos'' es un hecho porque puedes contar el dinero. Las opiniones son gustos personales, como ''mi limonada es la más rica''.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1", "s3"]}}', '{"units": {"s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/f4d0407cc1b493730cde5a8a68a7b476583c3e5e2c01a99d59ea2a4cc6e2f306.mp3", "hash": "d722acbb3c8112aaf7be9a8d8a7d39082d60f3d4c0005cf8d11b50a9ead21522", "bytes": 127584, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f4d0407cc1b493730cde5a8a68a7b476583c3e5e2c01a99d59ea2a4cc6e2f306.mp3", "duration_ms": 21200}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/f54b8670b1e2c62f592dd9c81982acb3f3e5216dfa84b117699e973cbede9959.mp3", "hash": "af4f9c1554a09d63901c0db1ce1ed4e5cd00e8ef4ea948f3fc8bda264e318ffe", "bytes": 84384, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/f54b8670b1e2c62f592dd9c81982acb3f3e5216dfa84b117699e973cbede9959.mp3", "duration_ms": 14000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "A melhor decisão com o troco", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher a MELHOR decisão quando um cliente paga com nota de 20 por um copo de 5: contar o troco com calma (não adivinhar nem ficar com ele)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 0, "type": "best_decision", "hints": ["O troco correto é 15 MXN. Como você pode ter certeza de que não está errado?"], "title": "O troco da nota de 20", "payload": {"options": [{"id": "a", "text_md": "Contar o troco com calma: 15 MXN, verificando cada moeda.", "rationale_md": "Esta é a melhor decisão porque garante que o troco esteja correto e demonstra honestidade."}, {"id": "b", "text_md": "Adivinhar o troco rápido e dar 10 MXN.", "rationale_md": "Adivinhar pode levar a erros. O troco correto é 15 MXN, não 10. Você pode perder dinheiro ou irritar a cliente."}, {"id": "c", "text_md": "Ficar com a nota e não dar troco.", "rationale_md": "Ficar com a nota é desonesto e pode fazer com que a cliente não volte. Além disso, é importante dar o troco correto."}], "scenario_md": "Uma cliente paga com uma nota de 20 MXN por um copo de limonada que custa 5 MXN. Liruf deve dar o troco. O que ele deve fazer?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf lembra o que aprendeu: detectar o que NÃO é um ingrediente da limonada (limões, açúcar, água… e uma bola?) ajudou a separar o que realmente custa dinheiro produzir. Agora ele tem sua primeira cliente, que paga com uma nota de 20 MXN por um copo de 5 MXN. Qual é a MELHOR decisão?", "difficulty": 1, "explanation_md": "Exato! Liruf contou 15 MXN com calma, certificando-se de dar o troco correto. Assim, evitou erros e foi honesto.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"a": 1, "b": 0, "c": 0}}}', '{"units": {"s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/f5455628624d3325c798d6af8ef3eabb6c067f573ee1fba3cc0f7f9eb547d92b.mp3", "hash": "26f59ee407ef3ad0a41e4c22cf5016f3b676099fd073ba1a5ab0319e720bf588", "bytes": 129888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f5455628624d3325c798d6af8ef3eabb6c067f573ee1fba3cc0f7f9eb547d92b.mp3", "duration_ms": 21600}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/4b92d7b0d7b7c56e7fe74c824da2985917524eaf804dc23937f54136814c68a8.mp3", "hash": "2dd2160f346f24b4a118e8bb01e7b14bb89be40d3127bb01a4c09f40ae944f68", "bytes": 57888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4b92d7b0d7b7c56e7fe74c824da2985917524eaf804dc23937f54136814c68a8.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "number-line", "title": "La recta numérica del ahorro", "locale": "es-MX", "subject": "mixed", "objectives": ["Ubicar en la recta numérica del 0 al 100 dónde va el ahorro de Liruf (20 pesos) y dónde la meta (80): ver cuánto falta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 0, "type": "number_line", "hints": ["El 20 está más cerca del 0 que del 100. Busca entre el 10 y el 30.", "Cuenta de 10 en 10 desde el 0: 10, 20, 30... ¡ahí está!"], "title": "La recta numérica del ahorro", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": true}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Agrupar el dinero de la caja: monedas con monedas y billetes con billetes, para contarlo más fácil. Ahora, Rho dibuja una recta gigante con gis: ''marca dónde vas y a dónde quieres llegar''. Liruf tiene ahorrados 20 pesos y su meta son 80 pesos. ¿Dónde está el 20 y dónde el 80 en la recta del 0 al 100? Arrastra el marcador al 20.", "difficulty": 1, "explanation_md": "¡Muy bien! El 20 está a la izquierda, cerca del 0, y el 80 está más a la derecha. Faltan 60 pesos para llegar a la meta de Liruf.", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/15590ffd45ba997e8c541d6a8fd52bc1c2a052f70759f8e9d1f0fb9b7b1099b6.mp3", "hash": "3d744fa2766b93dd04740d10133a00542aa8aa1ea2a8cf0c307eeb56b5709cfb", "bytes": 149184, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/15590ffd45ba997e8c541d6a8fd52bc1c2a052f70759f8e9d1f0fb9b7b1099b6.mp3", "duration_ms": 24800}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/5be00616e53500ba60352a5299c10d96acd6d8e4f59b28490cad285d6c3f8469.mp3", "hash": "ced6b0fcc6ba575b5efedffc81485754978fcc7c0dd10cfc2489972df9bdc1b6", "bytes": 67968, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5be00616e53500ba60352a5299c10d96acd6d8e4f59b28490cad285d6c3f8469.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "match-pairs", "title": "Match the correct prices", "locale": "en-US", "subject": "mixed", "objectives": ["Order steps, match products with prices, and classify purchases between needs for the stand and wants that can wait."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 5, "type": "match_pairs", "hints": ["Remember: the small cup costs 5 pesos, the pitcher costs 20, and the cookie costs 3."], "title": "Match the prices", "payload": {"left": [{"id": "cup", "text_md": "Small cup of lemonade"}, {"id": "pitcher", "text_md": "Pitcher of lemonade"}, {"id": "cookie", "text_md": "Cookie"}], "right": [{"id": "price5", "text_md": "5 pesos"}, {"id": "price20", "text_md": "20 pesos"}, {"id": "price3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Yesterday you sold three cups for 5 pesos each, and you added up 15 pesos! Today, Liruf needs to match the prices correctly to keep selling. The wind blew the price tags off. Help Liruf match each product with its correct price.", "difficulty": 1, "explanation_md": "Great job! The small cup costs 5 pesos, the pitcher 20, and the cookie 3. Now Liruf can sell without confusion.", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["cup", "price5"], ["pitcher", "price20"], ["cookie", "price3"]]}}', '{"units": {"s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/4a481de690270ae8b6995c26f190033b4526cb1c93611ec86de44394fcbc5129.mp3", "hash": "19172b2b49f3e12341469c0a38695067c2e57e957bd4285cf58eade74f3cbece", "bytes": 74736, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4a481de690270ae8b6995c26f190033b4526cb1c93611ec86de44394fcbc5129.mp3", "duration_ms": 12400}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/ebb897860f2cc96dc8a32a93befc4ebf0492183cc5cecd6dbbd45cce15e371db.mp3", "hash": "756f616b0e6072bc4746f2b40ef60687aef0e62a6aeb0cdf5516fbebba4f50f2", "bytes": 42624, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ebb897860f2cc96dc8a32a93befc4ebf0492183cc5cecd6dbbd45cce15e371db.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "repaso-true-false", "title": "Review: True or False?", "locale": "en-US", "subject": "mixed", "objectives": ["Answer from memory: if saving 20 pesos per week, the 80-peso guitar arrives in one month."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Remember: the guitar costs 80 pesos and you save 20 each week.", "A month has about 4 weeks. How much do you save in 4 weeks?"], "title": "True or False?", "payload": {"statement_md": "If you save 20 pesos each week, in one month you''ll have the 80 pesos for the guitar.", "justifications": [{"id": "j1", "text_md": "20 pesos per week × 4 weeks = 80 pesos."}, {"id": "j2", "text_md": "20 pesos per week × 3 weeks = 60 pesos, not enough."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Just like we calculated the profit per glass last time, today we''ll calculate if Rho can buy the guitar. Rho says the last phrase of the course. Is it true or false?", "difficulty": 2, "explanation_md": "Exactly! 20 pesos per week × 4 weeks = 80 pesos, just what the guitar costs. The phrase is true.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j1"}}', '{"units": {"s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/04693d07b30261301db6fb88bef42b7f263ceaff6d6bdf8e61d407cbeca099c7.mp3", "hash": "7cd1117f234c65db16fa07d883664b892dcc3e402212f5d21843402797da1394", "bytes": 76608, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/04693d07b30261301db6fb88bef42b7f263ceaff6d6bdf8e61d407cbeca099c7.mp3", "duration_ms": 12720}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/53deccdfb68b5def9918eb3a750dfbeb92b3008b2bfcb3eda5336a6218bdaafb.mp3", "hash": "060817ba1ee8e5e82b24aeb2d23e49520357223d60aad7fec3d0d79dc85a88dc", "bytes": 55008, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/53deccdfb68b5def9918eb3a750dfbeb92b3008b2bfcb3eda5336a6218bdaafb.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "repaso-true-false", "title": "Revisão: Certo ou errado?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Responder de memória se guardando 20 reais por semana o violão de 80 chega em um mês."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Lembre-se: o violão custa 80 reais e você economiza 20 a cada semana.", "Um mês tem aproximadamente 4 semanas. Quanto você economiza em 4 semanas?"], "title": "Certo ou errado?", "payload": {"statement_md": "Se você guardar 20 reais a cada semana, em um mês terá os 80 reais para o violão.", "justifications": [{"id": "j1", "text_md": "20 reais por semana × 4 semanas = 80 reais."}, {"id": "j2", "text_md": "20 reais por semana × 3 semanas = 60 reais, não é suficiente."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Assim como calculamos o lucro por copo da última vez, hoje calcularemos se Rho pode comprar o violão. Rho diz a última frase do curso. É certa ou errada?", "difficulty": 2, "explanation_md": "Exato! 20 reais por semana × 4 semanas = 80 reais, exatamente o que custa o violão. A frase é certa.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j1"}}', '{"units": {"s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/41b98cd5a12815230ff93a7c1cdc53d881b805c5985fcae50e82f696a6314792.mp3", "hash": "ef7a14d2990a8752dd6b0bfe8d45c7f082411c5f3fe9b3bf7193e40ccab939bd", "bytes": 71424, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/41b98cd5a12815230ff93a7c1cdc53d881b805c5985fcae50e82f696a6314792.mp3", "duration_ms": 11840}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/98912b12be3db53a65d3a255f5ca64bae1478c82f557554be36e3b7fef341abf.mp3", "hash": "c3311d217fee73f2a663358183afec795f6d2bd43911f23de2521b30ff8e5999", "bytes": 62208, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/98912b12be3db53a65d3a255f5ca64bae1478c82f557554be36e3b7fef341abf.mp3", "duration_ms": 10320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "speed-tap", "title": "Pegue as moedas!", "locale": "pt-BR", "subject": "mixed", "objectives": ["Reconhecer moedas rapidamente entre outros objetos.", "Praticar a tomada rápida de decisões sobre o que é dinheiro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 0, "type": "speed_tap", "hints": ["As moedas do Brasil são de 1, 5, 10, 25 e 50 centavos, e de 1 real. Procure esses números!", "Se tem forma redonda e diz ''BRL'' ou o número, é moeda."], "title": "Pegue as moedas!", "payload": {"items": [{"id": "moneda1", "text_md": "Moeda de 1 centavo"}, {"id": "boton1", "text_md": "Botão vermelho"}, {"id": "moneda2", "text_md": "Moeda de 5 centavos"}, {"id": "tapa1", "text_md": "Tampinha de suco"}, {"id": "moneda5", "text_md": "Moeda de 10 centavos"}, {"id": "moneda10", "text_md": "Moeda de 25 centavos"}, {"id": "boton2", "text_md": "Botão azul"}, {"id": "moneda20", "text_md": "Moeda de 1 real"}, {"id": "tapa2", "text_md": "Tampinha de suco"}], "seconds": 10, "instruction_md": "Toque apenas nas MOEDAS. Ignore botões e tampinhas de suco!"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembre-se de que ontem você decidiu quais gastos ajudam sua barraca. Hoje, você precisa de moedas reais para comprar esses limões. Dina e Liruf estão contando as moedas que têm. Você pode ajudar Liruf a encontrar apenas as moedas entre esses objetos?", "difficulty": 1, "explanation_md": "Bom! Você pegou moedas de 1, 5, 10, 25 e 50 centavos, e de 1 real. Liruf precisa delas para sua barraca. As tampinhas de suco não são dinheiro, então não toque nelas. Se tocou em uma tampinha, lembre-se: só as moedas servem para comprar limões.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["moneda1", "moneda2", "moneda5", "moneda10", "moneda20"]}}', '{"units": {"s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/772dbc06f2ebb5d78e35972d4d5a5c81accbfeeea1a0726b98047d9691151ee2.mp3", "hash": "1e0d3354ad436a9202bf2b1440258c26c321b0dbe63a989a5636ef8767135963", "bytes": 100656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/772dbc06f2ebb5d78e35972d4d5a5c81accbfeeea1a0726b98047d9691151ee2.mp3", "duration_ms": 16720}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/d6170efde0972071f59ecb45a9ffe379087511f2661bb3dfee481faf4d0485e0.mp3", "hash": "20e5c79b98fff816031434779c8e467626136ae3860a84b7ad6bb1eff2c6f3a6", "bytes": 114048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d6170efde0972071f59ecb45a9ffe379087511f2661bb3dfee481faf4d0485e0.mp3", "duration_ms": 18960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "lightning-round", "title": "Stand Lightning Round", "locale": "en-US", "subject": "mixed", "objectives": ["Make decisions within stand stories and see their immediate consequences on sales and savings."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning-round", "xp": 0, "type": "lightning_round", "hints": ["Remember that each cup costs 5 MXN. If a customer asks for 3 cups, that''s 3 × 5 = 15 MXN.", "For change, subtract the total from the bill they give you."], "title": "Accounts on the Fly!", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 MXN"}, {"id": "b", "text_md": "5 MXN"}, {"id": "c", "text_md": "15 MXN"}], "prompt_md": "Customer 1: ''Give me 2 cups of lemonade!'' Pays with a 20 MXN bill. How much change do you give?"}, {"id": "q2", "options": [{"id": "a", "text_md": "20 MXN"}, {"id": "b", "text_md": "30 MXN"}, {"id": "c", "text_md": "10 MXN"}], "prompt_md": "Customer 2: ''I want 4 cups!'' Pays with 50 MXN. How much change do you give?"}, {"id": "q3", "options": [{"id": "a", "text_md": "5 MXN"}, {"id": "b", "text_md": "0 MXN"}, {"id": "c", "text_md": "2 MXN"}], "prompt_md": "Customer 3: ''I need 1 cup!'' Pays with 10 MXN. How much change do you give?"}], "seconds_per_q": 15}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Quickly match each stand word with its example (savings→piggy bank, cost→lemons, profit→what''s left)! Now, during rush hour, customers arrive in a line. Help Liruf add up lemonade cups and give simple change. Against the clock!", "difficulty": 1, "explanation_md": "Excellent! Liruf was able to serve everyone thanks to your quick math. Each cup is 5 MXN, and with that you added up and gave change.", "audio_segment_id": "s1-lightning-round.prompt"}], "schema_version": 1}', '{"s1-lightning-round": {"correct": {"q1": "a", "q2": "b", "q3": "a"}}}', '{"units": {"s1-lightning-round.prompt": {"url": "http://localhost:4006/files/lesson-audio/895e698915f759734c659d5b9402cd6c2dc78af6f152808f07dab1df34e56290.mp3", "hash": "fa846c8a389b1df3c059beccfab6e34249a232fa29c5cfd58a34416db07c2e48", "bytes": 76608, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/895e698915f759734c659d5b9402cd6c2dc78af6f152808f07dab1df34e56290.mp3", "duration_ms": 12720}, "s1-lightning-round.explanation": {"url": "http://localhost:4006/files/lesson-audio/4902d58e7d99839b6b868b14dfc2c9ff8ccefe9a5d8a09d5d65d22f5cfa7582d.mp3", "hash": "b20f3dc02ecbbe54c08b4ef04ad92c41c838b727fd88b2f2083a42e052a60277", "bytes": 48384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4902d58e7d99839b6b868b14dfc2c9ff8ccefe9a5d8a09d5d65d22f5cfa7582d.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dinero", "title": "Money Combo: Cash Register Close", "locale": "en-US", "subject": "mixed", "objectives": ["Count coins to close the day''s cash register.", "Calculate the correct change when receiving a 20 MXN bill.", "Determine how many weeks are needed to save 80 MXN for the guitar."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 10, "type": "coin_count", "hints": ["First add the largest coins: 10+10=20, then 20+5=25, then 25+2+2=29, then 29+1+1+1=32."], "title": "Close the cash register", "payload": {"target": 32, "currency": "MXN", "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember yesterday you heard two customers talk about lemonade and answered true/false questions with pictures. Today we use what you learned to close the register! Liruf says: **''Time to close the register! Count all the coins we have today.''** In the register there are: 3 coins of 1 MXN, 2 coins of 2 MXN, 1 coin of 5 MXN, and 2 coins of 10 MXN. How much money is there in total?", "difficulty": 1, "explanation_md": "Correct! You added 10+10+5+2+2+1+1+1 = **32 MXN**. Great counting, just like Liruf! Reflect: how did yesterday help you count today?", "audio_segment_id": "s1-coin-count.prompt"}, {"id": "s2-make-change", "xp": 10, "type": "make_change", "hints": ["Subtract the price from what they paid: 20 - 5 = ?"], "title": "Give change from 20", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10, 20]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "A customer buys a glass of lemonade for **5 MXN** and pays with a **20 MXN** bill. Rho asks: **''How much change should Dina give?''**", "difficulty": 1, "explanation_md": "Very good! 20 - 5 = **15 MXN** change. Rho congratulates you. Think: what would happen if they paid with 10 MXN?", "audio_segment_id": "s2-make-change.prompt"}, {"id": "s3-savings-goal", "xp": 10, "type": "savings_goal", "hints": ["Divide the goal by what you save each week: 80 ÷ 20 = ?"], "title": "Weeks for the guitar", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina wants to save **80 MXN** for a guitar. Zara says: **''If you save 20 MXN from your earnings each week, how many weeks do you need?''**", "difficulty": 1, "explanation_md": "Exactly! 80 ÷ 20 = **4 weeks**. Zara will be proud! Reflect: what if you saved 10 MXN per week?", "audio_segment_id": "s3-savings-goal.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}, "s2-make-change": {}, "s3-savings-goal": {"correct": {"20": 4}}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/85eeefa9bb6c6a482d10cd03cd1f0df242edaaeb52df148223f9d107ba5da0d8.mp3", "hash": "14b5e11728255fad4949044f8a23e43b19dea6d8530d7e97153c96b8a5e63e4e", "bytes": 128016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/85eeefa9bb6c6a482d10cd03cd1f0df242edaaeb52df148223f9d107ba5da0d8.mp3", "duration_ms": 21280}, "s2-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/b95adca6268316c02f1e145a741bdf8b245ecc932fbe83ffc606f37e6469650e.mp3", "hash": "c4c03d99e6c8c0d6fdc4fc40af64303c3e00733cd9a2bc637718efc00363f24a", "bytes": 45504, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b95adca6268316c02f1e145a741bdf8b245ecc932fbe83ffc606f37e6469650e.mp3", "duration_ms": 7520}, "s3-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/bf4ac61863daa5aa4a5e562a2dc59aead1bd4a17b7c19f674a8e5a6c6baf1dce.mp3", "hash": "6f1e7f5da9e13681ab1a51d4ba676249b92e93c7ad4b1a8461d75d5c0dc8afea", "bytes": 45504, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bf4ac61863daa5aa4a5e562a2dc59aead1bd4a17b7c19f674a8e5a6c6baf1dce.mp3", "duration_ms": 7520}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/86ce12654a48c4972b3d99b0a70965f917919c117bff92ed136b1fc31231cb78.mp3", "hash": "1a84a03dd99ca053188714533b4ad0f12103fabce4790bc734ecfd3c213bba10", "bytes": 75168, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/86ce12654a48c4972b3d99b0a70965f917919c117bff92ed136b1fc31231cb78.mp3", "duration_ms": 12480}, "s2-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/f80f63bdcb936dd796c0cb3f4e0be35684967acb3961a2a2d40fd9916d77e9d4.mp3", "hash": "fb35c61f8f2d859a292eb4816d83800d515fbad4a7659af28ca440af2eeaf63b", "bytes": 53136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f80f63bdcb936dd796c0cb3f4e0be35684967acb3961a2a2d40fd9916d77e9d4.mp3", "duration_ms": 8800}, "s3-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/6e0de32c55c15ca49977bc8a569156459ef76dd322068da4a6e888a24e1a2adb.mp3", "hash": "20e4ab64264c62f40b22f467f6cc2c58ea6cf710065138f87f1cc5502cb2d487", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6e0de32c55c15ca49977bc8a569156459ef76dd322068da4a6e888a24e1a2adb.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Check the story_dialogue exercise", "locale": "en-US", "subject": "economics", "objectives": ["Introduce the concept of needs vs. wants through a concrete dialogue"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-story-dialogue", "xp": 0, "type": "story_dialogue", "hints": ["Remember that a need is something we need to live, like food."], "title": "Isolated practice of the story_dialogue type", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "Look, Liruf! I have 10 coins. We can buy an apple to eat.", "character": "dina"}, {"action": "idle", "emotion": "excited", "text_md": "I want a toy! It''s more fun.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina and Liruf are deciding what to buy with 10 coins. Dina wants to buy an apple (need) and Liruf wants a toy (want). Who chooses the need?", "difficulty": 1, "explanation_md": "Correct! Dina chooses the apple, which is a need, because we need to eat to live. Liruf wants a toy, which is a want.", "audio_segment_id": "s1-story-dialogue.prompt"}], "schema_version": 1}', '{}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "Necesidades y deseos en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Separar necesidades del puesto (limones, hielo) de deseos personales (paleta, cómic): el puesto come primero."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 0, "type": "needs_wants", "hints": ["Piensa: ¿sin esto el puesto puede seguir vendiendo limonada?", "Las necesidades ayudan a que el puesto funcione; los deseos son para ti."], "title": "¿Necesidad o deseo?", "payload": {"items": [{"id": "limones", "icon": "lemon", "text_md": "Limones para la limonada"}, {"id": "hielo", "icon": "ice", "text_md": "Hielo para enfriar los vasos"}, {"id": "paleta", "icon": "lollipop", "text_md": "Paleta de fresa"}, {"id": "comic", "icon": "book", "text_md": "Cómic de superhéroes"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Después de repartir 10 pesos de ganancia entre las dos alcancías — una parte para la meta de la guitarra y otra para reponer ingredientes — Liruf quiere comprar una paleta. Pero Dina le recuerda: **el puesto come primero**. Ayuda a Liruf a separar lo que es **necesidad** del puesto (limones, hielo) de lo que es **deseo** personal (paleta, cómic).", "difficulty": 1, "explanation_md": "¡Muy bien! Los limones y el hielo son necesidades porque sin ellos no hay limonada. La paleta y el cómic son deseos personales. Recuerda: primero el puesto, luego tus gustos.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/4f4502762b8675a3597a748da222dded679da3802fd52e73a1e18794db957653.mp3", "hash": "45547e6742713d94f4112891a710a0f477f2ab1765cc69d36c0eb5af3b050800", "bytes": 132336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4f4502762b8675a3597a748da222dded679da3802fd52e73a1e18794db957653.mp3", "duration_ms": 22000}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/ce27d9e10fe874f9db15c39690f3561cdeac10722f73704704276df1f3e68bfc.mp3", "hash": "1f1b48a337bee5fa3aac76d57a5416701bbe4eae48d972a6d90807ce24f32065", "bytes": 72288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ce27d9e10fe874f9db15c39690f3561cdeac10722f73704704276df1f3e68bfc.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "price-compare", "title": "Comparing lemon prices at the market", "locale": "en-US", "subject": "mixed", "objectives": ["Compare lemon prices at two market stalls and choose the cheapest one to spend less (lower cost = more profit)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 5, "type": "price_compare", "hints": ["Calculate the price per lemon by dividing the total price by the number of lemons."], "title": "Which lemon stall is cheaper?", "payload": {"offers": [{"id": "puesto-a", "qty": 5, "unit": "limones", "label": "Stall A: 5 lemons for $10", "price": 10}, {"id": "puesto-b", "qty": 3, "unit": "limones", "label": "Stall B: 3 lemons for $5", "price": 5}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember, lemons are a necessity for Liruf''s stall, not a personal want. Now let''s buy them at the best price.\\n\\nDina and Liruf are at the market. Two vendors shout their lemon offers. Liruf says: \\"I need the cheapest lemons for my lemonade!\\" Help Dina choose the cheapest stall so Liruf spends less and earns more at his lemonade stand.\\n\\n**Stall A:** 5 lemons for $10 MXN\\n**Stall B:** 3 lemons for $5 MXN\\n\\nWhich stall has the lowest price per lemon?", "difficulty": 1, "explanation_md": "Correct! Stall B costs $5 ÷ 3 ≈ $1.67 per lemon, while Stall A costs $10 ÷ 5 = $2 per lemon. Stall B is cheaper!", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-b"}}', '{"units": {"s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/2bb0f4c620d510421457e30f2b80367ab1abbdfae3bf19078772a3b4e02b159a.mp3", "hash": "ee418b3e6887313261c23eb72d995b388cc0b0eac2e88ad2883013529ee836ce", "bytes": 149616, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2bb0f4c620d510421457e30f2b80367ab1abbdfae3bf19078772a3b4e02b159a.mp3", "duration_ms": 24880}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/aa77f6bee04697c70fe43719d3c3e3204da0ecf46c668e3fb73af426b054f6a4.mp3", "hash": "7f8b828e23863a33af7bc836be70cccf00f2990137785a203f474816c4c0f6cb", "bytes": 60768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/aa77f6bee04697c70fe43719d3c3e3204da0ecf46c668e3fb73af426b054f6a4.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "key-ideas", "title": "The three golden rules of the little seller", "locale": "en-US", "subject": "mixed", "objectives": ["Set the 3 key ideas of the plan: have a goal (80 pesos), offer something people want (cold lemonade), and save what you earn."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": ["Remember that Liruf''s goal is the 80-peso guitar.", "Think about what Liruf offers to his neighbors."], "title": "The three golden rules", "payload": {"ideas": [{"icon": "target", "title": "Have a goal", "body_md": "Liruf wants a guitar for **80 pesos**. That''s his goal."}, {"icon": "lemonade", "title": "Offer something people want", "body_md": "Sell **cold lemonade** for 5 pesos a cup. Everyone loves it!"}, {"icon": "piggy_bank", "title": "Save what you earn", "body_md": "Every peso you earn, save it for your goal."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Hi! Yesterday we saw that Liruf wants to save 80 pesos by selling cups of lemonade for 5 pesos to buy his guitar. Today, Rho summarizes the three key rules of that plan. Rho draws the three golden rules of the little seller on his board. Help complete them. How many cups must Liruf sell?", "difficulty": 1, "explanation_md": "Exactly! Rho wrote the three key ideas: have a goal of 80 pesos, offer cold lemonade that people want, and save what you earn.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/9551f9885333ce37cd63186814a570096f88a717ba01f025d6482f9004b2c759.mp3", "hash": "5981e8710258f91486d9ff97f8f348290ad4d712db01a534b378f2aab6862319", "bytes": 26208, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/9551f9885333ce37cd63186814a570096f88a717ba01f025d6482f9004b2c759.mp3", "duration_ms": 4320}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/c360433638e8423126ffff6ef69fe0df555c5d5d7f4a75ba4d8353c71dcc5e2c.mp3", "hash": "6708a086457b9842d3a00c06eca62fc6dc80eb5a104bbbca658aa8711a234748", "bytes": 30096, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/c360433638e8423126ffff6ef69fe0df555c5d5d7f4a75ba4d8353c71dcc5e2c.mp3", "duration_ms": 4960}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/dbe8a7803929b4b08283977d53f5d9311cd871f5cee1520fb763b6e6cb5798bf.mp3", "hash": "618949d1973eacaef250e62d5dc529b4cd17e39146193d3d8bfe6ed99773322e", "bytes": 20448, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/dbe8a7803929b4b08283977d53f5d9311cd871f5cee1520fb763b6e6cb5798bf.mp3", "duration_ms": 3360}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/48ec988fcd17fe33d5899ba7439a7f207555d20131ba97cb4cc4956e7f95254e.mp3", "hash": "739833e0e87fdc032bbe2ff81ae86fb1e132426c62c80d74bef7af0a6fe7d9af", "bytes": 134208, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/48ec988fcd17fe33d5899ba7439a7f207555d20131ba97cb4cc4956e7f95254e.mp3", "duration_ms": 22320}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/cfb24f0f1aa3df50ea7e881aa1e609e30a1963d2c466affd1fde53514ecc50c3.mp3", "hash": "97573fe80b7aea849db18b6839a1d1e98f8087c07a2aa4b5f18c5b86d046ab7d", "bytes": 64656, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/cfb24f0f1aa3df50ea7e881aa1e609e30a1963d2c466affd1fde53514ecc50c3.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "Respirar y repasar antes de abrir el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "Respirar y repasar antes de abrir el puesto", "payload": {"recap_md": "Como descubriste al voltear las tarjetas, ya tienes **meta** (80 pesos), **producto** (limonada a 5 pesos) y sabes qué es **costo** y **ganancia**. Por ejemplo, si gastas 20 pesos en limones y vendes 10 vasos a 5 pesos, tu ganancia es 30 pesos.", "mood_prompt_md": "¿Cómo te sientes para abrir el puesto? Elige una opción:"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina te pregunta: **Liruf**, ¿cómo te sientes antes del gran día de apertura?", "difficulty": 1, "explanation_md": "¡Bien! Recuerda que tu meta es la guitarra de 80 pesos y tu limonada cuesta 5 pesos.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/08c4da05450053c5cdaa38cb54ad0010ec3639ec600090b9cd56451b431ff886.mp3", "hash": "ad40d60aa6616bff09f15aca990de91b9e6acdfbbedf96aa5e5f3d9c33733fe4", "bytes": 101664, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/08c4da05450053c5cdaa38cb54ad0010ec3639ec600090b9cd56451b431ff886.mp3", "duration_ms": 16880}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/d57eeccd4581911d663b02d56df1cee9d4ec719404fc5064f74685bbc65af0e6.mp3", "hash": "09c5b36d03c651fb85906913630aa58ccd3a0959b53814e3e7f5ce9d8e521bee", "bytes": 32976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d57eeccd4581911d663b02d56df1cee9d4ec719404fc5064f74685bbc65af0e6.mp3", "duration_ms": 5440}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/2a844e4e3a849d2f2c6d2e4063bff9c33a2a772fe689e8e4c61c012b97561964.mp3", "hash": "76b99796ccf2e3cef19956b8893d746122131eec6c8c7a662968d05f028d45ae", "bytes": 42048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2a844e4e3a849d2f2c6d2e4063bff9c33a2a772fe689e8e4c61c012b97561964.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "evidence-hunt", "title": "La búsqueda de la evidencia", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar un error en una suma de ventas", "Leer una gráfica simple de vasos vendidos por día", "Reconocer señales de un mal trato"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 0, "type": "evidence_hunt", "hints": ["Busca en el recibo la línea que dice ''limones''.", "El precio está después del nombre del producto."], "title": "La búsqueda de la evidencia", "payload": {"claim_md": "Los limones costaron **15 MXN**.", "sentences": [{"id": "s1", "text_md": "Limones: 15 MXN"}, {"id": "s2", "text_md": "Azúcar: 10 MXN"}, {"id": "s3", "text_md": "Vasos: 8 MXN"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "La semana pasada vimos que el sábado fue el mejor día porque vendieron más vasos. Hoy, Dina revisa los gastos para ver cuánto ganaron realmente. Dina encontró el recibo del mercado. Ayúdala a encontrar cuánto costaron los limones.", "difficulty": 1, "explanation_md": "¡Correcto! El recibo muestra que los limones costaron 15 MXN, justo como lo viste.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{"units": {"s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/e90484a700a63e52bba0ad2567d7857128da0a83795b0af48896b4da5aec61db.mp3", "hash": "9f283ee7449fddd734067edc74015ab978d4e372d4e898a24e75a447f27819eb", "bytes": 100656, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e90484a700a63e52bba0ad2567d7857128da0a83795b0af48896b4da5aec61db.mp3", "duration_ms": 16720}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/17650c9ac1272e8fa3f9166276e05c4f2c0606384dfb7086ac325c693f1b840a.mp3", "hash": "d4f9b810b646c5c12d3c3d491d6d13b3a7b0c87f208569dbde4111e4ca6ea46a", "bytes": 35424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/17650c9ac1272e8fa3f9166276e05c4f2c0606384dfb7086ac325c693f1b840a.mp3", "duration_ms": 5840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "La registradora de cartón de Rho", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar las instrucciones de la registradora casera: recibir pago, verificar monto, dar cambio, anotar la venta."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 0, "type": "code_order", "hints": ["Piensa: primero recibes el pago, luego verificas que sea correcto, después das el cambio y al final anotas la venta."], "title": "Ordena los pasos de la registradora", "payload": {"blocks": [{"id": "b1", "text_md": "Recibir pago"}, {"id": "b2", "text_md": "Verificar monto"}, {"id": "b3", "text_md": "Dar cambio"}, {"id": "b4", "text_md": "Anotar la venta"}], "language_hint": "es-MX"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que sabes que vender implica decisiones, veamos cómo Rho organiza su registradora para manejar esas ventas. Rho quiere evitar errores como los de la semana pasada cuando olvidó dar cambio. Por eso inventó una registradora de cartón que sigue instrucciones paso a paso. Recuerda cuando elegiste entre recibir 10 pesos hoy o esperar para ganar 20 la próxima semana. Ahora que Rho ya decidió vender, necesita organizar cómo manejar esos pagos. Ayuda a Rho a ordenar las instrucciones para que la registradora funcione bien. ¡Vamos, tú puedes!", "difficulty": 1, "explanation_md": "¡Excelente! El orden correcto es: recibir pago, verificar monto, dar cambio y anotar la venta. Así la registradora de Rho puede funcionar sin errores. Si te equivocaste, no te preocupes: la próxima vez recuerda que primero se recibe el dinero, luego se revisa, después se da el cambio y por último se anota.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["b1", "b2", "b3", "b4"]}}', '{"units": {"s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/487be02541e74c3cf68d0d32ef5396736863df21deb64d0ef4678d9e736c221a.mp3", "hash": "1900cb03e22e9ba297f1709a1086c3e10aa57a886d3e128a00c73578d7f05601", "bytes": 189504, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/487be02541e74c3cf68d0d32ef5396736863df21deb64d0ef4678d9e736c221a.mp3", "duration_ms": 31520}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/f761471868e8afbdb1b2c7ba8f99dd5fffc79f53b5357d7c4e576116adeede85.mp3", "hash": "889dc3d7a3305ba9fa836243ae9b456676134cf0d0d25dbd3705c6ed83e5b8e6", "bytes": 124128, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f761471868e8afbdb1b2c7ba8f99dd5fffc79f53b5357d7c4e576116adeede85.mp3", "duration_ms": 20640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "balance-scale", "title": "Equilibrando la balanza", "locale": "es-MX", "subject": "mixed", "objectives": ["Resolver problemas de equilibrio usando una balanza de platillos.", "Practicar sumas pequeñas para igualar cantidades."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-scale", "xp": 0, "type": "balance_scale", "hints": ["Prueba con una pesa de 2 y una de 3.", "También puedes usar cinco pesas de 1."], "title": "Equilibrando la balanza", "payload": {"weights": [{"id": "w1", "label": "Pesa de 1", "value": 1}, {"id": "w2", "label": "Pesa de 2", "value": 2}, {"id": "w3", "label": "Pesa de 3", "value": 3}], "left_fixed": [{"label": "Pesa fija", "value": 5}], "unknown_label": "Pesa desconocida"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina y Liruf están jugando con una balanza de verdad. En el platillo izquierdo hay una pesa de 5. En la mesa hay pesas de 1, 2 y 3. Ayuda a Liruf a poner pesas en el platillo derecho para que la balanza quede equilibrada. ¿Qué pesas eliges?", "difficulty": 1, "explanation_md": "¡Muy bien! Para que la balanza esté equilibrada, los dos platillos deben tener el mismo peso. 5 es igual a 2+3, o también 1+1+1+1+1. ¡Lo lograste!", "audio_segment_id": "s1-balance-scale.prompt"}], "schema_version": 1}', '{"s1-balance-scale": {}}', '{"units": {"s1-balance-scale.prompt": {"url": "http://localhost:4006/files/lesson-audio/24320ea2ba30c735fb11cea6ea331dad21f069e955500218cd22fb094ada83d2.mp3", "hash": "102ca8fb9eadbcc164c94c7907191a02c962d549c66c923a0cf485e1e2df9766", "bytes": 103104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/24320ea2ba30c735fb11cea6ea331dad21f069e955500218cd22fb094ada83d2.mp3", "duration_ms": 17120}, "s1-balance-scale.explanation": {"url": "http://localhost:4006/files/lesson-audio/53b30799b92bef1c5f305c11ddaf53de5db2e30d4db8e7f291fcb9edae4fd20d.mp3", "hash": "b51802f996e505758c5c773baa1a87e09cf883b50a76c434d3131b00449c5c1f", "bytes": 72288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/53b30799b92bef1c5f305c11ddaf53de5db2e30d4db8e7f291fcb9edae4fd20d.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "read-chart", "title": "The weekly sales chart", "locale": "en-US", "subject": "mixed", "objectives": ["Read the bar chart of cups sold per day and answer which was the best day of the week."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 10, "type": "read_chart", "hints": ["The best day is the one with the tallest bar.", "Count the little squares in each bar to compare."], "title": "The weekly sales chart", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Cups sold", "points": [{"x": "Monday", "y": 3}, {"x": "Tuesday", "y": 5}, {"x": "Wednesday", "y": 4}, {"x": "Thursday", "y": 6}, {"x": "Friday", "y": 8}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Monday"}, {"id": "martes", "text_md": "Tuesday"}, {"id": "miercoles", "text_md": "Wednesday"}, {"id": "jueves", "text_md": "Thursday"}, {"id": "viernes", "text_md": "Friday"}], "prompt_md": "Which was the best day of the week?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "After choosing the best lemon supplier last week, Zara has prepared her lemonade and is now checking her sales! Zara drew a bar chart with the cups of lemonade she sold each day of the week. Look at the chart and answer: which was the best day of the week?", "difficulty": 1, "explanation_md": "Correct! On Friday, 8 cups were sold, more than any other day. Zara was very busy!", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "viernes"}}}', '{"units": {"s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/9d365c91e49245b8df374c5332db50d67be14a7d331272739b45f7325504ceba.mp3", "hash": "591c3018fd4987c4f3f77d0299b7c971cd027b8a503a8b8bc8c5a43feeec5a05", "bytes": 74736, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9d365c91e49245b8df374c5332db50d67be14a7d331272739b45f7325504ceba.mp3", "duration_ms": 12400}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/8cab14f6624f5a2e3bf1edee9a0a1cb59b536c21dff041e36f138a558f0c0291.mp3", "hash": "09517452ef25fb0beeb92dca5724abc3b8226452354b3d0c0ec976b4af10946e", "bytes": 31536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8cab14f6624f5a2e3bf1edee9a0a1cb59b536c21dff041e36f138a558f0c0291.mp3", "duration_ms": 5200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Dialogue combination and two questions", "locale": "en-US", "subject": "mixed", "objectives": ["Verify that the player advances correctly between different types within the same lesson"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Liruf and his friend", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "Hi Rho! Did you know that in Mexico there are coins of 1, 2, 5, 10, and 20 pesos?", "character": "liruf"}, {"action": "idle", "emotion": "surprised", "text_md": "Really? How interesting! So I can pay for an 8-peso candy with a 10-peso coin and get change.", "character": "rho"}, {"action": "idle", "emotion": "encouraging", "text_md": "Exactly! And if you put two 5-peso coins together, you have 10 pesos.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "As you learned in the previous lesson about coins, today we will keep practicing. Liruf is talking with his friend Rho about Mexican coins. Listen carefully.", "difficulty": 1, "explanation_md": "This dialogue will help you remember the coins used in Mexico.", "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-truefalse", "xp": 10, "type": "true_false", "hints": ["Remember what Rho said about the 8-peso candy."], "title": "True or false?", "payload": {"statement_md": "Rho can pay for an 8-peso candy with a 10-peso coin and receive 2 pesos in change.", "justifications": [{"id": "j1", "text_md": "Yes, because 10 - 8 = 2, and 10-peso coins exist."}, {"id": "j2", "text_md": "No, because there are no 10-peso coins."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Based on what Liruf and Rho said, choose whether the statement is true or false. Before answering, ask yourself: how much is 10 minus 8?", "difficulty": 1, "explanation_md": "Rho said that with a 10-peso coin he can pay for an 8-peso candy and receive change, so the statement is true.", "audio_segment_id": "s2-truefalse.prompt"}, {"id": "s3-picturechoice", "xp": 10, "type": "picture_choice", "hints": ["Look for the image that has two identical coins that add up to 10."], "title": "Choose the correct combination", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "Two 5-peso coins", "image_url": "https://example.com/moneda5.png", "rationale_md": "Correct. Two 5-peso coins add up to 10 pesos."}, {"id": "opt2", "icon": "coin", "label": "One 10-peso coin", "image_url": "https://example.com/moneda10.png", "rationale_md": "Incorrect. Even though it''s worth 10, it''s not two 5-peso coins."}, {"id": "opt3", "icon": "coin", "label": "Five 2-peso coins", "image_url": "https://example.com/moneda2.png", "rationale_md": "Incorrect. Five 2-peso coins add up to 10, but they are not two 5-peso coins."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf said that putting two 5-peso coins together gives you 10 pesos. Which of the following images shows that combination? Think: how many 5-peso coins do you need to have 10?", "difficulty": 1, "explanation_md": "Two 5-peso coins add up to 10 pesos, so the image with two 5-peso coins is correct.", "audio_segment_id": "s3-picturechoice.prompt"}], "schema_version": 1}', '{"s2-truefalse": {"is_true": true, "correct_justification_id": "j1"}, "s3-picturechoice": {"correct_option_id": "opt1"}}', '{"units": {"s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/0777829e21817671e602eef80c2e7580484f58cf111957bcb6e848affcaa5976.mp3", "hash": "a86e0799d08e43c80d31b72ce9fc607d69b3dd773cc65bdceedc4779da13ff53", "bytes": 41616, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/0777829e21817671e602eef80c2e7580484f58cf111957bcb6e848affcaa5976.mp3", "duration_ms": 6880}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/3d89f7f0f835e95d1bcc9e2427c6b26f00f400bbd77d9ce86b6f90c5a8896d45.mp3", "hash": "ec9c029488f163e10478ee83de7eb9894c84475654e7c1e56479364970c83dcd", "bytes": 48816, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/3d89f7f0f835e95d1bcc9e2427c6b26f00f400bbd77d9ce86b6f90c5a8896d45.mp3", "duration_ms": 8080}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/eff020f72c70709a2a203de049ba6f7acb66b75c170abe65cc1d18e599d3c63e.mp3", "hash": "da56ba4bb0a34bfb1a4b6056c5486e218d962025694daee401e574c0e25b973a", "bytes": 32544, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/eff020f72c70709a2a203de049ba6f7acb66b75c170abe65cc1d18e599d3c63e.mp3", "duration_ms": 5360}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/3f29bfc894e52cdb54929ee946b4b1c13fead128553c23e34b78d172b73af280.mp3", "hash": "70f3f54bb27aa5df78ecb1dbd840fa590f9c4457de49ff4b0044b0c17256daef", "bytes": 51696, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3f29bfc894e52cdb54929ee946b4b1c13fead128553c23e34b78d172b73af280.mp3", "duration_ms": 8560}, "s2-truefalse.prompt": {"url": "http://localhost:4006/files/lesson-audio/747fa3b99d2b60d23a2c105e617b8703ece73ce2a49596e3d226740de2d1367f.mp3", "hash": "b71c65a92a10d4d292046988936aa79db95ed31f3262b98d6c131fb480d75f8f", "bytes": 48384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/747fa3b99d2b60d23a2c105e617b8703ece73ce2a49596e3d226740de2d1367f.mp3", "duration_ms": 8000}, "s1-dialogo.explanation": {"url": "http://localhost:4006/files/lesson-audio/32a00131890b2d6ba4a6209b0aefb892fce10e8ce96a2aa1db68c9aec4293e3c.mp3", "hash": "e089e5b38c9b1b9090dda3e03b62fbfaee129cc3aad1fa499a0ee52f532b1b12", "bytes": 20448, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/32a00131890b2d6ba4a6209b0aefb892fce10e8ce96a2aa1db68c9aec4293e3c.mp3", "duration_ms": 3360}, "s3-picturechoice.prompt": {"url": "http://localhost:4006/files/lesson-audio/ab205a7a4412328aa1eef1402bc19b1dd54309706131e5160dd7166e746068ce.mp3", "hash": "5845ec914e308cca7fc0120c2f2c75c79888915803fb409d06b74e8d00171703", "bytes": 59904, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ab205a7a4412328aa1eef1402bc19b1dd54309706131e5160dd7166e746068ce.mp3", "duration_ms": 9920}, "s2-truefalse.explanation": {"url": "http://localhost:4006/files/lesson-audio/6920bab8d2d54c7a1805e2ba7d8c4f4d0e696d446ac8483841230b5b49cfbe1c.mp3", "hash": "42536781ad17e42cd21c853c23156a76a8ac702aa1c8db520e9d47966ce73073", "bytes": 36864, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6920bab8d2d54c7a1805e2ba7d8c4f4d0e696d446ac8483841230b5b49cfbe1c.mp3", "duration_ms": 6080}, "s3-picturechoice.explanation": {"url": "http://localhost:4006/files/lesson-audio/7db4fc4c0dc7adc19fa3a83e3cc02704b629d1d88e9c5d01d50d0e84dc813363.mp3", "hash": "1af5e8bf31e8118df30a15511167b670ed417457c9f063790b624f77593b20ec", "bytes": 36864, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7db4fc4c0dc7adc19fa3a83e3cc02704b629d1d88e9c5d01d50d0e84dc813363.mp3", "duration_ms": 6080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Combinación de diálogo y dos preguntas", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar que el jugador avanza correctamente entre tipos distintos dentro de una misma lección"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Liruf y su amigo", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "¡Hola Rho! ¿Sabías que en México hay monedas de 1, 2, 5, 10 y 20 pesos?", "character": "liruf"}, {"action": "idle", "emotion": "surprised", "text_md": "¿En serio? ¡Qué interesante! Entonces puedo pagar un dulce de 8 pesos con una moneda de 10 y me dan cambio.", "character": "rho"}, {"action": "idle", "emotion": "encouraging", "text_md": "¡Exacto! Y si juntas dos monedas de 5, tienes 10 pesos.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendiste en la lección anterior sobre monedas, hoy seguiremos practicando. Liruf está conversando con su amigo Rho sobre las monedas de México. Escucha con atención.", "difficulty": 1, "explanation_md": "Este diálogo te ayudará a recordar las monedas que hay en México.", "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-truefalse", "xp": 10, "type": "true_false", "hints": ["Recuerda lo que dijo Rho sobre el dulce de 8 pesos."], "title": "¿Verdadero o falso?", "payload": {"statement_md": "Rho puede pagar un dulce de 8 pesos con una moneda de 10 pesos y recibir cambio de 2 pesos.", "justifications": [{"id": "j1", "text_md": "Sí, porque 10 - 8 = 2, y las monedas de 10 existen."}, {"id": "j2", "text_md": "No, porque no hay monedas de 10 pesos."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Según lo que dijeron Liruf y Rho, elige si la afirmación es verdadera o falsa. Antes de responder, pregúntate: ¿cuánto es 10 menos 8?", "difficulty": 1, "explanation_md": "Rho dijo que con una moneda de 10 puede pagar un dulce de 8 y recibir cambio, así que la afirmación es verdadera.", "audio_segment_id": "s2-truefalse.prompt"}, {"id": "s3-picturechoice", "xp": 10, "type": "picture_choice", "hints": ["Busca la imagen que tenga dos monedas iguales que sumen 10."], "title": "Elige la combinación correcta", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "Dos monedas de 5 pesos", "image_url": "https://example.com/moneda5.png", "rationale_md": "Correcto. Dos monedas de 5 suman 10 pesos."}, {"id": "opt2", "icon": "coin", "label": "Una moneda de 10 pesos", "image_url": "https://example.com/moneda10.png", "rationale_md": "Incorrecto. Aunque vale 10, no son dos monedas de 5."}, {"id": "opt3", "icon": "coin", "label": "Cinco monedas de 2 pesos", "image_url": "https://example.com/moneda2.png", "rationale_md": "Incorrecto. Cinco monedas de 2 suman 10, pero no son dos monedas de 5."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf dijo que juntando dos monedas de 5 se tienen 10 pesos. ¿Cuál de las siguientes imágenes muestra esa combinación? Piensa: ¿cuántas monedas de 5 necesitas para tener 10?", "difficulty": 1, "explanation_md": "Dos monedas de 5 pesos suman 10 pesos, así que la imagen con dos monedas de 5 es la correcta.", "audio_segment_id": "s3-picturechoice.prompt"}], "schema_version": 1}', '{"s2-truefalse": {"is_true": true, "correct_justification_id": "j1"}, "s3-picturechoice": {"correct_option_id": "opt1"}}', '{"units": {"s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/c08de48d2cc93bdaeb6d8976feb80c21065e1fbfa58b53b07dcecca0fd32dbc7.mp3", "hash": "a9476480423473d60659030559959f9543cbed720c9d6e3e5d36d39460b6d345", "bytes": 45504, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/c08de48d2cc93bdaeb6d8976feb80c21065e1fbfa58b53b07dcecca0fd32dbc7.mp3", "duration_ms": 7520}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/9b5c5fbb19a5a67aca28657f47c71c5b3aea00b4eed96db94a38d8a361f0a729.mp3", "hash": "1690fd1dc2546425ac12674d8d58b883558cded7f9b47bb5d6fc8d5cd0d5ad7d", "bytes": 49248, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9b5c5fbb19a5a67aca28657f47c71c5b3aea00b4eed96db94a38d8a361f0a729.mp3", "duration_ms": 8160}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/a73bd9bc6e4363fb78dbb37d77b7585ba562d47460da10652cb5fb896bb731d7.mp3", "hash": "e5a7e1b05b37bfcd9dc86872c7919c520fcb20ca6ebd09d75a0a2837117c5853", "bytes": 34848, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a73bd9bc6e4363fb78dbb37d77b7585ba562d47460da10652cb5fb896bb731d7.mp3", "duration_ms": 5760}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/3d29f45d2ada89ade91cf424f6e930bacd8084bc82784f4c27915dc665e106cd.mp3", "hash": "abd0429ff0c7b0e04682682d508dae8e69e54b167c039fa8b03ad85d65998f9a", "bytes": 65664, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3d29f45d2ada89ade91cf424f6e930bacd8084bc82784f4c27915dc665e106cd.mp3", "duration_ms": 10880}, "s2-truefalse.prompt": {"url": "http://localhost:4006/files/lesson-audio/877a7bc9400e47e9aefac889b80238b3afaba6f2992a0fc7e69fbea98d47ec5f.mp3", "hash": "e58ef30aa2af4c1723631ff4507984bf60427909fee0caf77711f6383232d62f", "bytes": 58464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/877a7bc9400e47e9aefac889b80238b3afaba6f2992a0fc7e69fbea98d47ec5f.mp3", "duration_ms": 9680}, "s1-dialogo.explanation": {"url": "http://localhost:4006/files/lesson-audio/6caa1481295dd8b7fe1228e894792781a7bc42f67bc0844799fcee6ca3a4afdb.mp3", "hash": "108bccf21df34213846057a070239d219b14f8d2d5947e62c955a940f69cac77", "bytes": 25344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6caa1481295dd8b7fe1228e894792781a7bc42f67bc0844799fcee6ca3a4afdb.mp3", "duration_ms": 4160}, "s3-picturechoice.prompt": {"url": "http://localhost:4006/files/lesson-audio/d9d4a411a05149369b97149081d76315737593b88ac9fe0fb6c0e324220950ed.mp3", "hash": "14c9aa4c23ec11ed6a5eb32217a05537d3f49b8277260f41cf986a66d0987429", "bytes": 73296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d9d4a411a05149369b97149081d76315737593b88ac9fe0fb6c0e324220950ed.mp3", "duration_ms": 12160}, "s2-truefalse.explanation": {"url": "http://localhost:4006/files/lesson-audio/2939b520a697954cc808485445d9777596ec8929095924ef71ee98576794b412.mp3", "hash": "b6bd9b2b02c8198e6f7ecd2ff5f66e7b89726acf6cc219c5b5edfa786a811e6c", "bytes": 45936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2939b520a697954cc808485445d9777596ec8929095924ef71ee98576794b412.mp3", "duration_ms": 7600}, "s3-picturechoice.explanation": {"url": "http://localhost:4006/files/lesson-audio/92d9d4d6f628600cb0dc7fd96681819fe0b4902847f4887dd3b44d48c479da8d.mp3", "hash": "0cebc46677dea44a81a58230c2eb28fee5fb4bb530204cda8c040730eef551d7", "bytes": 44064, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/92d9d4d6f628600cb0dc7fd96681819fe0b4902847f4887dd3b44d48c479da8d.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "Liruf e a decisão do caminho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Distinguir entre um fato e uma opinião ao tomar uma decisão em uma história ramificada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-branch", "xp": 0, "type": "story_branch", "hints": ["Pense: o caminho brilhante parece seguro? Isso é uma opinião. Há flores no campo? Isso é um fato."], "title": "Liruf e a decisão do caminho", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "brillante", "next": "brillante", "text_md": "Caminho brilhante (parece seguro, mas é uma opinião)"}, {"id": "sombreado", "next": "sombreado", "text_md": "Caminho sombreado (parece misterioso, mas pode ser um fato)"}], "emotion": "thinking", "text_md": "Liruf está em uma floresta e encontra dois caminhos: um brilhante e um sombreado. Dina diz: ''O caminho brilhante parece mais seguro, mas é um fato ou uma opinião?'' Qual Liruf escolhe?", "character": "liruf"}, {"id": "brillante", "choices": [{"id": "fin-brillante", "next": null, "text_md": "Fim da história"}], "emotion": "happy", "text_md": "O caminho brilhante leva a um campo com 20 flores! Isso é um fato: há flores. Liruf está feliz, mas lembra que a aparência de segurança era apenas uma opinião. Pergunta: Por que é importante distinguir fatos de opiniões ao decidir? Reflita: se você se guiar apenas por opiniões, pode se enganar.", "character": "liruf"}, {"id": "sombreado", "choices": [{"id": "fin-sombreado", "next": null, "text_md": "Fim da história"}], "emotion": "surprised", "text_md": "O caminho sombreado leva a uma caverna tranquila onde há um mapa antigo. O mapa mostra fatos reais da floresta! Liruf fica curioso e aprende que o misterioso nem sempre é ruim. Pergunta: Como distinguir fatos de opiniões ajudou você nesta decisão? Reflita: basear-se em fatos permite descobrir coisas novas.", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você já praticou identificar fatos e opiniões separadamente, vamos usar isso para ajudar a Liruf a decidir! Ajude Liruf a escolher seu caminho. Lembre-se: um fato pode ser comprovado, uma opinião é o que alguém pensa.", "difficulty": 1, "explanation_md": "Liruf aprendeu que as aparências podem ser opiniões, não fatos. Sempre verifique!", "audio_segment_id": "s1-branch.prompt"}], "schema_version": 1}', '{"s1-branch": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "brillante"}, {"score": 100, "node_id": "inicio", "choice_id": "sombreado"}]}}', '{"units": {"s1-branch.prompt": {"url": "http://localhost:4006/files/lesson-audio/dcd4cf6edb99673d2469f30cdb5766d1a9113442080262754aca7a1ef60a504f.mp3", "hash": "e8d20e16e95d40d29c23f4d620e63725a3bb1b5ca00c62469b61e03b666511ea", "bytes": 96768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dcd4cf6edb99673d2469f30cdb5766d1a9113442080262754aca7a1ef60a504f.mp3", "duration_ms": 16080}, "s1-branch.explanation": {"url": "http://localhost:4006/files/lesson-audio/c86fb0023b34cf526e3bd99ef3c98f21c03602ef005d99ee891b43b7aafbcebd.mp3", "hash": "aa020f1bfa241a8d3852e99e266f83dcde27e71b3c4f797a88b65f543a78f9e8", "bytes": 38736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c86fb0023b34cf526e3bd99ef3c98f21c03602ef005d99ee891b43b7aafbcebd.mp3", "duration_ms": 6400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Inventario nocturno: ¿cuántos limones quedan?", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar objetos hasta 20", "Escribir el número exacto de limones en la canasta"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cuenta-limones", "xp": 10, "type": "count_objects", "hints": ["Mira bien cada limón en la canasta. Señala con el dedo mientras cuentas: uno, dos, tres…", "Si te pierdes, empieza de nuevo. Los limones no se mueven."], "title": "¿Cuántos limones hay?", "payload": {"scene": [{"icon": "lemon", "tint": "primary", "count": 12}], "ask_icon": "lemon"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Ayer estimaste cuántos vasos salen de una jarra... ¡Hoy contaremos limones uno por uno para saber el número exacto! Liruf enciende su lamparita y mira la canasta de limones. Ayúdale a contar cuántos limones quedan. Escribe el número exacto.", "difficulty": 1, "explanation_md": "¡Correcto! Liruf contó 12 limones en la canasta. 12 es el número exacto.", "audio_segment_id": "s1-cuenta-limones.prompt"}], "schema_version": 1}', '{"s1-cuenta-limones": {"value": 12}}', '{"units": {"s1-cuenta-limones.prompt": {"url": "http://localhost:4006/files/lesson-audio/7980a3b71700f04ec08b11de0d4ff4b9dde69eb56c33affc3cea96935726a618.mp3", "hash": "87ff0aff6fb6bb43e57a080d9dc220de110f1b4f228cbaf060b0ca0b98238d5f", "bytes": 96336, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/7980a3b71700f04ec08b11de0d4ff4b9dde69eb56c33affc3cea96935726a618.mp3", "duration_ms": 16000}, "s1-cuenta-limones.explanation": {"url": "http://localhost:4006/files/lesson-audio/ecce289d1bed157e844fb0ad316a2208e58f0af54408f827c42a9a5ad2e7f24d.mp3", "hash": "4c7c1f53cdb0216ca6b5ca0d0c46a13ea36255a7bcd66ed62ee08348992fdc12", "bytes": 32544, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/ecce289d1bed157e844fb0ad316a2208e58f0af54408f827c42a9a5ad2e7f24d.mp3", "duration_ms": 5360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "read-chart", "title": "La gráfica de ventas de la semana", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer la gráfica de barras de vasos vendidos por día y responder cuál fue el mejor día de la semana."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 10, "type": "read_chart", "hints": ["El mejor día es el que tiene la barra más alta.", "Cuenta los cuadritos de cada barra para comparar."], "title": "La gráfica de ventas de la semana", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Vasos vendidos", "points": [{"x": "Lunes", "y": 3}, {"x": "Martes", "y": 5}, {"x": "Miércoles", "y": 4}, {"x": "Jueves", "y": 6}, {"x": "Viernes", "y": 8}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Lunes"}, {"id": "martes", "text_md": "Martes"}, {"id": "miercoles", "text_md": "Miércoles"}, {"id": "jueves", "text_md": "Jueves"}, {"id": "viernes", "text_md": "Viernes"}], "prompt_md": "¿Cuál fue el mejor día de la semana?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Después de elegir al mejor proveedor de limones la semana pasada, ¡Zara ya preparó su limonada y ahora revisa sus ventas! Zara dibujó una gráfica de barras con los vasos de limonada que vendió cada día de la semana. Observa la gráfica y responde: ¿cuál fue el mejor día de la semana?", "difficulty": 1, "explanation_md": "¡Correcto! El viernes se vendieron 8 vasos, más que cualquier otro día. ¡Zara estuvo muy ocupada!", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "viernes"}}}', '{"units": {"s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/473367c244777b1f2af6f9d3ce80909a011b7d43ae9e31ad4ac5ad31919b4139.mp3", "hash": "de332277dbbc67ea1f4c575c189346050168c7114b8eefcc464827146fbb6085", "bytes": 106848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/473367c244777b1f2af6f9d3ce80909a011b7d43ae9e31ad4ac5ad31919b4139.mp3", "duration_ms": 17760}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/937d21271daecd5c9775b16aa107bb730d94f841a72f4bbe99c8b2ad14fbb82c.mp3", "hash": "d94accf72282a18930eb992d34e78b2e2d7ea64179e4ba782783d22482952e34", "bytes": 41616, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/937d21271daecd5c9775b16aa107bb730d94f841a72f4bbe99c8b2ad14fbb82c.mp3", "duration_ms": 6880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "timeline-order", "title": "Liruf''s Daily Schedule", "locale": "en-US", "subject": "mixed", "objectives": ["Order the steps of selling over time", "Match products with prices", "Classify purchases between needs and wants"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline-order", "xp": 10, "type": "timeline_order", "hints": ["Think about what you do in the morning: do you eat breakfast before or after brushing your teeth?", "Liruf always buys lemons before squeezing them."], "title": "Liruf''s Daily Schedule", "payload": {"events": [{"id": "e1", "icon": "shopping_bag", "text_md": "Buy ingredients in the morning"}, {"id": "e2", "icon": "local_drink", "text_md": "Prepare the lemonade"}, {"id": "e3", "icon": "storefront", "text_md": "Sell at noon"}, {"id": "e4", "icon": "savings", "text_md": "Count money and put away at closing"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you''ve helped Liruf make her sign with the price of 5 pesos, let''s see what she does during the day to sell her lemonade! Drag each event to the correct place on the timeline. Remember: first you buy the ingredients, then you prepare the lemonade, then you sell it at noon, and finally you count the money and put it away.", "difficulty": 1, "explanation_md": "Great job! Liruf buys ingredients in the morning (5 pesos per glass), prepares, sells at noon, and at closing counts the money. For example, if she sold 3 glasses at 5 pesos each, she would have earned 15 pesos. That''s the right order!", "audio_segment_id": "s1-timeline-order.prompt"}], "schema_version": 1}', '{"s1-timeline-order": {"order": ["e1", "e2", "e3", "e4"]}}', '{"units": {"s1-timeline-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/602fb3096c3c641f761146790614be83aff284cb4b79b673674e65d888397683.mp3", "hash": "11bf5dbad752a5b3e1bbd9329168cca73f2a15375619f489538edbd8867fea3f", "bytes": 99648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/602fb3096c3c641f761146790614be83aff284cb4b79b673674e65d888397683.mp3", "duration_ms": 16560}, "s1-timeline-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/101bf689acfa82f087eba1d71e016c9010aacda9d544a699e36c8d18438518b3.mp3", "hash": "4aa75c4538f115b163d69b470f81e8d2bf10627b3ddd0e21051d52ec123d2dfd", "bytes": 80928, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/101bf689acfa82f087eba1d71e016c9010aacda9d544a699e36c8d18438518b3.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compara proveedores de limones", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer la tabla de dos proveedores de limones (precio y cantidad) y elegir el que da más por menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 0, "type": "compare_table", "hints": ["Fíjate en el precio y la cantidad: busca cuál te da más limones por cada peso."], "title": "Compara proveedores de limones", "payload": {"cols": [{"id": "precio", "label": "Precio"}, {"id": "cantidad", "label": "Cantidad de limones"}], "rows": [{"id": "proveedor-a", "label": "Proveedor A"}, {"id": "proveedor-b", "label": "Proveedor B"}], "tokens": [{"id": "t1", "text_md": "5 MXN"}, {"id": "t2", "text_md": "10 limones"}, {"id": "t3", "text_md": "5 MXN"}, {"id": "t4", "text_md": "8 limones"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Después de ver cómo el precio afecta las ventas, ahora Dina busca la mejor oferta para sus limones. Quiere comprar limones para su puesto de limonada y anotó en su libreta una tabla con dos proveedores. Ayuda a Dina a elegir el que da más limones por menos dinero. Piensa: ¿cuál le conviene más?", "difficulty": 1, "explanation_md": "¡Correcto! El proveedor A da 10 limones por 5 MXN, es decir, 2 limones por peso. El proveedor B da 8 limones por 5 MXN, solo 1.6 limones por peso. ¡El A es mejor trato!", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a_precio": "t1", "proveedor-b_precio": "t3", "proveedor-a_cantidad": "t2", "proveedor-b_cantidad": "t4"}}}', '{"units": {"s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/b63c2d67de6f5434da0ce9fa577858c6c816ff9563f960d99fcb9b3e10f407c1.mp3", "hash": "12fdc9342b0440f3d106ad5f4dfaa604db67af109c742c236200f0e1e7ce6310", "bytes": 108864, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b63c2d67de6f5434da0ce9fa577858c6c816ff9563f960d99fcb9b3e10f407c1.mp3", "duration_ms": 18080}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/d457488d0576ab744a95f12f4febab7de3250afb89e80bcc81b68f364e4177a7.mp3", "hash": "b8d4b584a2c6bfaa4beadab4212ee3abbc7410b0899660c714998737602abd41", "bytes": 91584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d457488d0576ab744a95f12f4febab7de3250afb89e80bcc81b68f364e4177a7.mp3", "duration_ms": 15200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "How much did Liruf earn?", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate and write how much Liruf earned in total if he sold 4 cups at 5 pesos each (20 pesos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-input", "xp": 10, "type": "number_input", "hints": ["Remember: each cup sells for 5 pesos. If he sold 4 cups, add 5 + 5 + 5 + 5.", "5 + 5 = 10, plus 5 = 15, plus 5 = 20."], "title": "Liruf''s Profit", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Complete the profit sentence: ''I sold a cup for 5 pesos, the ingredients cost 2, my profit is ___ pesos.'' Now, calculate how much Liruf earned in total if he sold 4 cups at 5 pesos each. Write the number.", "difficulty": 1, "explanation_md": "Correct! Liruf sold 4 cups at 5 pesos each, so 4 × 5 = 20 pesos in total.", "audio_segment_id": "s1-number-input.prompt"}], "schema_version": 1}', '{"s1-number-input": {"value": 20, "tolerance": 0}}', '{"units": {"s1-number-input.prompt": {"url": "http://localhost:4006/files/lesson-audio/477708b87b741119dcf12b34663d50bcb15b8c7dafefcab8fa941ccf12fe750f.mp3", "hash": "ee3932a0758dc26da2193f006b55c2cd931fc1669232f5e66ce67e59712bc9bb", "bytes": 75168, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/477708b87b741119dcf12b34663d50bcb15b8c7dafefcab8fa941ccf12fe750f.mp3", "duration_ms": 12480}, "s1-number-input.explanation": {"url": "http://localhost:4006/files/lesson-audio/8f9506c5872cfc3226197191484402a860b4ff87479886b8a80945f0bd95a0a2.mp3", "hash": "5d3366176f7a64917bf5fbd138f320f53ffadd7f66b75b8929c7aaf777ad5c85", "bytes": 35856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8f9506c5872cfc3226197191484402a860b4ff87479886b8a80945f0bd95a0a2.mp3", "duration_ms": 5920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dinero", "title": "Combo Dinheiro: Fechamento do Caixa", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas para fechar o caixa do dia.", "Calcular o troco correto ao receber uma nota de 20 MXN.", "Determinar quantas semanas são necessárias para economizar 80 MXN para o violão."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 10, "type": "coin_count", "hints": ["Some primeiro as moedas maiores: 10+10=20, depois 20+5=25, depois 25+2+2=29, depois 29+1+1+1=32."], "title": "Fechar o caixa", "payload": {"target": 32, "currency": "MXN", "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembre-se que ontem você ouviu dois clientes falando sobre a limonada e respondeu perguntas de verdadeiro/falso com imagens. Hoje usamos o que você aprendeu para fechar o caixa! Liruf diz: **''Hora de fechar o caixa! Conte todas as moedas que temos hoje.''** No caixa há: 3 moedas de 1 MXN, 2 moedas de 2 MXN, 1 moeda de 5 MXN e 2 moedas de 10 MXN. Quanto dinheiro há no total?", "difficulty": 1, "explanation_md": "Correto! Você somou 10+10+5+2+2+1+1+1 = **32 MXN**. Boa contagem, como Liruf! Reflita: como o que você aprendeu ontem te ajudou a contar hoje?", "audio_segment_id": "s1-coin-count.prompt"}, {"id": "s2-make-change", "xp": 10, "type": "make_change", "hints": ["Subtraia o preço do que ele pagou: 20 - 5 = ?"], "title": "Dar troco de 20", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10, 20]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Um cliente compra um copo de limonada de **5 MXN** e paga com uma nota de **20 MXN**. Rho pergunta: **''Quanto troco Dina deve dar?''**", "difficulty": 1, "explanation_md": "Muito bem! 20 - 5 = **15 MXN** de troco. Rho te parabeniza. Pense: o que aconteceria se ele pagasse com 10 MXN?", "audio_segment_id": "s2-make-change.prompt"}, {"id": "s3-savings-goal", "xp": 10, "type": "savings_goal", "hints": ["Divida a meta pelo que economiza a cada semana: 80 ÷ 20 = ?"], "title": "Semanas para o violão", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10, 20, 40]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quer economizar **80 MXN** para um violão. Zara diz: **''Se você guardar 20 MXN dos seus ganhos a cada semana, de quantas semanas precisa?''**", "difficulty": 1, "explanation_md": "Exato! 80 ÷ 20 = **4 semanas**. Zara ficará orgulhosa! Reflita: e se você economizasse 10 MXN por semana?", "audio_segment_id": "s3-savings-goal.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}, "s2-make-change": {}, "s3-savings-goal": {"correct": {"20": 4}}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/55719c5142bce2e36dabf873b0fd9837dff466c494cdd3248a7916a3456aa2a1.mp3", "hash": "2bdda2a212c15d066403643e9ccfcc4529a3d30bbf4777beb2b71d450ebf8212", "bytes": 189504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/55719c5142bce2e36dabf873b0fd9837dff466c494cdd3248a7916a3456aa2a1.mp3", "duration_ms": 31520}, "s2-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/7fc4d6933a3e2310e680b7a728015e3934f4f7bb55522f4f47e10eb3f59c1ae4.mp3", "hash": "5eb5fd2fc59635af91fc0377a62e4f05a08ac439f945fd43e937203961a6d334", "bytes": 64224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7fc4d6933a3e2310e680b7a728015e3934f4f7bb55522f4f47e10eb3f59c1ae4.mp3", "duration_ms": 10640}, "s3-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/2f1acae2ac84a6edd8dc5b364e6b0f263ea75413b4cf80a05a275b2746172347.mp3", "hash": "83c54f46b9ea40fa2d6980c2a293ab3c4f72ec8c47c80555cd13301f2430d354", "bytes": 79488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2f1acae2ac84a6edd8dc5b364e6b0f263ea75413b4cf80a05a275b2746172347.mp3", "duration_ms": 13200}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/2be3d1356933ed27b52693ea121ddc2f56f129e5afe75be8b95acf68be073b34.mp3", "hash": "6beb26074bc724b15fc6234744045e424085f8bf0b30f91b5e7a5a9225064601", "bytes": 92448, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2be3d1356933ed27b52693ea121ddc2f56f129e5afe75be8b95acf68be073b34.mp3", "duration_ms": 15360}, "s2-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/f75e8d04e378105b2b7e5a479c118ff93c4de339e518e1a9f5133007c3dab09b.mp3", "hash": "470d17fd0aa4f0eb28c19a5b89e6b52af3923054b91dbea60c7d1435e8687804", "bytes": 65088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f75e8d04e378105b2b7e5a479c118ff93c4de339e518e1a9f5133007c3dab09b.mp3", "duration_ms": 10800}, "s3-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/619f00fe1e0f1c85ee7b41ed58e82f7f3d182b5338e27afd77e0a57e3224c8d9.mp3", "hash": "340cbd6d3d61f1e3569ac1cc246d21030b73c92c9cbc47a653b1616aed96b730", "bytes": 62784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/619f00fe1e0f1c85ee7b41ed58e82f7f3d182b5338e27afd77e0a57e3224c8d9.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "true-false", "title": "¿Cierto o falso? El ahorro que crece", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo.", "Decidir si es cierto o falso: ''Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 0, "type": "true_false", "hints": ["Piensa: si cada día guardas 5 pesos, ¿la cantidad total aumenta o se queda igual?", "Imagina que hoy guardas 5, mañana otros 5… el total suma."], "title": "El ahorro que crece", "payload": {"statement_md": "Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día.", "justifications": [{"id": "j-crece", "text_md": "Es cierto, porque cada día sumas 5 pesos más, así que el total aumenta."}, {"id": "j-no-crece", "text_md": "Es falso, porque guardar siempre la misma cantidad no hace crecer el ahorro."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que ya sabes que 5 pesos es un precio justo para tu limonada, ¿qué pasa si guardas esos 5 pesos cada día? Dina y Liruf te ayudan a pensarlo. Dina dice: ''Si guardas 5 pesos de cada venta, cada día sumas 5 más. Mira: Día 1: 5 pesos, Día 2: 10 pesos, Día 3: 15 pesos... ¡el ahorro crece!'' Liruf debe decidir si es cierto o falso. ¿Tú qué opinas?", "difficulty": 1, "explanation_md": "¡Correcto! Es **cierto**: si guardas 5 pesos cada día, el ahorro total crece. Por ejemplo, en 3 días tendrías 15 pesos.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j-crece"}}', '{"units": {"s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/77a8334783a79eb484960c1386f08464ab3942e563a35eccc7456d8f505b4db6.mp3", "hash": "b7b14dd75ec041f178fe2f10a99f3544d4623c0b8a462340630fe7d4c2dd940e", "bytes": 148176, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/77a8334783a79eb484960c1386f08464ab3942e563a35eccc7456d8f505b4db6.mp3", "duration_ms": 24640}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/442b50fa6600d4604fde7b768c27d63a8033e84bd182725e38dff86e03085855.mp3", "hash": "800b0a068463326f329a809bd56b48f5c3337f401c1364234cadcbb0f79556d2", "bytes": 55008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/442b50fa6600d4604fde7b768c27d63a8033e84bd182725e38dff86e03085855.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "dialogue-choice", "title": "Decisão na barraca: Negociar ou ceder?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher o que responder a um cliente que pede desconto: negociar com gentileza sem abrir mão do lucro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-negociar-cliente", "xp": 10, "type": "dialogue_choice", "hints": ["Lembre-se de que o preço justo é 5 MXN. Se baixar muito, você perderá lucro.", "Você pode oferecer um pequeno desconto sem abrir mão de toda a margem."], "title": "A cliente insiste", "payload": {"turns": [{"id": "turn1", "npc_md": "Cliente: ''O que você diz, jovem? Me vende por 3? Venho sempre!''", "replies": [{"id": "r1a", "text_md": "Tá bom, vou te vender por 3."}, {"id": "r1b", "text_md": "Desculpe, o preço é 5 MXN, não posso baixar."}, {"id": "r1c", "text_md": "Que tal 4 MXN? Ainda é um bom preço."}]}, {"id": "turn2", "npc_md": "Cliente: (pensa) ''Hum… 4 MXN está bom. Levo duas!''", "replies": [{"id": "r2a", "text_md": "Claro! Aqui estão, obrigado pela compra."}, {"id": "r2b", "text_md": "Legal, mas só tenho uma lista, espera."}, {"id": "r2c", "text_md": "Duas limonadas, então são 8 MXN."}]}], "persona": {"name": "Liruf", "role_md": "dono da barraca de limonada", "character": "liruf"}, "opening_md": "Liruf lembra o que aprendeu: o preço de 5 MXN não é só um número, é o valor do seu trabalho. Mas a cliente é gentil e ele quer que ela vá embora contente."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como você aprendeu ontem ao decidir entre sorrir ou ignorar, e entre cobrar 5 ou 50, Liruf agora enfrenta uma nova situação: uma cliente sorri e diz: ''Parece deliciosa, mas 5 MXN está caro. Você me vende por 3?''", "difficulty": 2, "explanation_md": "Excelente! Liruf ofereceu 4 MXN, um desconto de 1 MXN que mantém o lucro e satisfaz a cliente.", "audio_segment_id": "s1-negociar-cliente.prompt"}], "schema_version": 1}', '{"s1-negociar-cliente": {"turns": [{"turn_id": "turn1", "qualities": {"ganancia": 0, "amabilidad": 0, "negociacion": 0}, "reactions": {"r1a": "incorrect", "r1b": "incorrect", "r1c": "correct"}}, {"turn_id": "turn2", "qualities": {"ganancia": 0, "amabilidad": 0, "negociacion": 0}, "reactions": {"r2a": "correct", "r2b": "incorrect", "r2c": "incorrect"}}]}}', '{"units": {"s1-negociar-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/3d26a3770844f83b8f6e64c07107bf6c30fff1600f590fa57d3529368ceb8be1.mp3", "hash": "a7159b33a600fcfe5dd3017fda2323d23156153a94eab6ce4253a0fda422d2c6", "bytes": 101088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3d26a3770844f83b8f6e64c07107bf6c30fff1600f590fa57d3529368ceb8be1.mp3", "duration_ms": 16800}, "s1-negociar-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/7993b3eda15434cace3706d68eaddb54eca327999afc8820915baab5f4f3f022.mp3", "hash": "d1d6fb291c648881eb359bbb0c6ea436f36a201c6c01b3d49a315df72d2b5ff3", "bytes": 53136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7993b3eda15434cace3706d68eaddb54eca327999afc8820915baab5f4f3f022.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "read-chart", "title": "O gráfico de vendas da semana", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler o gráfico de barras de copos vendidos por dia e responder qual foi o melhor dia da semana."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 10, "type": "read_chart", "hints": ["O melhor dia é aquele que tem a barra mais alta.", "Conte os quadradinhos de cada barra para comparar."], "title": "O gráfico de vendas da semana", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Copos vendidos", "points": [{"x": "Segunda-feira", "y": 3}, {"x": "Terça-feira", "y": 5}, {"x": "Quarta-feira", "y": 4}, {"x": "Quinta-feira", "y": 6}, {"x": "Sexta-feira", "y": 8}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Segunda-feira"}, {"id": "martes", "text_md": "Terça-feira"}, {"id": "miercoles", "text_md": "Quarta-feira"}, {"id": "jueves", "text_md": "Quinta-feira"}, {"id": "viernes", "text_md": "Sexta-feira"}], "prompt_md": "Qual foi o melhor dia da semana?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Depois de escolher o melhor fornecedor de limões na semana passada, a Zara já preparou sua limonada e agora confere suas vendas! Zara desenhou um gráfico de barras com os copos de limonada que vendeu cada dia da semana. Observe o gráfico e responda: qual foi o melhor dia da semana?", "difficulty": 1, "explanation_md": "Correto! Na sexta-feira foram vendidos 8 copos, mais do que qualquer outro dia. A Zara ficou muito ocupada!", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "viernes"}}}', '{"units": {"s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/70df21abce198a1426bc1c69908bc36c0ca4d880db8bc1a3b697d794d8b33703.mp3", "hash": "d4c3e6880573ca3e14ecebc4499f357ccd53e770d02b10e961760af7800e0ee1", "bytes": 114048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/70df21abce198a1426bc1c69908bc36c0ca4d880db8bc1a3b697d794d8b33703.mp3", "duration_ms": 18960}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/9099d8aaf609ac7db9ce4cd83de383a6acde143a579cbb049fe67f3273d3eeff.mp3", "hash": "37073ee56290ab695aff011d3758ab38aece99df03c6e56165064478e3320574", "bytes": 49248, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9099d8aaf609ac7db9ce4cd83de383a6acde143a579cbb049fe67f3273d3eeff.mp3", "duration_ms": 8160}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'en-US', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "odd-one-out", "title": "The Strange Ingredient", "locale": "en-US", "subject": "mixed", "objectives": ["Detect which is NOT an ingredient of lemonade (lemons, sugar, water... and a ball?): separate what actually costs money to produce."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 0, "type": "odd_one_out", "hints": ["Think about what you need to make lemonade: lemons, sugar, and water. Which of these is not used to make it?"], "title": "The Strange Ingredient", "payload": {"items": [{"id": "limones", "text_md": "Lemons"}, {"id": "azucar", "text_md": "Sugar"}, {"id": "agua", "text_md": "Water"}, {"id": "pelota", "text_md": "Ball"}], "reasons": [{"id": "r1", "text_md": "It is not an ingredient of lemonade."}, {"id": "r2", "text_md": "It is an ingredient of lemonade."}]}, "narrator": {"emotion": "surprised", "character": "rho"}, "prompt_md": "Yesterday, Rho put his earnings in his locked piggy bank. Today, he will use some of that money to buy ingredients for lemonade. Rho checks the shopping list. Something strange snuck in. Which of these is NOT an ingredient of lemonade?", "difficulty": 1, "explanation_md": "Exactly! The ball is not an ingredient of lemonade. Rho realized someone wrote it by mistake. The ingredients that cost money are lemons, sugar, and water.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "pelota", "correct_reason_id": "r1"}}', '{"units": {"s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/a7640e4f50762a3991316129b58cbcdc477c8a4f525dc0c3d02be70902addac1.mp3", "hash": "dda17bde28446a538ad4cb07f01fd45fdbf1b4e17489c868625e71059d9a0caa", "bytes": 103536, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/a7640e4f50762a3991316129b58cbcdc477c8a4f525dc0c3d02be70902addac1.mp3", "duration_ms": 17200}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/84fe19ca495738d32ea6b1f2a2ad3e00babcc852763070cb5f595b17c850cb6b.mp3", "hash": "01b6163d7b0b0070884eb2ffa58a2633c0d5e286cdcc9bd86dde57884ac0ed6d", "bytes": 73296, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/84fe19ca495738d32ea6b1f2a2ad3e00babcc852763070cb5f595b17c850cb6b.mp3", "duration_ms": 12160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "Liruf y la decisión del camino", "locale": "es-MX", "subject": "mixed", "objectives": ["Distinguir entre un hecho y una opinión al tomar una decisión en una historia ramificada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-branch", "xp": 0, "type": "story_branch", "hints": ["Piensa: ¿el camino brillante parece seguro? Eso es una opinión. ¿Hay flores en el campo? Eso es un hecho."], "title": "Liruf y la decisión del camino", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "brillante", "next": "brillante", "text_md": "Camino brillante (parece seguro, pero es una opinión)"}, {"id": "sombreado", "next": "sombreado", "text_md": "Camino sombreado (parece misterioso, pero puede ser un hecho)"}], "emotion": "thinking", "text_md": "Liruf está en un bosque y encuentra dos caminos: uno brillante y uno sombreado. Dina dice: ''El camino brillante parece más seguro, pero ¿es un hecho o una opinión?'' ¿Cuál elige Liruf?", "character": "liruf"}, {"id": "brillante", "choices": [{"id": "fin-brillante", "next": null, "text_md": "Fin de la historia"}], "emotion": "happy", "text_md": "¡El camino brillante lleva a un campo con 20 flores! Eso es un hecho: hay flores. Liruf está feliz, pero recuerda que la apariencia de seguridad era solo una opinión. Pregunta: ¿Por qué es importante distinguir hechos de opiniones al decidir? Reflexiona: si solo te guías por opiniones, podrías equivocarte.", "character": "liruf"}, {"id": "sombreado", "choices": [{"id": "fin-sombreado", "next": null, "text_md": "Fin de la historia"}], "emotion": "surprised", "text_md": "El camino sombreado lleva a una cueva tranquila donde hay un mapa antiguo. ¡El mapa muestra hechos reales del bosque! Liruf tiene curiosidad y aprende que lo misterioso no siempre es malo. Pregunta: ¿Cómo te ayudó distinguir hechos de opiniones en esta decisión? Reflexiona: basarte en hechos te permite descubrir cosas nuevas.", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que ya practicaste identificar hechos y opiniones por separado, ¡vamos a usar eso para ayudar a Liruf a decidir! Ayuda a Liruf a elegir su camino. Recuerda: un hecho se puede comprobar, una opinión es lo que alguien piensa.", "difficulty": 1, "explanation_md": "Liruf aprendió que las apariencias pueden ser opiniones, no hechos. ¡Siempre verifica!", "audio_segment_id": "s1-branch.prompt"}], "schema_version": 1}', '{"s1-branch": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "brillante"}, {"score": 100, "node_id": "inicio", "choice_id": "sombreado"}]}}', '{"units": {"s1-branch.prompt": {"url": "http://localhost:4006/files/lesson-audio/10c134227f5deb80d89dbd2765a0c88c855b7cb0f89a58a911f26b1daf1286e4.mp3", "hash": "5551b735ce248507c283c0096a02f6d4aa073ecaebbb6aa04e8d9edd8edd9bff", "bytes": 94464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/10c134227f5deb80d89dbd2765a0c88c855b7cb0f89a58a911f26b1daf1286e4.mp3", "duration_ms": 15680}, "s1-branch.explanation": {"url": "http://localhost:4006/files/lesson-audio/05665ddd53f846c12754077a4fc80356472fe44e77909157b1e2592d034b9ddc.mp3", "hash": "8e31b105b7db010dac786f7fb768bcbf72ed53945e7ff243d09246d8034abf5a", "bytes": 34416, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/05665ddd53f846c12754077a4fc80356472fe44e77909157b1e2592d034b9ddc.mp3", "duration_ms": 5680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Verificar el ejercicio story_dialogue", "locale": "es-MX", "subject": "economics", "objectives": ["Introducir el concepto de necesidades vs. deseos mediante un diálogo concreto"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-story-dialogue", "xp": 0, "type": "story_dialogue", "hints": ["Recuerda que una necesidad es algo que necesitamos para vivir, como comida."], "title": "Práctica aislada del tipo story_dialogue", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "¡Mira, Liruf! Tengo 10 monedas. Podemos comprar una manzana para comer.", "character": "dina"}, {"action": "idle", "emotion": "excited", "text_md": "¡Yo quiero un juguete! Es más divertido.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina y Liruf están decidiendo qué comprar con 10 monedas. Dina quiere comprar una manzana (necesidad) y Liruf quiere un juguete (deseo). ¿Quién elige la necesidad?", "difficulty": 1, "explanation_md": "¡Correcto! Dina elige la manzana, que es una necesidad, porque necesitamos comer para vivir. Liruf quiere un juguete, que es un deseo.", "audio_segment_id": "s1-story-dialogue.prompt"}], "schema_version": 1}', '{}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "match-pairs", "title": "Emparelhe os preços corretos", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar passos, emparelhar produtos com preços e classificar compras entre necessidades da barraca e gostos que podem esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 5, "type": "match_pairs", "hints": ["Lembre-se: o copo pequeno custa 5 pesos, a jarra custa 20 e o biscoito custa 3."], "title": "Emparelhe os preços", "payload": {"left": [{"id": "cup", "text_md": "Copo pequeno de limonada"}, {"id": "pitcher", "text_md": "Jarra de limonada"}, {"id": "cookie", "text_md": "Biscoito"}], "right": [{"id": "price5", "text_md": "5 pesos"}, {"id": "price20", "text_md": "20 pesos"}, {"id": "price3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ontem você vendeu três copos a 5 pesos cada, e somou 15 pesos! Hoje, Liruf precisa emparelhar os preços corretamente para continuar vendendo. O vento derrubou as etiquetas de preços. Ajude Liruf a emparelhar cada produto com seu preço correto.", "difficulty": 1, "explanation_md": "Muito bem! O copo pequeno custa 5 pesos, a jarra 20 e o biscoito 3. Assim Liruf pode vender sem confusão.", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["cup", "price5"], ["pitcher", "price20"], ["cookie", "price3"]]}}', '{"units": {"s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/e50e0892554c1513290193837f26ccf906be36461f112d38c71462def35c189c.mp3", "hash": "841568b13c3f8b92d2c30bfc6f226b70b36382108f375d99b230166e5ac5ce5e", "bytes": 104976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e50e0892554c1513290193837f26ccf906be36461f112d38c71462def35c189c.mp3", "duration_ms": 17440}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/3cddcf02c970bf174124f13b0b63c69da791f2a8d1351a6ae3f5e36cf4e323a8.mp3", "hash": "3e4c1142ddbf0f8a581d72998c3fb4f659e7a725e5277b9b9e4dead99b164700", "bytes": 55008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3cddcf02c970bf174124f13b0b63c69da791f2a8d1351a6ae3f5e36cf4e323a8.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'pt-BR', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "odd-one-out", "title": "O ingrediente estranho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar qual NÃO é um ingrediente da limonada (limões, açúcar, água… e uma bola?): separar o que realmente custa dinheiro produzir."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 0, "type": "odd_one_out", "hints": ["Pense no que você precisa para fazer limonada: limões, açúcar e água. Qual destes não é usado para prepará-la?"], "title": "O ingrediente estranho", "payload": {"items": [{"id": "limones", "text_md": "Limões"}, {"id": "azucar", "text_md": "Açúcar"}, {"id": "agua", "text_md": "Água"}, {"id": "pelota", "text_md": "Bola"}], "reasons": [{"id": "r1", "text_md": "Não é um ingrediente da limonada."}, {"id": "r2", "text_md": "Sim, é um ingrediente da limonada."}]}, "narrator": {"emotion": "surprised", "character": "rho"}, "prompt_md": "Ontem, Rho guardou seus ganhos no cofrinho com chave. Hoje, vai usar parte desse dinheiro para comprar ingredientes para a limonada. Rho confere a lista de compras. Algo estranho entrou. Qual destes NÃO é um ingrediente da limonada?", "difficulty": 1, "explanation_md": "Exato! A bola não é um ingrediente da limonada. Rho percebeu que alguém a escreveu por engano. Os ingredientes que custam dinheiro são limões, açúcar e água.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "pelota", "correct_reason_id": "r1"}}', '{"units": {"s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/4332a7309b92b1ac5f91701318889b8813a595a2652e689f73e88c460b58c928.mp3", "hash": "eb1b2e66ea8d1cf079f6923bae6d21fa14aced10cda26e06a54549baa419f144", "bytes": 98784, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/4332a7309b92b1ac5f91701318889b8813a595a2652e689f73e88c460b58c928.mp3", "duration_ms": 16400}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/00d2451dc5c44a5de928fe43ef68e905a9cc77d9ecc1817a409ced5be6c3d353.mp3", "hash": "84caa5b733a72d9105ee4bc2cf7deb00931546c50a78817b746c716f983c401b", "bytes": 70848, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/00d2451dc5c44a5de928fe43ef68e905a9cc77d9ecc1817a409ced5be6c3d353.mp3", "duration_ms": 11760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'en-US', '1', E'{"meta": {"cast": ["dina", "rho"], "slug": "fact-opinion", "title": "Facts and opinions at the lemonade stand", "locale": "en-US", "subject": "mixed", "objectives": ["Separating facts from opinions in lemonade stand sentences"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 0, "type": "fact_opinion", "hints": ["A fact can be measured or verified, like ''the cup costs 5 pesos''. An opinion expresses a personal taste."], "title": "Fact or opinion", "payload": {"statements": [{"id": "s1", "text_md": "The cup costs 5 pesos."}, {"id": "s2", "text_md": "My lemonade is the tastiest in the world."}, {"id": "s3", "text_md": "Today I sold 12 cups of lemonade."}, {"id": "s4", "text_md": "Liruf''s lemonade tastes better than Dina''s."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Yesterday we learned that promises like \\"I''ll give you 100 pesos tomorrow\\" sound suspicious. Today we''ll see how to tell what is real (fact) from what is just an opinion, so we don''t get fooled. Rho read these sentences from the day. Which ones are facts that can be proven and which are just opinions?", "difficulty": 1, "explanation_md": "Very good! Sentences that can be proven are facts. For example, ''the cup costs 5 pesos'' is a fact because you can count the money. Opinions are personal tastes, like ''my lemonade is the tastiest''.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1", "s3"]}}', '{"units": {"s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/f8930a732c4e7116171320aefb143c869be6a7f138d03ea39b3723288e807dd1.mp3", "hash": "e2ba07ef1b83fc905ae45182d4abcbcb05570b237c49834cef2fbaf662c8b1ee", "bytes": 127584, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/f8930a732c4e7116171320aefb143c869be6a7f138d03ea39b3723288e807dd1.mp3", "duration_ms": 21200}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/0d6eeec4e173ec4a5cb740d17cc7d8306d1adeeeffe4d0eb3a26dcc41662dfbe.mp3", "hash": "c39dcdc96571d28fa36f9af94e38f07967dae5bc06b2ffbc77af46acccdffd57", "bytes": 84816, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/0d6eeec4e173ec4a5cb740d17cc7d8306d1adeeeffe4d0eb3a26dcc41662dfbe.mp3", "duration_ms": 14080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "¿Preferirías…? Decisiones en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir entre dos caminos del vendedor y defenderlo: ¿ganar 10 pesos hoy o 20 la próxima semana? No hay respuesta única, hay razones."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 0, "type": "would_you_rather", "hints": [], "title": "¿Preferirías…?", "payload": {"a": {"icon": "coin", "text_md": "Ganar **10 pesos** hoy vendiendo un vaso de limonada a un cliente apurado."}, "b": {"icon": "calendar", "text_md": "Ganar **20 pesos** la próxima semana si le ofreces un trato especial al mismo cliente."}, "followup_md": "¿Qué prefieres? No hay respuesta incorrecta, solo distintas consecuencias."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ronda relámpago de cuentas del puesto: sumas de vasos y cambios simples contra el reloj. Ahora, Dina te pone un dilema.", "difficulty": 1, "explanation_md": "Dina te explicará por qué ambas opciones tienen sentido.", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 0, "b": 0}, "reveal_md": "¡Gran elección! Si elegiste **A**, hoy tienes 10 pesos seguros. Si elegiste **B**, esperas una semana para ganar el doble. Ambas son decisiones válidas. Dina dice: *''Lo importante es pensar en lo que más te conviene ahora y después.''*"}}', '{"units": {"s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/945b30104ad578f239154d99064f86534fa0d9dbaed5dfb10743712a6474c854.mp3", "hash": "309a740fabf3a7ddf1ef1dc2cb89c74fd2b7d2333716b0fda320f0f631d4f2a6", "bytes": 52704, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/945b30104ad578f239154d99064f86534fa0d9dbaed5dfb10743712a6474c854.mp3", "duration_ms": 8720}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/7376f3bc1789b336987252ea9986fae6498f75d34b12fa3c6d6cbef72aaeec6b.mp3", "hash": "413080c26ffd4200a19ec1ebf5cadfc79286a1ce9e20915a4bee9c4559633fa7", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7376f3bc1789b336987252ea9986fae6498f75d34b12fa3c6d6cbef72aaeec6b.mp3", "duration_ms": 3600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "Rho''s cardboard cash register", "locale": "en-US", "subject": "mixed", "objectives": ["Order the instructions for the homemade cash register: receive payment, verify amount, give change, record the sale."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 0, "type": "code_order", "hints": ["Think: first you receive the payment, then you check it''s correct, then you give change, and finally you record the sale."], "title": "Order the cash register steps", "payload": {"blocks": [{"id": "b1", "text_md": "Receive payment"}, {"id": "b2", "text_md": "Verify amount"}, {"id": "b3", "text_md": "Give change"}, {"id": "b4", "text_md": "Record the sale"}], "language_hint": "en-US"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you know selling involves decisions, let''s see how Rho organizes her cash register to handle those sales. Rho wants to avoid mistakes like last week when she forgot to give change. That''s why she invented a cardboard cash register that follows step-by-step instructions. Remember when you chose between receiving 10 pesos today or waiting to earn 20 next week? Now that Rho has decided to sell, she needs to organize how to handle those payments. Help Rho order the instructions so the cash register works well. Let''s go, you can do it!", "difficulty": 1, "explanation_md": "Excellent! The correct order is: receive payment, verify amount, give change, and record the sale. That way Rho''s cash register can work without errors. If you made a mistake, don''t worry: next time remember that first you receive the money, then you check it, then you give change, and finally you record it.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["b1", "b2", "b3", "b4"]}}', '{"units": {"s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/c2498101a88cfee69002670389fadcf0d75c9a7de3c584daebebb91fb8d53108.mp3", "hash": "3bcf36e653034eaa5aaebebbe83ab093041bde672a25b127da1fe1d69e0ebea0", "bytes": 155376, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c2498101a88cfee69002670389fadcf0d75c9a7de3c584daebebb91fb8d53108.mp3", "duration_ms": 25840}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/ad6d2477a027077ff6bccba2816824e037fee66278ada3c38efa1bdfc45a1a32.mp3", "hash": "dcdf841bbf92766ca4a764a970d0915ffa5a97a7c0c6957d40b6e9432f35cbbd", "bytes": 104544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ad6d2477a027077ff6bccba2816824e037fee66278ada3c38efa1bdfc45a1a32.mp3", "duration_ms": 17360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Verificar o exercício story_dialogue", "locale": "pt-BR", "subject": "economics", "objectives": ["Introduzir o conceito de necessidades vs. desejos por meio de um diálogo concreto"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-story-dialogue", "xp": 0, "type": "story_dialogue", "hints": ["Lembre-se de que uma necessidade é algo de que precisamos para viver, como comida."], "title": "Prática isolada do tipo story_dialogue", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "Olha, Liruf! Tenho 10 moedas. Podemos comprar uma maçã para comer.", "character": "dina"}, {"action": "idle", "emotion": "excited", "text_md": "Eu quero um brinquedo! É mais divertido.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina e Liruf estão decidindo o que comprar com 10 moedas. Dina quer comprar uma maçã (necessidade) e Liruf quer um brinquedo (desejo). Quem escolhe a necessidade?", "difficulty": 1, "explanation_md": "Correto! Dina escolhe a maçã, que é uma necessidade, porque precisamos comer para viver. Liruf quer um brinquedo, que é um desejo.", "audio_segment_id": "s1-story-dialogue.prompt"}], "schema_version": 1}', '{}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "interest-peek", "title": "Un vistazo al interés", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''interest_peek'' de forma aislada (flujo de predicción)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 0, "type": "interest_peek", "hints": ["El primer mes, gana el 10% de 80, que son 8 MXN. Así que después de un mes tiene 88 MXN.", "El segundo mes, vuelve a ganar el 10% de los 80 MXN iniciales, que son otros 8 MXN."], "title": "Predice el ahorro de Liruf", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 80, "prediction": {"kind": "choice", "options": [{"id": "opt-a", "text_md": "96 MXN"}, {"id": "opt-b", "text_md": "88 MXN"}, {"id": "opt-c", "text_md": "90 MXN"}]}}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf guardó **80 MXN** en su alcancía. Cada mes, su dinero crece un **10%** (interés simple). ¿Cuánto tendrá después de **2 meses**?", "difficulty": 1, "explanation_md": "¡Correcto! Liruf tendrá **96 MXN** después de 2 meses. Cada mes gana 8 MXN (10% de 80), así que en total gana 16 MXN. ¡Su dinero crece!", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 96, "tolerance": 0.01, "correct_option_id": "opt-a"}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "savings-goal", "title": "Liruf''s guitar", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate how many weeks until the 80-peso guitar if Liruf saves 20 pesos per week"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-savings-goal", "xp": 0, "type": "savings_goal", "hints": ["Think: 20 pesos per week, how many times does 20 fit into 80?"], "title": "Weeks for the guitar", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Putting together the day''s purchase without going over the 20-peso budget helped you choose ingredients. Now Liruf wants his 80-peso guitar. If he saves 20 pesos each week, how many weeks does he need?", "difficulty": 1, "explanation_md": "That''s right! 80 ÷ 20 = 4, so Liruf needs 4 weeks to save up the 80 pesos for the guitar.", "audio_segment_id": "s1-savings-goal.prompt"}], "schema_version": 1}', '{"s1-savings-goal": {"correct": {"20": 4}}}', '{"units": {"s1-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/f06efa3a9887f50e6b8c14ec80011794b5247378193ce18797a32c7acb7b472e.mp3", "hash": "7e3a760f72df4fdc6b1bde24ee5a597613368e6c9797b322900addda1f0d5926", "bytes": 62784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f06efa3a9887f50e6b8c14ec80011794b5247378193ce18797a32c7acb7b472e.mp3", "duration_ms": 10400}, "s1-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/4b84b1efe525f4a725a2e4f35f0d432a339ba4d40838b7320cdc7088561a602e.mp3", "hash": "07e7e3810a2f708b45db26b3bf858aeeec87ffff39e681e8cf24a35409476502", "bytes": 40608, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4b84b1efe525f4a725a2e4f35f0d432a339ba4d40838b7320cdc7088561a602e.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confiança nas suas contas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões simples de dinheiro comparando opções: preço justo, lugar seguro para guardar e distinguir um bom negócio de um ruim."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence", "xp": 0, "type": "confidence_quiz", "hints": ["Dica: Se um copo vale 5, dois copos valem 5 + 5."], "title": "Confiança nas suas contas", "payload": {"options": [{"id": "opt-10", "text_md": "10 MXN", "rationale_md": "Correto. 5 + 5 = 10."}, {"id": "opt-8", "text_md": "8 MXN", "rationale_md": "8 é menor que 10. Lembre-se que cada copo custa 5, então dois são 10."}, {"id": "opt-12", "text_md": "12 MXN", "rationale_md": "12 é mais que 10. 5 + 5 não dá 12, mas sim 10."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você já sabe reconhecer moedas de verdade, vamos ajudar o Liruf a contar o que ele ganhou! Liruf vendeu dois copos de limonada. Cada copo custa 5 MXN. Quanto dinheiro ele recebeu no total?", "difficulty": 1, "explanation_md": "Exato! Dois copos a 5 MXN cada um somam 10 MXN. Liruf está feliz.", "audio_segment_id": "s1-confidence.prompt"}], "schema_version": 1}', '{"s1-confidence": {"correct_option_id": "opt-10"}}', '{"units": {"s1-confidence.prompt": {"url": "http://localhost:4006/files/lesson-audio/2632c606bb742e9237478523d17d43706ae09a05247208ba6de5014bddc5e993.mp3", "hash": "882ae8b7b4ae7a6595137e1f8e344322d5f93848589279dccdb4a4846f59b642", "bytes": 87696, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2632c606bb742e9237478523d17d43706ae09a05247208ba6de5014bddc5e993.mp3", "duration_ms": 14560}, "s1-confidence.explanation": {"url": "http://localhost:4006/files/lesson-audio/a41f4b1eeb08af4fcce58bfc8a6b6bdc12d554b2874c822b2ee6c5dd2106797f.mp3", "hash": "cedbf5100f96bcc3082c74d3e4149b4c7d7ceeaeec99350631dd8eea5e79f049", "bytes": 42624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a41f4b1eeb08af4fcce58bfc8a6b6bdc12d554b2874c822b2ee6c5dd2106797f.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Bug Hunt: The Promotion That Doesn''t Add Up", "locale": "en-US", "subject": "mixed", "objectives": ["Find the error in a promotion poster and fix it using basic operations."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-hunt", "xp": 0, "type": "debug_hunt", "hints": [], "title": "The Promotion That Doesn''t Add Up", "payload": {"blocks": [{"id": "b1", "text_md": "**Current poster:** ''2 cups for 8 pesos''"}, {"id": "b2", "text_md": "**Individual price:** 1 cup = 5 pesos"}, {"id": "b3", "text_md": "**What is the error?**"}], "intro_md": "Remember how we helped the cart use fewer steps? Now we''ll help Liruf use fewer pesos. Look: one cup individually costs 5 pesos. Two cups individually cost 10 pesos. But Liruf''s poster says ''2 cups for 8 pesos''. That''s cheaper than 10 pesos! Where is the error?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Help Liruf find the error in the promotion poster.", "difficulty": 1, "explanation_md": "Exactly! The poster says ''2 cups for 8 pesos'', but each cup costs 5 pesos individually. Two cups individually would cost 10 pesos, so the promotion should be cheaper, not more expensive. The correction is ''2 cups for 9 pesos'' (or less).", "audio_segment_id": "s1-debug-hunt.prompt"}], "schema_version": 1}', '{"s1-debug-hunt": {"fix_md": "El cartel debe decir ''2 vasos por 9 pesos'' (o menos) para que sea más barato que comprarlos sueltos (10 pesos).", "bug_ids": ["b1"]}}', '{"units": {"s1-debug-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/c4e29995a8ab700a228d943362f7655b6cefe29eb757130eaa8f66f5c8ea1c1b.mp3", "hash": "474baffb4f0bf3dbfa4c29005e671a7eca704202392972fcded338390694d3ad", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c4e29995a8ab700a228d943362f7655b6cefe29eb757130eaa8f66f5c8ea1c1b.mp3", "duration_ms": 2880}, "s1-debug-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/c79ccd8857550e208aa299fa5f3412086d6dff48f8d717c34f9e154e1830381b.mp3", "hash": "6272ef29ede38f736e93707b8cf880e0c3dc7c3c0cf1a7b24a345f07f8e0ae23", "bytes": 84384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c79ccd8857550e208aa299fa5f3412086d6dff48f8d717c34f9e154e1830381b.mp3", "duration_ms": 14000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "A registradora de papelão da Rho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar as instruções da registradora caseira: receber pagamento, verificar valor, dar troco, anotar a venda."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 0, "type": "code_order", "hints": ["Pense: primeiro você recebe o pagamento, depois verifica se está correto, em seguida dá o troco e, por fim, anota a venda."], "title": "Ordene os passos da registradora", "payload": {"blocks": [{"id": "b1", "text_md": "Receber pagamento"}, {"id": "b2", "text_md": "Verificar valor"}, {"id": "b3", "text_md": "Dar troco"}, {"id": "b4", "text_md": "Anotar a venda"}], "language_hint": "pt-BR"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você sabe que vender envolve decisões, vamos ver como a Rho organiza sua registradora para lidar com essas vendas. Rho quer evitar erros como os da semana passada, quando esqueceu de dar troco. Por isso, inventou uma registradora de papelão que segue instruções passo a passo. Lembre-se de quando você escolheu entre receber 10 pesos hoje ou esperar para ganhar 20 na próxima semana. Agora que Rho já decidiu vender, precisa organizar como lidar com esses pagamentos. Ajude a Rho a ordenar as instruções para que a registradora funcione bem. Vamos lá, você consegue!", "difficulty": 1, "explanation_md": "Excelente! A ordem correta é: receber pagamento, verificar valor, dar troco e anotar a venda. Assim, a registradora da Rho pode funcionar sem erros. Se você errou, não se preocupe: na próxima vez, lembre-se de que primeiro se recebe o dinheiro, depois se confere, em seguida se dá o troco e, por último, se anota.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["b1", "b2", "b3", "b4"]}}', '{"units": {"s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/9741df8ba11b46ceb2ae94c33c1eb94317fc6029263266b4d48ff7fa6f296973.mp3", "hash": "4836d86397fab9f0a18ab9d44508237fb8bc1581ca00e2481d08f3e79183adde", "bytes": 219168, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9741df8ba11b46ceb2ae94c33c1eb94317fc6029263266b4d48ff7fa6f296973.mp3", "duration_ms": 36480}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/2c7aff104429bc8618c6ba53fcc2565ea645809b9f8527a0993fda1d95e03af7.mp3", "hash": "f00f42b832b660fd683022cfac47cb3f3d46d9e5a53e454cd3f36a627405a78b", "bytes": 143856, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2c7aff104429bc8618c6ba53fcc2565ea645809b9f8527a0993fda1d95e03af7.mp3", "duration_ms": 23920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimate lemonade cups", "locale": "en-US", "subject": "mixed", "objectives": ["Estimate amounts using a slider bar", "Relate estimation to exact counting"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-slider", "xp": 0, "type": "estimate_slider", "hints": ["Think: if the pitcher is big, will it yield 1 cup or 100? Neither! Something like 8 is fine."], "title": "How many cups come out of the pitcher?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Remember that Liruf sold 4 cups of lemonade. Now Zara wants to make more, but first she needs to know how many cups come out of a pitcher. Zara made a big pitcher of lemonade. Without counting, slide the bar to estimate: about how many cups do you think come out of this pitcher?", "difficulty": 1, "explanation_md": "Great! A big pitcher gives about 8 cups. Zara is happy with your estimate. Remember that a pitcher holds about 8 small cups, so 8 is a reasonable estimate.", "audio_segment_id": "s1-estimate-slider.prompt"}], "schema_version": 1}', '{"s1-estimate-slider": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-slider.prompt": {"url": "http://localhost:4006/files/lesson-audio/f6f40b2f86fc80ea14ac09f48ea779ff72e40cd3c110464a5e1b87a9c9dde1e6.mp3", "hash": "4f5c4cef873d8274f67188033c78147d8255adef8be5dcd680876c67b75e12e3", "bytes": 100224, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/f6f40b2f86fc80ea14ac09f48ea779ff72e40cd3c110464a5e1b87a9c9dde1e6.mp3", "duration_ms": 16640}, "s1-estimate-slider.explanation": {"url": "http://localhost:4006/files/lesson-audio/20c7f8cb13a640b09fe980bc1ec9eef23e9a562644966583db1d7821e14f730e.mp3", "hash": "2c5b307b5ca75508b986d0f8a8073574d48656a0f196ba29579e48a74bcfd366", "bytes": 59904, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/20c7f8cb13a640b09fe980bc1ec9eef23e9a562644966583db1d7821e14f730e.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "picture-choice", "title": "Prática: Escolha a imagem correta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar o exercício ''picture_choice'' de forma isolada (inclui geração de imagens)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-picture-choice", "xp": 0, "type": "picture_choice", "hints": ["Dica: Procure a moeda ou nota que vale 5 pesos."], "title": "Escolha a imagem correta", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "5 pesos", "image_url": "https://example.com/5pesos.png", "rationale_md": "Correto. Esta é a moeda de 5 pesos que a Zara precisa."}, {"id": "opt2", "icon": "apple", "label": "Maçã", "image_url": "https://example.com/apple.png", "rationale_md": "A maçã é o que a Zara quer comprar, mas não é o preço."}, {"id": "opt3", "icon": "banana", "label": "Banana", "image_url": "https://example.com/banana.png", "rationale_md": "A banana é outra fruta, não o preço da maçã."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Olá! Da última vez você ajudou a Dina a contar moedas. Agora a Zara quer comprar uma maçã. **Olhe as imagens** e escolha aquela que mostra quanto custa a maçã.\\n\\n**Qual destas imagens mostra 5 pesos?**", "difficulty": 1, "explanation_md": "Muito bem! A imagem com a moeda de 5 pesos é a correta. As outras opções mostram uma maçã e uma banana.", "audio_segment_id": "s1-picture-choice.prompt"}], "schema_version": 1}', '{"s1-picture-choice": {"correct_option_id": "opt1"}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "make-change", "title": "Dar el cambio correcto", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el cambio al pagar con un billete de 20 por un artículo de 5 pesos usando monedas de 10 y 5.", "Identificar las monedas mexicanas de 1, 2, 5 y 10 pesos.", "Planificar semanas para alcanzar una meta de ahorro de 80 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 15, "type": "make_change", "hints": ["Piensa: 20 - 5 = 15. ¿Qué monedas suman 15?", "Puedes usar una moneda de 10 y una de 5."], "title": "El cambio de la señora del perrito", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¿Recuerdas cómo juntamos 5 pesos con monedas de 1 y 2? Ahora usaremos ese total como el precio de la limonada. La señora del perrito te da un billete de **20** pesos por un vaso de limonada que cuesta **5** pesos. ¿Cuánto cambio debes regresarle? Elige la combinación de monedas correcta.", "difficulty": 2, "explanation_md": "¡Correcto! 20 - 5 = 15, y 10 + 5 = 15. Debes regresar una moneda de 10 y una de 5.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/e101eed3e48846df3911f5df2f3ac0fe60eb10c1af1b4cf4ea3c10481abc97cd.mp3", "hash": "4005d1495a18b35755bb3f7e2e235061be0f6fd5724c95c6363d24b387d8d2f8", "bytes": 114624, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e101eed3e48846df3911f5df2f3ac0fe60eb10c1af1b4cf4ea3c10481abc97cd.mp3", "duration_ms": 19040}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/651228ae7d4bb5f179df52ad121a80a149601da4c4000ec13c401881f3eb21d2.mp3", "hash": "2477926f459afb74d5c45c84054d869b5da2844c9810ffee85e55382af6af9e4", "bytes": 57456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/651228ae7d4bb5f179df52ad121a80a149601da4c4000ec13c401881f3eb21d2.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "price-compare", "title": "Comparar precios de limones en el mercado", "locale": "es-MX", "subject": "mixed", "objectives": ["Comparar precios de limones en dos puestos del mercado y elegir el más barato para gastar menos (costo más bajo = más ganancia)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 5, "type": "price_compare", "hints": ["Calcula el precio por limón dividiendo el precio total entre la cantidad de limones."], "title": "¿Cuál puesto de limones es más barato?", "payload": {"offers": [{"id": "puesto-a", "qty": 5, "unit": "limones", "label": "Puesto A: 5 limones por $10", "price": 10}, {"id": "puesto-b", "qty": 3, "unit": "limones", "label": "Puesto B: 3 limones por $5", "price": 5}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Recuerda que los limones son una necesidad para el puesto de Liruf, no un deseo personal. Ahora vamos a comprarlos al mejor precio.\\n\\nDina y Liruf están en el mercado. Dos marchantes gritan sus ofertas de limones. Liruf dice: \\"¡Necesito los limones más baratos para mi limonada!\\" Ayuda a Dina a elegir el puesto más barato para que Liruf gaste menos y gane más en su puesto de limonada.\\n\\n**Puesto A:** 5 limones por $10 MXN\\n**Puesto B:** 3 limones por $5 MXN\\n\\n¿Cuál puesto tiene el precio más bajo por limón?", "difficulty": 1, "explanation_md": "¡Correcto! El Puesto B cuesta $5 ÷ 3 ≈ $1.67 por limón, mientras que el Puesto A cuesta $10 ÷ 5 = $2 por limón. ¡El Puesto B es más barato!", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-b"}}', '{"units": {"s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/4226e9393410c1e21277e261c584931d5c2c3fca89660ef51665891a3a8cac76.mp3", "hash": "a70322f88de933a45aedbc86875c51dc45bc1ccd2b7af07ce38412fc5b6e2db8", "bytes": 185184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4226e9393410c1e21277e261c584931d5c2c3fca89660ef51665891a3a8cac76.mp3", "duration_ms": 30800}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/4829a47da076a35022ec34e6c971458f790e387888747176a1fb981d546718ef.mp3", "hash": "57f0e17f0b050632faa16e4b4b272dbe002426a62119c2d004a8bc124daee555", "bytes": 78624, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4829a47da076a35022ec34e6c971458f790e387888747176a1fb981d546718ef.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "balance-scale", "title": "Balancing the Scale", "locale": "en-US", "subject": "mixed", "objectives": ["Solve balance problems using a pan balance.", "Practice small sums to equalize amounts."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-scale", "xp": 0, "type": "balance_scale", "hints": ["Try a weight of 2 and a weight of 3.", "You can also use five weights of 1."], "title": "Balancing the Scale", "payload": {"weights": [{"id": "w1", "label": "Weight of 1", "value": 1}, {"id": "w2", "label": "Weight of 2", "value": 2}, {"id": "w3", "label": "Weight of 3", "value": 3}], "left_fixed": [{"label": "Fixed weight", "value": 5}], "unknown_label": "Unknown weight"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina and Liruf are playing with a real balance. On the left pan there is a weight of 5. On the table there are weights of 1, 2, and 3. Help Liruf put weights on the right pan so that the balance is even. Which weights do you choose?", "difficulty": 1, "explanation_md": "Great job! For the balance to be even, both pans must have the same weight. 5 equals 2+3, or also 1+1+1+1+1. You did it!", "audio_segment_id": "s1-balance-scale.prompt"}], "schema_version": 1}', '{"s1-balance-scale": {}}', '{"units": {"s1-balance-scale.prompt": {"url": "http://localhost:4006/files/lesson-audio/99f2791c576a3cfe73eb0dcb3fddcad0ec9853f1301c5c37915d5ed1f83ffc5b.mp3", "hash": "067df75c0098b9a2d950f914a15c2cd3308b684f77b83123be55e6a06409aaa2", "bytes": 79488, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/99f2791c576a3cfe73eb0dcb3fddcad0ec9853f1301c5c37915d5ed1f83ffc5b.mp3", "duration_ms": 13200}, "s1-balance-scale.explanation": {"url": "http://localhost:4006/files/lesson-audio/2ed3a862b8ee28b2181a997c1090d1a64f005d0b29bde095257f6fbcfcc45803.mp3", "hash": "3c811e2d98550067e8bf2c67936b1650def02bc24cb65766094803c7e4ddc07c", "bytes": 62784, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2ed3a862b8ee28b2181a997c1090d1a64f005d0b29bde095257f6fbcfcc45803.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "measure-read", "title": "La jarra medidora: sirve vasos parejos", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer la marca de la jarra medidora para servir vasos parejos: cada vaso justo hasta la línea, ni de más ni de menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 10, "type": "measure_read", "hints": ["Observa la línea donde apunta la aguja. Cada línea grande vale 100 ml."], "title": "La jarra medidora", "payload": {"max": 1000, "min": 0, "unit": "ml", "ticks": 10, "instrument": "beaker", "pointer_value": 500}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que sabemos equilibrar valores, ¡veamos cómo medir cantidades iguales para repartir justo! Liruf tiene una jarra medidora con marcas cada 100 ml. La jarra va de 0 ml a 1000 ml. La aguja señala 500 ml. ¿Cuántos ml hay en la jarra?", "difficulty": 1, "explanation_md": "¡Correcto! La aguja está exactamente en la marca de 500 ml, que es la mitad de la jarra.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 500, "tolerance": 0}}', '{"units": {"s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/5d2cd2fef9c637652006b9e0fe9784a9f01069055f4942ca0dc0c32a4e4a8b96.mp3", "hash": "bff747a492098515ad7e8ae4ce9373001b713c270150f2dc6aafc1bf39ede73c", "bytes": 109728, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5d2cd2fef9c637652006b9e0fe9784a9f01069055f4942ca0dc0c32a4e4a8b96.mp3", "duration_ms": 18240}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/5198a71b92bb2499118a572d69ced0c1c20e452d0668898dd9b320f88e6f5d8b.mp3", "hash": "d205b560b8b91a461f64d83508ecdc59e1d0d91508dee6db8c0f1927fa88d282", "bytes": 38736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5198a71b92bb2499118a572d69ced0c1c20e452d0668898dd9b320f88e6f5d8b.mp3", "duration_ms": 6400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "count-objects", "title": "Nighttime inventory: how many lemons are left?", "locale": "en-US", "subject": "mixed", "objectives": ["Counting objects up to 20", "Write the exact number of lemons in the basket"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cuenta-limones", "xp": 10, "type": "count_objects", "hints": ["Look carefully at each lemon in the basket. Point with your finger as you count: one, two, three…", "If you get lost, start again. The lemons don''t move."], "title": "How many lemons are there?", "payload": {"scene": [{"icon": "lemon", "tint": "primary", "count": 12}], "ask_icon": "lemon"}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Yesterday you estimated how many glasses come from a pitcher... Today we''ll count lemons one by one to know the exact number! Liruf turns on his little lamp and looks at the basket of lemons. Help him count how many lemons are left. Write the exact number.", "difficulty": 1, "explanation_md": "Correct! Liruf counted 12 lemons in the basket. 12 is the exact number.", "audio_segment_id": "s1-cuenta-limones.prompt"}], "schema_version": 1}', '{"s1-cuenta-limones": {"value": 12}}', '{"units": {"s1-cuenta-limones.prompt": {"url": "http://localhost:4006/files/lesson-audio/e51cfce3c60523cc6072927b8c0760f643b2174c291a2842eabf0bb01cc385bb.mp3", "hash": "0a5ed0e77d85357f5625ca869792f4635cf47c71a77cd50836fd37d4d4d4655a", "bytes": 87696, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/e51cfce3c60523cc6072927b8c0760f643b2174c291a2842eabf0bb01cc385bb.mp3", "duration_ms": 14560}, "s1-cuenta-limones.explanation": {"url": "http://localhost:4006/files/lesson-audio/c3dd09fe7550f5acbe45fb5bde91debca4d679fb2e36d0290c380a96890b02fa.mp3", "hash": "adedc07309ac3c24fb378302a819d331cae90958441261d33c79c6e3deba7917", "bytes": 29664, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/c3dd09fe7550f5acbe45fb5bde91debca4d679fb2e36d0290c380a96890b02fa.mp3", "duration_ms": 4880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "dialogue-choice", "title": "Decision at the stand: Negotiate or give in?", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing how to respond to a customer asking for a discount: negotiate kindly without giving away the profit."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-negociar-cliente", "xp": 10, "type": "dialogue_choice", "hints": ["Remember that the fair price is 5 MXN. If you lower it too much, you''ll lose profit.", "You can offer a small discount without giving away the entire margin."], "title": "The customer insists", "payload": {"turns": [{"id": "turn1", "npc_md": "Customer: ''What do you say, young man? Can you give it to me for 3? I come often!''", "replies": [{"id": "r1a", "text_md": "Okay, I''ll give it to you for 3."}, {"id": "r1b", "text_md": "Sorry, the price is 5 MXN, I can''t lower it."}, {"id": "r1c", "text_md": "How about 4 MXN? It''s still a good price."}]}, {"id": "turn2", "npc_md": "Customer: (thinks) ''Mmm… 4 MXN is fine. I''ll take two!''", "replies": [{"id": "r2a", "text_md": "Sure! Here you go, thanks for your purchase."}, {"id": "r2b", "text_md": "Great, but I only have one list, wait."}, {"id": "r2c", "text_md": "Two lemonades, that''s 8 MXN then."}]}], "persona": {"name": "Liruf", "role_md": "lemonade stand owner", "character": "liruf"}, "opening_md": "Liruf remembers what he learned: the price of 5 MXN is not just a number, it''s the value of his work. But the customer is kind and he wants her to leave happy."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Just like yesterday when you learned to decide between smiling or ignoring, and between charging 5 or 50, Liruf now faces a new situation: a customer smiles and says, ''It looks delicious, but 5 MXN is expensive. Can you give it to me for 3?''", "difficulty": 2, "explanation_md": "Excellent! Liruf offered 4 MXN, a 1 MXN discount that keeps profit and satisfies the customer.", "audio_segment_id": "s1-negociar-cliente.prompt"}], "schema_version": 1}', '{"s1-negociar-cliente": {"turns": [{"turn_id": "turn1", "qualities": {"ganancia": 0, "amabilidad": 0, "negociacion": 0}, "reactions": {"r1a": "incorrect", "r1b": "incorrect", "r1c": "correct"}}, {"turn_id": "turn2", "qualities": {"ganancia": 0, "amabilidad": 0, "negociacion": 0}, "reactions": {"r2a": "correct", "r2b": "incorrect", "r2c": "incorrect"}}]}}', '{"units": {"s1-negociar-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/5520dc2444ddfb411cb8910850a28f7b17b98f1bcc9d96996853981ed8f2e95c.mp3", "hash": "0e6f30f972940a1b7fe511dee7fd08806b89da5618f6010d774813c37b19a475", "bytes": 86256, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5520dc2444ddfb411cb8910850a28f7b17b98f1bcc9d96996853981ed8f2e95c.mp3", "duration_ms": 14320}, "s1-negociar-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/bb8dd61c2cea1d6a06a95f33a7ab04f93743af034ec20135092c3eee64b4b688.mp3", "hash": "6061658a51f93005a698be580d41b6b455556986dee6410b9289d488cc928787", "bytes": 38736, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bb8dd61c2cea1d6a06a95f33a7ab04f93743af034ec20135092c3eee64b4b688.mp3", "duration_ms": 6400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "dialogue-choice", "title": "Decisión en el puesto: ¿Negociar o ceder?", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir qué responderle a un cliente que pide rebaja: negociar con amabilidad sin regalar la ganancia."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-negociar-cliente", "xp": 10, "type": "dialogue_choice", "hints": ["Recuerda que el precio justo es 5 MXN. Si bajas mucho, perderás ganancia.", "Puedes ofrecer un descuento pequeño sin regalar todo el margen."], "title": "La clienta insiste", "payload": {"turns": [{"id": "turn1", "npc_md": "Clienta: ''¿Qué dices, joven? ¿Me la dejas en 3? ¡Voy seguido!''", "replies": [{"id": "r1a", "text_md": "Está bien, te la dejo en 3."}, {"id": "r1b", "text_md": "Lo siento, el precio es 5 MXN, no puedo bajarlo."}, {"id": "r1c", "text_md": "¿Qué tal en 4 MXN? Sigue siendo un buen precio."}]}, {"id": "turn2", "npc_md": "Clienta: (piensa) ''Mmm… 4 MXN está bien. ¡Llévate dos!''", "replies": [{"id": "r2a", "text_md": "¡Claro! Aquí tienes, gracias por tu compra."}, {"id": "r2b", "text_md": "Genial, pero solo tengo una lista, espera."}, {"id": "r2c", "text_md": "Dos limonadas, son 8 MXN entonces."}]}], "persona": {"name": "Liruf", "role_md": "dueño del puesto de limonada", "character": "liruf"}, "opening_md": "Liruf recuerda lo que aprendió: el precio de 5 MXN no es solo un número, es el valor de su trabajo. Pero la clienta es amable y él quiere que se vaya contenta."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como aprendiste ayer al decidir entre sonreír o ignorar, y entre cobrar 5 o 50, Liruf ahora enfrenta una nueva situación: una clienta sonríe y dice: ''Se ve deliciosa, pero 5 MXN está caro. ¿Me la dejas en 3?''", "difficulty": 2, "explanation_md": "¡Excelente! Liruf ofreció 4 MXN, un descuento de 1 MXN que mantiene ganancia y satisface a la clienta.", "audio_segment_id": "s1-negociar-cliente.prompt"}], "schema_version": 1}', '{"s1-negociar-cliente": {"turns": [{"turn_id": "turn1", "qualities": {"ganancia": 0, "amabilidad": 0, "negociacion": 0}, "reactions": {"r1a": "incorrect", "r1b": "incorrect", "r1c": "correct"}}, {"turn_id": "turn2", "qualities": {"ganancia": 0, "amabilidad": 0, "negociacion": 0}, "reactions": {"r2a": "correct", "r2b": "incorrect", "r2c": "incorrect"}}]}}', '{"units": {"s1-negociar-cliente.prompt": {"url": "http://localhost:4006/files/lesson-audio/4c6f67dfb70d2a15ddd21e35ee8a662719a3b3745f31d9494c0edd19fa7fea5c.mp3", "hash": "42d4bf60b32ed1283d0d8c8a691662a64ef6edb66b96fade6aac6574de19ec8b", "bytes": 94896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4c6f67dfb70d2a15ddd21e35ee8a662719a3b3745f31d9494c0edd19fa7fea5c.mp3", "duration_ms": 15760}, "s1-negociar-cliente.explanation": {"url": "http://localhost:4006/files/lesson-audio/8a6e3c95076b49794b2c082baa47d9a247a61fe56d164d670aceb59dba84e0a3.mp3", "hash": "effa4d0a93a8da2fb7bae9bd7556e5c00b676a5013c39fe17a7e372613106163", "bytes": 53568, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8a6e3c95076b49794b2c082baa47d9a247a61fe56d164d670aceb59dba84e0a3.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'es-MX', '1', '{"meta": {"cast": ["rho", "liruf"], "slug": "odd-one-out", "title": "El ingrediente extraño", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar cuál NO es un ingrediente de la limonada (limones, azúcar, agua… ¿y una pelota?): separar lo que sí cuesta dinero producir."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 0, "type": "odd_one_out", "hints": ["Piensa en lo que necesitas para hacer limonada: limones, azúcar y agua. ¿Cuál de estos no se usa para prepararla?"], "title": "El ingrediente extraño", "payload": {"items": [{"id": "limones", "text_md": "Limones"}, {"id": "azucar", "text_md": "Azúcar"}, {"id": "agua", "text_md": "Agua"}, {"id": "pelota", "text_md": "Pelota"}], "reasons": [{"id": "r1", "text_md": "No es un ingrediente de la limonada."}, {"id": "r2", "text_md": "Sí es un ingrediente de la limonada."}]}, "narrator": {"emotion": "surprised", "character": "rho"}, "prompt_md": "Ayer, Rho guardó sus ganancias en su alcancía con llave. Hoy, va a usar parte de ese dinero para comprar ingredientes para la limonada. Rho revisa la lista de compras. Algo raro se coló. ¿Cuál de estos NO es un ingrediente de la limonada?", "difficulty": 1, "explanation_md": "¡Exacto! La pelota no es un ingrediente de la limonada. Rho se dio cuenta de que alguien la escribió por error. Los ingredientes que cuestan dinero son limones, azúcar y agua.", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "pelota", "correct_reason_id": "r1"}}', '{"units": {"s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/7a64e693e510f29f6c8aa66ae36829e35632c634ed76d6e1e462974246934061.mp3", "hash": "84bbdd271ce28709d5c83b40ab3949d29546b25ca4172a49547304e47f686834", "bytes": 102096, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/7a64e693e510f29f6c8aa66ae36829e35632c634ed76d6e1e462974246934061.mp3", "duration_ms": 16960}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/2c97e6b3fe30bddab75ef9b2f1acefb96fcbe0eed542dc553ad402d06ad46686.mp3", "hash": "a25d4ec90fc8817a250bb895952a6944988287d8cabcefa41a25f15dac4e1a48", "bytes": 66528, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2c97e6b3fe30bddab75ef9b2f1acefb96fcbe0eed542dc553ad402d06ad46686.mp3", "duration_ms": 11040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimar copos de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Estimar quantidades usando uma barra deslizante", "Relacionar a estimativa com a contagem exata"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-slider", "xp": 0, "type": "estimate_slider", "hints": ["Pense: se a jarra é grande, sairão 1 copo ou 100? Nenhum! Algo como 8 está bom."], "title": "Quantos copos saem da jarra?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Lembremos que Liruf vendeu 4 copos de limonada. Agora Zara quer preparar mais, mas primeiro precisa saber quantos copos saem de uma jarra. Zara preparou uma jarra grande de limonada. Sem contar, deslize a barra para estimar: quantos copos você acha que saem desta jarra?", "difficulty": 1, "explanation_md": "Legal! Uma jarra grande dá aproximadamente 8 copos. Zara está feliz com sua estimativa. Lembre-se de que uma jarra tem espaço para uns 8 copos pequenos, então 8 é uma estimativa razoável.", "audio_segment_id": "s1-estimate-slider.prompt"}], "schema_version": 1}', '{"s1-estimate-slider": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 6}}', '{"units": {"s1-estimate-slider.prompt": {"url": "http://localhost:4006/files/lesson-audio/0d1130cb676ec7c0f5fb48b75c49f89a769186da5afe17cdc2bb0dc548e9d3ae.mp3", "hash": "8e6ce0bc7b1613fb79283a1a733752dd73c3009d61e6c3f1dddf3d8c768c024a", "bytes": 107424, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/0d1130cb676ec7c0f5fb48b75c49f89a769186da5afe17cdc2bb0dc548e9d3ae.mp3", "duration_ms": 17840}, "s1-estimate-slider.explanation": {"url": "http://localhost:4006/files/lesson-audio/c8ae2929de96e39d45281ab47e3e0c199829d4491c8972fb585fd52a7fc96641.mp3", "hash": "c0d1be83a151d3ea2162822c29616df971730d342e8bb0777dd1f758aa34d3f0", "bytes": 80496, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/c8ae2929de96e39d45281ab47e3e0c199829d4491c8972fb585fd52a7fc96641.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "repaso-quiz-mcq", "title": "Review: How much do you earn per cup?", "locale": "en-US", "subject": "mixed", "objectives": ["Answer from memory, without help, the central ideas of the stand: the fair price of the cup and how savings grow."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-repaso-ganancia", "xp": 5, "type": "quiz_mcq", "hints": ["Profit is what''s left after subtracting expenses from the price."], "title": "How much do you earn per cup?", "payload": {"options": [{"id": "a", "text_md": "3 pesos", "rationale_md": "Correct. 5 - 2 = 3."}, {"id": "b", "text_md": "7 pesos", "rationale_md": "Almost, but you added the price and the ingredients. Profit is calculated by subtracting costs from the price, not adding."}, {"id": "c", "text_md": "2 pesos", "rationale_md": "That''s the cost of the ingredients, not the profit. Remember to subtract: price - cost = profit."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you have everything ready for tomorrow, Dina asks you a quick question about yesterday. While they pack up the stand together, Dina smiles and asks: **''Without looking at the notebook… how much do you earn per cup?''**\\n\\nRemember your stand: you sold cups for **5** pesos each, and the ingredients cost you **2** pesos per cup. So for each cup, how much profit do you get?", "difficulty": 1, "explanation_md": "Exactly! If you sell the cup for **5** pesos and the ingredients cost **2**, the profit is **3** pesos per cup. Well done, Liruf!", "audio_segment_id": "s1-repaso-ganancia.prompt"}], "schema_version": 1}', '{"s1-repaso-ganancia": {"correct_option_id": "a"}}', '{"units": {"s1-repaso-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/f89db5eb6af5023a59d56e08a2da7e42b62babf3057e5445e77e9d32127b9588.mp3", "hash": "1b21463b17e5db478f843c7432741b62d680d668705481d57872583d7db767eb", "bytes": 107856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f89db5eb6af5023a59d56e08a2da7e42b62babf3057e5445e77e9d32127b9588.mp3", "duration_ms": 17920}, "s1-repaso-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/8555348ba5301ec370c640f734d3990d9c70bde63d750f82e9346d79ec76e780.mp3", "hash": "2777295e1aa65722e143572aefa1302223c9016c5289dfbfc6eb2f9f9e4669e0", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8555348ba5301ec370c640f734d3990d9c70bde63d750f82e9346d79ec76e780.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "repaso-quiz-mcq", "title": "Repaso: ¿Cuánto ganas por vaso?", "locale": "es-MX", "subject": "mixed", "objectives": ["Responder de memoria, sin ayuda, las ideas centrales del puesto: el precio justo del vaso y cómo crece el ahorro."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-repaso-ganancia", "xp": 5, "type": "quiz_mcq", "hints": ["La ganancia es lo que sobra después de restar los gastos del precio."], "title": "¿Cuánto ganas por vaso?", "payload": {"options": [{"id": "a", "text_md": "3 pesos", "rationale_md": "Correcto. 5 - 2 = 3."}, {"id": "b", "text_md": "7 pesos", "rationale_md": "Casi, pero sumaste el precio y los ingredientes. La ganancia se calcula restando los costos del precio, no sumando."}, {"id": "c", "text_md": "2 pesos", "rationale_md": "Ese es el costo de los ingredientes, no la ganancia. Recuerda restar: precio - costo = ganancia."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que ya dejaste todo listo para mañana, Dina te hace una pregunta rápida sobre ayer. Mientras guardan el puesto juntos, Dina sonríe y pregunta: **''Sin ver el cuaderno… ¿cuánto ganas por vaso?''**\\n\\nRecuerda tu puesto: vendiste vasos a **5** pesos cada uno, y los ingredientes te costaron **2** pesos por vaso. Así que por cada vaso, ¿cuánto te queda de ganancia?", "difficulty": 1, "explanation_md": "¡Exacto! Si vendes el vaso en **5** pesos y los ingredientes cuestan **2**, la ganancia es **3** pesos por vaso. ¡Bien hecho, Liruf!", "audio_segment_id": "s1-repaso-ganancia.prompt"}], "schema_version": 1}', '{"s1-repaso-ganancia": {"correct_option_id": "a"}}', '{"units": {"s1-repaso-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/fa47d5c943ba83a9db4fa389964c2adae0c33729f4cd1bc09a541c7065a5ccdd.mp3", "hash": "39f952ec9d0ee8a7e7a5c615a321129b1b772171ad9adddc5a1f624b52a4315d", "bytes": 137088, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fa47d5c943ba83a9db4fa389964c2adae0c33729f4cd1bc09a541c7065a5ccdd.mp3", "duration_ms": 22800}, "s1-repaso-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/68545c37b380ed7bb81ad0f0ef956cf1ad904690b14021e46f94cca8dca15ee1.mp3", "hash": "60ffc7efd5efe3772f2d79e0ae931c5d97cfec84af138aaca8fef2e3ce127238", "bytes": 57456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/68545c37b380ed7bb81ad0f0ef956cf1ad904690b14021e46f94cca8dca15ee1.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "balance-scale", "title": "Equilibrando a balança", "locale": "pt-BR", "subject": "mixed", "objectives": ["Resolver problemas de equilíbrio usando uma balança de pratos.", "Praticar somas pequenas para igualar quantidades."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-scale", "xp": 0, "type": "balance_scale", "hints": ["Tente com um peso de 2 e um de 3.", "Você também pode usar cinco pesos de 1."], "title": "Equilibrando a balança", "payload": {"weights": [{"id": "w1", "label": "Peso de 1", "value": 1}, {"id": "w2", "label": "Peso de 2", "value": 2}, {"id": "w3", "label": "Peso de 3", "value": 3}], "left_fixed": [{"label": "Peso fixo", "value": 5}], "unknown_label": "Peso desconhecido"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina e Liruf estão brincando com uma balança de verdade. No prato esquerdo há um peso de 5. Na mesa há pesos de 1, 2 e 3. Ajude Liruf a colocar pesos no prato direito para que a balança fique equilibrada. Quais pesos você escolhe?", "difficulty": 1, "explanation_md": "Muito bem! Para que a balança fique equilibrada, os dois pratos devem ter o mesmo peso. 5 é igual a 2+3, ou também 1+1+1+1+1. Você conseguiu!", "audio_segment_id": "s1-balance-scale.prompt"}], "schema_version": 1}', '{"s1-balance-scale": {}}', '{"units": {"s1-balance-scale.prompt": {"url": "http://localhost:4006/files/lesson-audio/359a2601fc0d7e56a3e4935b550003a93d2ccfc2821eeb9e2130e4411c4ed9bb.mp3", "hash": "a3bcc85d9d9f048e2ca4f92c111babc66a215aa7a0f2ff08f5da0085351257b4", "bytes": 110736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/359a2601fc0d7e56a3e4935b550003a93d2ccfc2821eeb9e2130e4411c4ed9bb.mp3", "duration_ms": 18400}, "s1-balance-scale.explanation": {"url": "http://localhost:4006/files/lesson-audio/173414b96c2d1675efafdace4ea1a22a8bb3397bfb64935151dc8541a9a4f571.mp3", "hash": "3f831e58f114eb087587efddbb36ca71e284f157abf42161968cf543f39b72eb", "bytes": 79488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/173414b96c2d1675efafdace4ea1a22a8bb3397bfb64935151dc8541a9a4f571.mp3", "duration_ms": 13200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "Liruf''s Plan", "locale": "en-US", "subject": "mixed", "objectives": ["See the full plan in one scene: sell lemonade cups for 5 pesos until you save up the 80 for the guitar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "hints": [], "title": "Liruf''s Plan", "payload": {"art": {"icon": "lemonade", "tint": "primary"}, "action": "idle", "body_md": "Dina remembers: \\"Like we talked yesterday, we''re going to earn the money ourselves!\\" Liruf is in his room, in front of a poster board. With a blue marker he draws a lemonade cup and writes: **1 cup = 5 pesos**. Then he draws many cups and finally a guitar. He says: *\\"If I sell 16 cups, I''ll save up the 80 pesos for the guitar.\\"* Dina looks at him and smiles: *\\"What a great plan, Liruf!\\"*", "emotion": "neutral", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Watch the scene and listen carefully.", "difficulty": 1, "explanation_md": "Liruf drew his plan: 16 cups at 5 pesos each add up to 80 pesos for the guitar.", "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/153a98ba02c6c3d9234cb073309dd31d1aa4366c6937827bc7de981ed5359354.mp3", "hash": "662e9f8813d312a19bfa80cb4aa1402e6efe1f8f93ba71a1150f26f803f390d9", "bytes": 139104, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/153a98ba02c6c3d9234cb073309dd31d1aa4366c6937827bc7de981ed5359354.mp3", "duration_ms": 23120}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/e6d2719da936a74851c885d2e20f8c4a812ff4eb6131623deab7d697c4c19e03.mp3", "hash": "51dc9039fc5a8bc952adaf3f11946ea5fde52bbcc3507f9ca60af67f7a444152", "bytes": 11808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e6d2719da936a74851c885d2e20f8c4a812ff4eb6131623deab7d697c4c19e03.mp3", "duration_ms": 1920}, "s1-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/91a6d54e927fc7d48ffba330bb59e41edb20d883242821021d4fe5397b36d37a.mp3", "hash": "4d8267d207be6774fd1fa042447b92d5f53a25da3d01dd3d4f3eacaf42cbfee1", "bytes": 34848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/91a6d54e927fc7d48ffba330bb59e41edb20d883242821021d4fe5397b36d37a.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "El plan de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Ver el plan completo en una escena: vender vasos de limonada a 5 pesos hasta juntar los 80 de la guitarra."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "hints": [], "title": "El plan de Liruf", "payload": {"art": {"icon": "lemonade", "tint": "primary"}, "action": "idle", "body_md": "Dina recuerda: \\"¡Como hablamos ayer, vamos a ganar el dinero nosotros mismos!\\" Liruf está en su cuarto, frente a una cartulina. Con un marcador azul dibuja un vaso de limonada y escribe: **1 vaso = 5 pesos**. Luego dibuja muchos vasos y al final una guitarra. Dice: *\\"Si vendo 16 vasos, junto los 80 pesos para la guitarra.\\"* Dina lo mira y sonríe: *\\"¡Qué buen plan, Liruf!\\"*", "emotion": "neutral", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Observa la escena y escucha con atención.", "difficulty": 1, "explanation_md": "Liruf dibujó su plan: 16 vasos de 5 pesos cada uno suman 80 pesos para la guitarra.", "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/4e5d90a5af5e63291fb9aab84715e282c0d8562f953d8e65bd5059f8acb44c6d.mp3", "hash": "a276ec2a4ed971bc343b5378b1ec514d2e9e679ff9b3021b589e9b7d2ef826f5", "bytes": 153936, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/4e5d90a5af5e63291fb9aab84715e282c0d8562f953d8e65bd5059f8acb44c6d.mp3", "duration_ms": 25600}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/a93cc10e214639600150d50c75dc5f75f8b5c2aad840b41d28c9af9e155a75a3.mp3", "hash": "7e6faea94c0e2b18c7425e193d9310c68def6c5b441fd63bdcd980b4f26beac8", "bytes": 16704, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a93cc10e214639600150d50c75dc5f75f8b5c2aad840b41d28c9af9e155a75a3.mp3", "duration_ms": 2720}, "s1-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/17be23b9f8fa0a6b772bd802b50fc08660f9b252e176327ab3e53b7e63b406c8.mp3", "hash": "1a7c5588f59f48e33c88882939d5bc67095481a46c847f1e74a2d9fd36f8079e", "bytes": 41616, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/17be23b9f8fa0a6b772bd802b50fc08660f9b252e176327ab3e53b7e63b406c8.mp3", "duration_ms": 6880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "O plano de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ver o plano completo em uma cena: vender copos de limonada a 5 pesos até juntar os 80 do violão."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "hints": [], "title": "O plano de Liruf", "payload": {"art": {"icon": "lemonade", "tint": "primary"}, "action": "idle", "body_md": "Dina lembra: \\"Como conversamos ontem, vamos ganhar o dinheiro nós mesmos!\\" Liruf está em seu quarto, em frente a um cartaz. Com um marcador azul desenha um copo de limonada e escreve: **1 copo = 5 pesos**. Depois desenha muitos copos e no final um violão. Diz: *\\"Se eu vender 16 copos, junto os 80 pesos para o violão.\\"* Dina olha e sorri: *\\"Que bom plano, Liruf!\\"*", "emotion": "neutral", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Observe a cena e escute com atenção.", "difficulty": 1, "explanation_md": "Liruf desenhou seu plano: 16 copos de 5 pesos cada um somam 80 pesos para o violão.", "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/774881650a1a25a177718bd2698fdd12c4e23168b74046002a5df2033d718850.mp3", "hash": "9b341a7cc1d4bef618bab8e1e420d8414df254c2e9d18c34067853d4896257b1", "bytes": 153504, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/774881650a1a25a177718bd2698fdd12c4e23168b74046002a5df2033d718850.mp3", "duration_ms": 25520}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/13b5c52b38473e97a1b3f69fd1e61c28a056a4ed5395796d18649d3185a851a3.mp3", "hash": "3dda1d384c490fec5e2146aefe50b6fbd29cb49184dbc5ab93f9b70eed928a26", "bytes": 19008, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/13b5c52b38473e97a1b3f69fd1e61c28a056a4ed5395796d18649d3185a851a3.mp3", "duration_ms": 3120}, "s1-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/9809d1b8e6ab335176dd26713c4d3be86152b2e4305f50993aea2e8ec4989666.mp3", "hash": "c079bcccceeff0301c622b1e3da3b0ca9ff277526344883675e362434044c351", "bytes": 43488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9809d1b8e6ab335176dd26713c4d3be86152b2e4305f50993aea2e8ec4989666.mp3", "duration_ms": 7200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Choose the fair price", "locale": "en-US", "subject": "mixed", "objectives": ["Make simple money decisions by comparing options: fair price, safe place to keep money, and distinguish a good deal from a bad one."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 5, "type": "quiz_mcq", "hints": ["Think: if you set a very high price, customers will leave; if it''s too low, you won''t earn anything."], "title": "Fair price", "payload": {"options": [{"id": "opt-50", "text_md": "50 pesos", "rationale_md": "50 pesos is too expensive for a glass of lemonade. Customers won''t pay that much, and you''ll be left without selling."}, {"id": "opt-5", "text_md": "5 pesos", "rationale_md": "5 pesos is the fair price: it covers the cost of 3 pesos for ingredients and gives you a profit of 2 pesos per glass. It''s a price that customers are willing to pay."}, {"id": "opt-1", "text_md": "1 peso", "rationale_md": "1 peso is too little: it doesn''t even cover the cost of ingredients (3 pesos). You would sell, but you''d lose money on each glass."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hi! You''ve already decided to open your lemonade stand with a goal of 80 pesos. Remember in the last lesson you asked yourself how you felt about opening the stand. Now, Liruf also has his lemonade stand. It costs Liruf 3 pesos to make each glass (ingredients). He plans to sell each glass for 5 pesos. So, for each glass, he earns 2 pesos (5 - 3 = 2). What is the best price to sell each glass?", "difficulty": 1, "explanation_md": "Excellent! 5 pesos is the fair price: it covers the cost of 3 pesos and gives you a profit of 2 pesos, and it''s also attractive to customers.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "opt-5"}}', '{"units": {"s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/c1ffe3b400157d08a8b656ec74ed0622b91138e7ac297cf68d15d616bfe93792.mp3", "hash": "db2bda5230f725a6443fc03d39c6deb24b84aead2edcc0c0f9dd816c1f7fc863", "bytes": 139968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c1ffe3b400157d08a8b656ec74ed0622b91138e7ac297cf68d15d616bfe93792.mp3", "duration_ms": 23280}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/f93cca22315301dddbd4ce01912d89368c7775e4d46563738beef4cc6164dc13.mp3", "hash": "7b21ebc1f585f0aca6ad78751d83713ecff02fc409079d2845d213cba5df7caf", "bytes": 48816, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f93cca22315301dddbd4ce01912d89368c7775e4d46563738beef4cc6164dc13.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Escolha o preço justo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões simples de dinheiro comparando opções: preço justo, lugar seguro para guardar e distinguir um bom negócio de um mau."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 5, "type": "quiz_mcq", "hints": ["Pense: se você colocar um preço muito alto, os clientes vão embora; se for muito baixo, você não ganhará nada."], "title": "Preço justo", "payload": {"options": [{"id": "opt-50", "text_md": "50 pesos", "rationale_md": "50 pesos é caro demais para um copo de limonada. Os clientes não vão pagar tanto e você ficará sem vender."}, {"id": "opt-5", "text_md": "5 pesos", "rationale_md": "5 pesos é o preço justo: cobre o custo de 3 pesos dos ingredientes e dá um lucro de 2 pesos por copo. É um preço que os clientes estão dispostos a pagar."}, {"id": "opt-1", "text_md": "1 peso", "rationale_md": "1 peso é muito pouco: não cobre nem o custo dos ingredientes (3 pesos). Você venderia, mas perderia dinheiro em cada copo."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Olá! Você já decidiu abrir sua barraca de limonada com uma meta de 80 pesos. Lembre-se de que na lição passada você se perguntou como se sentia ao abrir a barraca. Agora, o Liruf também tem sua barraca de limonada. O Liruf gasta 3 pesos para fazer cada copo (ingredientes). Ele pensa em vender cada copo por 5 pesos. Assim, para cada copo, ele ganha 2 pesos (5 - 3 = 2). Qual é o melhor preço para vender cada copo?", "difficulty": 1, "explanation_md": "Excelente! 5 pesos é o preço justo: cobre o custo de 3 pesos e dá um lucro de 2 pesos, além de ser atraente para os clientes.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "opt-5"}}', '{"units": {"s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/25398c0fd99be4ccc32126ce8e5571afc4383beb90d02d254abad63e2a7fd977.mp3", "hash": "478a7f048b50d54d91e47fbace34f70e16b60b47d3a4b38f79e6486fb2ceaa53", "bytes": 177984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/25398c0fd99be4ccc32126ce8e5571afc4383beb90d02d254abad63e2a7fd977.mp3", "duration_ms": 29600}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/973c8de10567d1b2e1c5fdc42e367fb111b6efb66cd72e72d1963a51e15b12b4.mp3", "hash": "3bb2b1b5d092638c3479b80eedc4c194afc5655784e52234d9be3fe3168aa65a", "bytes": 61776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/973c8de10567d1b2e1c5fdc42e367fb111b6efb66cd72e72d1963a51e15b12b4.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Group the money from the cash register", "locale": "en-US", "subject": "mixed", "objectives": ["Order steps, match products with prices, and sort purchases between needs for the stand and treats that can wait."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-sets", "xp": 10, "type": "group_sets", "hints": ["Observe if the object is round (coin) or rectangular (bill).", "Coins are made of metal and bills are made of paper."], "title": "Group the money from the cash register", "payload": {"items": [{"id": "item1", "text_md": "5 MXN coin"}, {"id": "item2", "text_md": "5 MXN coin"}, {"id": "item3", "text_md": "5 MXN coin"}, {"id": "item4", "text_md": "20 MXN bill"}, {"id": "item5", "text_md": "20 MXN bill"}], "set_a": "coins", "set_b": "bills"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Complete the pattern of the row of cups on the counter (small, large, small, large…): discover what comes next. Now, Liruf needs to separate the money from the cash register to count it more easily. Drag each coin or bill to the correct zone: coins with coins, bills with bills.", "difficulty": 1, "explanation_md": "Great! You separated 3 coins and 2 bills. This makes it easier to count: 3 coins of 5 MXN add up to 15 MXN and 2 bills of 20 MXN add up to 40 MXN. Liruf can keep track quickly!", "audio_segment_id": "s1-group-sets.prompt"}], "schema_version": 1}', '{"s1-group-sets": {"zones": {"item1": "a", "item2": "a", "item3": "a", "item4": "b", "item5": "b"}}}', '{"units": {"s1-group-sets.prompt": {"url": "http://localhost:4006/files/lesson-audio/c96f29c767539d912d4a2d0264310b1fecdd3f122f01036c01fd29e0e0aa8be3.mp3", "hash": "3d2768cba38de6298d02077cd90995b23da32b61b4359e1cbf407c3895662757", "bytes": 102528, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c96f29c767539d912d4a2d0264310b1fecdd3f122f01036c01fd29e0e0aa8be3.mp3", "duration_ms": 17040}, "s1-group-sets.explanation": {"url": "http://localhost:4006/files/lesson-audio/001e1578d967c72bdaf6a1b9a9174011332271d02cbefee78c5229cc82432f61.mp3", "hash": "720495965319279b24de28dc301881e758b354c5124e24def1f2c5aa5c3d33fb", "bytes": 69408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/001e1578d967c72bdaf6a1b9a9174011332271d02cbefee78c5229cc82432f61.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Agrupa el dinero de la caja", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar pasos, emparejar productos con precios y clasificar compras entre necesidades del puesto y gustos que pueden esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-sets", "xp": 10, "type": "group_sets", "hints": ["Observa si el objeto es redondo (moneda) o rectangular (billete).", "Las monedas son de metal y los billetes de papel."], "title": "Agrupa el dinero de la caja", "payload": {"items": [{"id": "item1", "text_md": "Moneda de 5 MXN"}, {"id": "item2", "text_md": "Moneda de 5 MXN"}, {"id": "item3", "text_md": "Moneda de 5 MXN"}, {"id": "item4", "text_md": "Billete de 20 MXN"}, {"id": "item5", "text_md": "Billete de 20 MXN"}], "set_a": "monedas", "set_b": "billetes"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Completar el patrón de la fila de vasos del mostrador (chico, grande, chico, grande…): descubrir qué sigue. Ahora, Liruf necesita separar el dinero de la caja para contarlo más fácil. Arrastra cada moneda o billete a la zona correcta: monedas con monedas, billetes con billetes.", "difficulty": 1, "explanation_md": "¡Bien! Separaste 3 monedas y 2 billetes. Así es más fácil contar: 3 monedas de 5 MXN suman 15 MXN y 2 billetes de 20 MXN suman 40 MXN. ¡Liruf puede llevar la cuenta rápido!", "audio_segment_id": "s1-group-sets.prompt"}], "schema_version": 1}', '{"s1-group-sets": {"zones": {"item1": "a", "item2": "a", "item3": "a", "item4": "b", "item5": "b"}}}', '{"units": {"s1-group-sets.prompt": {"url": "http://localhost:4006/files/lesson-audio/3fdd085a89909896f05b7e793a05d4ec297a9f6138c8065091b81bee868b9ce6.mp3", "hash": "7195860b9c5fcf0091b72cbcdc4ff9136ba63d7d91ae50e5e9f97d44574f64ac", "bytes": 103968, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3fdd085a89909896f05b7e793a05d4ec297a9f6138c8065091b81bee868b9ce6.mp3", "duration_ms": 17280}, "s1-group-sets.explanation": {"url": "http://localhost:4006/files/lesson-audio/23ecde36a59c647cab662d47efa54fe431c08bbef569c2bd0323e64e044210ca.mp3", "hash": "f42955d165df47f6bc88681e47608adb4f98fc931dbbd7088ea6a4548d760803", "bytes": 100224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/23ecde36a59c647cab662d47efa54fe431c08bbef569c2bd0323e64e044210ca.mp3", "duration_ms": 16640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "machine-io", "title": "Grandma''s tipping machine", "locale": "en-US", "subject": "mixed", "objectives": ["Discover the ''tipping machine'' rule by observing inputs and outputs (1 in gives 2 out, 3 in gives 6 out): the machine doubles."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 0, "type": "machine_io", "hints": ["Observe: 1 → 2, 3 → 6. What operation repeats?", "Try: 1 x 2 = 2, 3 x 2 = 6. So 2 x 2 = ?"], "title": "The tipping machine", "payload": {"options": [{"id": "opt-4", "text_md": "4"}, {"id": "opt-5", "text_md": "5"}, {"id": "opt-3", "text_md": "3"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 2}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf''s grandma has a mysterious little machine. Dina says: ''Read the mark on the measuring jug to pour even glasses: each glass exactly to the line, no more, no less. Now the tipping machine! Look, if you put in 1 coin, 2 come out. If you put in 3 coins, 6 come out. How many come out if you put in 2 coins?''", "difficulty": 1, "explanation_md": "Correct! The machine doubles: 2 x 2 = 4. So with 2 coins, 4 come out.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 4, "correct_option_id": "opt-4"}}', '{"units": {"s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/3668498526eb1899b70e64e67d16a1f7da262c59ce9419b22051e4358c2c08ea.mp3", "hash": "751d716c5fdccf19c07209beee12d44b3b14de2e12e0c87aff4acb894cefb25f", "bytes": 109296, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3668498526eb1899b70e64e67d16a1f7da262c59ce9419b22051e4358c2c08ea.mp3", "duration_ms": 18160}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/cfda9b629794688fa48c4d4e619c27e8ef5c9bad96eb31c4ff0d148a9ff946b1.mp3", "hash": "15fafd83763a6e3e254219e81115aaa4f5720b2de035d07f38e61c2e40d98cef", "bytes": 34848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cfda9b629794688fa48c4d4e619c27e8ef5c9bad96eb31c4ff0d148a9ff946b1.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "machine-io", "title": "La máquina de propinas de la abuela", "locale": "es-MX", "subject": "mixed", "objectives": ["Descubrir la regla de la ''máquina de propinas'' viendo entradas y salidas (entra 1 sale 2, entra 3 sale 6): la máquina duplica."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 0, "type": "machine_io", "hints": ["Observa: 1 → 2, 3 → 6. ¿Qué operación se repite?", "Prueba: 1 x 2 = 2, 3 x 2 = 6. Entonces 2 x 2 = ?"], "title": "La máquina de propinas", "payload": {"options": [{"id": "opt-4", "text_md": "4"}, {"id": "opt-5", "text_md": "5"}, {"id": "opt-3", "text_md": "3"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 2}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "La abuela de Liruf tiene una maquinita misteriosa. Dina dice: ''Leer la marca de la jarra medidora para servir vasos parejos: cada vaso justo hasta la línea, ni de más ni de menos. ¡Ahora la máquina de propinas! Mira, si metes 1 moneda, salen 2. Si metes 3 monedas, salen 6. ¿Cuántas salen si metes 2 monedas?''", "difficulty": 1, "explanation_md": "¡Correcto! La máquina duplica: 2 x 2 = 4. Así que con 2 monedas salen 4.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 4, "correct_option_id": "opt-4"}}', '{"units": {"s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/470ff835a8d9e7d9b0bfb549c5a037d25dd05d685a947f7b8493fa5241940711.mp3", "hash": "fad233b64c6bf93c713e0872eedcb312df3d57a987821c24ef287c34b0020934", "bytes": 130464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/470ff835a8d9e7d9b0bfb549c5a037d25dd05d685a947f7b8493fa5241940711.mp3", "duration_ms": 21680}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/6dbd5d64804a2500eb7daed869ad16477d293d4f8dd2d8e633b386029d903f21.mp3", "hash": "02ccc5161af4bdc96cd4644f652ecd6b3ed184da57073c978edf13b362a3bac0", "bytes": 42624, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6dbd5d64804a2500eb7daed869ad16477d293d4f8dd2d8e633b386029d903f21.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "machine-io", "title": "A máquina de gorjetas da avó", "locale": "pt-BR", "subject": "mixed", "objectives": ["Descobrir a regra da ''máquina de gorjetas'' vendo entradas e saídas (entra 1 sai 2, entra 3 sai 6): a máquina duplica."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 0, "type": "machine_io", "hints": ["Observe: 1 → 2, 3 → 6. Qual operação se repete?", "Teste: 1 x 2 = 2, 3 x 2 = 6. Então 2 x 2 = ?"], "title": "A máquina de gorjetas", "payload": {"options": [{"id": "opt-4", "text_md": "4"}, {"id": "opt-5", "text_md": "5"}, {"id": "opt-3", "text_md": "3"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 2}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "A avó de Liruf tem uma maquininha misteriosa. Dina diz: ''Ler a marca do jarro medidor para servir copos iguais: cada copo exatamente até a linha, nem mais nem menos. Agora a máquina de gorjetas! Olha, se você coloca 1 moeda, saem 2. Se coloca 3 moedas, saem 6. Quantas saem se colocar 2 moedas?''", "difficulty": 1, "explanation_md": "Correto! A máquina duplica: 2 x 2 = 4. Assim, com 2 moedas saem 4.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 4, "correct_option_id": "opt-4"}}', '{"units": {"s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/7ffd1f75ab4d81c817bf7fb9252da61a2eba5ec6ff76aa305ddef30cfd734897.mp3", "hash": "d3713a90adfc88c767e6280c9177e91b80881e12470a5b7e44763ea9260743f7", "bytes": 139104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7ffd1f75ab4d81c817bf7fb9252da61a2eba5ec6ff76aa305ddef30cfd734897.mp3", "duration_ms": 23120}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/d0ab94c65e71364d159228f22f9b591540fc82da85bdd5794d4af3602bd31d3e.mp3", "hash": "8a50f28bcc9a4741c614d545c7956603ec63fb6d4f5a68ab43a301ee4fdaa63a", "bytes": 42624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d0ab94c65e71364d159228f22f9b591540fc82da85bdd5794d4af3602bd31d3e.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-dialogo-doble-choice", "title": "Combinação de diálogo e duas perguntas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Verificar se o jogador avança corretamente entre tipos diferentes dentro de uma mesma lição"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Liruf e seu amigo", "payload": {"lines": [{"action": "idle", "emotion": "happy", "text_md": "Olá Rho! Sabia que no México existem moedas de 1, 2, 5, 10 e 20 pesos?", "character": "liruf"}, {"action": "idle", "emotion": "surprised", "text_md": "Sério? Que interessante! Então posso pagar um doce de 8 pesos com uma moeda de 10 e receber troco.", "character": "rho"}, {"action": "idle", "emotion": "encouraging", "text_md": "Exato! E se você juntar duas moedas de 5, tem 10 pesos.", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Como você aprendeu na lição anterior sobre moedas, hoje continuaremos praticando. Liruf está conversando com seu amigo Rho sobre as moedas do México. Ouça com atenção.", "difficulty": 1, "explanation_md": "Este diálogo vai te ajudar a lembrar as moedas que existem no México.", "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-truefalse", "xp": 10, "type": "true_false", "hints": ["Lembre-se do que Rho disse sobre o doce de 8 pesos."], "title": "Verdadeiro ou falso?", "payload": {"statement_md": "Rho pode pagar um doce de 8 pesos com uma moeda de 10 pesos e receber troco de 2 pesos.", "justifications": [{"id": "j1", "text_md": "Sim, porque 10 - 8 = 2, e as moedas de 10 existem."}, {"id": "j2", "text_md": "Não, porque não existem moedas de 10 pesos."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "De acordo com o que Liruf e Rho disseram, escolha se a afirmação é verdadeira ou falsa. Antes de responder, pergunte-se: quanto é 10 menos 8?", "difficulty": 1, "explanation_md": "Rho disse que com uma moeda de 10 pode pagar um doce de 8 e receber troco, então a afirmação é verdadeira.", "audio_segment_id": "s2-truefalse.prompt"}, {"id": "s3-picturechoice", "xp": 10, "type": "picture_choice", "hints": ["Procure a imagem que tenha duas moedas iguais que somem 10."], "title": "Escolha a combinação correta", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "Duas moedas de 5 pesos", "image_url": "https://example.com/moneda5.png", "rationale_md": "Correto. Duas moedas de 5 somam 10 pesos."}, {"id": "opt2", "icon": "coin", "label": "Uma moeda de 10 pesos", "image_url": "https://example.com/moneda10.png", "rationale_md": "Incorreto. Embora valha 10, não são duas moedas de 5."}, {"id": "opt3", "icon": "coin", "label": "Cinco moedas de 2 pesos", "image_url": "https://example.com/moneda2.png", "rationale_md": "Incorreto. Cinco moedas de 2 somam 10, mas não são duas moedas de 5."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf disse que juntando duas moedas de 5 se tem 10 pesos. Qual das seguintes imagens mostra essa combinação? Pense: quantas moedas de 5 você precisa para ter 10?", "difficulty": 1, "explanation_md": "Duas moedas de 5 pesos somam 10 pesos, então a imagem com duas moedas de 5 é a correta.", "audio_segment_id": "s3-picturechoice.prompt"}], "schema_version": 1}', '{"s2-truefalse": {"is_true": true, "correct_justification_id": "j1"}, "s3-picturechoice": {"correct_option_id": "opt1"}}', '{"units": {"s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/47448952d547339348a291b7fd7073b343241dcea741353b9765277799838da7.mp3", "hash": "93c102c30de8c716a2b7f71f9311b06391743a64cf4db9633f189765777116b4", "bytes": 38304, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/47448952d547339348a291b7fd7073b343241dcea741353b9765277799838da7.mp3", "duration_ms": 6320}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/967b77ed45bb2823d35b47bdc185a68c57c408c1b7f406a637d1fb509201b11f.mp3", "hash": "120b6d56ee3219f8e8f48ea5e86b0618bace35f9f4187e4ba8b856973299a212", "bytes": 47808, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/967b77ed45bb2823d35b47bdc185a68c57c408c1b7f406a637d1fb509201b11f.mp3", "duration_ms": 7920}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/a27f4434bf7e62ad7ccae0dd81477edf766d5ea16a703198887d543887e24ae6.mp3", "hash": "74e53dedd589cf2b0e99c5cfd1e203aa22bb3769e03ef4829bd25cd345f61f49", "bytes": 29088, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a27f4434bf7e62ad7ccae0dd81477edf766d5ea16a703198887d543887e24ae6.mp3", "duration_ms": 4800}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/c15d0ef3bd439ed0b367acb0a2b99964af8283b7321849a6233d05b42d9dfabb.mp3", "hash": "1b38439a3bca4ea8133902d7241ef50c9367886a5ad683eb79abe3a99df377e3", "bytes": 74736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c15d0ef3bd439ed0b367acb0a2b99964af8283b7321849a6233d05b42d9dfabb.mp3", "duration_ms": 12400}, "s2-truefalse.prompt": {"url": "http://localhost:4006/files/lesson-audio/a39ee31051e18d7ed6a79e03f9a8af72ad7ffa35565fce199852bbc21fabc35a.mp3", "hash": "d7e6e43b0f70967ef289043e8587d45a833a7ccb08415ceb3c650df6bc97d1d9", "bytes": 67104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a39ee31051e18d7ed6a79e03f9a8af72ad7ffa35565fce199852bbc21fabc35a.mp3", "duration_ms": 11120}, "s1-dialogo.explanation": {"url": "http://localhost:4006/files/lesson-audio/3b9bdd3bcb523213c029fdd2330d4341cde51f4e1b14aa5ba4f54d58609a218c.mp3", "hash": "76d55c344ece6b83dab1960f3eaa21595bca9a11479270ebb15a9dc248e48c38", "bytes": 33984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3b9bdd3bcb523213c029fdd2330d4341cde51f4e1b14aa5ba4f54d58609a218c.mp3", "duration_ms": 5600}, "s3-picturechoice.prompt": {"url": "http://localhost:4006/files/lesson-audio/d729b2d2156acf85804e3ccc0e5ef284c0625ac3eccdae6a51b7daffd7e5ebb2.mp3", "hash": "9eadd900a0e26317569c13f4c59057eacd0286b8eff316eed82cc902820404be", "bytes": 76608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d729b2d2156acf85804e3ccc0e5ef284c0625ac3eccdae6a51b7daffd7e5ebb2.mp3", "duration_ms": 12720}, "s2-truefalse.explanation": {"url": "http://localhost:4006/files/lesson-audio/f3dc4f37d6d264417e46ace8d6193114a95e5e04c8066e82674f4679e552f289.mp3", "hash": "3be9b1b20efd8c302d05c1dd87831d8ccea89d6abc77a885c594b524c76281b9", "bytes": 48816, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f3dc4f37d6d264417e46ace8d6193114a95e5e04c8066e82674f4679e552f289.mp3", "duration_ms": 8080}, "s3-picturechoice.explanation": {"url": "http://localhost:4006/files/lesson-audio/512b6449a9f9c6a04b5382df82be36e24e3e273b1e90dc8fe2227c60f0d5280c.mp3", "hash": "aaaaa68bc8377ef2259355f2c1d438942c85ef2392feabe4ad1e5ba707e2b007", "bytes": 44496, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/512b6449a9f9c6a04b5382df82be36e24e3e273b1e90dc8fe2227c60f0d5280c.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-narrativa-choice", "title": "Un sábado en el puesto de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura-sabado", "xp": 0, "type": "story_scene", "hints": [], "title": "¡Llegan los clientes!", "payload": {"art": {"icon": "lemonade_stand", "tint": "primary"}, "action": "idle", "body_md": "—¡Buenos días! —dice Dina—. Al igual que ayer con la máquina de propinas que duplicaba (si entraba 1, salían 2), hoy también usaremos reglas para decidir el precio. Hoy es sábado y tenemos mucha clientela. Liruf, ¿cuánto cobramos por vaso? El precio normal es 5 pesos, pero podemos cambiarlo. Por ejemplo, si hay 10 clientes y cada uno compra un vaso, ganaríamos 50 pesos con el precio normal. ¡Tú decides!\\n\\nLiruf mira la fila: —Podríamos subirlo un poco, pero sin asustar a nadie. ¿Qué te parece?\\n\\nRho, desde el mostrador, sugiere: —Podemos poner 6 pesos, o 7, o hasta 8. ¡Tú decides!", "emotion": "happy", "backdrop": "band", "character": "dina"}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "Dina y Liruf abren el puesto un sábado soleado. Ya hay fila de clientes.", "difficulty": 1, "explanation_md": "Dina recuerda que la máquina de propinas duplicaba: si entraba 1, salían 2. Hoy hay que decidir el precio.", "audio_segment_id": "s1-apertura-sabado.prompt"}, {"id": "s2-decision-precio", "xp": 15, "type": "quiz_mcq", "hints": ["Piensa: si subes mucho el precio, algunos clientes podrían no comprar."], "title": "Elige el precio del día", "payload": {"options": [{"id": "opt-6", "text_md": "6 pesos", "rationale_md": "Un aumento pequeño, justo para ganar un poco más sin perder clientes."}, {"id": "opt-7", "text_md": "7 pesos", "rationale_md": "Podría ser demasiado para algunos; quizá vendas menos vasos."}, {"id": "opt-8", "text_md": "8 pesos", "rationale_md": "Un salto grande desde 5 pesos; muchos clientes podrían irse."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¿Qué precio pondrás al vaso de limonada hoy?", "difficulty": 2, "explanation_md": "Elegiste 6 pesos, un precio justo que anima a los clientes. Dina sonríe.", "audio_segment_id": "s2-decision-precio.prompt"}], "schema_version": 1}', '{"s2-decision-precio": {"correct_option_id": "opt-6"}}', '{"units": {"s1-apertura-sabado.body": {"url": "http://localhost:4006/files/lesson-audio/453aaed96b2a31d7c0c718e5cd8c4dcadba614910e8d77c4a8d9a962c94c2b7e.mp3", "hash": "0c3a53b2b94cda33164ba6c3809e426db3548933ea2ab9d3803da59433eb238e", "bytes": 235008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/453aaed96b2a31d7c0c718e5cd8c4dcadba614910e8d77c4a8d9a962c94c2b7e.mp3", "duration_ms": 39120}, "s1-apertura-sabado.prompt": {"url": "http://localhost:4006/files/lesson-audio/015be5ee0c49fc3b190ea4aad0bf452a96ace40687d7fd7c40157f36af8a7485.mp3", "hash": "21fda58f31caba21df6e48681fcbb439fd1749f2e65685a8d1a6daf2c89442af", "bytes": 34416, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/015be5ee0c49fc3b190ea4aad0bf452a96ace40687d7fd7c40157f36af8a7485.mp3", "duration_ms": 5680}, "s2-decision-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/8f5961682111596294c1109d2bf908f77f97f75824fe31a7b3fddb189f637aff.mp3", "hash": "1b613ac7f680360e43660845d6c4eca3bc1e2bcd273744ee0795dd199aaff1c2", "bytes": 21456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8f5961682111596294c1109d2bf908f77f97f75824fe31a7b3fddb189f637aff.mp3", "duration_ms": 3520}, "s1-apertura-sabado.explanation": {"url": "http://localhost:4006/files/lesson-audio/583e72260472eb2740f6804c05674b56d447e0a472fccefc21b83b70ca2624e8.mp3", "hash": "28666e1dac508af755e0b9c437da85599cb50982f7b64b518b9db628062a475b", "bytes": 46368, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/583e72260472eb2740f6804c05674b56d447e0a472fccefc21b83b70ca2624e8.mp3", "duration_ms": 7680}, "s2-decision-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/1161a5383fdf2c2e948c0ac24e4cae13035ccca278c85b16305353a790894662.mp3", "hash": "1b28ed02db95af0e77a75ba177842cbf2839be40b60fc5a7ef6dc261ed2279c9", "bytes": 34848, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1161a5383fdf2c2e948c0ac24e4cae13035ccca278c85b16305353a790894662.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-narrativa-choice", "title": "Um sábado na barraca de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Unir várias habilidades em uma mesma lição: ouvir a situação, decidir, calcular e cobrar."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura-sabado", "xp": 0, "type": "story_scene", "hints": [], "title": "Chegam os clientes!", "payload": {"art": {"icon": "lemonade_stand", "tint": "primary"}, "action": "idle", "body_md": "—Bom dia! —diz Dina—. Assim como ontem com a máquina de gorjetas que dobrava (se entrava 1, saíam 2), hoje também usaremos regras para decidir o preço. Hoje é sábado e temos muitos clientes. Liruf, quanto vamos cobrar por copo? O preço normal é 5 pesos, mas podemos mudar. Por exemplo, se houver 10 clientes e cada um comprar um copo, ganharíamos 50 pesos com o preço normal. Você decide!\\n\\nLiruf olha a fila: —Poderíamos aumentar um pouco, mas sem assustar ninguém. O que acha?\\n\\nRho, do balcão, sugere: —Podemos colocar 6 pesos, ou 7, ou até 8. Você decide!", "emotion": "happy", "backdrop": "band", "character": "dina"}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "Dina e Liruf abrem a barraca em um sábado ensolarado. Já tem fila de clientes.", "difficulty": 1, "explanation_md": "Dina lembra que a máquina de gorjetas dobrava: se entrava 1, saíam 2. Hoje é preciso decidir o preço.", "audio_segment_id": "s1-apertura-sabado.prompt"}, {"id": "s2-decision-precio", "xp": 15, "type": "quiz_mcq", "hints": ["Pense: se você aumentar muito o preço, alguns clientes podem não comprar."], "title": "Escolha o preço do dia", "payload": {"options": [{"id": "opt-6", "text_md": "6 pesos", "rationale_md": "Um aumento pequeno, justo para ganhar um pouco mais sem perder clientes."}, {"id": "opt-7", "text_md": "7 pesos", "rationale_md": "Pode ser demais para alguns; talvez você venda menos copos."}, {"id": "opt-8", "text_md": "8 pesos", "rationale_md": "Um salto grande desde 5 pesos; muitos clientes podem ir embora."}], "shuffle": false}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Qual preço você vai colocar no copo de limonada hoje?", "difficulty": 2, "explanation_md": "Você escolheu 6 pesos, um preço justo que anima os clientes. Dina sorri.", "audio_segment_id": "s2-decision-precio.prompt"}], "schema_version": 1}', '{"s2-decision-precio": {"correct_option_id": "opt-6"}}', '{"units": {"s1-apertura-sabado.body": {"url": "http://localhost:4006/files/lesson-audio/1729f2f47f2034421061bde3fe23e90dc1669aacb56d495e7481016ad6f01e10.mp3", "hash": "68e36786724eb98fcb032be28a54043ccb0b32f66824d0aacb036796237b9e17", "bytes": 261504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1729f2f47f2034421061bde3fe23e90dc1669aacb56d495e7481016ad6f01e10.mp3", "duration_ms": 43520}, "s1-apertura-sabado.prompt": {"url": "http://localhost:4006/files/lesson-audio/5ce6e4a67e180aca40ac39831d7ca29e7125bb2ae475e400c6eebad1e8416d4a.mp3", "hash": "87942094556ab00c1a61034b97400d95fa345491f1d79c305dcaa3d0ced445b1", "bytes": 40176, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5ce6e4a67e180aca40ac39831d7ca29e7125bb2ae475e400c6eebad1e8416d4a.mp3", "duration_ms": 6640}, "s2-decision-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/3a100b459fdbfb3fff7a4b01f9d268adf0e9be4f0e2ff981ac73d014a4264ccf.mp3", "hash": "960960a7a6237ddc5ecfc67b541c0b8b316db57e3e377163b30d0b010d0f725f", "bytes": 22464, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3a100b459fdbfb3fff7a4b01f9d268adf0e9be4f0e2ff981ac73d014a4264ccf.mp3", "duration_ms": 3680}, "s1-apertura-sabado.explanation": {"url": "http://localhost:4006/files/lesson-audio/413b5f9e6ffde544d86c2b23c3a7bd364a57690b3039b754af07e43a65fc1807.mp3", "hash": "d23a7781a5a0e3386a88b0f02ddea770e1e72a9a1b23b5c7f18a9c3de35ff931", "bytes": 53136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/413b5f9e6ffde544d86c2b23c3a7bd364a57690b3039b754af07e43a65fc1807.mp3", "duration_ms": 8800}, "s2-decision-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/23c3933d6df720c9c87b45d6024db354ad347815b2c239fc427c6068bdaad1f6.mp3", "hash": "89f3438c93e61483fc8d296bc13686ad5628db7fcccd898bcd511b70c03e156a", "bytes": 36864, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/23c3933d6df720c9c87b45d6024db354ad347815b2c239fc427c6068bdaad1f6.mp3", "duration_ms": 6080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compare lemon suppliers", "locale": "en-US", "subject": "mixed", "objectives": ["Read the table of two lemon suppliers (price and quantity) and choose the one that gives more for less."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 0, "type": "compare_table", "hints": ["Look at the price and quantity: find which one gives you more lemons per peso."], "title": "Compare lemon suppliers", "payload": {"cols": [{"id": "precio", "label": "Price"}, {"id": "cantidad", "label": "Quantity of lemons"}], "rows": [{"id": "proveedor-a", "label": "Supplier A"}, {"id": "proveedor-b", "label": "Supplier B"}], "tokens": [{"id": "t1", "text_md": "5 MXN"}, {"id": "t2", "text_md": "10 lemons"}, {"id": "t3", "text_md": "5 MXN"}, {"id": "t4", "text_md": "8 lemons"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "After seeing how price affects sales, Dina is now looking for the best deal on her lemons. She wants to buy lemons for her lemonade stand and wrote down a table with two suppliers in her notebook. Help Dina choose the one that gives more lemons for less money. Think: which one is better for her?", "difficulty": 1, "explanation_md": "Correct! Supplier A gives 10 lemons for 5 MXN, that is, 2 lemons per peso. Supplier B gives 8 lemons for 5 MXN, only 1.6 lemons per peso. A is the better deal!", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a_precio": "t1", "proveedor-b_precio": "t3", "proveedor-a_cantidad": "t2", "proveedor-b_cantidad": "t4"}}}', '{"units": {"s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/43b4afd03a05e331b841d94837b76dbded1dc9c643173ee52122a14a24ed4268.mp3", "hash": "abc0b8cb2bfacc1533895ca4782d4077a82410b6c333269e6c756f00e0832a16", "bytes": 88128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/43b4afd03a05e331b841d94837b76dbded1dc9c643173ee52122a14a24ed4268.mp3", "duration_ms": 14640}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/b06de0a05b9b73224292c7103d8621805f18da45d1a79564f0930d5677a26691.mp3", "hash": "76f17c2ebe957b3802ca2b3911d954f9c9e55fee63af921e012aa54ecc6c9cbf", "bytes": 73728, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b06de0a05b9b73224292c7103d8621805f18da45d1a79564f0930d5677a26691.mp3", "duration_ms": 12240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "make-change", "title": "Dar o troco correto", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o troco ao pagar com uma nota de 20 por um artigo de 5 pesos usando moedas de 10 e 5.", "Identificar as moedas brasileiras de 1, 2, 5 e 10 reais.", "Planejar semanas para alcançar uma meta de economia de 80 reais."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-make-change", "xp": 15, "type": "make_change", "hints": ["Pense: 20 - 5 = 15. Quais moedas somam 15?", "Você pode usar uma moeda de 10 e uma de 5."], "title": "O troco da senhora do cachorrinho", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra como juntamos 5 reais com moedas de 1 e 2? Agora vamos usar esse total como o preço da limonada. A senhora do cachorrinho te dá uma nota de **20** reais por um copo de limonada que custa **5** reais. Quanto troco você deve devolver? Escolha a combinação de moedas correta.", "difficulty": 2, "explanation_md": "Correto! 20 - 5 = 15, e 10 + 5 = 15. Você deve devolver uma moeda de 10 e uma de 5.", "audio_segment_id": "s1-make-change.prompt"}], "schema_version": 1}', '{"s1-make-change": {}}', '{"units": {"s1-make-change.prompt": {"url": "http://localhost:4006/files/lesson-audio/d1f83424aa12c99f848210e683d727bcd169481ee9d433166835b0bece0fce49.mp3", "hash": "0d3cd6d72ecdd544551a52787cf67cf38b72cc01b025b581f94beb9760bf3c1e", "bytes": 107856, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d1f83424aa12c99f848210e683d727bcd169481ee9d433166835b0bece0fce49.mp3", "duration_ms": 17920}, "s1-make-change.explanation": {"url": "http://localhost:4006/files/lesson-audio/6d19536a1968b0fc075309e5d7baebe76111dd6a5ce05a3eef1ae94625b15900.mp3", "hash": "0baee62cc9cfab587bdc2448811a50f6ea29dc2dbc263e88778fad3bdbb31882", "bytes": 56016, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6d19536a1968b0fc075309e5d7baebe76111dd6a5ce05a3eef1ae94625b15900.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "timeline-order", "title": "El orden del día de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar pasos de la venta en el tiempo", "Emparejar productos con precios", "Clasificar compras entre necesidades y gustos"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline-order", "xp": 10, "type": "timeline_order", "hints": ["Piensa en lo que haces tú por la mañana: ¿desayunas antes o después de lavarte los dientes?", "Liruf siempre compra limones antes de exprimirlos."], "title": "El orden del día de Liruf", "payload": {"events": [{"id": "e1", "icon": "shopping_bag", "text_md": "Comprar ingredientes por la mañana"}, {"id": "e2", "icon": "local_drink", "text_md": "Preparar la limonada"}, {"id": "e3", "icon": "storefront", "text_md": "Vender al mediodía"}, {"id": "e4", "icon": "savings", "text_md": "Contar dinero y guardar al cierre"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que ya ayudaste a Liruf a armar su letrero con el precio de 5 pesos, ¡veamos qué hace durante el día para vender su limonada! Arrastra cada evento al lugar correcto en la línea del tiempo. Recuerda: primero se compran los ingredientes, luego se prepara la limonada, después se vende al mediodía, y al final se cuenta el dinero y se guarda.", "difficulty": 1, "explanation_md": "¡Muy bien! Liruf compra ingredientes por la mañana (5 pesos por vaso), prepara, vende al mediodía y al cierre cuenta el dinero. Por ejemplo, si vendió 3 vasos a 5 pesos cada uno, habrá ganado 15 pesos. ¡Ese es el orden correcto!", "audio_segment_id": "s1-timeline-order.prompt"}], "schema_version": 1}', '{"s1-timeline-order": {"order": ["e1", "e2", "e3", "e4"]}}', '{"units": {"s1-timeline-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/3fe8f202ce9155748c88e79f80416ea5865bef398c84cda3037ff522439f5a0d.mp3", "hash": "61e9f80db0a2864bd940247d575604c2b98e30ec5853ebe1729d1ab37ef4aadd", "bytes": 135216, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3fe8f202ce9155748c88e79f80416ea5865bef398c84cda3037ff522439f5a0d.mp3", "duration_ms": 22480}, "s1-timeline-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/d2767979d952149ec472576a8bf04e1afe379e607bf00f38dfcc8dcf804c8dd2.mp3", "hash": "88a48eecacf0c84a11889301b0376d0a42fa2c8ebbdb2b755e9dc9d17ee25924", "bytes": 98784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d2767979d952149ec472576a8bf04e1afe379e607bf00f38dfcc8dcf804c8dd2.mp3", "duration_ms": 16400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "timeline-order", "title": "A ordem do dia de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar etapas da venda no tempo", "Emparelhar produtos com preços", "Classificar compras entre necessidades e desejos"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-timeline-order", "xp": 10, "type": "timeline_order", "hints": ["Pense no que você faz pela manhã: você toma café antes ou depois de escovar os dentes?", "Liruf sempre compra limões antes de espremê-los."], "title": "A ordem do dia de Liruf", "payload": {"events": [{"id": "e1", "icon": "shopping_bag", "text_md": "Comprar ingredientes pela manhã"}, {"id": "e2", "icon": "local_drink", "text_md": "Preparar a limonada"}, {"id": "e3", "icon": "storefront", "text_md": "Vender ao meio-dia"}, {"id": "e4", "icon": "savings", "text_md": "Contar dinheiro e guardar no fechamento"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você já ajudou Liruf a fazer sua placa com o preço de 5 pesos, vamos ver o que ele faz durante o dia para vender sua limonada! Arraste cada evento para o lugar certo na linha do tempo. Lembre-se: primeiro se compram os ingredientes, depois se prepara a limonada, em seguida se vende ao meio-dia, e no final se conta o dinheiro e se guarda.", "difficulty": 1, "explanation_md": "Muito bem! Liruf compra ingredientes pela manhã (5 pesos por copo), prepara, vende ao meio-dia e no fechamento conta o dinheiro. Por exemplo, se ele vendeu 3 copos a 5 pesos cada, terá ganhado 15 pesos. Essa é a ordem correta!", "audio_segment_id": "s1-timeline-order.prompt"}], "schema_version": 1}', '{"s1-timeline-order": {"order": ["e1", "e2", "e3", "e4"]}}', '{"units": {"s1-timeline-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/42f2f5a84cfaa4c73a1bfa9c21af6c37fe7ccce801d9cd3f3e7a49d9c2e89723.mp3", "hash": "4507fd18c91ca806781342c1f0a20ad23d4ad75c3dca565cb8c1d9fb303bd358", "bytes": 132336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/42f2f5a84cfaa4c73a1bfa9c21af6c37fe7ccce801d9cd3f3e7a49d9c2e89723.mp3", "duration_ms": 22000}, "s1-timeline-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/d3cfebdf475173f135aab653f9c07e7bfca2201c6a866ac9a5494c5417d9b460.mp3", "hash": "18d86e0a211388facc322aed0feccc34858cf974f9f3c35d55af089aa24daa62", "bytes": 98208, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d3cfebdf475173f135aab653f9c07e7bfca2201c6a866ac9a5494c5417d9b460.mp3", "duration_ms": 16320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Clasifica las compras del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Clasificar las compras del día en dos cubetas: NECESIDAD del puesto (limones, vasos) o GUSTO que puede esperar (stickers, globos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 0, "type": "sort_buckets", "hints": ["Piensa: ¿sin esto el puesto no puede vender limonada?", "Los gustos son cosas que te hacen feliz, pero el puesto funciona sin ellas."], "title": "Clasifica las compras del puesto", "payload": {"items": [{"id": "limones", "text_md": "Limones (para la limonada)"}, {"id": "vasos", "text_md": "Vasos (para servir la limonada)"}, {"id": "stickers", "text_md": "Stickers de estrellas"}, {"id": "globos", "text_md": "Globos de colores"}], "buckets": [{"id": "necesidad", "label": "NECESIDAD del puesto"}, {"id": "gusto", "label": "GUSTO que puede esperar"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ayer ayudaste a Dina y Liruf a reconocer las monedas iguales. Hoy usarán ese dinero para decidir qué comprar. Tienen 20 pesos en monedas de 10. Ayuda a Dina y Liruf a separar la lista de compras. Arrastra cada artículo a la cubeta correcta: **NECESIDAD del puesto** (cosas que deben comprar sí o sí) o **GUSTO que puede esperar** (cosas que les gustan pero no son urgentes).", "difficulty": 1, "explanation_md": "¡Muy bien! Los limones y vasos son NECESIDAD porque sin ellos Liruf no puede preparar ni vender limonada. Los stickers y globos son GUSTOS que pueden esperar a otro día.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/7cd0d2e878dd0f6fbe09e7314761bfd89090843a1c07e223247dd49ddf618f8f.mp3", "hash": "c995b0e3a39e406efa93a2f09e6e59f064a1e8e17f3c590ebeb04ad1ea6e6619", "bytes": 146736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7cd0d2e878dd0f6fbe09e7314761bfd89090843a1c07e223247dd49ddf618f8f.mp3", "duration_ms": 24400}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/30b238922cf755622baa3d137529d461a96c8c6bdf653e03eb951e81d0cec2cf.mp3", "hash": "d641812502d30ae7c16b914db38b30a6425b7d632956889913c6327c733962c5", "bytes": 67536, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/30b238922cf755622baa3d137529d461a96c8c6bdf653e03eb951e81d0cec2cf.mp3", "duration_ms": 11200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classifique as compras da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Classificar as compras do dia em dois baldes: NECESSIDADE da barraca (limões, copos) ou GOSTO que pode esperar (adesivos, balões)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 0, "type": "sort_buckets", "hints": ["Pense: sem isso a barraca não pode vender limonada?", "Os gostos são coisas que te deixam feliz, mas a barraca funciona sem elas."], "title": "Classifique as compras da barraca", "payload": {"items": [{"id": "limones", "text_md": "Limões (para a limonada)"}, {"id": "vasos", "text_md": "Copos (para servir a limonada)"}, {"id": "stickers", "text_md": "Adesivos de estrelas"}, {"id": "globos", "text_md": "Balões coloridos"}], "buckets": [{"id": "necesidad", "label": "NECESSIDADE da barraca"}, {"id": "gusto", "label": "GOSTO que pode esperar"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ontem você ajudou Dina e Liruf a reconhecer as moedas iguais. Hoje eles usarão esse dinheiro para decidir o que comprar. Eles têm 20 pesos em moedas de 10. Ajude Dina e Liruf a separar a lista de compras. Arraste cada item para o balde correto: **NECESSIDADE da barraca** (coisas que eles precisam comprar de qualquer jeito) ou **GOSTO que pode esperar** (coisas que eles gostam mas não são urgentes).", "difficulty": 1, "explanation_md": "Muito bem! Os limões e copos são NECESSIDADE porque sem eles Liruf não pode preparar nem vender limonada. Os adesivos e balões são GOSTOS que podem esperar para outro dia.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/d3e00e30f973f0328c6cc51347ec39e163974cacbcd22b1aa4c69187edfe5926.mp3", "hash": "3053cb3b965dabfe779afaec8ccbca5ee17beae0f1502b8ff74051275072c0c7", "bytes": 157824, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d3e00e30f973f0328c6cc51347ec39e163974cacbcd22b1aa4c69187edfe5926.mp3", "duration_ms": 26240}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/86d98bf7962382a403df73e32dd25b8ce5b1b002d589cd9f20fa303a444e73ec.mp3", "hash": "bf6ca4f8c2032ffc15d8473e2cc614bd6e89ffbe0136a55396822b4861a9b74e", "bytes": 71424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/86d98bf7962382a403df73e32dd25b8ce5b1b002d589cd9f20fa303a444e73ec.mp3", "duration_ms": 11840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "savings-goal", "title": "La guitarra de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular cuántas semanas faltan para la guitarra de 80 pesos si Liruf ahorra 20 pesos por semana"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-savings-goal", "xp": 0, "type": "savings_goal", "hints": ["Piensa: 20 pesos por semana, ¿cuántas veces 20 caben en 80?"], "title": "Semanas para la guitarra", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Armar la compra del día sin pasarse del presupuesto de 20 pesos te ayudó a elegir ingredientes. Ahora Liruf quiere su guitarra de 80 pesos. Si ahorra 20 pesos cada semana, ¿cuántas semanas necesita?", "difficulty": 1, "explanation_md": "¡Así es! 80 ÷ 20 = 4, por lo que Liruf necesita 4 semanas para juntar los 80 pesos de la guitarra.", "audio_segment_id": "s1-savings-goal.prompt"}], "schema_version": 1}', '{"s1-savings-goal": {"correct": {"20": 4}}}', '{"units": {"s1-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/1cae3ab8f3f43d3d0be8cd3b0a0aea3aa83b2626128f34d0fcb69a119d059612.mp3", "hash": "7ff7024d9fa5f2cf27031797510dc6f38e7a01e229728af4703eaefbdd0af9f8", "bytes": 92016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1cae3ab8f3f43d3d0be8cd3b0a0aea3aa83b2626128f34d0fcb69a119d059612.mp3", "duration_ms": 15280}, "s1-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/2c5240c723d8d568e0eda47b8991b9618616990c8c53b17e2eb5a6d6face2362.mp3", "hash": "59e28181d16a0805ae857980137686a842960f96801a940827f980898f92bd35", "bytes": 53136, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2c5240c723d8d568e0eda47b8991b9618616990c8c53b17e2eb5a6d6face2362.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "savings-goal", "title": "O violão de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular quantas semanas faltam para o violão de 80 pesos se Liruf economiza 20 pesos por semana"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-savings-goal", "xp": 0, "type": "savings_goal", "hints": ["Pense: 20 pesos por semana, quantas vezes 20 cabem em 80?"], "title": "Semanas para o violão", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Montar a compra do dia sem passar do orçamento de 20 pesos te ajudou a escolher ingredientes. Agora Liruf quer seu violão de 80 pesos. Se ela economiza 20 pesos a cada semana, quantas semanas precisa?", "difficulty": 1, "explanation_md": "Isso mesmo! 80 ÷ 20 = 4, então Liruf precisa de 4 semanas para juntar os 80 pesos do violão.", "audio_segment_id": "s1-savings-goal.prompt"}], "schema_version": 1}', '{"s1-savings-goal": {"correct": {"20": 4}}}', '{"units": {"s1-savings-goal.prompt": {"url": "http://localhost:4006/files/lesson-audio/cfdab7b09e6c159bdfb756e9537329b8ff41861da126419052b57280895e1066.mp3", "hash": "b7a1ba93a87d07cc4424f46f5ffef86a3aee05fa7257b41427679c83e91a2288", "bytes": 93456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cfdab7b09e6c159bdfb756e9537329b8ff41861da126419052b57280895e1066.mp3", "duration_ms": 15520}, "s1-savings-goal.explanation": {"url": "http://localhost:4006/files/lesson-audio/b399de0ebb2af87c910f59ecc5a2859595503168524a8f84aa9e7f5d6a825109.mp3", "hash": "791097dda6f23d8c77c6ee1ac76e3dcb2c0c2f981764734ebc84d8092d18765f", "bytes": 53136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b399de0ebb2af87c910f59ecc5a2859595503168524a8f84aa9e7f5d6a825109.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "pattern-complete", "title": "Completa el patrón de los vasos", "locale": "es-MX", "subject": "mixed", "objectives": ["Completar el patrón de la fila de vasos del mostrador (chico, grande, chico, grande…): descubrir qué sigue."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-pattern-vasos", "xp": 0, "type": "pattern_complete", "hints": ["El patrón alterna entre chico y grande. ¿Cuál fue el último vaso que viste?"], "title": "Patrón de vasos", "payload": {"options": [{"id": "opt1", "icon": "cup_small", "tint": "primary"}, {"id": "opt2", "icon": "cup_large", "tint": "primary"}, {"id": "opt3", "icon": "cup_medium", "tint": "primary"}], "sequence": [{"icon": "cup_small", "tint": "primary"}, {"icon": "cup_large", "tint": "primary"}, {"icon": "cup_small", "tint": "primary"}, {"icon": "cup_large", "tint": "primary"}], "missing_slots": 1}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Ahora que ya ordenamos el día de venta, ¡veamos cómo Zara organiza los vasos para sus clientes al mediodía! Zara está acomodando los vasos en el mostrador. Observa el patrón: **chico**, **grande**, **chico**, **grande**... ¿Qué vaso sigue?", "difficulty": 1, "explanation_md": "¡Correcto! El patrón es chico, grande, chico, grande... El último era grande, así que el siguiente es chico. ¡Bien hecho, Zara!", "audio_segment_id": "s1-pattern-vasos.prompt"}], "schema_version": 1}', '{"s1-pattern-vasos": {"correct": {"0": "opt1"}}}', '{"units": {"s1-pattern-vasos.prompt": {"url": "http://localhost:4006/files/lesson-audio/12fe9aa7de8cbfed6787bb5aff6b62179021eeff7302cc96088e1817e8cf93d6.mp3", "hash": "32251a489dad202dadf0af48d3433b152628533b43d0216a7f97354feb7f59c4", "bytes": 81936, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/12fe9aa7de8cbfed6787bb5aff6b62179021eeff7302cc96088e1817e8cf93d6.mp3", "duration_ms": 13600}, "s1-pattern-vasos.explanation": {"url": "http://localhost:4006/files/lesson-audio/71844f2c9f0e48ec830af7ca43d3bc6bb3192098e57d7bf4bc1f844edd6d320c.mp3", "hash": "90232590607f6346406afc5adad782caf6782632be3201c962cc5cbd16e56aa5", "bytes": 45504, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/71844f2c9f0e48ec830af7ca43d3bc6bb3192098e57d7bf4bc1f844edd6d320c.mp3", "duration_ms": 7520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "pattern-complete", "title": "Complete o padrão dos copos", "locale": "pt-BR", "subject": "mixed", "objectives": ["Completar o padrão da fileira de copos do balcão (pequeno, grande, pequeno, grande…): descobrir o que vem a seguir."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-pattern-vasos", "xp": 0, "type": "pattern_complete", "hints": ["O padrão alterna entre pequeno e grande. Qual foi o último copo que você viu?"], "title": "Padrão de copos", "payload": {"options": [{"id": "opt1", "icon": "cup_small", "tint": "primary"}, {"id": "opt2", "icon": "cup_large", "tint": "primary"}, {"id": "opt3", "icon": "cup_medium", "tint": "primary"}], "sequence": [{"icon": "cup_small", "tint": "primary"}, {"icon": "cup_large", "tint": "primary"}, {"icon": "cup_small", "tint": "primary"}, {"icon": "cup_large", "tint": "primary"}], "missing_slots": 1}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Agora que já organizamos o dia de vendas, vamos ver como a Zara organiza os copos para seus clientes ao meio-dia! A Zara está arrumando os copos no balcão. Observe o padrão: **pequeno**, **grande**, **pequeno**, **grande**... Qual copo vem a seguir?", "difficulty": 1, "explanation_md": "Correto! O padrão é pequeno, grande, pequeno, grande... O último era grande, então o próximo é pequeno. Muito bem, Zara!", "audio_segment_id": "s1-pattern-vasos.prompt"}], "schema_version": 1}', '{"s1-pattern-vasos": {"correct": {"0": "opt1"}}}', '{"units": {"s1-pattern-vasos.prompt": {"url": "http://localhost:4006/files/lesson-audio/7d5b8d9da5eb9e2a7825e737bfcb3b29f159f08273924710f66c5ce7891860bd.mp3", "hash": "51494ffbfc7ce2670393544e96798fa257164108b6faa5fbfb8177150a212b92", "bytes": 95904, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/7d5b8d9da5eb9e2a7825e737bfcb3b29f159f08273924710f66c5ce7891860bd.mp3", "duration_ms": 15920}, "s1-pattern-vasos.explanation": {"url": "http://localhost:4006/files/lesson-audio/de9c87f73fbe15aeb8c929f81df8b223e4ca9c98ba509116d32e4c7e42825ca7.mp3", "hash": "41c7f9d7a4de6428affb5de038bc4f711dc6ac5aeb61dc3035ed27fc9f3c9733", "bytes": 56448, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/de9c87f73fbe15aeb8c929f81df8b223e4ca9c98ba509116d32e4c7e42825ca7.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "order-steps", "title": "Order the lemonade steps", "locale": "en-US", "subject": "mixed", "objectives": ["Order steps, match products with prices, and classify purchases between stand needs and treats that can wait."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-order-steps", "xp": 0, "type": "order_steps", "hints": ["Think: what do you do first with the lemons?", "After squeezing, what liquid do you add?"], "title": "Mixed-up recipe", "payload": {"items": [{"id": "step1", "text_md": "Squeeze lemons"}, {"id": "step2", "text_md": "Add water"}, {"id": "step3", "text_md": "Sweeten"}, {"id": "step4", "text_md": "Taste"}, {"id": "step5", "text_md": "Serve"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Let''s remember: yesterday we helped Liruf decide what to buy for his stand. Remember that lemons were a NEED for the stand, so today we use them to make lemonade! We bought 3 lemons that cost $6 in total. Now, help Liruf order the steps to make lemonade. Drag the cards into the correct order: first squeeze lemons, then add water, sweeten, taste, and serve.", "difficulty": 1, "explanation_md": "Well done! The correct order is: squeeze lemons, add water, sweeten, taste, and serve. Liruf can now prepare the lemonade.", "audio_segment_id": "s1-order-steps.prompt"}], "schema_version": 1}', '{"s1-order-steps": {"order": ["step1", "step2", "step3", "step4", "step5"]}}', '{"units": {"s1-order-steps.prompt": {"url": "http://localhost:4006/files/lesson-audio/28c4abb31461489de07784faadce40df57b499efc59a9940a3539a9210dae06f.mp3", "hash": "ff548e61144bdd6cbc5cf82bd5c1d6e038c3796f64461ec46edcc8e861fb24c7", "bytes": 120384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/28c4abb31461489de07784faadce40df57b499efc59a9940a3539a9210dae06f.mp3", "duration_ms": 20000}, "s1-order-steps.explanation": {"url": "http://localhost:4006/files/lesson-audio/072202868b2f114b4721cbef1e1db41762623425cb03979b316b15391ee157d0.mp3", "hash": "5d12a11eabb501656b2b31b77f6decaa8af4b80e45100b27c93448bf08b00371", "bytes": 50688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/072202868b2f114b4721cbef1e1db41762623425cb03979b316b15391ee157d0.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "order-steps", "title": "Ordene os passos da limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar passos, combinar produtos com preços e classificar compras entre necessidades da barraca e gostos que podem esperar."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-order-steps", "xp": 0, "type": "order_steps", "hints": ["Pense: o que você faz primeiro com os limões?", "Depois de espremer, que líquido você adiciona?"], "title": "Receita bagunçada", "payload": {"items": [{"id": "step1", "text_md": "Espremer limões"}, {"id": "step2", "text_md": "Adicionar água"}, {"id": "step3", "text_md": "Adoçar"}, {"id": "step4", "text_md": "Provar"}, {"id": "step5", "text_md": "Servir"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembremos: ontem ajudamos a Liruf a decidir o que comprar para sua barraca. Lembre-se de que os limões eram uma NECESSIDADE para a barraca, então hoje os usamos para fazer limonada! Compramos 3 limões que custaram $6 no total. Agora, ajude a Liruf a ordenar os passos para fazer limonada. Arraste os cartões na ordem correta: primeiro espremer limões, depois adicionar água, adoçar, provar e servir.", "difficulty": 1, "explanation_md": "Muito bem! A ordem correta é: espremer limões, adicionar água, adoçar, provar e servir. Liruf já pode preparar a limonada.", "audio_segment_id": "s1-order-steps.prompt"}], "schema_version": 1}', '{"s1-order-steps": {"order": ["step1", "step2", "step3", "step4", "step5"]}}', '{"units": {"s1-order-steps.prompt": {"url": "http://localhost:4006/files/lesson-audio/a231916f1fab702af8794449d166fbc609952721567db18b90dc1440e44c59bc.mp3", "hash": "81b1f554e103781ef662f314c24a122299b26d91d2c2c3608de49b6003ed3041", "bytes": 165888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a231916f1fab702af8794449d166fbc609952721567db18b90dc1440e44c59bc.mp3", "duration_ms": 27600}, "s1-order-steps.explanation": {"url": "http://localhost:4006/files/lesson-audio/46f4d2666c8adecfa7cf8eec01ef78f05f6164cc4cddf09f376e6ec586217cf5.mp3", "hash": "751698b02df8794452f29ea83f8fc35149642dc435b817f1a796d9a7c277c611", "bytes": 64656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/46f4d2666c8adecfa7cf8eec01ef78f05f6164cc4cddf09f376e6ec586217cf5.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Put together today''s purchase with 20 pesos", "locale": "en-US", "subject": "mixed", "objectives": ["Count money with 1, 2, 5, and 10 peso coins", "Calculate change from a 20-peso bill", "Plan how many weeks until the goal of 80 pesos"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 0, "type": "budget_fit", "hints": ["Add up the prices of the ingredients you choose and make sure they don''t exceed 20 pesos."], "title": "Market purchase", "payload": {"items": [{"id": "limones", "icon": "lemon", "need": true, "label": "Lemons (5 pesos)", "price": 5}, {"id": "azucar", "icon": "sugar", "need": false, "label": "Sugar (3 pesos)", "price": 3}, {"id": "hielo", "icon": "ice", "need": false, "label": "Ice (2 pesos)", "price": 2}, {"id": "vasos", "icon": "cup", "need": true, "label": "Cups (4 pesos)", "price": 4}, {"id": "agua", "icon": "water", "need": false, "label": "Water (1 peso)", "price": 1}, {"id": "menta", "icon": "mint", "need": false, "label": "Mint (6 pesos)", "price": 6}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf has a **20-peso bill** and wants to buy ingredients for his lemonade stand. Help him choose which ones fit his budget. Remember, you compared lemon prices earlier to spend less; now it''s time to put together the purchase.", "difficulty": 1, "explanation_md": "Great job! You chose a combination that adds up to exactly 20 pesos or less, so Liruf can buy without going over.", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/e1952bacfe50613a845db028b2011fa4fac51fd3b628331200cf904d75c9a04a.mp3", "hash": "261d9ce6679867814ae21c041083df6baca7576b2f152f543dd2fc240caf68ab", "bytes": 71856, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e1952bacfe50613a845db028b2011fa4fac51fd3b628331200cf904d75c9a04a.mp3", "duration_ms": 11920}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/5bb1f853fa4692e3ea7cf06c33aa2db83046127975a353e6de8d09445d51a2b4.mp3", "hash": "228aaf83a31976f3e29e38e64402b43df1b21efe884b4d42335c2b6b1c0ae861", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5bb1f853fa4692e3ea7cf06c33aa2db83046127975a353e6de8d09445d51a2b4.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Armar la compra del día con 20 pesos", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar dinero con monedas de 1, 2, 5 y 10", "Calcular cambio de un billete de 20", "Planear cuántas semanas faltan para la meta de 80 pesos"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-budget-fit", "xp": 0, "type": "budget_fit", "hints": ["Suma los precios de los ingredientes que elijas y asegúrate de que no pasen de 20 pesos."], "title": "Compra en el mercado", "payload": {"items": [{"id": "limones", "icon": "lemon", "need": true, "label": "Limones (5 pesos)", "price": 5}, {"id": "azucar", "icon": "sugar", "need": false, "label": "Azúcar (3 pesos)", "price": 3}, {"id": "hielo", "icon": "ice", "need": false, "label": "Hielo (2 pesos)", "price": 2}, {"id": "vasos", "icon": "cup", "need": true, "label": "Vasos (4 pesos)", "price": 4}, {"id": "agua", "icon": "water", "need": false, "label": "Agua (1 peso)", "price": 1}, {"id": "menta", "icon": "mint", "need": false, "label": "Menta (6 pesos)", "price": 6}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf tiene un billete de **20 pesos** y quiere comprar ingredientes para su puesto de limonada. Ayúdale a elegir cuáles caben en su presupuesto. Recuerda que antes comparaste precios de limones para gastar menos; ahora es momento de armar la compra.", "difficulty": 1, "explanation_md": "¡Bien hecho! Elegiste una combinación que suma exactamente 20 pesos o menos, así que Liruf puede comprar sin pasarse.", "audio_segment_id": "s1-budget-fit.prompt"}], "schema_version": 1}', '{"s1-budget-fit": {}}', '{"units": {"s1-budget-fit.prompt": {"url": "http://localhost:4006/files/lesson-audio/51067e2bccd90aed683a098a0bcfd3a151610e1b66251e5e043642599c588cb9.mp3", "hash": "bb4570a13f6d884e4e438150a8f2e1f0b1f3d807d18ee6a8d72fb242bd54887e", "bytes": 97344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/51067e2bccd90aed683a098a0bcfd3a151610e1b66251e5e043642599c588cb9.mp3", "duration_ms": 16160}, "s1-budget-fit.explanation": {"url": "http://localhost:4006/files/lesson-audio/66020f8bf6180d3b65175e5ec347af725e2c973b55b6c0169bcbdf397a2c11d5.mp3", "hash": "789f09471a2411f6b300f28ef4cc023626a79160190bb386e69f24fa7080816b", "bytes": 49824, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/66020f8bf6180d3b65175e5ec347af725e2c973b55b6c0169bcbdf397a2c11d5.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contar moedas da primeira venda", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas de 1 e 2 pesos para formar 5 pesos exatos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 0, "type": "coin_count", "hints": ["Agrupe as moedas de 1: 1+1+1 = 3. Depois some a de 2: 3+2 = 5."], "title": "Contar as moedas da primeira venda", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que sabemos que Liruf já tem 20 pesos e precisa chegar a 80, cada venda conta! Hoje ele recebeu moedas pela sua primeira venda: Liruf vendeu seu primeiro copo de limonada. O cliente pagou com estas moedas: **1, 1, 2, 1**. Quanto dinheiro Liruf recebeu no total?", "difficulty": 1, "explanation_md": "Muito bem! 1+1+1+2 = 5 pesos exatos, o preço do copo.", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/23fed0657826bcded5fa9b419c51137c9659fe055935b1465159d6f7eee13dcf.mp3", "hash": "4be349f7563960ee8a35d7409b326f419d1a00a829b6e786d8a1d80a4836a2a1", "bytes": 113184, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/23fed0657826bcded5fa9b419c51137c9659fe055935b1465159d6f7eee13dcf.mp3", "duration_ms": 18800}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/86f6c6aacabc450c5e5f5d8144a17137dc61339f54c08e66ce3163b85ad47c78.mp3", "hash": "a0cc682cab7de6b32c2e8902c8ac85d6ebf28dc4a0e83a2e7b9f7971cd8e9a5b", "bytes": 42048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/86f6c6aacabc450c5e5f5d8144a17137dc61339f54c08e66ce3163b85ad47c78.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "key-ideas", "title": "Las tres reglas de oro del pequeño vendedor", "locale": "es-MX", "subject": "mixed", "objectives": ["Fijar las 3 ideas clave del plan: tener una meta (80 pesos), ofrecer algo que la gente quiera (limonada fría), y guardar lo ganado."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": ["Recuerda que la meta de Liruf es la guitarra de 80 pesos.", "Piensa en lo que Liruf ofrece a sus vecinos."], "title": "Las tres reglas de oro", "payload": {"ideas": [{"icon": "target", "title": "Tener una meta", "body_md": "Liruf quiere una guitarra de **80 pesos**. Esa es su meta."}, {"icon": "lemonade", "title": "Ofrecer algo que la gente quiera", "body_md": "Vender **limonada fría** a 5 pesos el vaso. ¡A todos les gusta!"}, {"icon": "piggy_bank", "title": "Guardar lo ganado", "body_md": "Cada peso que ganes, guárdalo para tu meta."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "¡Hola! Ayer vimos que Liruf quiere juntar 80 pesos vendiendo vasos de limonada a 5 pesos para comprar su guitarra. Hoy, Rho resume las tres reglas clave de ese plan. Rho dibuja en su pizarra las tres reglas de oro del pequeño vendedor. Ayuda a completarlas. ¿Cuántos vasos debe vender Liruf?", "difficulty": 1, "explanation_md": "¡Exacto! Rho escribió las tres ideas clave: tener una meta de 80 pesos, ofrecer limonada fría que la gente quiera, y guardar lo ganado.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/62e5fbc14c57613141edf3a2916fc980505dc561883fcb76008a6f11a404552e.mp3", "hash": "7326068db84a65baa9c4329cc2c4ac1cc8881e702a22f594ec2838dd88be9737", "bytes": 24768, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/62e5fbc14c57613141edf3a2916fc980505dc561883fcb76008a6f11a404552e.mp3", "duration_ms": 4080}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/904e4cddeb59e9863c5b93746007f33248fa54363764afd3d0173db77347d2a5.mp3", "hash": "ee45cc1d8179d3febb63a7bb2dd7e70b87f9c3b2648f32cb8c04c20d6de52a0e", "bytes": 32544, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/904e4cddeb59e9863c5b93746007f33248fa54363764afd3d0173db77347d2a5.mp3", "duration_ms": 5360}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/389ebe78def9f3dd82fd04798369fcfdab1abfbe92f27cf8875218e036be43e0.mp3", "hash": "13f62ab6cf7527ddf97e86f04bd74a1adf83637a14a0b0dff6fb904018545659", "bytes": 18576, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/389ebe78def9f3dd82fd04798369fcfdab1abfbe92f27cf8875218e036be43e0.mp3", "duration_ms": 3040}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/6d8968e3bdb8b75670b222964e7aa364c0a73eaf247e5489054f2e8f37d72adf.mp3", "hash": "60c56ef87c4131f0587991c95c3e48a2bfcd1237ae5904b0bc26b9cb95c976e6", "bytes": 125568, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/6d8968e3bdb8b75670b222964e7aa364c0a73eaf247e5489054f2e8f37d72adf.mp3", "duration_ms": 20880}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/2649f8f33673682a0fbe4246bc7f33f4fc1c10bd6e34bf4086a7b95182136174.mp3", "hash": "b71c8b898a0f98a85a116884d7b7a870de93670545df05c87e89331748af270b", "bytes": 62784, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2649f8f33673682a0fbe4246bc7f33f4fc1c10bd6e34bf4086a7b95182136174.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "key-ideas", "title": "As três regras de ouro do pequeno vendedor", "locale": "pt-BR", "subject": "mixed", "objectives": ["Fixar as 3 ideias-chave do plano: ter uma meta (80 pesos), oferecer algo que as pessoas queiram (limonada gelada) e guardar o que ganhou."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": ["Lembre-se de que a meta de Liruf é o violão de 80 pesos.", "Pense no que Liruf oferece aos seus vizinhos."], "title": "As três regras de ouro", "payload": {"ideas": [{"icon": "target", "title": "Ter uma meta", "body_md": "Liruf quer um violão de **80 pesos**. Essa é a sua meta."}, {"icon": "lemonade", "title": "Oferecer algo que as pessoas queiram", "body_md": "Vender **limonada gelada** a 5 pesos o copo. Todo mundo gosta!"}, {"icon": "piggy_bank", "title": "Guardar o que ganhou", "body_md": "Cada peso que você ganhar, guarde para sua meta."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Olá! Ontem vimos que Liruf quer juntar 80 pesos vendendo copos de limonada a 5 pesos para comprar seu violão. Hoje, Rho resume as três regras-chave desse plano. Rho desenha em seu quadro as três regras de ouro do pequeno vendedor. Ajude a completá-las. Quantos copos Liruf deve vender?", "difficulty": 1, "explanation_md": "Exato! Rho escreveu as três ideias-chave: ter uma meta de 80 pesos, oferecer limonada gelada que as pessoas queiram e guardar o que ganhou.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/13a1ed3b3468d32831c446e576f725da3cbf1b464619df9bf802308eb35699e1.mp3", "hash": "fbeea5e4f118bbb39f5ec9daa5e2cc153febc1606efaa9100d4c0a61b80376ce", "bytes": 31104, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/13a1ed3b3468d32831c446e576f725da3cbf1b464619df9bf802308eb35699e1.mp3", "duration_ms": 5120}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/bffaadbc55d1baf245dc4fb8e22cf5af08e914d8af0b59d2101ffc788aed449c.mp3", "hash": "2f2d195eb88eaae8682fe2684e3304db90bdce2c40389e88ee561cfd36d0352b", "bytes": 32544, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/bffaadbc55d1baf245dc4fb8e22cf5af08e914d8af0b59d2101ffc788aed449c.mp3", "duration_ms": 5360}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/edbb90012f0ad3708851f5fc1377c369b72d731de5997942264e1655cb44ace9.mp3", "hash": "5b75f8fcabf72f30090dc194b7107391119d7a3d1f2f55740103e9380f4690a5", "bytes": 22464, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/edbb90012f0ad3708851f5fc1377c369b72d731de5997942264e1655cb44ace9.mp3", "duration_ms": 3680}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/26e309ab5885e61c8e7d82787d64257ee4a70bb889c46bc48acf5a6220c32942.mp3", "hash": "1832ba4187f8de51032830484cc2d86247eb2abad23d9c5991e640768db0827e", "bytes": 128016, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/26e309ab5885e61c8e7d82787d64257ee4a70bb889c46bc48acf5a6220c32942.mp3", "duration_ms": 21280}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/cc3d25f0475ee59e9896fd490ecde5b3604a9ed3483fb00e9237b30d10c17ccc.mp3", "hash": "baeae7f4b3d608e2135964cf885265c7a43093258ed9f33a177524c2c79f2459", "bytes": 73728, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/cc3d25f0475ee59e9896fd490ecde5b3604a9ed3483fb00e9237b30d10c17ccc.mp3", "duration_ms": 12240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Counting coins from the first sale", "locale": "en-US", "subject": "mixed", "objectives": ["Counting 1 and 2 peso coins to make exactly 5 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 0, "type": "coin_count", "hints": ["Group the 1-peso coins: 1+1+1 = 3. Then add the 2-peso coin: 3+2 = 5."], "title": "Count the coins from the first sale", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that we know Liruf already has 20 pesos and needs to reach 80, every sale counts! Today he received coins from his first sale: Liruf sold his first glass of lemonade. The customer paid with these coins: **1, 1, 2, 1**. How much money did Liruf receive in total?", "difficulty": 1, "explanation_md": "Great job! 1+1+1+2 = 5 exact pesos, the price of the glass.", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/97fcc5c80126982b6908f9b9b8f3dc9455e035e53cfd19d5f8bf0018d314a5b7.mp3", "hash": "1e3f21c9f720eae8469069f9fae377ecf3b4d87ddf98e8b535a03ec5a1eba45e", "bytes": 99648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/97fcc5c80126982b6908f9b9b8f3dc9455e035e53cfd19d5f8bf0018d314a5b7.mp3", "duration_ms": 16560}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/27b86189c173e625f0dc7174dadefa0fbca0a0a876833b7fb550499644922b01.mp3", "hash": "acd70085f649e49ced7a8d7d22299cbad98affb0fccb9b1b30318da126a470fe", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/27b86189c173e625f0dc7174dadefa0fbca0a0a876833b7fb550499644922b01.mp3", "duration_ms": 5280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contar monedas de la primera venta", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas de 1 y 2 pesos para formar 5 pesos exactos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-coin-count", "xp": 0, "type": "coin_count", "hints": ["Agrupa las monedas de 1: 1+1+1 = 3. Luego suma la de 2: 3+2 = 5."], "title": "Contar las monedas de la primera venta", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que sabemos que Liruf ya tiene 20 pesos y necesita llegar a 80, ¡cada venta cuenta! Hoy recibió monedas por su primera venta: Liruf vendió su primer vaso de limonada. El cliente pagó con estas monedas: **1, 1, 2, 1**. ¿Cuánto dinero recibió Liruf en total?", "difficulty": 1, "explanation_md": "¡Muy bien! 1+1+1+2 = 5 pesos exactos, el precio del vaso.", "audio_segment_id": "s1-coin-count.prompt"}], "schema_version": 1}', '{"s1-coin-count": {}}', '{"units": {"s1-coin-count.prompt": {"url": "http://localhost:4006/files/lesson-audio/e31b1714c982b9427a4bf38260336e5b95e737a195e576e4ba022127a6898e9b.mp3", "hash": "be47084bc84f6e80972d0bbe3639eb51866a6b33bfb66acca9a635eac0b53910", "bytes": 119376, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e31b1714c982b9427a4bf38260336e5b95e737a195e576e4ba022127a6898e9b.mp3", "duration_ms": 19840}, "s1-coin-count.explanation": {"url": "http://localhost:4006/files/lesson-audio/acc567ef429ce04312c576a4aac4f4924e94c5852fb326c5eb3c46ab3a43e315.mp3", "hash": "e2de715433c5859872047b64902cc04543fd166c061e4a3714f361e3842f66bf", "bytes": 34416, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/acc567ef429ce04312c576a4aac4f4924e94c5852fb326c5eb3c46ab3a43e315.mp3", "duration_ms": 5680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Encuentra el error en la cuenta de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar un error en una suma de ventas", "Leer una gráfica simple de vasos vendidos por día", "Reconocer señales de un mal trato"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 0, "type": "spot_error", "hints": ["Revisa cada paso de la suma. ¿Alguna cifra parece demasiado grande?", "Si vendió 3 vasos a 5 MXN cada uno, el total debe ser 15, no 20."], "title": "La cuenta que no cuadra", "payload": {"steps": [{"id": "step1", "text_md": "Vendió 3 vasos de limonada a 5 MXN cada uno."}, {"id": "step2", "text_md": "Anotó: 5 + 5 + 5 = 20"}, {"id": "step3", "text_md": "Escribió el total: 20 MXN"}], "context_md": "Asomarse a un secreto del ahorro: si la alcancía del banco ''agradece'' con moneditas extra por esperar, el dinero guardado crece solito con el tiempo. Pero hoy Liruf tiene un problema: al cerrar su puesto de limonada, su cuenta no cuadra. Ayúdale a encontrar el paso equivocado."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ayuda a Liruf a encontrar el error en su cuenta.", "difficulty": 1, "explanation_md": "¡Exacto! Liruf sumó 5 + 5 + 5 y obtuvo 20, pero 5+5+5 es 15. El error está en el paso 3, donde escribió 20 en lugar de 15.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step2"], "correction_md": "El error está en el paso 2: 5 + 5 + 5 = 15, no 20. Liruf debe corregir el total a 15 MXN."}}', '{"units": {"s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/807c086920d1a95d6de1a0fab8b2cf36ec72d72fb9ccf75ca91459eea43898f4.mp3", "hash": "73d0aed3c6fbb1205e2f1e3e98cc56844419fe86ed00637e4994319470f91727", "bytes": 20016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/807c086920d1a95d6de1a0fab8b2cf36ec72d72fb9ccf75ca91459eea43898f4.mp3", "duration_ms": 3280}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/13ea63f047ba9b7894d884e01c9431a51c6259540cebb617ab46798628c5e559.mp3", "hash": "3aed008f15f33dfb92150d99eca48cb7792bd8737ac966a1ed100d1e79f78a9b", "bytes": 73296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/13ea63f047ba9b7894d884e01c9431a51c6259540cebb617ab46798628c5e559.mp3", "duration_ms": 12160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Encontre o erro na conta de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar um erro em uma soma de vendas", "Ler um gráfico simples de copos vendidos por dia", "Reconhecer sinais de um mau negócio"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 0, "type": "spot_error", "hints": ["Revise cada passo da soma. Algum número parece grande demais?", "Se ele vendeu 3 copos a 5 MXN cada, o total deve ser 15, não 20."], "title": "A conta que não fecha", "payload": {"steps": [{"id": "step1", "text_md": "Ele vendeu 3 copos de limonada a 5 MXN cada."}, {"id": "step2", "text_md": "Anotou: 5 + 5 + 5 = 20"}, {"id": "step3", "text_md": "Escreveu o total: 20 MXN"}], "context_md": "Descubra um segredo da poupança: se o cofrinho do banco ''agradece'' com moedinhas extras por esperar, o dinheiro guardado cresce sozinho com o tempo. Mas hoje Liruf tem um problema: ao fechar sua barraca de limonada, a conta não fecha. Ajude-o a encontrar o passo errado."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ajude Liruf a encontrar o erro na conta dele.", "difficulty": 1, "explanation_md": "Exato! Liruf somou 5 + 5 + 5 e obteve 20, mas 5+5+5 é 15. O erro está no passo 3, onde ele escreveu 20 em vez de 15.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["step2"], "correction_md": "El error está en el paso 2: 5 + 5 + 5 = 15, no 20. Liruf debe corregir el total a 15 MXN."}}', '{"units": {"s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/a0f9989823f768ea05de55bcdb183d65d2c306a9518f0cef5fce3935776f3b38.mp3", "hash": "1a8bd523481bdbe6a9d5b386037d825974b5484b6eba88c08a069ee480452454", "bytes": 19584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a0f9989823f768ea05de55bcdb183d65d2c306a9518f0cef5fce3935776f3b38.mp3", "duration_ms": 3200}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/f704d6bf3380789e83d506976275010941e957935c021a6ee3cbc129e9e503d4.mp3", "hash": "681313b9b0831e4edc0ad774fa56c430d0d37da5310fa2a7251570c3a7bf3424", "bytes": 78048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f704d6bf3380789e83d506976275010941e957935c021a6ee3cbc129e9e503d4.mp3", "duration_ms": 12960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Cacería de errores: la promo que no cuadra", "locale": "es-MX", "subject": "mixed", "objectives": ["Encontrar el error en un cartel de promoción y corregirlo usando operaciones básicas."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-hunt", "xp": 0, "type": "debug_hunt", "hints": [], "title": "La promo que no cuadra", "payload": {"blocks": [{"id": "b1", "text_md": "**Cartel actual:** ''2 vasos por 8 pesos''"}, {"id": "b2", "text_md": "**Precio suelto:** 1 vaso = 5 pesos"}, {"id": "b3", "text_md": "**¿Cuál es el error?**"}], "intro_md": "¿Recuerdas cómo ayudamos al carrito a usar menos pasos? Ahora ayudaremos a Liruf a usar menos pesos. Mira: un vaso suelto cuesta 5 pesos. Dos vasos sueltos cuestan 10 pesos. Pero el cartel de Liruf dice ''2 vasos por 8 pesos''. ¡Eso es más barato que 10 pesos! ¿Dónde está el error?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ayuda a Liruf a encontrar el error en el cartel de promoción.", "difficulty": 1, "explanation_md": "¡Exacto! El cartel dice ''2 vasos por 8 pesos'', pero cada vaso cuesta 5 pesos suelto. Dos vasos sueltos costarían 10 pesos, así que la promo debería ser más barata, no más cara. La corrección es ''2 vasos por 9 pesos'' (o menos).", "audio_segment_id": "s1-debug-hunt.prompt"}], "schema_version": 1}', '{"s1-debug-hunt": {"fix_md": "El cartel debe decir ''2 vasos por 9 pesos'' (o menos) para que sea más barato que comprarlos sueltos (10 pesos).", "bug_ids": ["b1"]}}', '{"units": {"s1-debug-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/9544d68346d2da77341ade1ab9678b4a604cab1afc57a158747448bd6f163cd3.mp3", "hash": "7d59ddd83d0836aea5aed70f4132ab2f9b17e4a7382c3266d3b5e6338c556ebd", "bytes": 24768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9544d68346d2da77341ade1ab9678b4a604cab1afc57a158747448bd6f163cd3.mp3", "duration_ms": 4080}, "s1-debug-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/202376bcfacb9f1e366e7c71520a30dc8bbcdb324da54aa6c36b0231412c45a3.mp3", "hash": "cb051f9d3e077ea0e0d6b3170ad265597c941311b9e86da04a992890a138f88b", "bytes": 102528, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/202376bcfacb9f1e366e7c71520a30dc8bbcdb324da54aa6c36b0231412c45a3.mp3", "duration_ms": 17040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Caça aos erros: a promoção que não fecha", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encontrar o erro em um cartaz de promoção e corrigi-lo usando operações básicas."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-hunt", "xp": 0, "type": "debug_hunt", "hints": [], "title": "A promoção que não fecha", "payload": {"blocks": [{"id": "b1", "text_md": "**Cartaz atual:** ''2 copos por 8 pesos''"}, {"id": "b2", "text_md": "**Preço avulso:** 1 copo = 5 pesos"}, {"id": "b3", "text_md": "**Qual é o erro?**"}], "intro_md": "Você lembra como ajudamos o carrinho a usar menos passos? Agora vamos ajudar a Liruf a usar menos pesos. Olha: um copo avulso custa 5 pesos. Dois copos avulsos custam 10 pesos. Mas o cartaz da Liruf diz ''2 copos por 8 pesos''. Isso é mais barato que 10 pesos! Onde está o erro?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ajude a Liruf a encontrar o erro no cartaz de promoção.", "difficulty": 1, "explanation_md": "Exato! O cartaz diz ''2 copos por 8 pesos'', mas cada copo custa 5 pesos avulso. Dois copos avulsos custariam 10 pesos, então a promoção deveria ser mais barata, não mais cara. A correção é ''2 copos por 9 pesos'' (ou menos).", "audio_segment_id": "s1-debug-hunt.prompt"}], "schema_version": 1}', '{"s1-debug-hunt": {"fix_md": "El cartel debe decir ''2 vasos por 9 pesos'' (o menos) para que sea más barato que comprarlos sueltos (10 pesos).", "bug_ids": ["b1"]}}', '{"units": {"s1-debug-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/c8df66029a4c4442fa1e4c49fb92d413c4f4c230aec2b171c77bbe708f0ae58b.mp3", "hash": "265fa889d43a4421c8d92972549c11379cf60786a3a3f87c5143b44bcbaf0811", "bytes": 25344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c8df66029a4c4442fa1e4c49fb92d413c4f4c230aec2b171c77bbe708f0ae58b.mp3", "duration_ms": 4160}, "s1-debug-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/3831ff05d7e51bfd179b46f144d488853fd82d79687eb23f7c004e6e0ad33c08.mp3", "hash": "a781932785157be7b94d00ec35d8169b309400caf3f2163f086f2e0771985c39", "bytes": 106416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3831ff05d7e51bfd179b46f144d488853fd82d79687eb23f7c004e6e0ad33c08.mp3", "duration_ms": 17680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "match-pairs", "title": "Empareja los precios correctos", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar pasos, emparejar productos con precios y clasificar compras entre necesidades del puesto y gustos que pueden esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 5, "type": "match_pairs", "hints": ["Recuerda: el vaso chico cuesta 5 pesos, la jarra cuesta 20 y la galleta cuesta 3."], "title": "Empareja los precios", "payload": {"left": [{"id": "cup", "text_md": "Vaso chico de limonada"}, {"id": "pitcher", "text_md": "Jarra de limonada"}, {"id": "cookie", "text_md": "Galleta"}], "right": [{"id": "price5", "text_md": "5 pesos"}, {"id": "price20", "text_md": "20 pesos"}, {"id": "price3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ayer vendiste tres vasos a 5 pesos cada uno, ¡y sumaste 15 pesos! Hoy, Liruf necesita emparejar los precios correctamente para seguir vendiendo. El viento tiró las etiquetas de precios. Ayuda a Liruf a emparejar cada producto con su precio correcto.", "difficulty": 1, "explanation_md": "¡Muy bien! El vaso chico cuesta 5 pesos, la jarra 20 y la galleta 3. Así Liruf puede vender sin confusión.", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["cup", "price5"], ["pitcher", "price20"], ["cookie", "price3"]]}}', '{"units": {"s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/c2b5e8a2afdb2f2957bfeaec4d71bd04a7e097e4a3ebe3c67a81fb30e72b1567.mp3", "hash": "e99cf39eb61d4103bc746e7c44fd8a5d85277e9794a8838c078e9b4be871afe0", "bytes": 100224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c2b5e8a2afdb2f2957bfeaec4d71bd04a7e097e4a3ebe3c67a81fb30e72b1567.mp3", "duration_ms": 16640}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/a3590f4bb4484e1f5c62f26024a8a9d8fa6802b39dfdde06b622c3329e167079.mp3", "hash": "904b29a2213bb63658f8cc73ee02d2b48620cd80d715c99615c6a2e1877165d1", "bytes": 52128, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a3590f4bb4484e1f5c62f26024a8a9d8fa6802b39dfdde06b622c3329e167079.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "equation-builder", "title": "Build the afternoon sum", "locale": "en-US", "subject": "mixed", "objectives": ["Build the afternoon sum with chips: 5 + 5 + 5 = 15 pesos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ecuacion", "xp": 0, "type": "equation_builder", "hints": ["Start with the number 5, then the plus sign +, another 5, another +, and another 5."], "title": "Build the afternoon sum", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}], "target_result": 15}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Yesterday you counted the remaining lemons; today we''ll use those lemons to sell lemonade and add up what we earned. Rho gives you cards with numbers and plus signs (+). Build the afternoon sum yourself: three glasses of lemonade at 5 pesos each. What is the total?", "difficulty": 1, "explanation_md": "Correct! 5 + 5 + 5 = 15 pesos, the afternoon total. If you put another combination, check that the numbers and signs are in order.", "audio_segment_id": "s1-ecuacion.prompt"}], "schema_version": 1}', '{"s1-ecuacion": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-ecuacion.prompt": {"url": "http://localhost:4006/files/lesson-audio/98c1730de9c54519e86f255e7375b01efd5677d6922d6365a4099dcc8d902832.mp3", "hash": "f41af747fb00c740537bf18643d104337d74cd68599ff4e33ce516ccd73b9c22", "bytes": 116064, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/98c1730de9c54519e86f255e7375b01efd5677d6922d6365a4099dcc8d902832.mp3", "duration_ms": 19280}, "s1-ecuacion.explanation": {"url": "http://localhost:4006/files/lesson-audio/e0d30249ec0f8b3a549b9059809a37e073455e5b8e2649cc401ede87660ec641.mp3", "hash": "54522382022eb0d7287f074450e8fa9b9004ba95e54a339fe394733de5de9b87", "bytes": 69408, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/e0d30249ec0f8b3a549b9059809a37e073455e5b8e2649cc401ede87660ec641.mp3", "duration_ms": 11520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "equation-builder", "title": "Monte a soma da tarde", "locale": "pt-BR", "subject": "mixed", "objectives": ["Montar com fichas a soma da tarde: 5 + 5 + 5 = 15 reais"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ecuacion", "xp": 0, "type": "equation_builder", "hints": ["Comece com o número 5, depois o sinal +, outro 5, outro +, e outro 5."], "title": "Monte a soma da tarde", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}], "target_result": 15}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Ontem você contou os limões que sobraram; hoje vamos usar esses limões para vender limonada e somar o que ganhamos. Rho te dá cartões com números e sinais (+). Monte você mesmo a soma da tarde: três copos de limonada a 5 reais cada. Qual é o total?", "difficulty": 1, "explanation_md": "Correto! 5 + 5 + 5 = 15 reais, o total da tarde. Se você colocou outra combinação, revise se os números e sinais estão em ordem.", "audio_segment_id": "s1-ecuacion.prompt"}], "schema_version": 1}', '{"s1-ecuacion": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-ecuacion.prompt": {"url": "http://localhost:4006/files/lesson-audio/abf17fb5118b4e3c66b0a3b217835a19070988b518e35f3c111f18b135061785.mp3", "hash": "8a9253c89af98ddaf1d640d1758439b8bb82d514a2aea1e33fcc7d73ffcc8280", "bytes": 102096, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/abf17fb5118b4e3c66b0a3b217835a19070988b518e35f3c111f18b135061785.mp3", "duration_ms": 16960}, "s1-ecuacion.explanation": {"url": "http://localhost:4006/files/lesson-audio/a0613832583b2cbd82024186b5df76ef136575ebee7ead8b11188a2428765c2f.mp3", "hash": "8c0f2d253348ce8bca670a0822d5dea4b598421bfc579e0c67975994a39cc461", "bytes": 72288, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a0613832583b2cbd82024186b5df76ef136575ebee7ead8b11188a2428765c2f.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "rho"], "slug": "fact-opinion", "title": "Fatos e opiniões na barraca de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Separar fatos de opiniões em frases da barraca de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 0, "type": "fact_opinion", "hints": ["Um fato pode ser medido ou verificado, como ''o copo custa 5 reais''. Uma opinião expressa um gosto pessoal."], "title": "Fato ou opinião", "payload": {"statements": [{"id": "s1", "text_md": "O copo custa 5 reais."}, {"id": "s2", "text_md": "Minha limonada é a mais gostosa do mundo."}, {"id": "s3", "text_md": "Hoje vendi 12 copos de limonada."}, {"id": "s4", "text_md": "A limonada de Liruf é mais gostosa que a de Dina."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Ontem aprendemos que promessas como \\"te dou 100 reais amanhã\\" parecem suspeitas. Hoje veremos como distinguir entre o que é real (fato) e o que é apenas uma opinião, para não nos deixarmos enganar. Rho leu estas frases do dia. Quais são fatos que podem ser comprovados e quais são apenas opiniões?", "difficulty": 1, "explanation_md": "Muito bem! As frases que podem ser comprovadas são fatos. Por exemplo, ''o copo custa 5 reais'' é um fato porque você pode contar o dinheiro. As opiniões são gostos pessoais, como ''minha limonada é a mais gostosa''.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1", "s3"]}}', '{"units": {"s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/c320bc01b592b77016b7948ca2212ead8befade505ab332e3f3a4e7975ff3d5e.mp3", "hash": "249915a51922daad60292f0f50060ccaa1ff042e0d764f92950b62403c9284eb", "bytes": 131904, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/c320bc01b592b77016b7948ca2212ead8befade505ab332e3f3a4e7975ff3d5e.mp3", "duration_ms": 21920}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/446d6b5e4371a72007899d29d87757ae18536c4887eef6db49851dd66654d1e0.mp3", "hash": "5160b8b4b3f120b515eb8d79c9c1cb28910aa15db965faef686b67866b2911a3", "bytes": 101088, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/446d6b5e4371a72007899d29d87757ae18536c4887eef6db49851dd66654d1e0.mp3", "duration_ms": 16800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "Needs and wants at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Separate stand needs (lemons, ice) from personal wants (popsicle, comic): the stand eats first."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 0, "type": "needs_wants", "hints": ["Think: without this, can the stand keep selling lemonade?", "Needs help the stand work; wants are for you."], "title": "Need or want?", "payload": {"items": [{"id": "limones", "icon": "lemon", "text_md": "Lemons for lemonade"}, {"id": "hielo", "icon": "ice", "text_md": "Ice to chill the cups"}, {"id": "paleta", "icon": "lollipop", "text_md": "Strawberry popsicle"}, {"id": "comic", "icon": "book", "text_md": "Superhero comic"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "After splitting 10 pesos of profit between two piggy banks — one part for the guitar goal and another to restock ingredients — Liruf wants to buy a popsicle. But Dina reminds him: **the stand eats first**. Help Liruf separate what is a **need** for the stand (lemons, ice) from what is a personal **want** (popsicle, comic).", "difficulty": 1, "explanation_md": "Very good! Lemons and ice are needs because without them there is no lemonade. The popsicle and comic are personal wants. Remember: first the stand, then your treats.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/1d8975b080b4b2b28ee442244e1dd6f2e68ff74dca7711dba560c5c8052ef463.mp3", "hash": "d6fbc8aaf5d3d9ef243dba5e378dd2dc9dbf1e60a77baba145263f8b12727a2e", "bytes": 95328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1d8975b080b4b2b28ee442244e1dd6f2e68ff74dca7711dba560c5c8052ef463.mp3", "duration_ms": 15840}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/19e36210f7b819d4940ff3de6c6a71891568e9684e85287ac4caa2b44f96866e.mp3", "hash": "d1e564f9e58bf1c23f43b67f0ab898a1c0cf6159a30f28ce88e4f2fefab60eca", "bytes": 56016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/19e36210f7b819d4940ff3de6c6a71891568e9684e85287ac4caa2b44f96866e.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "Necessidades e desejos na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Separar necessidades da barraca (limões, gelo) de desejos pessoais (picolé, gibi): a barraca come primeiro."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 0, "type": "needs_wants", "hints": ["Pense: sem isso, a barraca pode continuar vendendo limonada?", "As necessidades ajudam a barraca a funcionar; os desejos são para você."], "title": "Necessidade ou desejo?", "payload": {"items": [{"id": "limones", "icon": "lemon", "text_md": "Limões para a limonada"}, {"id": "hielo", "icon": "ice", "text_md": "Gelo para gelar os copos"}, {"id": "paleta", "icon": "lollipop", "text_md": "Picolé de morango"}, {"id": "comic", "icon": "book", "text_md": "Gibi de super-heróis"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Depois de dividir 10 pesos de lucro entre os dois cofrinhos — uma parte para a meta do violão e outra para repor ingredientes — Liruf quer comprar um picolé. Mas Dina lembra: **a barraca come primeiro**. Ajude Liruf a separar o que é **necessidade** da barraca (limões, gelo) do que é **desejo** pessoal (picolé, gibi).", "difficulty": 1, "explanation_md": "Muito bem! Os limões e o gelo são necessidades porque sem eles não há limonada. O picolé e o gibi são desejos pessoais. Lembre-se: primeiro a barraca, depois seus gostos.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/596ea5e5fe7697833b631e258323477b79bcd003871fa5efcc52e4a19166b342.mp3", "hash": "d183b7ef70389a14cf232ae50ace88d7e6d07e0d4779df2eb11e462a378fd815", "bytes": 128016, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/596ea5e5fe7697833b631e258323477b79bcd003871fa5efcc52e4a19166b342.mp3", "duration_ms": 21280}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/27e9286ec3e7ad7cc8bdc5104ce5ac429e9450415557194970ecc94df5b937d7.mp3", "hash": "9c3c61ea68a5486a60010b4e4e075c48f83bd6cd3d1c00fdf896256e8cb65978", "bytes": 78624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/27e9286ec3e7ad7cc8bdc5104ce5ac429e9450415557194970ecc94df5b937d7.mp3", "duration_ms": 13040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "The best decision with change", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the BEST decision when a customer pays with a 20 bill for a 5 glass: count the change calmly (not guess it or keep it)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 0, "type": "best_decision", "hints": ["The correct change is 15 MXN. How can you be sure you don''t make a mistake?"], "title": "Change from the 20 bill", "payload": {"options": [{"id": "a", "text_md": "Count the change calmly: 15 MXN, checking each coin.", "rationale_md": "This is the best decision because it ensures the change is correct and shows honesty."}, {"id": "b", "text_md": "Guess the change quickly and give 10 MXN.", "rationale_md": "Guessing can lead to mistakes. The correct change is 15 MXN, not 10. You could lose money or upset the customer."}, {"id": "c", "text_md": "Keep the bill and give no change.", "rationale_md": "Keeping the bill is dishonest and could make the customer not come back. Also, it''s important to give the correct change."}], "scenario_md": "A customer pays with a 20 MXN bill for a glass of lemonade that costs 5 MXN. Liruf must give change. What should he do?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf remembers what he learned: detecting what is NOT an ingredient of lemonade (lemons, sugar, water... and a ball?) helped him separate what actually costs money to produce. Now he has his first customer, who pays with a 20 MXN bill for a 5 MXN glass. What is the BEST decision?", "difficulty": 1, "explanation_md": "Exactly! Liruf counted 15 MXN calmly, making sure to give the correct change. That way he avoided mistakes and was honest.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"a": 1, "b": 0, "c": 0}}}', '{"units": {"s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/58be0f081760079b04fc4781bf83337f50272f048abfb70093f569231518eb13.mp3", "hash": "95540faf5936a7e3e6c88610d17e2475034b36a33518736312d5112a23f16ef6", "bytes": 99648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/58be0f081760079b04fc4781bf83337f50272f048abfb70093f569231518eb13.mp3", "duration_ms": 16560}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/cda71e18b5bf0a74e8c60ca94a9a009c7f0a4b32665e551ce840b404294edb82.mp3", "hash": "bf7ee6194c4096ae98de7b0b0d3280de28e9d8748ac58e20c3635b72b49d6fcd", "bytes": 49824, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cda71e18b5bf0a74e8c60ca94a9a009c7f0a4b32665e551ce840b404294edb82.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "La mejor decisión con el cambio", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir la MEJOR decisión cuando un cliente paga con billete de 20 por un vaso de 5: contar el cambio con calma (no adivinarlo ni quedárselo)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 0, "type": "best_decision", "hints": ["El cambio correcto es 15 MXN. ¿Cómo puedes estar seguro de que no te equivocas?"], "title": "El cambio del billete de 20", "payload": {"options": [{"id": "a", "text_md": "Contar el cambio con calma: 15 MXN, verificando cada moneda.", "rationale_md": "Esta es la mejor decisión porque asegura que el cambio sea correcto y demuestra honestidad."}, {"id": "b", "text_md": "Adivinar el cambio rápido y darle 10 MXN.", "rationale_md": "Adivinar puede llevar a errores. El cambio correcto es 15 MXN, no 10. Podrías perder dinero o enojar a la clienta."}, {"id": "c", "text_md": "Quedarse con el billete y no dar cambio.", "rationale_md": "Quedarse con el billete es deshonesto y podría hacer que la clienta no vuelva. Además, es importante dar el cambio correcto."}], "scenario_md": "Una clienta paga con un billete de 20 MXN por un vaso de limonada que cuesta 5 MXN. Liruf debe darle cambio. ¿Qué debe hacer?"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf recuerda lo que aprendió: detectar lo que NO es un ingrediente de la limonada (limones, azúcar, agua… ¿y una pelota?) le ayudó a separar lo que sí cuesta dinero producir. Ahora tiene su primera clienta, que paga con un billete de 20 MXN por un vaso de 5 MXN. ¿Cuál es la MEJOR decisión?", "difficulty": 1, "explanation_md": "¡Exacto! Liruf contó 15 MXN con calma, asegurándose de dar el cambio correcto. Así evitó errores y fue honesto.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"a": 1, "b": 0, "c": 0}}}', '{"units": {"s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/26fbe48440d0a228fd1e8a53c847a94820f662196aa2a12b67d9fde57f41006b.mp3", "hash": "39925f1db6a1755a1132eaf95778eba4899bb349eb2e5e312873fd8e9206f751", "bytes": 124128, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/26fbe48440d0a228fd1e8a53c847a94820f662196aa2a12b67d9fde57f41006b.mp3", "duration_ms": 20640}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/38e26103ed7a1b3cd02a9809626a202632d33fe86831687e0fece1eccd012748.mp3", "hash": "620ec29654455373393990c146b0e8b8087c8e23f29148eb5d503a66f2bf0c6c", "bytes": 55008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/38e26103ed7a1b3cd02a9809626a202632d33fe86831687e0fece1eccd012748.mp3", "duration_ms": 9120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "repaso-true-false", "title": "Repaso: ¿Cierto o falso?", "locale": "es-MX", "subject": "mixed", "objectives": ["Responder de memoria si guardando 20 pesos por semana la guitarra de 80 llega en un mes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Recuerda: la guitarra cuesta 80 pesos y ahorras 20 cada semana.", "Un mes tiene aproximadamente 4 semanas. ¿Cuánto ahorras en 4 semanas?"], "title": "¿Cierto o falso?", "payload": {"statement_md": "Si guardas 20 pesos cada semana, en un mes tendrás los 80 pesos para la guitarra.", "justifications": [{"id": "j1", "text_md": "20 pesos por semana × 4 semanas = 80 pesos."}, {"id": "j2", "text_md": "20 pesos por semana × 3 semanas = 60 pesos, no alcanza."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Al igual que calculamos la ganancia por vaso la vez pasada, hoy calcularemos si Rho puede comprar la guitarra. Rho lanza la última frase del curso. ¿Es cierta o falsa?", "difficulty": 2, "explanation_md": "¡Exacto! 20 pesos por semana × 4 semanas = 80 pesos, justo lo que cuesta la guitarra. La frase es cierta.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j1"}}', '{"units": {"s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/202ba42b39aee1b5b82e2f4093ede53f5c7c97e90e8f23b4f67e5a52edcdc12a.mp3", "hash": "01cd03e522bf2921119b2d51d461757f067cd24f4914bafed865325c73bc6d74", "bytes": 70416, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/202ba42b39aee1b5b82e2f4093ede53f5c7c97e90e8f23b4f67e5a52edcdc12a.mp3", "duration_ms": 11680}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/ca775ba624ad8da5b5671039c97798f9054fbcc6a213b6247544aa5ca4cfb41b.mp3", "hash": "18ca0271d4f27e74c56ad7d69c397f66b0e4b9945e70b621c0d15cb9f5e2f454", "bytes": 59904, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/ca775ba624ad8da5b5671039c97798f9054fbcc6a213b6247544aa5ca4cfb41b.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "Quanto Liruf ganhou?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular e escrever quanto Liruf ganhou no total se vendeu 4 copos a 5 pesos cada um (20 pesos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-input", "xp": 10, "type": "number_input", "hints": ["Lembre-se: cada copo é vendido a 5 pesos. Se vendeu 4 copos, some 5 + 5 + 5 + 5.", "5 + 5 = 10, mais 5 = 15, mais 5 = 20."], "title": "Lucro de Liruf", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Completar a frase do lucro: ''Vendi um copo por 5 pesos, os ingredientes custaram 2, meu lucro é ___ pesos''. Agora, calcule quanto Liruf ganhou no total se vendeu 4 copos a 5 pesos cada um. Escreva o número.", "difficulty": 1, "explanation_md": "Correto! Liruf vendeu 4 copos a 5 pesos cada um, então 4 × 5 = 20 pesos no total.", "audio_segment_id": "s1-number-input.prompt"}], "schema_version": 1}', '{"s1-number-input": {"value": 20, "tolerance": 0}}', '{"units": {"s1-number-input.prompt": {"url": "http://localhost:4006/files/lesson-audio/1b50aa01679088ab53a1e6dc5ecb5f18c2b1fd3ac9ca7c5686478d8df3258bb1.mp3", "hash": "5bff084d95c58a3e3d4f86f57f99252481079f9494be831cc58d7b09fa3f7bb2", "bytes": 99216, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1b50aa01679088ab53a1e6dc5ecb5f18c2b1fd3ac9ca7c5686478d8df3258bb1.mp3", "duration_ms": 16480}, "s1-number-input.explanation": {"url": "http://localhost:4006/files/lesson-audio/e41cda2f0c2fab7320c6bfc0d9f4b6dc6eaedac5450f1d5950d829301028e94d.mp3", "hash": "595a211a95da1599c42c3f9ccf6556b325fa321bfc513d2dcc882ab3d302f7b8", "bytes": 52704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e41cda2f0c2fab7320c6bfc0d9f4b6dc6eaedac5450f1d5950d829301028e94d.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "red-flags", "title": "Beware of offers that are too good to be true!", "locale": "en-US", "subject": "mixed", "objectives": ["Spot an error in a sales sum", "Read a simple graph of cups sold per day", "Recognize signs of a bad deal"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 0, "type": "red_flags", "hints": ["Think: how much money is it asking for today and how much does it promise to give you tomorrow? Is the profit very large?", "Do you know that person? Why would they be so generous if they don''t know you?"], "title": "Suspicious offer", "payload": {"flags": [{"id": "flag1", "text_md": "The promise is too good: 20 pesos turn into 100 in one day."}, {"id": "flag2", "text_md": "The seller is a stranger and is in a hurry."}, {"id": "flag3", "text_md": "There is no guarantee or contract, just words."}, {"id": "flag4", "text_md": "Asks for money upfront without giving anything in return."}], "artifact_md": "**Ad:** ''Magical deal! Give me 20 pesos today and receive 100 tomorrow. Don''t think twice!''", "artifact_kind": "ad"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "After checking your receipt and seeing that the lemons cost 20 pesos, Liruf now faces an offer that also mentions 20 pesos. A hurried seller approaches and says: ''Give me your 20 pesos today and tomorrow I''ll give you 100. It''s a magical deal!'' Liruf remembers that he earned 80 pesos selling lemonade after subtracting the cost of the lemons (100 - 20 = 80). This offer promises exactly that same profit, but without working. What red flags do you see?", "difficulty": 1, "explanation_md": "Exactly! Promising 100 pesos tomorrow for only 20 today is a profit of 80 pesos (100 - 20 = 80), too good to be true. Also, the seller is a stranger and is in a hurry, which should make you suspicious.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["flag1", "flag2", "flag3", "flag4"]}}', '{"units": {"s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/2fda95cc8b75d08af91c8bec2a14306a75ce5715981b9b2b5ee8bbbdd9ef00c5.mp3", "hash": "7bd7aad22b2a1dcf1d2829d776957d1925c5bc976ede86223fe223b97f4ae898", "bytes": 151056, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2fda95cc8b75d08af91c8bec2a14306a75ce5715981b9b2b5ee8bbbdd9ef00c5.mp3", "duration_ms": 25120}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/4e00ba899c5d8d4a0c005534abb4a6f5dd47a98573bbd54b3fb67ccbcae8fef8.mp3", "hash": "94e193867051f0dda532f7c139eb4d751b7c183d65682985440a6833a1213992", "bytes": 77184, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4e00ba899c5d8d4a0c005534abb4a6f5dd47a98573bbd54b3fb67ccbcae8fef8.mp3", "duration_ms": 12800}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "red-flags", "title": "¡Cuidado con las ofertas demasiado buenas!", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar un error en una suma de ventas", "Leer una gráfica simple de vasos vendidos por día", "Reconocer señales de un mal trato"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 0, "type": "red_flags", "hints": ["Piensa: ¿cuánto dinero te pide hoy y cuánto promete darte mañana? ¿Es una ganancia muy grande?", "¿Conoces a esa persona? ¿Por qué sería tan generoso si no te conoce?"], "title": "Oferta sospechosa", "payload": {"flags": [{"id": "flag1", "text_md": "La promesa es demasiado buena: 20 pesos se convierten en 100 en un día."}, {"id": "flag2", "text_md": "El vendedor es un desconocido y está apurado."}, {"id": "flag3", "text_md": "No hay garantía ni contrato, solo palabras."}, {"id": "flag4", "text_md": "Pide dinero por adelantado sin dar nada a cambio."}], "artifact_md": "**Anuncio:** ''¡Negocio mágico! Dame 20 pesos hoy y mañana recibe 100. ¡No lo pienses más!''", "artifact_kind": "ad"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Después de revisar tu recibo y ver que los limones costaron 20 pesos, ahora Liruf se enfrenta a una oferta que también menciona 20 pesos. Un vendedor apurado se acerca y le dice: ''Dame tus 20 pesos hoy y mañana te doy 100. ¡Es un negocio mágico!'' Liruf recuerda que ganó 80 pesos vendiendo limonada después de restar el costo de los limones (100 - 20 = 80). Esta oferta promete exactamente esa misma ganancia, pero sin trabajar. ¿Qué señales de alerta ves?", "difficulty": 1, "explanation_md": "¡Exacto! Prometer 100 pesos mañana por solo 20 hoy es una ganancia de 80 pesos (100 - 20 = 80), demasiado buena para ser verdad. Además, el vendedor es un desconocido y está apurado, lo que debe hacerte desconfiar.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["flag1", "flag2", "flag3", "flag4"]}}', '{"units": {"s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/16f7c4ae9dc37d5ba35ffbce34b15d6c71c0b87c432811ee233b21cb15ff01d9.mp3", "hash": "a650ec53bce776c10868e61fcaaead376bffa6fe26c5e908bd4c6d2aaa0b37cd", "bytes": 181728, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/16f7c4ae9dc37d5ba35ffbce34b15d6c71c0b87c432811ee233b21cb15ff01d9.mp3", "duration_ms": 30240}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/1883ffa5bb209c8c89256d68d07fe08266c8cd99ff8e1ee5e4acfaa8972814ff.mp3", "hash": "55fe3bce76cc0c62602e60fce863ab4c2572a8b8ef16d58f40b72180863382d9", "bytes": 91584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1883ffa5bb209c8c89256d68d07fe08266c8cd99ff8e1ee5e4acfaa8972814ff.mp3", "duration_ms": 15200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "red-flags", "title": "Cuidado com ofertas boas demais!", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar um erro em uma soma de vendas", "Ler um gráfico simples de copos vendidos por dia", "Reconhecer sinais de um mau negócio"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 0, "type": "red_flags", "hints": ["Pense: quanto dinheiro ele pede hoje e quanto promete te dar amanhã? É um lucro muito grande?", "Você conhece essa pessoa? Por que ela seria tão generosa se não te conhece?"], "title": "Oferta suspeita", "payload": {"flags": [{"id": "flag1", "text_md": "A promessa é boa demais: 20 pesos se transformam em 100 em um dia."}, {"id": "flag2", "text_md": "O vendedor é um desconhecido e está apressado."}, {"id": "flag3", "text_md": "Não há garantia nem contrato, apenas palavras."}, {"id": "flag4", "text_md": "Pede dinheiro adiantado sem dar nada em troca."}], "artifact_md": "**Anúncio:** ''Negócio mágico! Me dê 20 pesos hoje e amanhã receba 100. Não pense mais!''", "artifact_kind": "ad"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Depois de revisar seu recibo e ver que os limões custaram 20 pesos, agora Liruf enfrenta uma oferta que também menciona 20 pesos. Um vendedor apressado se aproxima e diz: ''Me dê seus 20 pesos hoje e amanhã te dou 100. É um negócio mágico!'' Liruf lembra que ganhou 80 pesos vendendo limonada depois de subtrair o custo dos limões (100 - 20 = 80). Essa oferta promete exatamente esse mesmo lucro, mas sem trabalhar. Que sinais de alerta você vê?", "difficulty": 1, "explanation_md": "Exato! Prometer 100 pesos amanhã por apenas 20 hoje é um lucro de 80 pesos (100 - 20 = 80), bom demais para ser verdade. Além disso, o vendedor é um desconhecido e está apressado, o que deve fazer você desconfiar.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["flag1", "flag2", "flag3", "flag4"]}}', '{"units": {"s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/c9c3bb0f80023b19f72755d43f3593ac306b9d9b6ea20dc2d5a298929c2d63f3.mp3", "hash": "83daec0a7959f59d25dd5a9b4d6474ec57c50f493e410bca21b73871463c7ec1", "bytes": 198576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c9c3bb0f80023b19f72755d43f3593ac306b9d9b6ea20dc2d5a298929c2d63f3.mp3", "duration_ms": 33040}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/55ae232ab26d1b39a3d304cec5aed514c42c70bc0e257e323ea36ac74a69a185.mp3", "hash": "b59f2237f4e6c7e6670d41858a689d5186622a3ffa12c5271893be7ac17dfe56", "bytes": 103536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/55ae232ab26d1b39a3d304cec5aed514c42c70bc0e257e323ea36ac74a69a185.mp3", "duration_ms": 17200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "speed-tap", "title": "Catch the coins!", "locale": "en-US", "subject": "mixed", "objectives": ["Recognize coins at a glance among other objects.", "Practice making quick decisions about what is money."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 0, "type": "speed_tap", "hints": ["Mexico''s coins are 1, 2, 5, 10, and 20 pesos. Look for those numbers!", "If it''s round and says ''MXN'' or the number, it''s a coin."], "title": "Catch the coins!", "payload": {"items": [{"id": "moneda1", "text_md": "1 peso coin"}, {"id": "boton1", "text_md": "Red button"}, {"id": "moneda2", "text_md": "2 peso coin"}, {"id": "tapa1", "text_md": "Juice lid"}, {"id": "moneda5", "text_md": "5 peso coin"}, {"id": "moneda10", "text_md": "10 peso coin"}, {"id": "boton2", "text_md": "Blue button"}, {"id": "moneda20", "text_md": "20 peso coin"}, {"id": "tapa2", "text_md": "Juice lid"}], "seconds": 10, "instruction_md": "Touch only the COINS. Ignore buttons and juice lids!"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Remember that yesterday you decided which expenses help your stand. Today, you need real coins to buy those lemons. Dina and Liruf are counting the coins they have. Can you help Liruf find only the coins among these objects?", "difficulty": 1, "explanation_md": "Great! You caught 1, 2, 5, 10, and 20 peso coins. Liruf needs those for his stand. Juice lids are not money, so don''t touch them. If you touched a lid, remember: only coins can buy lemons.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["moneda1", "moneda2", "moneda5", "moneda10", "moneda20"]}}', '{"units": {"s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/f7ab4fd4d16e23da57cfdc44eceb1b1b33e495bc595bd5c73959d8de69104254.mp3", "hash": "a356715396c43964ce4acfca2a07a2cbbc69e8a6fe2b10f31e7595ca842a7cb3", "bytes": 69984, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f7ab4fd4d16e23da57cfdc44eceb1b1b33e495bc595bd5c73959d8de69104254.mp3", "duration_ms": 11600}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/90709023ceac053e054f3f1e22165c06203bdc05dd95ad4ba1ed80aebba4b5d0.mp3", "hash": "cd308d6d0cf171ffdb3bc35f5e6c5b7fade1ac3892c86abe8aabb80130539e3d", "bytes": 73296, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/90709023ceac053e054f3f1e22165c06203bdc05dd95ad4ba1ed80aebba4b5d0.mp3", "duration_ms": 12160}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "picture-choice", "title": "Practice: Choose the correct image", "locale": "en-US", "subject": "mixed", "objectives": ["Test the ''picture_choice'' exercise in isolation (includes image generation)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-picture-choice", "xp": 0, "type": "picture_choice", "hints": ["Hint: Look for the coin or bill that is worth 5 pesos."], "title": "Choose the correct image", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "5 pesos", "image_url": "https://example.com/5pesos.png", "rationale_md": "Correct. This is the 5-peso coin that Zara needs."}, {"id": "opt2", "icon": "apple", "label": "Apple", "image_url": "https://example.com/apple.png", "rationale_md": "The apple is what Zara wants to buy, but it is not the price."}, {"id": "opt3", "icon": "banana", "label": "Banana", "image_url": "https://example.com/banana.png", "rationale_md": "The banana is another fruit, not the price of the apple."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hi! Last time you helped Dina count coins. Now Zara wants to buy an apple. **Look at the images** and choose the one that shows how much the apple costs.\\n\\n**Which of these images shows 5 pesos?**", "difficulty": 1, "explanation_md": "Great job! The image with the 5-peso coin is correct. The other options show an apple and a banana.", "audio_segment_id": "s1-picture-choice.prompt"}], "schema_version": 1}', '{"s1-picture-choice": {"correct_option_id": "opt1"}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "concept-reveal", "title": "Discover cost and profit", "locale": "en-US", "subject": "mixed", "objectives": ["Understand that money is earned by offering something others want", "Identify that a clear goal helps you start"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": [], "title": "Flip the cards", "payload": {"cards": [{"icon": "coin", "back_md": "What you spend on lemons and sugar to make the lemonade.", "front_md": "What is ''cost''?"}, {"icon": "star", "back_md": "What you have left after paying the cost. For example, if you sell 10 cups for 5 pesos each, you collect 50 pesos. If the cost was 20 pesos, your profit is 30 pesos.", "front_md": "What is ''profit''?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Set the 3 key ideas of the plan: have a goal (80 pesos), offer something people want (cold lemonade), and save what you earn. Now Zara hid two important concepts behind cards. Flip them to discover what they mean!", "difficulty": 1, "explanation_md": "You discovered that cost is what you spend and profit is what you keep! Liruf spent 20 pesos on lemons and sugar, and earned 40 pesos selling lemonade. His profit was 20 pesos.", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/115643c7b766c03fa7b995b38fdfc01c2b9f1f429fbc2270d5e997e1c6f392a5.mp3", "hash": "8ed196125290617c12061bf711f786dc89d7c0cbd05c505619506bca30e29247", "bytes": 77184, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/115643c7b766c03fa7b995b38fdfc01c2b9f1f429fbc2270d5e997e1c6f392a5.mp3", "duration_ms": 12800}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/e35d8ec14aa6c8a5bbd4c5b4ce422f0e8311d0292a6b87b2e90ff85d2d6d3fef.mp3", "hash": "cfa12e5db74675b9a96d64cf619ecdbc116c73f0625495b8f040eb8cb21d0b90", "bytes": 17136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e35d8ec14aa6c8a5bbd4c5b4ce422f0e8311d0292a6b87b2e90ff85d2d6d3fef.mp3", "duration_ms": 2800}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/50d2ade6a7417010dfcc1b6f360f01e9884dea3925876c86e90f34c07bc42114.mp3", "hash": "dbdd484d5339fb2f3e9197b5cd24dfcff11d908c40db8033319c8dfe39dd4bed", "bytes": 64224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/50d2ade6a7417010dfcc1b6f360f01e9884dea3925876c86e90f34c07bc42114.mp3", "duration_ms": 10640}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/d363b535e7489d2ca066aec37e712f70118a1b46bcb46007c7c8c540e675c6f6.mp3", "hash": "b192a5f2d9d1ff93ebeb422bfdef6409ac84b83c1bc841e8bb20afd22bb90070", "bytes": 61776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d363b535e7489d2ca066aec37e712f70118a1b46bcb46007c7c8c540e675c6f6.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "concept-reveal", "title": "Descubre costo y ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren", "Identificar que una meta clara ayuda a empezar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": [], "title": "Voltea las tarjetas", "payload": {"cards": [{"icon": "coin", "back_md": "Lo que gastas en limones y azúcar para hacer la limonada.", "front_md": "¿Qué es ''costo''?"}, {"icon": "star", "back_md": "Lo que te queda después de pagar el costo. Por ejemplo, si vendes 10 vasos a 5 pesos cada uno, juntas 50 pesos. Si el costo fue 20 pesos, tu ganancia es 30 pesos.", "front_md": "¿Qué es ''ganancia''?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Fijar las 3 ideas clave del plan: tener una meta (80 pesos), ofrecer algo que la gente quiera (limonada fría), y guardar lo ganado. Ahora Zara escondió dos conceptos importantes detrás de tarjetas. ¡Voltéalas para descubrir qué significan!", "difficulty": 1, "explanation_md": "¡Descubriste que costo es lo que gastas y ganancia lo que te queda! Liruf gastó 20 pesos en limones y azúcar, y ganó 40 pesos vendiendo limonada. Su ganancia fue 20 pesos.", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/d1b1c427a2c15cc8003ec6c0193b84d7543664cb61b67f189898e33e35f983d1.mp3", "hash": "dcd46a3ec693668be3e002dcb27d4c64bea6fed94066c5be594c1961ba631ce4", "bytes": 93888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d1b1c427a2c15cc8003ec6c0193b84d7543664cb61b67f189898e33e35f983d1.mp3", "duration_ms": 15600}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/c3fc2472b9344e8a8daa276044617f5d9682ee1384a35b6bf5812c9665da0ae8.mp3", "hash": "6bd0908b1e6018003c66701e1719ace57bd2beee3aad6527d23ef149ad5df8e5", "bytes": 22464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c3fc2472b9344e8a8daa276044617f5d9682ee1384a35b6bf5812c9665da0ae8.mp3", "duration_ms": 3680}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/d8efe888e59f2612932307a7a8e57d46d53668ea1ee060f5d8dd364098ea80bd.mp3", "hash": "f0da796360ccd29ec9421a9f81afec8149d0dcc3315e76217c9f4cbab200efbb", "bytes": 69408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d8efe888e59f2612932307a7a8e57d46d53668ea1ee060f5d8dd364098ea80bd.mp3", "duration_ms": 11520}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/102e47e350d524a274c2f21f7a60922853253130340532c9c76635f618faeb67.mp3", "hash": "d7fc68ec5bd962ed5e60669d30ee9d5c2e85e337ff19464fb8f988bd7e06be09", "bytes": 74736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/102e47e350d524a274c2f21f7a60922853253130340532c9c76635f618faeb67.mp3", "duration_ms": 12400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "concept-reveal", "title": "Descubra custo e lucro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender que o dinheiro é ganho oferecendo algo que outros querem", "Identificar que uma meta clara ajuda a começar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": [], "title": "Vire os cartões", "payload": {"cards": [{"icon": "coin", "back_md": "O que você gasta em limões e açúcar para fazer a limonada.", "front_md": "O que é ''custo''?"}, {"icon": "star", "back_md": "O que sobra depois de pagar o custo. Por exemplo, se você vende 10 copos a 5 pesos cada, junta 50 pesos. Se o custo foi 20 pesos, seu lucro é 30 pesos.", "front_md": "O que é ''lucro''?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Fixar as 3 ideias-chave do plano: ter uma meta (80 pesos), oferecer algo que as pessoas queiram (limonada gelada) e guardar o que ganhou. Agora Zara escondeu dois conceitos importantes atrás de cartões. Vire-os para descobrir o que significam!", "difficulty": 1, "explanation_md": "Você descobriu que custo é o que você gasta e lucro é o que sobra! Liruf gastou 20 pesos em limões e açúcar, e ganhou 40 pesos vendendo limonada. Seu lucro foi de 20 pesos.", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/2acbaac30fa1033e374044825c3011af90dd17f7ddcde9c0484883bbee58ff9a.mp3", "hash": "2b85ca6ca87f194552b6dc444011a784fa1ab46e043ef0eb32e1917a9673a79a", "bytes": 115056, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2acbaac30fa1033e374044825c3011af90dd17f7ddcde9c0484883bbee58ff9a.mp3", "duration_ms": 19120}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/f93333867142daf1c5170fb923aa35d0dcb39a08fe01354df4a8d1a86b3cf8c5.mp3", "hash": "997f4c49147c4239a21cdf25e36184da1da7c35bb4542e22b48f7c87555c6b8e", "bytes": 24336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f93333867142daf1c5170fb923aa35d0dcb39a08fe01354df4a8d1a86b3cf8c5.mp3", "duration_ms": 4000}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/dac0477a5356964636016caa700d844720b1067edcfa3af719729c683f327eea.mp3", "hash": "d51fe47f43daaf2d64df61df277b29bb7aff2133a019a775f76ba4ba862eadb9", "bytes": 78048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dac0477a5356964636016caa700d844720b1067edcfa3af719729c683f327eea.mp3", "duration_ms": 12960}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/c71f5162c567802f1ddd30518c93dec490e27c1dc5c1405e4714009ff2407030.mp3", "hash": "6509c176c2f75e3648b2c5a63cc0110c2e73e19975d944acd1d2c9743d7994a5", "bytes": 78048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c71f5162c567802f1ddd30518c93dec490e27c1dc5c1405e4714009ff2407030.mp3", "duration_ms": 12960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "lightning-round", "title": "Ronda relámpago de cuentas del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones dentro de historias del puesto y ver sus consecuencias inmediatas en las ventas y el ahorro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning-round", "xp": 0, "type": "lightning_round", "hints": ["Recuerda que cada vaso cuesta 5 MXN. Si un cliente pide 3 vasos, son 3 × 5 = 15 MXN.", "Para el cambio, resta el total del billete que te dan."], "title": "¡Cuentas al vuelo!", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 MXN"}, {"id": "b", "text_md": "5 MXN"}, {"id": "c", "text_md": "15 MXN"}], "prompt_md": "Cliente 1: ''¡Dame 2 vasos de limonada!'' Paga con un billete de 20 MXN. ¿Cuánto cambio le das?"}, {"id": "q2", "options": [{"id": "a", "text_md": "20 MXN"}, {"id": "b", "text_md": "30 MXN"}, {"id": "c", "text_md": "10 MXN"}], "prompt_md": "Cliente 2: ''¡Quiero 4 vasos!'' Paga con 50 MXN. ¿Cuánto cambio le das?"}, {"id": "q3", "options": [{"id": "a", "text_md": "5 MXN"}, {"id": "b", "text_md": "0 MXN"}, {"id": "c", "text_md": "2 MXN"}], "prompt_md": "Cliente 3: ''¡Necesito 1 vaso!'' Paga con 10 MXN. ¿Cuánto cambio le das?"}], "seconds_per_q": 15}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Relaciona a toda velocidad cada palabra del puesto con su ejemplo (ahorro→alcancía, costo→limones, ganancia→lo que sobra)! Ahora, en la hora pico, los clientes llegan en fila. Ayuda a Liruf a sumar vasos de limonada y dar cambios simples. ¡Contra el reloj!", "difficulty": 1, "explanation_md": "¡Excelente! Liruf pudo atender a todos gracias a tus cuentas rápidas. Cada vaso son 5 MXN, y con eso sumaste y diste cambio.", "audio_segment_id": "s1-lightning-round.prompt"}], "schema_version": 1}', '{"s1-lightning-round": {"correct": {"q1": "a", "q2": "b", "q3": "a"}}}', '{"units": {"s1-lightning-round.prompt": {"url": "http://localhost:4006/files/lesson-audio/6d1136c5bd530c6cfea8e11318c8e4be100d93412f3be8294d75db2b0539b650.mp3", "hash": "481554483c472fd2ddd79a10dc8051d83cc7109165123be0a3b6bbe3761c9d97", "bytes": 108288, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6d1136c5bd530c6cfea8e11318c8e4be100d93412f3be8294d75db2b0539b650.mp3", "duration_ms": 18000}, "s1-lightning-round.explanation": {"url": "http://localhost:4006/files/lesson-audio/1114438d2edfbb04d121c928930f814df30e67230800c503f562853901c95272.mp3", "hash": "87faaed3d92fe377f428902212e19057043586c6c923dc56702fb092165dba11", "bytes": 57024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1114438d2edfbb04d121c928930f814df30e67230800c503f562853901c95272.mp3", "duration_ms": 9440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "lightning-round", "title": "Rodada relâmpago de contas da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões dentro de histórias da barraca e ver suas consequências imediatas nas vendas e na economia."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-lightning-round", "xp": 0, "type": "lightning_round", "hints": ["Lembre-se que cada copo custa 5 MXN. Se um cliente pedir 3 copos, são 3 × 5 = 15 MXN.", "Para o troco, subtraia o total da nota que te derem."], "title": "Contas na mosca!", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 MXN"}, {"id": "b", "text_md": "5 MXN"}, {"id": "c", "text_md": "15 MXN"}], "prompt_md": "Cliente 1: ''Me dá 2 copos de limonada!'' Paga com uma nota de 20 MXN. Quanto troco você dá?"}, {"id": "q2", "options": [{"id": "a", "text_md": "20 MXN"}, {"id": "b", "text_md": "30 MXN"}, {"id": "c", "text_md": "10 MXN"}], "prompt_md": "Cliente 2: ''Quero 4 copos!'' Paga com 50 MXN. Quanto troco você dá?"}, {"id": "q3", "options": [{"id": "a", "text_md": "5 MXN"}, {"id": "b", "text_md": "0 MXN"}, {"id": "c", "text_md": "2 MXN"}], "prompt_md": "Cliente 3: ''Preciso de 1 copo!'' Paga com 10 MXN. Quanto troco você dá?"}], "seconds_per_q": 15}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Relacione a toda velocidade cada palavra da barraca com seu exemplo (economia→cofrinho, custo→limões, lucro→o que sobra)! Agora, na hora do pico, os clientes chegam em fila. Ajude a Liruf a somar copos de limonada e dar trocos simples. Contra o relógio!", "difficulty": 1, "explanation_md": "Excelente! Liruf conseguiu atender a todos graças às suas contas rápidas. Cada copo são 5 MXN, e com isso você somou e deu troco.", "audio_segment_id": "s1-lightning-round.prompt"}], "schema_version": 1}', '{"s1-lightning-round": {"correct": {"q1": "a", "q2": "b", "q3": "a"}}}', '{"units": {"s1-lightning-round.prompt": {"url": "http://localhost:4006/files/lesson-audio/9d0697cdb8e9e0a0af02f1fd2f15784cc3249dd6d6e11884b95894263368c2cd.mp3", "hash": "f1e64b9879522606f7f5abc974456d442dfef38c24ef826c106d56fd3d78b79b", "bytes": 120384, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9d0697cdb8e9e0a0af02f1fd2f15784cc3249dd6d6e11884b95894263368c2cd.mp3", "duration_ms": 20000}, "s1-lightning-round.explanation": {"url": "http://localhost:4006/files/lesson-audio/0c46edc9708abebc289bd22425dd6f746b1d080670c9345d9f1c11841f828fb7.mp3", "hash": "95ffd0069d64ceda34c59dade60e252fbc21efec796d4e7a8430300c9a6ff6b8", "bytes": 65088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0c46edc9708abebc289bd22425dd6f746b1d080670c9345d9f1c11841f828fb7.mp3", "duration_ms": 10800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "number-line", "title": "The savings number line", "locale": "en-US", "subject": "mixed", "objectives": ["Locate on the number line from 0 to 100 where Liruf''s savings (20 pesos) are and where the goal (80) is: see how much is missing."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 0, "type": "number_line", "hints": ["20 is closer to 0 than to 100. Look between 10 and 30.", "Count by 10s from 0: 10, 20, 30... there it is!"], "title": "The savings number line", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": true}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Group the money in the box: coins with coins and bills with bills, to count it more easily. Now, Rho draws a giant number line with chalk: ''mark where you are and where you want to go''. Liruf has saved 20 pesos and his goal is 80 pesos. Where is 20 and where is 80 on the number line from 0 to 100? Drag the marker to 20.", "difficulty": 1, "explanation_md": "Very good! 20 is on the left, near 0, and 80 is further to the right. 60 pesos are missing to reach Liruf''s goal.", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/192de92cc8a4f8fda7161a6581f1369ebdd1a9105389f986cd7fabb4ef570472.mp3", "hash": "8fe034fa8d2ea6e06969fce7b238a8240ce44291c157f01bf689507d1f98e137", "bytes": 156816, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/192de92cc8a4f8fda7161a6581f1369ebdd1a9105389f986cd7fabb4ef570472.mp3", "duration_ms": 26080}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/15a2d1fa9e58a34fdc31763bb5009af1eb73dd1bef779443587cf47aa591ba15.mp3", "hash": "bae7b35b9a9ec978089ce4f0d474e3ff69791a2cd05f7ce48f65ead447110e27", "bytes": 57024, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/15a2d1fa9e58a34fdc31763bb5009af1eb73dd1bef779443587cf47aa591ba15.mp3", "duration_ms": 9440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "flash-match", "title": "Flash Match: Conecte conceitos da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Relacione rapidamente cada palavra da barraca com seu exemplo (economia→cofrinho, custo→limões, lucro→o que sobra)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 0, "type": "flash_match", "hints": ["Pense no que cada palavra significa na barraca de limonada: economia é guardar, custo é o que você paga, lucro é o que sobra."], "title": "Flash Match: Conecte conceitos da barraca", "payload": {"left": [{"id": "l1", "text_md": "Economia"}, {"id": "l2", "text_md": "Custo"}, {"id": "l3", "text_md": "Lucro"}], "right": [{"id": "r1", "text_md": "Cofrinho"}, {"id": "r2", "text_md": "Limões"}, {"id": "r3", "text_md": "O que sobra"}], "seconds": 30}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Depois de praticar como responder a um cliente que pede desconto, agora vamos revisar os conceitos-chave da barraca! Dina acabou de vender toda a sua limonada e conta seus lucros. Com a economia de ontem, ela comprou mais limões hoje. Zara pega seu cronômetro: ''Vamos ver quão rápido você conecta os conceitos!'' Una cada palavra da esquerda com seu exemplo da direita. Você tem 30 segundos!", "difficulty": 1, "explanation_md": "Excelente! Economia vai com cofrinho porque você guarda dinheiro, custo vai com limões porque você os compra para fazer limonada, e lucro vai com o que sobra depois de vender.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["l1", "r1"], ["l2", "r2"], ["l3", "r3"]]}}', '{"units": {"s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/681410ec7184506a10f46b8befa473613602681eda9a73af06328fbe5d4ec8a7.mp3", "hash": "81b0e6777a092e8f3cc58a5c80be01d30a9cd5316e2516ed5d79e2f4254ac2c1", "bytes": 145728, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/681410ec7184506a10f46b8befa473613602681eda9a73af06328fbe5d4ec8a7.mp3", "duration_ms": 24240}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/3ac1302cbe468a113240efdf6145332e511ad4885cb5091b28d748c41f1f2551.mp3", "hash": "35bd40a2b4bccc199837ba04c8d29a2d93a7b741317be240b052f14e5820fdca", "bytes": 60768, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/3ac1302cbe468a113240efdf6145332e511ad4885cb5091b28d748c41f1f2551.mp3", "duration_ms": 10080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "number-line", "title": "A reta numérica da poupança", "locale": "pt-BR", "subject": "mixed", "objectives": ["Localizar na reta numérica de 0 a 100 onde está a poupança de Liruf (20 pesos) e onde está a meta (80): ver quanto falta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 0, "type": "number_line", "hints": ["O 20 está mais perto do 0 do que do 100. Procure entre o 10 e o 30.", "Conte de 10 em 10 a partir do 0: 10, 20, 30... aí está!"], "title": "A reta numérica da poupança", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": true}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Agrupar o dinheiro da caixa: moedas com moedas e notas com notas, para contar mais fácil. Agora, Rho desenha uma reta gigante com giz: ''marque onde você está e aonde quer chegar''. Liruf economizou 20 pesos e sua meta são 80 pesos. Onde está o 20 e onde está o 80 na reta de 0 a 100? Arraste o marcador para o 20.", "difficulty": 1, "explanation_md": "Muito bem! O 20 está à esquerda, perto do 0, e o 80 está mais à direita. Faltam 60 pesos para Liruf atingir a meta.", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 20, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/79ff6a584888784f3473ef06122d41f0f3c044d8dd57c0edae3d210eedab0349.mp3", "hash": "3bbddc9a2fdf466f3cb4e6a090009f652a1dbf00d450c6d895ff4549f1739558", "bytes": 152496, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/79ff6a584888784f3473ef06122d41f0f3c044d8dd57c0edae3d210eedab0349.mp3", "duration_ms": 25360}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/d909c27ee103f865fec75e8d6396e63b3a547662e9e832c1f45dd7b73c3980b0.mp3", "hash": "3450ee57f85a4c6f668037f19fed9c6b73b9fb5389a728d0188ffe914d961bec", "bytes": 67104, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/d909c27ee103f865fec75e8d6396e63b3a547662e9e832c1f45dd7b73c3980b0.mp3", "duration_ms": 11120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "flash-match", "title": "Flash Match: Connect Stand Concepts", "locale": "en-US", "subject": "mixed", "objectives": ["Match each stand word with its example at full speed (savings→piggy bank, cost→lemons, profit→what''s left)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 0, "type": "flash_match", "hints": ["Think about what each word means at the lemonade stand: savings is keeping, cost is what you pay, profit is what''s left."], "title": "Flash Match: Connect Stand Concepts", "payload": {"left": [{"id": "l1", "text_md": "Savings"}, {"id": "l2", "text_md": "Cost"}, {"id": "l3", "text_md": "Profit"}], "right": [{"id": "r1", "text_md": "Piggy bank"}, {"id": "r2", "text_md": "Lemons"}, {"id": "r3", "text_md": "What''s left"}], "seconds": 30}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "After practicing how to respond to a customer asking for a discount, now let''s review the key concepts of the stand! Dina just sold all her lemonade and counts her earnings. With yesterday''s savings, she bought more lemons today. Zara pulls out her stopwatch: ''Let''s see how fast you can connect the concepts!'' Match each word on the left with its example on the right. You have 30 seconds!", "difficulty": 1, "explanation_md": "Excellent! Savings goes with piggy bank because you keep money, cost goes with lemons because you buy them to make lemonade, and profit goes with what''s left after selling.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["l1", "r1"], ["l2", "r2"], ["l3", "r3"]]}}', '{"units": {"s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/aa1d449e5cf5965ffa279b63ba4650f72d6c5c829d15beed7c7a4724d489db97.mp3", "hash": "e69d27980479266dacb5ec560ffb6111d935e2f5ffb51642a96a057d3a19054d", "bytes": 135648, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/aa1d449e5cf5965ffa279b63ba4650f72d6c5c829d15beed7c7a4724d489db97.mp3", "duration_ms": 22560}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/4042e1fd9da6d07e5a45d223dc358e07d2b2ec9685a5c039f8dbb0d28ba4578b.mp3", "hash": "1ba5e8f5f3655761f2b698617fe85ff65309a6fbe28f9059bb45c6a9e31e990a", "bytes": 59328, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/4042e1fd9da6d07e5a45d223dc358e07d2b2ec9685a5c039f8dbb0d28ba4578b.mp3", "duration_ms": 9840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "flash-match", "title": "Flash Match: Conecta conceptos del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Relacionar a toda velocidad cada palabra del puesto con su ejemplo (ahorro→alcancía, costo→limones, ganancia→lo que sobra)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 0, "type": "flash_match", "hints": ["Piensa en lo que cada palabra significa en el puesto de limonada: ahorro es guardar, costo es lo que pagas, ganancia es lo que te queda."], "title": "Flash Match: Conecta conceptos del puesto", "payload": {"left": [{"id": "l1", "text_md": "Ahorro"}, {"id": "l2", "text_md": "Costo"}, {"id": "l3", "text_md": "Ganancia"}], "right": [{"id": "r1", "text_md": "Alcancía"}, {"id": "r2", "text_md": "Limones"}, {"id": "r3", "text_md": "Lo que sobra"}], "seconds": 30}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Después de practicar cómo responder a un cliente que pide rebaja, ¡ahora repasemos los conceptos clave del puesto! Dina acaba de vender toda su limonada y cuenta sus ganancias. Con el ahorro de ayer, compró más limones hoy. Zara saca su cronómetro: ''¡A ver qué tan rápido conectas los conceptos!'' Une cada palabra de la izquierda con su ejemplo de la derecha. ¡Tienes 30 segundos!", "difficulty": 1, "explanation_md": "¡Excelente! Ahorro va con alcancía porque guardas dinero, costo va con limones porque los compras para hacer limonada, y ganancia va con lo que sobra después de vender.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["l1", "r1"], ["l2", "r2"], ["l3", "r3"]]}}', '{"units": {"s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/2c6540a7753217f2311e0e504ec9b81de6f89b32732400aaa15407748e64a7d5.mp3", "hash": "5a92bcb3181d12658c925391cc1cee5b21f69fff5f33cb3569b9a80c34c1e247", "bytes": 135648, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/2c6540a7753217f2311e0e504ec9b81de6f89b32732400aaa15407748e64a7d5.mp3", "duration_ms": 22560}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/985cd126835a3dee82c1a64d60cdef25fd2c8fbc6254141c464b423c979f8245.mp3", "hash": "b7c84c5b247e6576eb775ae691917b7c09bf2902616878ff37bb4ef04720d7f9", "bytes": 59328, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/985cd126835a3dee82c1a64d60cdef25fd2c8fbc6254141c464b423c979f8245.mp3", "duration_ms": 9840}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "Respirar e revisar antes de abrir a barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender que o dinheiro é ganho oferecendo algo que outros querem, e que uma meta clara (o violão de 80 pesos) ajuda a começar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "Respirar e revisar antes de abrir a barraca", "payload": {"recap_md": "Como você descobriu ao virar os cartões, já tem **meta** (80 pesos), **produto** (limonada a 5 pesos) e sabe o que é **custo** e **lucro**. Por exemplo, se gastar 20 pesos em limões e vender 10 copos a 5 pesos, seu lucro é 30 pesos.", "mood_prompt_md": "Como você se sente para abrir a barraca? Escolha uma opção:"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina pergunta: **Liruf**, como você se sente antes do grande dia de abertura?", "difficulty": 1, "explanation_md": "Legal! Lembre-se de que sua meta é o violão de 80 pesos e sua limonada custa 5 pesos.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/9db75945ff8e263e0a0882d445dd9c0bf74f286be9b0b222e5a4d3540a350099.mp3", "hash": "1146725e284a351fbf1c7e14a071ec8e471953a9e05f74e46464647dfb228ae6", "bytes": 103536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9db75945ff8e263e0a0882d445dd9c0bf74f286be9b0b222e5a4d3540a350099.mp3", "duration_ms": 17200}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/4c86bb8241932b71aa66c34338e0f57188117cdb899ba386818d45ab9ffd9fc3.mp3", "hash": "83d6c48d68c1f79e31741e4cd4d5fa67c32f763c8157b907db8071c292c9a946", "bytes": 31968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4c86bb8241932b71aa66c34338e0f57188117cdb899ba386818d45ab9ffd9fc3.mp3", "duration_ms": 5280}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/cec945c0b00e0eaffd4c1c65798a1498c05a32bda7e5503caf18e384a0c3ae11.mp3", "hash": "ffe17f0dfbd32cf4faea79ed992f600b17efdf6dc60f71a94c1b13accd0c80c0", "bytes": 42624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cec945c0b00e0eaffd4c1c65798a1498c05a32bda7e5503caf18e384a0c3ae11.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "La ruta del carrito repartidor", "locale": "es-MX", "subject": "mixed", "objectives": ["Guiar al carrito repartidor por la cuadrícula del barrio hasta la casa del cliente gastando la menor cantidad de pasos."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 15, "type": "robot_path", "hints": ["Piensa en la ruta más corta evitando las paredes. ¿Cuántos pasos hacia arriba y hacia la derecha necesitas?", "Puedes dibujar la cuadrícula en un papel para visualizar los movimientos."], "title": "La ruta del carrito repartidor", "payload": {"goal": {"x": 3, "y": 3}, "grid": {"h": 4, "w": 4}, "start": {"x": 1, "y": 1, "dir": "up"}, "walls": [{"x": 2, "y": 1}, {"x": 2, "y": 2}], "commands": ["forward", "left", "right"], "max_commands": 6}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que ya sabes ordenar los pasos de la registradora, ¡vamos a ordenar los pasos del carrito repartidor! Después de anotar la venta, Dina y Zara necesitan entregar el pedido. El carrito repartidor está en la posición (1,1) mirando hacia arriba. La casa del cliente está en (3,3). Hay paredes en (2,1) y (2,2). El carrito solo puede avanzar (forward), girar a la izquierda (left) o girar a la derecha (right). Ayuda a Zara a programar el carrito para que llegue a la casa en la menor cantidad de pasos (máximo 6). Recuerda: primero gira para orientarte, luego avanza. ¡Como cuando cuentas pasos en el piso!", "difficulty": 2, "explanation_md": "¡Excelente! Usaste 5 comandos: girar a la derecha, avanzar, girar a la izquierda, avanzar y avanzar. ¡El carrito llegó a la casa del cliente en solo 5 pasos! Dina y Zara están felices porque el pedido llegó a tiempo.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/86f53457cf998180b4d3900321dd6c0ca6f7bd6df636a088a8314f32f72489d5.mp3", "hash": "515a76facb4e6a98e531703c56b986a04bbf576432075a9f16f6254fa1f50902", "bytes": 229824, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/86f53457cf998180b4d3900321dd6c0ca6f7bd6df636a088a8314f32f72489d5.mp3", "duration_ms": 38240}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/c0391de7e180330142d5fe5fafdae90661cefff650537c237299ae093a6da7d9.mp3", "hash": "db96713878d26343ea057b8c74611777a2bbe350fa7b540ed5fd8d146bf72efa", "bytes": 92448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c0391de7e180330142d5fe5fafdae90661cefff650537c237299ae093a6da7d9.mp3", "duration_ms": 15360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "A rota do carrinho entregador", "locale": "pt-BR", "subject": "mixed", "objectives": ["Guiar o carrinho entregador pela grade do bairro até a casa do cliente gastando o menor número de passos."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 15, "type": "robot_path", "hints": ["Pense na rota mais curta evitando as paredes. Quantos passos para cima e para a direita você precisa?", "Você pode desenhar a grade em um papel para visualizar os movimentos."], "title": "A rota do carrinho entregador", "payload": {"goal": {"x": 3, "y": 3}, "grid": {"h": 4, "w": 4}, "start": {"x": 1, "y": 1, "dir": "up"}, "walls": [{"x": 2, "y": 1}, {"x": 2, "y": 2}], "commands": ["forward", "left", "right"], "max_commands": 6}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você já sabe ordenar os passos da registradora, vamos ordenar os passos do carrinho entregador! Depois de anotar a venda, Dina e Zara precisam entregar o pedido. O carrinho entregador está na posição (1,1) olhando para cima. A casa do cliente está em (3,3). Há paredes em (2,1) e (2,2). O carrinho só pode avançar (forward), girar à esquerda (left) ou girar à direita (right). Ajude a Zara a programar o carrinho para chegar à casa no menor número de passos (máximo 6). Lembre-se: primeiro gire para se orientar, depois avance. Como quando você conta passos no chão!", "difficulty": 2, "explanation_md": "Excelente! Você usou 5 comandos: girar à direita, avançar, girar à esquerda, avançar e avançar. O carrinho chegou à casa do cliente em apenas 5 passos! Dina e Zara estão felizes porque o pedido chegou a tempo.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/e8c6643e556b4b432f8d938113ce379ddc5f09a4a04df6825c2ffb654637448b.mp3", "hash": "f61712c40af4f7c2f74d4452097deb5b049c45c4ff073589ba011ad8a0a62ae7", "bytes": 237888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e8c6643e556b4b432f8d938113ce379ddc5f09a4a04df6825c2ffb654637448b.mp3", "duration_ms": 39600}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/c4c667c275240a97a3bf54047faa2ccd3b4dbfeb04d4cbccc165a74aea8aadd2.mp3", "hash": "0977f79493e70a693d5ab977ace8e3b9f5dde5966951c1b51dccf4840ff87634", "bytes": 96336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c4c667c275240a97a3bf54047faa2ccd3b4dbfeb04d4cbccc165a74aea8aadd2.mp3", "duration_ms": 16000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-arrange-largo", "title": "Big nightly cleanup at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Chain several skills in one lesson: listen to the situation, decide, calculate, and charge.", "Leave the stand ready for tomorrow: match prices, order the recipe, classify purchases, and arrange the day''s timeline."], "estimated_minutes": 15}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-precios", "xp": 5, "type": "match_pairs", "hints": ["Remember that a glass of lemonade costs 5 MXN."], "title": "Match prices", "payload": {"left": [{"id": "vaso", "text_md": "Glass of lemonade"}, {"id": "galletas", "text_md": "Bag of cookies"}, {"id": "jugo", "text_md": "Orange juice"}], "right": [{"id": "precio5", "text_md": "5 MXN"}, {"id": "precio10", "text_md": "10 MXN"}, {"id": "precio20", "text_md": "20 MXN"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf has 37 MXN in the cash box and needs to give 20 MXN change to a customer. Help Liruf match each product with its correct price to know how much to charge.", "difficulty": 1, "explanation_md": "Great! The glass of lemonade costs 5 MXN, the bag of cookies 10 MXN, and the orange juice 20 MXN. So if a customer buys an orange juice (20 MXN) and pays with 40 MXN, Liruf must give 20 MXN change.", "audio_segment_id": "s1-match-precios.prompt"}, {"id": "s2-order-receta", "xp": 5, "type": "order_steps", "hints": ["First squeeze the lemons, then mix with water and sugar."], "title": "Order the recipe", "payload": {"items": [{"id": "exprimir", "text_md": "Squeeze the lemons"}, {"id": "mezclar", "text_md": "Mix with water and sugar"}, {"id": "servir", "text_md": "Serve in glasses"}, {"id": "decorar", "text_md": "Garnish with a lemon slice"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina wants to prepare lemonade for tomorrow. Order the steps to make the lemonade, from first to last.", "difficulty": 1, "explanation_md": "Correct! First squeeze, then mix, then serve, and finally garnish. That way Dina will have lemonade ready to sell tomorrow.", "audio_segment_id": "s2-order-receta.prompt"}, {"id": "s3-sort-compras", "xp": 5, "type": "sort_buckets", "hints": ["Cookies are food, lemonade is a drink."], "title": "Classify purchases", "payload": {"items": [{"id": "galletas", "text_md": "Cookies"}, {"id": "limonada", "text_md": "Lemonade"}, {"id": "pan", "text_md": "Bread"}, {"id": "jugo", "text_md": "Orange juice"}], "buckets": [{"id": "comida", "label": "Food"}, {"id": "bebida", "label": "Drink"}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Rho is organizing the day''s purchases. Classify each purchase into the correct category: ''Food'' or ''Drink''.", "difficulty": 1, "explanation_md": "Very good! Cookies and bread go in Food; lemonade and juice go in Drink. That way Rho knows what to restock tomorrow.", "audio_segment_id": "s3-sort-compras.prompt"}, {"id": "s4-timeline-dia", "xp": 5, "type": "timeline_order", "hints": ["First they open the stand, then they serve customers, then they count the earnings, and finally they close."], "title": "Day''s timeline", "payload": {"events": [{"id": "abrir", "icon": "store", "text_md": "Open the stand"}, {"id": "atender", "icon": "people", "text_md": "Serve customers"}, {"id": "contar", "icon": "money", "text_md": "Count the day''s earnings"}, {"id": "cerrar", "icon": "lock", "text_md": "Close the stand"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Zara is closing the stand. Remember that today they earned 40 MXN and they already have 60 MXN saved for the 80 MXN guitar. Order the events of the day at the stand, from opening to closing.", "difficulty": 1, "explanation_md": "Perfect! Open, serve, count earnings, and close is the correct order. Today they earned 40 MXN, totaling 60 MXN. Only 20 MXN left for the guitar!", "audio_segment_id": "s4-timeline-dia.prompt"}], "schema_version": 1}', '{"s2-order-receta": {"order": ["exprimir", "mezclar", "servir", "decorar"]}, "s3-sort-compras": {"assignments": {"pan": "comida", "jugo": "bebida", "galletas": "comida", "limonada": "bebida"}}, "s4-timeline-dia": {"order": ["abrir", "atender", "contar", "cerrar"]}, "s1-match-precios": {"pairs": [["vaso", "precio5"], ["galletas", "precio10"], ["jugo", "precio20"]]}}', '{"units": {"s2-order-receta.prompt": {"url": "http://localhost:4006/files/lesson-audio/303cb354a2d43a1689fabc66e7d5b7a94b716df971a9a01393d4bfd385cb848c.mp3", "hash": "a7edb0fd464343849eca0b25fdafcdda2f9c746c3f6150a3707643243810bddf", "bytes": 30528, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/303cb354a2d43a1689fabc66e7d5b7a94b716df971a9a01393d4bfd385cb848c.mp3", "duration_ms": 5040}, "s3-sort-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/2f82948dc47c4016ef5d8c78f2b59afb43d4470a4e7683fb02c7c928b8e2f633.mp3", "hash": "631c0e33b5d29c4d316abc4c68c8f8cc20bede69e10faf4edbee706941d1fbb3", "bytes": 47808, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/2f82948dc47c4016ef5d8c78f2b59afb43d4470a4e7683fb02c7c928b8e2f633.mp3", "duration_ms": 7920}, "s4-timeline-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/fc13d4154bcf7574e759e5ada57b544612e6aa3c135159009eace88a79fbf6d7.mp3", "hash": "ce0f4268e31d33733ae4d5cc0a7d1ab20491caba263743077ebab8c97a0282f9", "bytes": 81504, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/fc13d4154bcf7574e759e5ada57b544612e6aa3c135159009eace88a79fbf6d7.mp3", "duration_ms": 13520}, "s1-match-precios.prompt": {"url": "http://localhost:4006/files/lesson-audio/b65602525c9d9f51303574bc8bb6fd6ad6c6f42df31b80c8d70abe2a81b457f5.mp3", "hash": "e6baecb712a0224dad0bcedd0b967ec42745181455ae154bc70b29911cf5815b", "bytes": 64656, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/b65602525c9d9f51303574bc8bb6fd6ad6c6f42df31b80c8d70abe2a81b457f5.mp3", "duration_ms": 10720}, "s2-order-receta.explanation": {"url": "http://localhost:4006/files/lesson-audio/c5625cc164a41485f6e2d589370a63c3de7fd8353ed34d6ffd2935f992b59f27.mp3", "hash": "8a4597a885d98c7234e6795602df5d9ae8378926ab381dfca4680c71f9df0405", "bytes": 43488, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c5625cc164a41485f6e2d589370a63c3de7fd8353ed34d6ffd2935f992b59f27.mp3", "duration_ms": 7200}, "s3-sort-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/c60bbff33f4fcc62ac1a3e0bcc0f793fa5f653ac56b30c2d93f834deeaa40b2d.mp3", "hash": "82db04ad7420fced3c128b4a8e776251cfd6d0494e38768afc768cd632cc8a54", "bytes": 51696, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/c60bbff33f4fcc62ac1a3e0bcc0f793fa5f653ac56b30c2d93f834deeaa40b2d.mp3", "duration_ms": 8560}, "s4-timeline-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/81ee77c9dcf07a299451066aa697e6985a4d85e54cf4b3ef33ab9c66457c0697.mp3", "hash": "30e57806b490867d6715d1e2c81ead5d7830cf4edf2fc020db7ab71cb38c6033", "bytes": 76608, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/81ee77c9dcf07a299451066aa697e6985a4d85e54cf4b3ef33ab9c66457c0697.mp3", "duration_ms": 12720}, "s1-match-precios.explanation": {"url": "http://localhost:4006/files/lesson-audio/312897e187f107f7404f5149a0fded160ebbcce393a6ce6a7cb6715bde226aea.mp3", "hash": "2c82780e52863b5f8c0fd9fe872afbcb1ae803dd0210bad5bcc95103d7d5d8b9", "bytes": 88704, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/312897e187f107f7404f5149a0fded160ebbcce393a6ce6a7cb6715bde226aea.mp3", "duration_ms": 14720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-arrange-largo", "title": "Gran limpieza nocturna en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar.", "Dejar el puesto listo para mañana: emparejar precios, ordenar la receta, clasificar compras y acomodar la línea del tiempo del día."], "estimated_minutes": 15}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-precios", "xp": 5, "type": "match_pairs", "hints": ["Recuerda que un vaso de limonada cuesta 5 MXN."], "title": "Emparejar precios", "payload": {"left": [{"id": "vaso", "text_md": "Vaso de limonada"}, {"id": "galletas", "text_md": "Bolsa de galletas"}, {"id": "jugo", "text_md": "Jugo de naranja"}], "right": [{"id": "precio5", "text_md": "5 MXN"}, {"id": "precio10", "text_md": "10 MXN"}, {"id": "precio20", "text_md": "20 MXN"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf tiene 37 MXN en la caja y necesita dar 20 MXN de cambio a un cliente. Ayuda a Liruf a emparejar cada producto con su precio correcto para saber cuánto cobrar.", "difficulty": 1, "explanation_md": "¡Bien! El vaso de limonada cuesta 5 MXN, la bolsa de galletas 10 MXN y el jugo de naranja 20 MXN. Así, si un cliente compra un jugo de naranja (20 MXN) y paga con 40 MXN, Liruf debe dar 20 MXN de cambio.", "audio_segment_id": "s1-match-precios.prompt"}, {"id": "s2-order-receta", "xp": 5, "type": "order_steps", "hints": ["Primero se exprimen los limones, luego se mezcla con agua y azúcar."], "title": "Ordenar la receta", "payload": {"items": [{"id": "exprimir", "text_md": "Exprimir los limones"}, {"id": "mezclar", "text_md": "Mezclar con agua y azúcar"}, {"id": "servir", "text_md": "Servir en vasos"}, {"id": "decorar", "text_md": "Decorar con una rodaja de limón"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quiere preparar limonada para mañana. Ordena los pasos para preparar la limonada, del primero al último.", "difficulty": 1, "explanation_md": "¡Correcto! Primero exprimir, luego mezclar, después servir y finalmente decorar. Así Dina tendrá limonada lista para vender mañana.", "audio_segment_id": "s2-order-receta.prompt"}, {"id": "s3-sort-compras", "xp": 5, "type": "sort_buckets", "hints": ["Las galletas son comida, la limonada es bebida."], "title": "Clasificar compras", "payload": {"items": [{"id": "galletas", "text_md": "Galletas"}, {"id": "limonada", "text_md": "Limonada"}, {"id": "pan", "text_md": "Pan"}, {"id": "jugo", "text_md": "Jugo de naranja"}], "buckets": [{"id": "comida", "label": "Comida"}, {"id": "bebida", "label": "Bebida"}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Rho está organizando las compras del día. Clasifica cada compra en la categoría correcta: ''Comida'' o ''Bebida''.", "difficulty": 1, "explanation_md": "¡Muy bien! Las galletas y el pan van en Comida; la limonada y el jugo en Bebida. Así Rho sabe qué reponer mañana.", "audio_segment_id": "s3-sort-compras.prompt"}, {"id": "s4-timeline-dia", "xp": 5, "type": "timeline_order", "hints": ["Primero abren el puesto, luego atienden clientes, después cuentan las ganancias y finalmente cierran."], "title": "Línea del tiempo del día", "payload": {"events": [{"id": "abrir", "icon": "store", "text_md": "Abrir el puesto"}, {"id": "atender", "icon": "people", "text_md": "Atender a los clientes"}, {"id": "contar", "icon": "money", "text_md": "Contar las ganancias del día"}, {"id": "cerrar", "icon": "lock", "text_md": "Cerrar el puesto"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Zara está cerrando el puesto. Recuerda que hoy ganaron 40 MXN y ya llevan 60 MXN ahorrados para la guitarra de 80 MXN. Ordena los eventos del día en el puesto, desde que abren hasta que cierran.", "difficulty": 1, "explanation_md": "¡Perfecto! Abrir, atender, contar ganancias y cerrar es el orden correcto. Hoy ganaron 40 MXN, sumando 60 MXN en total. ¡Solo faltan 20 MXN para la guitarra!", "audio_segment_id": "s4-timeline-dia.prompt"}], "schema_version": 1}', '{"s2-order-receta": {"order": ["exprimir", "mezclar", "servir", "decorar"]}, "s3-sort-compras": {"assignments": {"pan": "comida", "jugo": "bebida", "galletas": "comida", "limonada": "bebida"}}, "s4-timeline-dia": {"order": ["abrir", "atender", "contar", "cerrar"]}, "s1-match-precios": {"pairs": [["vaso", "precio5"], ["galletas", "precio10"], ["jugo", "precio20"]]}}', '{"units": {"s2-order-receta.prompt": {"url": "http://localhost:4006/files/lesson-audio/a4562159f829ab2446c2ae2726d40bff2e248c9318106217b73c6fbcb80ca03e.mp3", "hash": "35ce97b427e3b7eaa654914d3535c43001af53525cce452ce87eeb8fae5e08e5", "bytes": 46368, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a4562159f829ab2446c2ae2726d40bff2e248c9318106217b73c6fbcb80ca03e.mp3", "duration_ms": 7680}, "s3-sort-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/21c809584eb74b74b0291d843b198cf09c63fdd62138d9ce114a5d57663ec9b5.mp3", "hash": "332a962c6114a909fcabaf94a043692283317a7be54f232c82dcffe311ea25e0", "bytes": 46944, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/21c809584eb74b74b0291d843b198cf09c63fdd62138d9ce114a5d57663ec9b5.mp3", "duration_ms": 7760}, "s4-timeline-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/caeb2ca903339ac3a5217e31c6637d30d24f129e1a655678d04db8b454e477b2.mp3", "hash": "1dbc0189240405398a77c4025d9b4b9f3321741140c978fa621813ac7704b33f", "bytes": 86256, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/caeb2ca903339ac3a5217e31c6637d30d24f129e1a655678d04db8b454e477b2.mp3", "duration_ms": 14320}, "s1-match-precios.prompt": {"url": "http://localhost:4006/files/lesson-audio/9a0555d2823a95a78b96006fd9516f47a753df0f71d384055167eaea15b66488.mp3", "hash": "cebdbb3aed9952b5d86ef9b86ee050ea2913517f94e199d1841dfed2bb375ddb", "bytes": 87264, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/9a0555d2823a95a78b96006fd9516f47a753df0f71d384055167eaea15b66488.mp3", "duration_ms": 14480}, "s2-order-receta.explanation": {"url": "http://localhost:4006/files/lesson-audio/7e7e6da574ef32b9cfcc4ed8fe633c449baafc3299b703c3c17a958b9fe70747.mp3", "hash": "b582c38c67d3cea4eb72e84bd662cc3504f388e21b66b626ce25aa5bf56535dc", "bytes": 56448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7e7e6da574ef32b9cfcc4ed8fe633c449baafc3299b703c3c17a958b9fe70747.mp3", "duration_ms": 9360}, "s3-sort-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/6da1968262964500fe2e9eacb38f1881523edd4196879658cc1b579bcf88f821.mp3", "hash": "500630d890c64a362c47b81bd5cfc2a772f22eb2914fd4652fdf5f74065547de", "bytes": 50688, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/6da1968262964500fe2e9eacb38f1881523edd4196879658cc1b579bcf88f821.mp3", "duration_ms": 8400}, "s4-timeline-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/51f019e66df9a69b1530541a2ca4d658d9b89f07ca2b3fb419f00de57f108267.mp3", "hash": "1f52e7ffccc0c2f3296afd6de381553ae77aa7825266a8ae38fa593c4b6a7b91", "bytes": 80064, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/51f019e66df9a69b1530541a2ca4d658d9b89f07ca2b3fb419f00de57f108267.mp3", "duration_ms": 13280}, "s1-match-precios.explanation": {"url": "http://localhost:4006/files/lesson-audio/7b1f37e9181746e32cb4fe9eb6c8ae62392f76609a8230bb1ce24ad7c5231704.mp3", "hash": "f81d7fac8b301add56caf1aa0c141c84002fa08a1878a64d0c3490179e033a79", "bytes": 120816, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/7b1f37e9181746e32cb4fe9eb6c8ae62392f76609a8230bb1ce24ad7c5231704.mp3", "duration_ms": 20080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "combo-arrange-largo", "title": "Grande limpeza noturna na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encadear várias habilidades em uma mesma lição: ouvir a situação, decidir, calcular e cobrar.", "Deixar a barraca pronta para amanhã: combinar preços, ordenar a receita, classificar compras e organizar a linha do tempo do dia."], "estimated_minutes": 15}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-precios", "xp": 5, "type": "match_pairs", "hints": ["Lembre-se de que um copo de limonada custa 5 MXN."], "title": "Combinar preços", "payload": {"left": [{"id": "vaso", "text_md": "Copo de limonada"}, {"id": "galletas", "text_md": "Pacote de biscoitos"}, {"id": "jugo", "text_md": "Suco de laranja"}], "right": [{"id": "precio5", "text_md": "5 MXN"}, {"id": "precio10", "text_md": "10 MXN"}, {"id": "precio20", "text_md": "20 MXN"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Liruf tem 37 MXN no caixa e precisa dar 20 MXN de troco a um cliente. Ajude Liruf a combinar cada produto com seu preço correto para saber quanto cobrar.", "difficulty": 1, "explanation_md": "Ótimo! O copo de limonada custa 5 MXN, o pacote de biscoitos 10 MXN e o suco de laranja 20 MXN. Assim, se um cliente comprar um suco de laranja (20 MXN) e pagar com 40 MXN, Liruf deve dar 20 MXN de troco.", "audio_segment_id": "s1-match-precios.prompt"}, {"id": "s2-order-receta", "xp": 5, "type": "order_steps", "hints": ["Primeiro espreme-se os limões, depois mistura-se com água e açúcar."], "title": "Ordenar a receita", "payload": {"items": [{"id": "exprimir", "text_md": "Espremer os limões"}, {"id": "mezclar", "text_md": "Misturar com água e açúcar"}, {"id": "servir", "text_md": "Servir em copos"}, {"id": "decorar", "text_md": "Decorar com uma rodela de limão"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina quer preparar limonada para amanhã. Ordene os passos para preparar a limonada, do primeiro ao último.", "difficulty": 1, "explanation_md": "Correto! Primeiro espremer, depois misturar, em seguida servir e finalmente decorar. Assim Dina terá limonada pronta para vender amanhã.", "audio_segment_id": "s2-order-receta.prompt"}, {"id": "s3-sort-compras", "xp": 5, "type": "sort_buckets", "hints": ["Os biscoitos são comida, a limonada é bebida."], "title": "Classificar compras", "payload": {"items": [{"id": "galletas", "text_md": "Biscoitos"}, {"id": "limonada", "text_md": "Limonada"}, {"id": "pan", "text_md": "Pão"}, {"id": "jugo", "text_md": "Suco de laranja"}], "buckets": [{"id": "comida", "label": "Comida"}, {"id": "bebida", "label": "Bebida"}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Rho está organizando as compras do dia. Classifique cada compra na categoria correta: ''Comida'' ou ''Bebida''.", "difficulty": 1, "explanation_md": "Muito bem! Os biscoitos e o pão vão em Comida; a limonada e o suco em Bebida. Assim Rho sabe o que repor amanhã.", "audio_segment_id": "s3-sort-compras.prompt"}, {"id": "s4-timeline-dia", "xp": 5, "type": "timeline_order", "hints": ["Primeiro abrem a barraca, depois atendem clientes, em seguida contam os ganhos e finalmente fecham."], "title": "Linha do tempo do dia", "payload": {"events": [{"id": "abrir", "icon": "store", "text_md": "Abrir a barraca"}, {"id": "atender", "icon": "people", "text_md": "Atender os clientes"}, {"id": "contar", "icon": "money", "text_md": "Contar os ganhos do dia"}, {"id": "cerrar", "icon": "lock", "text_md": "Fechar a barraca"}]}, "narrator": {"emotion": "neutral", "character": "zara"}, "prompt_md": "Zara está fechando a barraca. Lembre-se de que hoje ganharam 40 MXN e já têm 60 MXN economizados para o violão de 80 MXN. Ordene os eventos do dia na barraca, desde a abertura até o fechamento.", "difficulty": 1, "explanation_md": "Perfeito! Abrir, atender, contar ganhos e fechar é a ordem correta. Hoje ganharam 40 MXN, somando 60 MXN no total. Faltam apenas 20 MXN para o violão!", "audio_segment_id": "s4-timeline-dia.prompt"}], "schema_version": 1}', '{"s2-order-receta": {"order": ["exprimir", "mezclar", "servir", "decorar"]}, "s3-sort-compras": {"assignments": {"pan": "comida", "jugo": "bebida", "galletas": "comida", "limonada": "bebida"}}, "s4-timeline-dia": {"order": ["abrir", "atender", "contar", "cerrar"]}, "s1-match-precios": {"pairs": [["vaso", "precio5"], ["galletas", "precio10"], ["jugo", "precio20"]]}}', '{"units": {"s2-order-receta.prompt": {"url": "http://localhost:4006/files/lesson-audio/6de2f9a7e12cb47ebf4ff0c13eb220e26e50b1adcbda72997932cc2b4e2986ec.mp3", "hash": "99074839830ed581c958948cbe3912d8a437742bbe73e43c70418b5d6110ac71", "bytes": 44496, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6de2f9a7e12cb47ebf4ff0c13eb220e26e50b1adcbda72997932cc2b4e2986ec.mp3", "duration_ms": 7360}, "s3-sort-compras.prompt": {"url": "http://localhost:4006/files/lesson-audio/bcc84749bdc77142e36a85fa729eb5841dcc88e56ca4d21663b18f806cffd8ec.mp3", "hash": "f76aea866ce4fe65396ba44be3d6d20cc494de215116118be97efa9491524c96", "bytes": 51696, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/bcc84749bdc77142e36a85fa729eb5841dcc88e56ca4d21663b18f806cffd8ec.mp3", "duration_ms": 8560}, "s4-timeline-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/51c239d98d1d3ff480bc9d362a1f6395e436b1f83f888ef05e62b5ccbb5c8db5.mp3", "hash": "ae28a3983b23bfa450acfad9e1fcb3a723cb77ec38e0c9317f66e15267037799", "bytes": 93024, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/51c239d98d1d3ff480bc9d362a1f6395e436b1f83f888ef05e62b5ccbb5c8db5.mp3", "duration_ms": 15440}, "s1-match-precios.prompt": {"url": "http://localhost:4006/files/lesson-audio/e8b5f181523146be713c9d67748a7dee6b4c13ee2defb0b3188a79acdbe92cf7.mp3", "hash": "a680ac7417c7061efbf7796d945654669186beca448c3aedf9c6eb00b181b3d8", "bytes": 78048, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/e8b5f181523146be713c9d67748a7dee6b4c13ee2defb0b3188a79acdbe92cf7.mp3", "duration_ms": 12960}, "s2-order-receta.explanation": {"url": "http://localhost:4006/files/lesson-audio/f5337f8842c33d023449718c2ad6021065904cc8b0d0a861fa0e841e136020ed.mp3", "hash": "71804b7eda91833da33e04271b80996659fa2034cb49ad47c028e782a00365f6", "bytes": 63648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f5337f8842c33d023449718c2ad6021065904cc8b0d0a861fa0e841e136020ed.mp3", "duration_ms": 10560}, "s3-sort-compras.explanation": {"url": "http://localhost:4006/files/lesson-audio/3e92a757c912b3cbaf7276cf06b9fe13f9da277b09b353b7480fb1d97a866d2d.mp3", "hash": "ad040246adf73951732709382deef24ea830fdba0b8a360ad0be732877d67198", "bytes": 52704, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/3e92a757c912b3cbaf7276cf06b9fe13f9da277b09b353b7480fb1d97a866d2d.mp3", "duration_ms": 8720}, "s4-timeline-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/dd8372a2403d5828ff54c8a613842522f0743a425d37e038daffdceb2079987f.mp3", "hash": "9df20e354eb9584ee17c68b8b38bb674169af1ff22bfc8675e052709506fce2c", "bytes": 81504, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/dd8372a2403d5828ff54c8a613842522f0743a425d37e038daffdceb2079987f.mp3", "duration_ms": 13520}, "s1-match-precios.explanation": {"url": "http://localhost:4006/files/lesson-audio/0c8c4f729338ed5469135f673b2d59f16cedeb5e33d9bd0e16345945190669ca.mp3", "hash": "da7fb6fa267f10608101a4a64161bc5266123d435a9476c94f3691904b529a30", "bytes": 111744, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/0c8c4f729338ed5469135f673b2d59f16cedeb5e33d9bd0e16345945190669ca.mp3", "duration_ms": 18560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "true-false", "title": "True or false? Savings that grow", "locale": "en-US", "subject": "mixed", "objectives": ["Make simple money decisions by comparing options: fair price, safe place to keep money, and distinguish a good deal from a bad one.", "Decide if it''s true or false: ''If I save 5 pesos from each sale, my savings GROW every day.''"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 0, "type": "true_false", "hints": ["Think: if you save 5 pesos each day, does the total amount increase or stay the same?", "Imagine you save 5 today, another 5 tomorrow… the total adds up."], "title": "Savings that grow", "payload": {"statement_md": "If I save 5 pesos from each sale, my savings GROW every day.", "justifications": [{"id": "j-crece", "text_md": "It is true, because each day you add 5 more pesos, so the total increases."}, {"id": "j-no-crece", "text_md": "It is false, because saving the same amount each time does not make savings grow."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you know 5 pesos is a fair price for your lemonade, what happens if you save those 5 pesos every day? Dina and Liruf help you think about it. Dina says: ''If you save 5 pesos from each sale, you add 5 more each day. Look: Day 1: 5 pesos, Day 2: 10 pesos, Day 3: 15 pesos... savings grow!'' Liruf must decide if it''s true or false. What do you think?", "difficulty": 1, "explanation_md": "Correct! It is **true**: if you save 5 pesos each day, the total savings grow. For example, in 3 days you would have 15 pesos.", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "j-crece"}}', '{"units": {"s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/5d3994a3e3c8c4e268297d68150965e508992179e93eb6c9e4b9748def0a6b88.mp3", "hash": "7646a0c5499f98c19e5fc4893652a5bc618bf9ea5e3eff30cbabe46472b2daad", "bytes": 125136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5d3994a3e3c8c4e268297d68150965e508992179e93eb6c9e4b9748def0a6b88.mp3", "duration_ms": 20800}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/ff5ab3c9fda8f7b7f856bbebcffdd848cfd0ed97f5676f20f7b9b7880871b55b.mp3", "hash": "3ebeead921f1307ae43976972fdfff32ff9b9f50f87b6e7e3c81f05a67f781d1", "bytes": 45936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ff5ab3c9fda8f7b7f856bbebcffdd848cfd0ed97f5676f20f7b9b7880871b55b.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Say yes or no, case by case", "locale": "en-US", "subject": "mixed", "objectives": ["Make simple money decisions by comparing options: fair price, safe place to keep, and distinguishing a good deal from a bad one."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 0, "type": "yes_no_cases", "hints": ["Ask yourself: does this help sell more lemonade or take care of the stand?", "If you''re not sure, think about whether the expense is necessary today or can wait."], "title": "Yes or no, case by case", "payload": {"cases": [{"id": "case1", "text_md": "Buy more lemons to make lemonade."}, {"id": "case2", "text_md": "Buy a new toy to play with at the stand."}, {"id": "case3", "text_md": "Buy ice to keep the lemonade cold."}], "rule_md": "Decide if each expense helps the lemonade stand. If it''s necessary to sell or maintain the stand, it''s **yes**. If it''s a treat that can wait, it''s **no**."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you know how to give the correct change when a customer pays with a 20 bill, it''s time to decide what to spend that money on! Remember how you slowly counted out 15 pesos in change for the 5-peso glass... now that money is in your cash box and you must decide how to use it. Liruf is reviewing her list of temptations and needs. Help her decide if each expense helps her lemonade stand.", "difficulty": 1, "explanation_md": "Great! Remember: every spending decision should help the stand. As Liruf says, ''more lemons: yes; a new toy today: no, not yet''.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["case1", "case3"]}}', '{"units": {"s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/c2d1fcfa87f1cb7f32766dd031b992b1c32cad4051962c52a64633ab6d146261.mp3", "hash": "133586d9e81bd7ac64a3e57d3966780ee55f3c1df30b872914ef3f04bc55dd92", "bytes": 111744, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c2d1fcfa87f1cb7f32766dd031b992b1c32cad4051962c52a64633ab6d146261.mp3", "duration_ms": 18560}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/3209136036a9aa4c6fec312b40d7bb3536ea520bd0e5f9dcf62e11cbeebdb000.mp3", "hash": "009a6019f99a6be4770e3361e5cd47339936d70835e41d7612a321713ac58884", "bytes": 50688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3209136036a9aa4c6fec312b40d7bb3536ea520bd0e5f9dcf62e11cbeebdb000.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Decir sí o no, caso por caso", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 0, "type": "yes_no_cases", "hints": ["Pregúntate: ¿esto ayuda a vender más limonada o a cuidar el puesto?", "Si no estás seguro, piensa si el gasto es necesario hoy o puede esperar."], "title": "Sí o no, caso por caso", "payload": {"cases": [{"id": "case1", "text_md": "Comprar más limones para hacer limonada."}, {"id": "case2", "text_md": "Comprar un juguete nuevo para jugar en el puesto."}, {"id": "case3", "text_md": "Comprar hielo para mantener fría la limonada."}], "rule_md": "Decide si cada gasto ayuda al puesto de limonada. Si es necesario para vender o mantener el puesto, es **sí**. Si es un gusto que puede esperar, es **no**."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que ya sabes dar el cambio correcto cuando un cliente paga con un billete de 20, ¡es momento de decidir en qué gastar ese dinero! Recuerda cómo contaste despacio el cambio de 15 pesos para el vaso de 5... ahora ese dinero está en tu caja y debes decidir cómo usarlo. Liruf está revisando su lista de tentaciones y necesidades. Ayúdale a decidir si cada gasto ayuda a su puesto de limonada.", "difficulty": 1, "explanation_md": "¡Bien! Recuerda: cada decisión de gasto debe ayudar al puesto. Como dice Liruf, ''más limones: sí; un juguete nuevo hoy: no, todavía no''.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["case1", "case3"]}}', '{"units": {"s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/79184400c5d3b369420989eb13919818fa6daf4e9a926c502267bd9812bc7156.mp3", "hash": "5fa5242bfd588c503b0a68b6ac78b315b2dee7c3cd5076b1a659654dde997f5c", "bytes": 149184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/79184400c5d3b369420989eb13919818fa6daf4e9a926c502267bd9812bc7156.mp3", "duration_ms": 24800}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/f9885b69af545c958ba0d58679459643aaa9076e60571fac50e43e7e050da06b.mp3", "hash": "bce9a1e41f994a6a94c8796415bdea1c1be8e75fc1806f1e8055d20af10fbe2d", "bytes": 61344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f9885b69af545c958ba0d58679459643aaa9076e60571fac50e43e7e050da06b.mp3", "duration_ms": 10160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Dizer sim ou não, caso a caso", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões simples de dinheiro comparando opções: preço justo, lugar seguro para guardar e distinguir um bom negócio de um mau."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 0, "type": "yes_no_cases", "hints": ["Pergunte-se: isso ajuda a vender mais limonada ou a cuidar da barraca?", "Se não tiver certeza, pense se o gasto é necessário hoje ou pode esperar."], "title": "Sim ou não, caso a caso", "payload": {"cases": [{"id": "case1", "text_md": "Comprar mais limões para fazer limonada."}, {"id": "case2", "text_md": "Comprar um brinquedo novo para brincar na barraca."}, {"id": "case3", "text_md": "Comprar gelo para manter a limonada gelada."}], "rule_md": "Decida se cada gasto ajuda a barraca de limonada. Se for necessário para vender ou manter a barraca, é **sim**. Se for um desejo que pode esperar, é **não**."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você já sabe dar o troco certo quando um cliente paga com uma nota de 20, é hora de decidir em que gastar esse dinheiro! Lembre-se de como você contou devagar o troco de 15 reais para o copo de 5... agora esse dinheiro está no seu caixa e você precisa decidir como usá-lo. Liruf está revisando sua lista de tentações e necessidades. Ajude-o a decidir se cada gasto ajuda sua barraca de limonada.", "difficulty": 1, "explanation_md": "Bom! Lembre-se: cada decisão de gasto deve ajudar a barraca. Como diz Liruf, ''mais limões: sim; um brinquedo novo hoje: não, ainda não''.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["case1", "case3"]}}', '{"units": {"s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/b831be158e5f927f396b3485543f664bc1bdba71e0303ac11ddcb4d9d05c6ead.mp3", "hash": "378ad3380b1122fdcc35363c128caeaded98d97a92541fb2645bb12ecf7d49e7", "bytes": 148608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b831be158e5f927f396b3485543f664bc1bdba71e0303ac11ddcb4d9d05c6ead.mp3", "duration_ms": 24720}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/baae6085936cbf9ac6c1ac0de5466987a7350d2a9eda46ea7146f262d907d5f7.mp3", "hash": "6c3cc7308d1b48537660e7722218459a6057758c2b382b27e17ec913b465dcd5", "bytes": 70416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/baae6085936cbf9ac6c1ac0de5466987a7350d2a9eda46ea7146f262d907d5f7.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "Breathe and review before opening the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Understand that money is earned by offering something others want, and that a clear goal (the 80-peso guitar) helps you get started."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-checkpoint", "xp": 0, "type": "checkpoint", "hints": [], "title": "Breathe and review before opening the stand", "payload": {"recap_md": "As you discovered by flipping the cards, you already have a **goal** (80 pesos), a **product** (lemonade at 5 pesos), and you know what **cost** and **profit** are. For example, if you spend 20 pesos on lemons and sell 10 cups at 5 pesos, your profit is 30 pesos.", "mood_prompt_md": "How do you feel about opening the stand? Choose an option:"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Dina asks you: **Liruf**, how do you feel before the big opening day?", "difficulty": 1, "explanation_md": "Great! Remember your goal is the 80-peso guitar and your lemonade costs 5 pesos.", "audio_segment_id": "s1-checkpoint.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-checkpoint.recap": {"url": "http://localhost:4006/files/lesson-audio/dc68c8442c31245735234fb28bf5ccaafe7112c4f33b869251d31e6facdaaeb3.mp3", "hash": "15268322cb3377effce68ab7aec2d0d9dd63ae00bb999b6c6d3a8ada18d6317a", "bytes": 82368, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/dc68c8442c31245735234fb28bf5ccaafe7112c4f33b869251d31e6facdaaeb3.mp3", "duration_ms": 13680}, "s1-checkpoint.prompt": {"url": "http://localhost:4006/files/lesson-audio/cce4a0271d8067033653ddb60eb960cb4c3062b2765c39938910bf6e796692a5.mp3", "hash": "1cc8e2c65c9def7f1bf3628ffa19f35b584dab6c996fdc252a5595e9c3ba3f74", "bytes": 25344, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cce4a0271d8067033653ddb60eb960cb4c3062b2765c39938910bf6e796692a5.mp3", "duration_ms": 4160}, "s1-checkpoint.explanation": {"url": "http://localhost:4006/files/lesson-audio/94607aadba97c5e784f8b8117a16b9df8ee1fc0194599ebf61588f1702d51248.mp3", "hash": "0671687f30d34c6c04e4f03747668105b601d88c4569f54432eef7da9bfbeee5", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/94607aadba97c5e784f8b8117a16b9df8ee1fc0194599ebf61588f1702d51248.mp3", "duration_ms": 4880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "memory-flip", "title": "Jogo da memória com moedas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encontrar os pares escondidos de moedas iguais (1 com 1, 5 com 5, 10 com 10): reconhecer as moedas do México."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 0, "type": "memory_flip", "hints": ["Lembre-se: as moedas de 1 são as menores, as de 5 são prateadas e as de 10 têm o centro dourado."], "title": "Encontre os pares", "payload": {"pairs": [{"a_md": "Moeda de 1 peso", "b_md": "1"}, {"a_md": "Moeda de 5 pesos", "b_md": "5"}, {"a_md": "Moeda de 10 pesos", "b_md": "10"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que você já sabe os preços da barraca (copo pequeno: 5, jarra: 20, biscoito: 3), Zara quer ajudar você a reconhecer as moedas para cobrar direitinho. Ela inventou um jogo da memória com as moedas da caixa. Vire os cartões para encontrar pares de moedas iguais. Combine 1 com 1, 5 com 5 e 10 com 10! Por exemplo, Zara precisa de uma moeda de 5 pesos para comprar um biscoito.", "difficulty": 1, "explanation_md": "Muito bem! Você combinou as moedas de 1, 5 e 10. Assim você reconhece as moedas do México. Por exemplo, a moeda de 5 pesos serve para pagar um copo pequeno, a de 10 para dois biscoitos, e a de 1 para completar o troco.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/72cfb0e9eaadbff4d5144e12975d6ce033620e07e86d9d7146cb61c81c304842.mp3", "hash": "07225e9954925b3486e53fd5d444d9a5518a08550f1a426e5fbecf7fcdf522df", "bytes": 165888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/72cfb0e9eaadbff4d5144e12975d6ce033620e07e86d9d7146cb61c81c304842.mp3", "duration_ms": 27600}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/86347cdb007bfdbb76ce7555c3ff0729d29c1ee9ccba48b198b9912a2377d050.mp3", "hash": "e2f8fb5d85fd999fb6f1ae76c5be0439bfe25732366b95a44a7bc8fcfdf8c24d", "bytes": 95904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/86347cdb007bfdbb76ce7555c3ff0729d29c1ee9ccba48b198b9912a2377d050.mp3", "duration_ms": 15920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "price-compare", "title": "Comparar preços de limões no mercado", "locale": "pt-BR", "subject": "mixed", "objectives": ["Comparar preços de limões em duas barracas do mercado e escolher a mais barata para gastar menos (custo mais baixo = mais lucro)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 5, "type": "price_compare", "hints": ["Calcule o preço por limão dividindo o preço total pela quantidade de limões."], "title": "Qual barraca de limões é mais barata?", "payload": {"offers": [{"id": "puesto-a", "qty": 5, "unit": "limones", "label": "Barraca A: 5 limões por $10", "price": 10}, {"id": "puesto-b", "qty": 3, "unit": "limones", "label": "Barraca B: 3 limões por $5", "price": 5}], "currency": "MXN"}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembre-se de que os limões são uma necessidade para a barraca do Liruf, não um desejo pessoal. Agora vamos comprá-los pelo melhor preço.\\n\\nDina e Liruf estão no mercado. Dois vendedores gritam suas ofertas de limões. Liruf diz: \\"Preciso dos limões mais baratos para minha limonada!\\" Ajude a Dina a escolher a barraca mais barata para que Liruf gaste menos e ganhe mais em sua barraca de limonada.\\n\\n**Barraca A:** 5 limões por $10 MXN\\n**Barraca B:** 3 limões por $5 MXN\\n\\nQual barraca tem o menor preço por limão?", "difficulty": 1, "explanation_md": "Correto! A Barraca B custa $5 ÷ 3 ≈ $1,67 por limão, enquanto a Barraca A custa $10 ÷ 5 = $2 por limão. A Barraca B é mais barata!", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-b"}}', '{"units": {"s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/8f87a947b4fa05916214617fdbdbff9a01b8a8d1dadfe4c972b092152dac6e07.mp3", "hash": "93b95a8115eeaa91187b821e6ccdcaa4b84f54b2345b7c11022e2e212800bd24", "bytes": 220176, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8f87a947b4fa05916214617fdbdbff9a01b8a8d1dadfe4c972b092152dac6e07.mp3", "duration_ms": 36640}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/23888bd3a5f2f0cd31dffe875531550d4800807af7e9f8375a7be06a0777be02.mp3", "hash": "1c83e35efed7c54c2613796534142c1385e6fcc5cccbfdd6c7005a73a58b2eab", "bytes": 74304, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/23888bd3a5f2f0cd31dffe875531550d4800807af7e9f8375a7be06a0777be02.mp3", "duration_ms": 12320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "¿Cuánto ganó Liruf?", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular y escribir cuánto ganó Liruf en total si vendió 4 vasos a 5 pesos cada uno (20 pesos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-input", "xp": 10, "type": "number_input", "hints": ["Recuerda: cada vaso se vende a 5 pesos. Si vendió 4 vasos, suma 5 + 5 + 5 + 5.", "5 + 5 = 10, más 5 = 15, más 5 = 20."], "title": "Ganancia de Liruf", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Completar la frase de la ganancia: ''Vendí un vaso en 5 pesos, los ingredientes costaron 2, mi ganancia es ___ pesos''. Ahora, calcula cuánto ganó Liruf en total si vendió 4 vasos a 5 pesos cada uno. Escribe el número.", "difficulty": 1, "explanation_md": "¡Correcto! Liruf vendió 4 vasos a 5 pesos cada uno, así que 4 × 5 = 20 pesos en total.", "audio_segment_id": "s1-number-input.prompt"}], "schema_version": 1}', '{"s1-number-input": {"value": 20, "tolerance": 0}}', '{"units": {"s1-number-input.prompt": {"url": "http://localhost:4006/files/lesson-audio/5839e406dae9f528e2828a53ace830e6364cce6a186b4fe5f5841b7372ee062f.mp3", "hash": "2c9494c308e89d0ff72d73c292b2b0a25d126bf83c3221a1e1bee075f7e6eaef", "bytes": 102528, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5839e406dae9f528e2828a53ace830e6364cce6a186b4fe5f5841b7372ee062f.mp3", "duration_ms": 17040}, "s1-number-input.explanation": {"url": "http://localhost:4006/files/lesson-audio/d761b54ac0cea68c01b43444989301e5187b1c0f7cddef70c85002300d74e91b.mp3", "hash": "e9922b2e70769b68ad1356d96c2928dc485d65c95a874c07563c067fed43eb0e", "bytes": 47808, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d761b54ac0cea68c01b43444989301e5187b1c0f7cddef70c85002300d74e91b.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Causa y efecto en el puesto de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar un error en una suma de ventas", "Leer una gráfica simple de vasos vendidos por día", "Reconocer señales de un mal trato"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-causa-efecto", "xp": 0, "type": "cause_effect", "hints": ["Piensa: si hace calor, la gente tiene más sed."], "title": "Conecta causas y efectos", "payload": {"slots": 3, "events": [{"id": "e1", "text_md": "Día soleado y caluroso"}, {"id": "e2", "text_md": "Subir el precio de 5 MXN a 10 MXN"}, {"id": "e3", "text_md": "Liruf pone música alegre en el puesto"}, {"id": "e4", "text_md": "Un cliente dice que la limonada está muy dulce"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Recordemos que ayer descubrimos que Liruf sumó mal sus ventas: dijo que vendió 20 vasos, pero en realidad fueron 5+5+5=15. Hoy vamos a practicar detectando errores en sumas de ventas. Primero, ayuda a Liruf a entender qué pasó en sus ventas. Une cada causa con su efecto.", "difficulty": 1, "explanation_md": "¡Excelente! Día soleado causa más sed, lo que lleva a más vasos vendidos. Subir el precio al doble causa menos clientes. Ahora, revisa esta cuenta: Liruf anotó que el lunes vendió 6 vasos, martes 7, miércoles 8, y dijo que el total fue 25. ¿Es correcto? 6+7+8=21, no 25. ¡Encuentra el error!", "audio_segment_id": "s1-causa-efecto.prompt"}], "schema_version": 1}', '{"s1-causa-efecto": {"chain": ["e1", "e2", "e3"]}}', '{"units": {"s1-causa-efecto.prompt": {"url": "http://localhost:4006/files/lesson-audio/420dffa811b4cf14cc57a4242f9acea43869f0825e3ea480e8c9c2a2b05d38f4.mp3", "hash": "654aca16fc6ebca66874b442bfaf24f6d46f7fddc5d657c28b621bbf43a712e3", "bytes": 119376, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/420dffa811b4cf14cc57a4242f9acea43869f0825e3ea480e8c9c2a2b05d38f4.mp3", "duration_ms": 19840}, "s1-causa-efecto.explanation": {"url": "http://localhost:4006/files/lesson-audio/714b17688e49967300a245982c461a8dae5ec8e7ec60374074b64665f02955fd.mp3", "hash": "8647a06e8d3688f5614f70214e4f012bbf877a62a1988bcbb0d2b092f927bea7", "bytes": 148608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/714b17688e49967300a245982c461a8dae5ec8e7ec60374074b64665f02955fd.mp3", "duration_ms": 24720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Causa e efeito na barraca de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar um erro em uma soma de vendas", "Ler um gráfico simples de copos vendidos por dia", "Reconhecer sinais de um mau negócio"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-causa-efecto", "xp": 0, "type": "cause_effect", "hints": ["Pense: se faz calor, as pessoas têm mais sede."], "title": "Conecte causas e efeitos", "payload": {"slots": 3, "events": [{"id": "e1", "text_md": "Dia ensolarado e quente"}, {"id": "e2", "text_md": "Aumentar o preço de 5 MXN para 10 MXN"}, {"id": "e3", "text_md": "Liruf coloca música alegre na barraca"}, {"id": "e4", "text_md": "Um cliente diz que a limonada está muito doce"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lembra que ontem descobrimos que Liruf somou errado suas vendas: disse que vendeu 20 copos, mas na verdade foram 5+5+5=15. Hoje vamos praticar detectando erros em somas de vendas. Primeiro, ajude Liruf a entender o que aconteceu em suas vendas. Ligue cada causa ao seu efeito.", "difficulty": 1, "explanation_md": "Excelente! Dia ensolarado causa mais sede, o que leva a mais copos vendidos. Aumentar o preço ao dobro causa menos clientes. Agora, revise esta conta: Liruf anotou que na segunda vendeu 6 copos, terça 7, quarta 8, e disse que o total foi 25. Está correto? 6+7+8=21, não 25. Encontre o erro!", "audio_segment_id": "s1-causa-efecto.prompt"}], "schema_version": 1}', '{"s1-causa-efecto": {"chain": ["e1", "e2", "e3"]}}', '{"units": {"s1-causa-efecto.prompt": {"url": "http://localhost:4006/files/lesson-audio/22ee2884d66d7596c820f686b0cf761b423d6e87d2f3fc1adc81291d4be93ca3.mp3", "hash": "f55750b96b995e6f82069a075ce1ea3fa922afcd02e4df06aaf8471ee76cf29c", "bytes": 121248, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/22ee2884d66d7596c820f686b0cf761b423d6e87d2f3fc1adc81291d4be93ca3.mp3", "duration_ms": 20160}, "s1-causa-efecto.explanation": {"url": "http://localhost:4006/files/lesson-audio/366c101156ca62c202a4bf3775e97bc29950b1446436bf9aa5513c81f0bfea85.mp3", "hash": "a34b7baaadd38e95a81d10f3ed98b4e60a716df9838f9b797e8dfd699d66d41e", "bytes": 151056, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/366c101156ca62c202a4bf3775e97bc29950b1446436bf9aa5513c81f0bfea85.mp3", "duration_ms": 25120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Troca justa: trocar limonada por limões?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Decidir se uma troca é justa comparando valores de duas ofertas usando moedas de 1, 2, 5 e 10."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 0, "type": "fair_trade", "hints": ["Cada copo de limonada custa 5 pesos. Quanto valem 2 copos?", "Compare o valor total dos copos com o valor do saco de limões."], "title": "Troca justa: trocar limonada por limões?", "payload": {"offer_a": {"qty": 2, "icon": "cup", "label": "Copos de limonada"}, "offer_b": {"qty": 1, "icon": "lemon", "label": "Saco de limões"}, "rate_md": "Cada copo de limonada custa **5 pesos**."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf continua economizando para seu violão de 80 pesos. Já sabe que precisa de 4 semanas economizando 20 pesos a cada semana. Hoje, enquanto prepara limonada para vender, o feirante lhe faz uma oferta: trocar 2 copos de limonada por um saco de limões que vale 10 pesos. A troca é justa?", "difficulty": 1, "explanation_md": "Correto! 2 copos de limonada valem 10 pesos (2 × 5 = 10), igual ao saco de limões. É uma troca justa!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/850642786cf3740ecde0be0e03e2f987e8ec69e89fa903b6dc4dc44736bd7ce7.mp3", "hash": "4fd4673a0560cda0abc1ff814f8679d2d9223fcf101617d13662ae33d06fbcd0", "bytes": 129024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/850642786cf3740ecde0be0e03e2f987e8ec69e89fa903b6dc4dc44736bd7ce7.mp3", "duration_ms": 21440}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/5b92e6d97f22f1f3fef874f37592fb8de655b042125eaf7b1926829e27d4505a.mp3", "hash": "b233a3981559b8ae4717f2004cb75e5da9828da5a553be2e3ea4d6fb4d62ca00", "bytes": 66096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5b92e6d97f22f1f3fef874f37592fb8de655b042125eaf7b1926829e27d4505a.mp3", "duration_ms": 10960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confidence in your accounts", "locale": "en-US", "subject": "mixed", "objectives": ["Make simple money decisions by comparing options: fair price, safe place to keep, and distinguish a good deal from a bad one."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence", "xp": 0, "type": "confidence_quiz", "hints": ["Hint: If one glass is worth 5, two glasses are worth 5 + 5."], "title": "Confidence in your accounts", "payload": {"options": [{"id": "opt-10", "text_md": "10 MXN", "rationale_md": "Correct. 5 + 5 = 10."}, {"id": "opt-8", "text_md": "8 MXN", "rationale_md": "8 is less than 10. Remember, each glass costs 5, so two are 10."}, {"id": "opt-12", "text_md": "12 MXN", "rationale_md": "12 is more than 10. 5 + 5 does not equal 12, but 10."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Now that you know how to recognize real coins, let''s help Liruf count what he earned! Liruf sold two glasses of lemonade. Each glass costs 5 MXN. How much money did he receive in total?", "difficulty": 1, "explanation_md": "Exactly! Two glasses at 5 MXN each add up to 10 MXN. Liruf is happy.", "audio_segment_id": "s1-confidence.prompt"}], "schema_version": 1}', '{"s1-confidence": {"correct_option_id": "opt-10"}}', '{"units": {"s1-confidence.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d20a6295e33b59c2e2acc6b26f4c82188dc86ded1e2d4223f32946ebddf019e.mp3", "hash": "1a4faea0a4e06c677e88ea3b861186f724b36050d3170c1305060437080ec413", "bytes": 67536, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8d20a6295e33b59c2e2acc6b26f4c82188dc86ded1e2d4223f32946ebddf019e.mp3", "duration_ms": 11200}, "s1-confidence.explanation": {"url": "http://localhost:4006/files/lesson-audio/749c3e242c215fb2746382f5bacdaf1b9ce21632692da1665e6fe5656ffeb00a.mp3", "hash": "a95974eb5f871ae1ea3acb560be1d03ebc9c51f2801cfe0760292523596b58a6", "bytes": 32544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/749c3e242c215fb2746382f5bacdaf1b9ce21632692da1665e6fe5656ffeb00a.mp3", "duration_ms": 5360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confianza en tus cuentas", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence", "xp": 0, "type": "confidence_quiz", "hints": ["Pista: Si un vaso vale 5, dos vasos valen 5 + 5."], "title": "Confianza en tus cuentas", "payload": {"options": [{"id": "opt-10", "text_md": "10 MXN", "rationale_md": "Correcto. 5 + 5 = 10."}, {"id": "opt-8", "text_md": "8 MXN", "rationale_md": "8 es menor que 10. Recuerda que cada vaso cuesta 5, así que dos son 10."}, {"id": "opt-12", "text_md": "12 MXN", "rationale_md": "12 es más que 10. 5 + 5 no da 12, sino 10."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Ahora que ya sabes reconocer monedas de verdad, ¡ayudemos a Liruf a contar lo que ganó! Liruf vendió dos vasos de limonada. Cada vaso cuesta 5 MXN. ¿Cuánto dinero recibió en total?", "difficulty": 1, "explanation_md": "¡Exacto! Dos vasos a 5 MXN cada uno suman 10 MXN. Liruf está contento.", "audio_segment_id": "s1-confidence.prompt"}], "schema_version": 1}', '{"s1-confidence": {"correct_option_id": "opt-10"}}', '{"units": {"s1-confidence.prompt": {"url": "http://localhost:4006/files/lesson-audio/8daf103cf31b78a92cb7f46f1a551d928b2dd70a565514c92953438224216c51.mp3", "hash": "2d45a28f260b81b43bc028620186c452572165307147dbea2d5e3140be9b1dd3", "bytes": 74304, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8daf103cf31b78a92cb7f46f1a551d928b2dd70a565514c92953438224216c51.mp3", "duration_ms": 12320}, "s1-confidence.explanation": {"url": "http://localhost:4006/files/lesson-audio/7b49fbf703d31f73804f6d946d5b7f250b01369bd107874534426fefd3b62e96.mp3", "hash": "70740a89f6bad8c6c73d674d7dfdd48550cc35f20843e3b2f3c1e81547978688", "bytes": 44496, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7b49fbf703d31f73804f6d946d5b7f250b01369bd107874534426fefd3b62e96.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "picture-choice", "title": "Práctica: Elige la imagen correcta", "locale": "es-MX", "subject": "mixed", "objectives": ["Verificar el ejercicio ''picture_choice'' de forma aislada (incluye generación de imágenes)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-picture-choice", "xp": 0, "type": "picture_choice", "hints": ["Pista: Busca la moneda o billete que vale 5 pesos."], "title": "Elige la imagen correcta", "payload": {"options": [{"id": "opt1", "icon": "coin", "label": "5 pesos", "image_url": "https://example.com/5pesos.png", "rationale_md": "Correcto. Esta es la moneda de 5 pesos que Zara necesita."}, {"id": "opt2", "icon": "apple", "label": "Manzana", "image_url": "https://example.com/apple.png", "rationale_md": "La manzana es lo que Zara quiere comprar, pero no es el precio."}, {"id": "opt3", "icon": "banana", "label": "Plátano", "image_url": "https://example.com/banana.png", "rationale_md": "El plátano es otra fruta, no el precio de la manzana."}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "¡Hola! La última vez ayudaste a Dina a contar monedas. Ahora Zara quiere comprar una manzana. **Mira las imágenes** y elige la que muestra cuánto cuesta la manzana.\\n\\n**¿Cuál de estas imágenes muestra 5 pesos?**", "difficulty": 1, "explanation_md": "¡Muy bien! La imagen con la moneda de 5 pesos es la correcta. Las otras opciones muestran una manzana y un plátano.", "audio_segment_id": "s1-picture-choice.prompt"}], "schema_version": 1}', '{"s1-picture-choice": {"correct_option_id": "opt1"}}', '{}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'es-MX', '1', E'{"meta": {"cast": ["rho", "liruf"], "slug": "rank-choices", "title": "Prioriza tus compras", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar de más a menos urgente en qué gastar la ganancia de hoy: reponer limones primero, luego vasos, y al final adornos."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank-choices", "xp": 15, "type": "rank_choices", "hints": ["Piensa: ¿qué necesitas para seguir vendiendo limonada mañana?", "Los limones son la base de la receta, sin ellos no hay limonada."], "title": "¿Qué comprar primero?", "payload": {"items": [{"id": "limones", "text_md": "Reponer limones"}, {"id": "vasos", "text_md": "Comprar vasos nuevos"}, {"id": "adornos", "text_md": "Adornos para el puesto"}], "criterion_md": "Ordena de **más urgente** a **menos urgente** para el puesto de limonada."}, "narrator": {"emotion": "neutral", "character": "rho"}, "prompt_md": "Ayer ordenaste los pasos para hacer limonada. ¡Hoy ordenarás qué comprar primero con las ganancias!\\n\\nRho ganó **20 pesos** en su puesto de limonada. Ayuda a Rho a ordenar las compras de la más urgente a la menos urgente.", "difficulty": 2, "explanation_md": "¡Excelente! Primero reponer limones porque son la base de la receta. Luego vasos para servir, y al final adornos que pueden esperar.", "audio_segment_id": "s1-rank-choices.prompt"}], "schema_version": 1}', '{"s1-rank-choices": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-rank-choices.prompt": {"url": "http://localhost:4006/files/lesson-audio/729d1b0e370a71511024f6f2aa312864ebf4e8355b4222cd55d26c25a491efe0.mp3", "hash": "a4f024af2e2cafbfcd2196c46fa645b9858f51069eb409cb5c9682d07737b6de", "bytes": 88128, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/729d1b0e370a71511024f6f2aa312864ebf4e8355b4222cd55d26c25a491efe0.mp3", "duration_ms": 14640}, "s1-rank-choices.explanation": {"url": "http://localhost:4006/files/lesson-audio/90244025efb63648ac0ff649315cbd504dd76704e3eae58a15e74caa7235170a.mp3", "hash": "c3151cde9cf9de15e400cc424bb3f1de5634f6149ad68835ee3a8b2f6f1318d3", "bytes": 53568, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/90244025efb63648ac0ff649315cbd504dd76704e3eae58a15e74caa7235170a.mp3", "duration_ms": 8880}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "evidence-hunt", "title": "The Search for Evidence", "locale": "en-US", "subject": "mixed", "objectives": ["Detect an Error in a Sales Sum", "Read a Simple Graph of Cups Sold per Day", "Recognize Signs of a Bad Deal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 0, "type": "evidence_hunt", "hints": ["Look on the receipt for the line that says ''lemons''.", "The price is after the product name."], "title": "The Search for Evidence", "payload": {"claim_md": "The lemons cost **15 MXN**.", "sentences": [{"id": "s1", "text_md": "Lemons: 15 MXN"}, {"id": "s2", "text_md": "Sugar: 10 MXN"}, {"id": "s3", "text_md": "Cups: 8 MXN"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Last week we saw that Saturday was the best day because they sold more cups. Today, Dina reviews the expenses to see how much they really earned. Dina found the market receipt. Help her find out how much the lemons cost.", "difficulty": 1, "explanation_md": "Correct! The receipt shows that the lemons cost 15 MXN, just as you saw.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{"units": {"s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/26cfe406b51248f06fdbcce8df00f28f2689c25e9d1e8d8f605b14306c4e501c.mp3", "hash": "d58ce89e9a8c4537075cf1da7c789298698c97fd7beee8274be175fa22e8a45e", "bytes": 69408, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/26cfe406b51248f06fdbcce8df00f28f2689c25e9d1e8d8f605b14306c4e501c.mp3", "duration_ms": 11520}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/6f75db312e8e598dd2b0df6e411a31e9ae28468d01551db674bf24bb539e6232.mp3", "hash": "096157c2f1728462bebd19cf4286ca09cdc1a4ebed436f38ab4d570c0f75cd59", "bytes": 29664, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6f75db312e8e598dd2b0df6e411a31e9ae28468d01551db674bf24bb539e6232.mp3", "duration_ms": 4880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho", "zara"], "slug": "evidence-hunt", "title": "A busca pela evidência", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar um erro em uma soma de vendas", "Ler um gráfico simples de copos vendidos por dia", "Reconhecer sinais de um mau negócio"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 0, "type": "evidence_hunt", "hints": ["Procure no recibo a linha que diz ''limões''.", "O preço está depois do nome do produto."], "title": "A busca pela evidência", "payload": {"claim_md": "Os limões custaram **15 MXN**.", "sentences": [{"id": "s1", "text_md": "Limões: 15 MXN"}, {"id": "s2", "text_md": "Açúcar: 10 MXN"}, {"id": "s3", "text_md": "Copos: 8 MXN"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Na semana passada vimos que sábado foi o melhor dia porque venderam mais copos. Hoje, Dina revisa os gastos para ver quanto realmente ganharam. Dina encontrou o recibo do mercado. Ajude-a a descobrir quanto custaram os limões.", "difficulty": 1, "explanation_md": "Correto! O recibo mostra que os limões custaram 15 MXN, exatamente como você viu.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1"]}}', '{"units": {"s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/edba1ca8dca867a12a49d801b5b12a653ce82a72af14e8b892356d0950cab2a7.mp3", "hash": "2a23109446e93802d6289e8558864f348aa34f829dbcbf5b1572faeb1e61a353", "bytes": 89568, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/edba1ca8dca867a12a49d801b5b12a653ce82a72af14e8b892356d0950cab2a7.mp3", "duration_ms": 14880}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/6cd74ea36c1d44f494a031ad5395c4cc5337953d37f6edd2181ed95cc9aa04e1.mp3", "hash": "25f1674807bc79d7b99aa270adfe3c44797e8f391cf75d46cf0779da6caa342f", "bytes": 43056, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6cd74ea36c1d44f494a031ad5395c4cc5337953d37f6edd2181ed95cc9aa04e1.mp3", "duration_ms": 7120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "Would You Rather…? Stand Decisions", "locale": "en-US", "subject": "mixed", "objectives": ["Choose between two seller paths and defend it: earn 10 pesos today or 20 next week? There''s no single answer, there are reasons."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 0, "type": "would_you_rather", "hints": [], "title": "Would You Rather…?", "payload": {"a": {"icon": "coin", "text_md": "Earn **10 pesos** today by selling a glass of lemonade to a hurried customer."}, "b": {"icon": "calendar", "text_md": "Earn **20 pesos** next week if you offer a special deal to the same customer."}, "followup_md": "What do you prefer? There''s no wrong answer, just different consequences."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Lightning round of stand accounts: cup sums and simple change against the clock. Now, Dina gives you a dilemma.", "difficulty": 1, "explanation_md": "Dina will explain why both options make sense.", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 0, "b": 0}, "reveal_md": "¡Gran elección! Si elegiste **A**, hoy tienes 10 pesos seguros. Si elegiste **B**, esperas una semana para ganar el doble. Ambas son decisiones válidas. Dina dice: *''Lo importante es pensar en lo que más te conviene ahora y después.''*"}}', '{"units": {"s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/fdacea8a9ddc8ba8eebb2cfe4c2538db97aef8baa2137b1dceadf9c011ce0280.mp3", "hash": "c90e35ac8c77a94939a69bfafe7dab2a8dfe9683e0b7667703f881edf460444d", "bytes": 36288, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fdacea8a9ddc8ba8eebb2cfe4c2538db97aef8baa2137b1dceadf9c011ce0280.mp3", "duration_ms": 6000}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/3072a5e0888c7b78eb30ad0d5ef3e183e88522c7f6e09e194561561a985be831.mp3", "hash": "166ec533f58eef1fb18451ce9ff2c570a15feacd298eff174d8bc4a5d04f852a", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3072a5e0888c7b78eb30ad0d5ef3e183e88522c7f6e09e194561561a985be831.mp3", "duration_ms": 2720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "¿Você prefere…? Decisões na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher entre dois caminhos do vendedor e defendê-lo: ganhar 10 reais hoje ou 20 na próxima semana? Não há resposta única, há razões."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 0, "type": "would_you_rather", "hints": [], "title": "¿Você prefere…?", "payload": {"a": {"icon": "coin", "text_md": "Ganhar **10 reais** hoje vendendo um copo de limonada para um cliente apressado."}, "b": {"icon": "calendar", "text_md": "Ganhar **20 reais** na próxima semana se você oferecer um trato especial ao mesmo cliente."}, "followup_md": "O que você prefere? Não há resposta errada, apenas consequências diferentes."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Rodada relâmpago de contas da barraca: somas de copos e trocos simples contra o relógio. Agora, Dina te coloca um dilema.", "difficulty": 1, "explanation_md": "Dina vai explicar por que ambas as opções fazem sentido.", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 0, "b": 0}, "reveal_md": "¡Gran elección! Si elegiste **A**, hoy tienes 10 pesos seguros. Si elegiste **B**, esperas una semana para ganar el doble. Ambas son decisiones válidas. Dina dice: *''Lo importante es pensar en lo que más te conviene ahora y después.''*"}}', '{"units": {"s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/9f5c190faa64f6621afcd1644eedaf18bf1218a38e7348d55b3a826aaeb14177.mp3", "hash": "f50f545d685fb8c7f7663e0e7031d402da7ad6affe4f09c0e07be03135ed174a", "bytes": 60768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9f5c190faa64f6621afcd1644eedaf18bf1218a38e7348d55b3a826aaeb14177.mp3", "duration_ms": 10080}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/f3dd128f47820cfb742701133230a0d3f5fe144a7641d256415789f44b3bcf5e.mp3", "hash": "48ad8e4ef68e555dc76e092adb19e3cea5e2535fc918ce2e6b68321bb14eb6fe", "bytes": 24336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f3dd128f47820cfb742701133230a0d3f5fe144a7641d256415789f44b3bcf5e.mp3", "duration_ms": 4000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "measure-read", "title": "O copo medidor: serve copos iguais", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler a marca do copo medidor para servir copos iguais: cada copo exatamente até a linha, nem mais nem menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-measure-read", "xp": 10, "type": "measure_read", "hints": ["Observe a linha onde a agulha aponta. Cada linha grande vale 100 ml."], "title": "O copo medidor", "payload": {"max": 1000, "min": 0, "unit": "ml", "ticks": 10, "instrument": "beaker", "pointer_value": 500}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Agora que sabemos equilibrar valores, vamos ver como medir quantidades iguais para dividir de forma justa! Liruf tem um copo medidor com marcas a cada 100 ml. O copo vai de 0 ml a 1000 ml. A agulha aponta para 500 ml. Quantos ml há no copo?", "difficulty": 1, "explanation_md": "Correto! A agulha está exatamente na marca de 500 ml, que é a metade do copo.", "audio_segment_id": "s1-measure-read.prompt"}], "schema_version": 1}', '{"s1-measure-read": {"value": 500, "tolerance": 0}}', '{"units": {"s1-measure-read.prompt": {"url": "http://localhost:4006/files/lesson-audio/73009a16bf8eae563e5f048398a8ed08558b1ce3df9fd29adafc9c2551dd4d69.mp3", "hash": "8736b934bd7a056b4777ac310b9f78634de37827bacb2f382247fa46461fa868", "bytes": 109728, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/73009a16bf8eae563e5f048398a8ed08558b1ce3df9fd29adafc9c2551dd4d69.mp3", "duration_ms": 18240}, "s1-measure-read.explanation": {"url": "http://localhost:4006/files/lesson-audio/9469416c73083255ef212a8bffcd7e1647950e266e80cffbffc5dd7bc8544413.mp3", "hash": "129646d9d1692668614277ad05c56f769b1c04b2d136c5c9c5d4fbaba7f03068", "bytes": 43488, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9469416c73083255ef212a8bffcd7e1647950e266e80cffbffc5dd7bc8544413.mp3", "duration_ms": 7200}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Distribute the profit", "locale": "en-US", "subject": "mixed", "objectives": ["Distribute 10 pesos of profit between two piggy banks", "Count coins of 1, 2, 5, and 10", "Calculate change from a 20-peso bill"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 0, "type": "piggy_split", "hints": ["First calculate the change: 20 - (2 × 5) = ?", "Then, decide how much of the 10 pesos goes to each piggy bank."], "title": "Distribute the profit", "payload": {"jars": [{"id": "guitar", "icon": "guitar", "label": "Guitar piggy bank", "hint_md": "Goal: 80 pesos"}, {"id": "stand", "icon": "shop", "label": "Stall piggy bank", "hint_md": "To restock ingredients"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Today you sold 2 glasses of lemonade. Each glass costs 5 pesos. They pay you with a 20-peso bill. How much change should you give? Then, with that profit of 10 pesos, distribute between the guitar piggy bank (goal: 80 pesos) and the stall piggy bank (to restock ingredients).", "difficulty": 1, "explanation_md": "Great! The change is 20 - 10 = 10 pesos. You distributed 6 for the guitar and 4 for the stall, so you''re making progress toward the goal!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"stand": {"max": 5, "min": 2}, "guitar": {"max": 8, "min": 5}}, "rationale_md": "Repartir 10 pesos: puedes poner entre 5 y 8 para la guitarra (mitad o más) y el resto para el puesto. Por ejemplo, 6 y 4."}}', '{"units": {"s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/59a05f9839b5250c69dea842b0e90e11416739abdbad02710c3192b8902deb6f.mp3", "hash": "b0b013b337559579374fcba8bb2283e7e1b9fecf867c2068459d976a31a12fa8", "bytes": 94896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/59a05f9839b5250c69dea842b0e90e11416739abdbad02710c3192b8902deb6f.mp3", "duration_ms": 15760}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/ba91d8d1697315ce12c29b7f307a50e170bdbdabbaa856213ec63738220ad1f1.mp3", "hash": "86e5fce3f70a2e765b90942da50985b98cecb8c5780de6206e308868e61a7fd4", "bytes": 52128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ba91d8d1697315ce12c29b7f307a50e170bdbdabbaa856213ec63738220ad1f1.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Repartir la ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Repartir 10 pesos de ganancia entre dos alcancías", "Contar monedas de 1, 2, 5 y 10", "Calcular cambio de un billete de 20"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 0, "type": "piggy_split", "hints": ["Primero calcula el cambio: 20 - (2 × 5) = ?", "Luego, decide cuánto de los 10 pesos va a cada alcancía."], "title": "Repartir la ganancia", "payload": {"jars": [{"id": "guitar", "icon": "guitar", "label": "Alcancía de la guitarra", "hint_md": "Meta: 80 pesos"}, {"id": "stand", "icon": "shop", "label": "Alcancía del puesto", "hint_md": "Para reponer ingredientes"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hoy vendiste 2 vasos de limonada. Cada vaso cuesta 5 pesos. Te pagan con un billete de 20. ¿Cuánto cambio debes dar? Luego, con esa ganancia de 10 pesos, reparte entre la alcancía de la guitarra (meta: 80 pesos) y la alcancía del puesto (para reponer ingredientes).", "difficulty": 1, "explanation_md": "¡Bien! El cambio es 20 - 10 = 10 pesos. Repartiste 6 para la guitarra y 4 para el puesto, ¡así avanzas a la meta!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"stand": {"max": 5, "min": 2}, "guitar": {"max": 8, "min": 5}}, "rationale_md": "Repartir 10 pesos: puedes poner entre 5 y 8 para la guitarra (mitad o más) y el resto para el puesto. Por ejemplo, 6 y 4."}}', '{"units": {"s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/8e272e85e305a7b521972c991e44018c6a8cc4ad66be9278e14044169dbdcddc.mp3", "hash": "66ef3a45f6eaa48f66bb0da1c39757666fb4df5bb021b1f99d33d4abc1bac16d", "bytes": 116064, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8e272e85e305a7b521972c991e44018c6a8cc4ad66be9278e14044169dbdcddc.mp3", "duration_ms": 19280}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/30fc53033b4651d340131bd9d1045924c644d154f0424247ccc6cb47df959362.mp3", "hash": "ce450b7aef669bb6dcb75d4b81e07c1497c1a26cf9d0842ee59ddca00ad8e8bd", "bytes": 59904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/30fc53033b4651d340131bd9d1045924c644d154f0424247ccc6cb47df959362.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Dividir o lucro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Dividir 10 pesos de lucro entre dois cofrinhos", "Contar moedas de 1, 2, 5 e 10", "Calcular troco de uma nota de 20"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-piggy-split", "xp": 0, "type": "piggy_split", "hints": ["Primeiro calcule o troco: 20 - (2 × 5) = ?", "Depois, decida quanto dos 10 pesos vai para cada cofrinho."], "title": "Dividir o lucro", "payload": {"jars": [{"id": "guitar", "icon": "guitar", "label": "Cofrinho do violão", "hint_md": "Meta: 80 pesos"}, {"id": "stand", "icon": "shop", "label": "Cofrinho da barraca", "hint_md": "Para repor ingredientes"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Hoje você vendeu 2 copos de limonada. Cada copo custa 5 pesos. Pagam com uma nota de 20. Quanto troco você deve dar? Depois, com esse lucro de 10 pesos, divida entre o cofrinho do violão (meta: 80 pesos) e o cofrinho da barraca (para repor ingredientes).", "difficulty": 1, "explanation_md": "Bom! O troco é 20 - 10 = 10 pesos. Você dividiu 6 para o violão e 4 para a barraca, assim você avança para a meta!", "audio_segment_id": "s1-piggy-split.prompt"}], "schema_version": 1}', '{"s1-piggy-split": {"targets": {"stand": {"max": 5, "min": 2}, "guitar": {"max": 8, "min": 5}}, "rationale_md": "Repartir 10 pesos: puedes poner entre 5 y 8 para la guitarra (mitad o más) y el resto para el puesto. Por ejemplo, 6 y 4."}}', '{"units": {"s1-piggy-split.prompt": {"url": "http://localhost:4006/files/lesson-audio/3e3f9ab4c6e915e53eea289885dee1d43fa99710aa4517d9f5aa9f28588404ab.mp3", "hash": "0219e502df9e1877e545f14fd9b17e04b0a4fbd970f30ce5f43a1a7ba7bccfc5", "bytes": 117504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3e3f9ab4c6e915e53eea289885dee1d43fa99710aa4517d9f5aa9f28588404ab.mp3", "duration_ms": 19520}, "s1-piggy-split.explanation": {"url": "http://localhost:4006/files/lesson-audio/09ddd05bc130a7c24ef1cfb851eda0fbd1449233c37efbd838918efa8a9083fe.mp3", "hash": "5e4054ee40b8ec9a63d5f031589ed38986b7e4b3a9790069f82f39ccf21109e9", "bytes": 58896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/09ddd05bc130a7c24ef1cfb851eda0fbd1449233c37efbd838918efa8a9083fe.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Write the word ''savings''", "locale": "en-US", "subject": "mixed", "objectives": ["Write the word that names the money you keep for later: ''savings''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Starts with the letter S and has 7 letters.", "It is the opposite of spending: keeping for later."], "title": "Write the secret word", "payload": {"max_chars": 10, "placeholder": "Write here..."}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Dina and Rho tell you: Rho saved 3 pesos from his lemonade sale. That is savings. Remember how you added 5+5 and felt confident? Now, write the word that names the money you keep for later: ''savings''. Hint: it starts with S and has 7 letters.", "difficulty": 1, "explanation_md": "Great job! The word ''savings'' has 7 letters and is the money you keep for later, just like Rho taught you. Just as you added 5+5 with confidence, now you know that saving is keeping for later.", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["ahorro"], "keywords": ["ahorro"], "case_sensitive": false}}', '{"units": {"s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/505e68e38758645a9d6d4e65bba5e4542cc2f90f7ce974305202509851e659c6.mp3", "hash": "90cc2cafb484baf8ce8b4f2a23bd0a894fcac41524cd5c1aa790f57e06aec2e5", "bytes": 108864, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/505e68e38758645a9d6d4e65bba5e4542cc2f90f7ce974305202509851e659c6.mp3", "duration_ms": 18080}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/002de82e45ddb1446e240e82470aadb35aab2a511fe0f0a7a7a8fb2c32b75425.mp3", "hash": "3a545d049c81b653da448bbbfdf138b314699eaf2c3f63ea712b51ac5084ea74", "bytes": 84384, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/002de82e45ddb1446e240e82470aadb35aab2a511fe0f0a7a7a8fb2c32b75425.mp3", "duration_ms": 14000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "type-answer", "title": "Escribir la palabra ''ahorro''", "locale": "es-MX", "subject": "mixed", "objectives": ["Escribir la palabra que nombra el dinero que guardas para después: ''ahorro''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Empieza con la letra A y tiene 6 letras.", "Es lo contrario de gastar: guardar para después."], "title": "Escribe la palabra secreta", "payload": {"max_chars": 10, "placeholder": "Escribe aquí..."}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Dina y Rho te cuentan: Rho guardó 3 pesos de su venta de limonada. Eso es un ahorro. ¿Recuerdas cómo sumaste 5+5 y te sentiste seguro? Ahora, escribe la palabra que nombra el dinero que guardas para después: ''ahorro''. Pista: empieza con A y tiene 6 letras.", "difficulty": 1, "explanation_md": "¡Muy bien! La palabra ''ahorro'' tiene 6 letras y es el dinero que guardas para después, como Rho te enseñó. Así como sumaste 5+5 con confianza, ahora sabes que ahorrar es guardar para más tarde.", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["ahorro"], "keywords": ["ahorro"], "case_sensitive": false}}', '{"units": {"s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/9b17008fcb43c0a48b9e9be3bb1e021e7f7ccfbd45d63fa27f11b5c1601cac48.mp3", "hash": "b762b84f73b0bbf0ef75dcab76eb81e902df517406465c43fb1cab3d3c89a161", "bytes": 125136, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9b17008fcb43c0a48b9e9be3bb1e021e7f7ccfbd45d63fa27f11b5c1601cac48.mp3", "duration_ms": 20800}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/341bc90f7976a0a4fb418f7cf4c634709998a5b7d3e3b3941666fe337f8b7b9f.mp3", "hash": "5257d142acea9c1a13c921bd3603f499ad8648f5d92f185106024c6c2ecbd4b3", "bytes": 89136, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/341bc90f7976a0a4fb418f7cf4c634709998a5b7d3e3b3941666fe337f8b7b9f.mp3", "duration_ms": 14800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "build-sentence", "title": "Arma el letrero del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar palabras para formar un letrero de limonada con precio"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-arma-letrero", "xp": 0, "type": "build_sentence", "hints": ["Empieza con el nombre de la bebida: ''Limonada''.", "Después de ''a'' viene el número del precio."], "title": "Arma el letrero del puesto", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "Limonada"}, {"id": "t2", "text_md": "fría"}, {"id": "t3", "text_md": "a"}, {"id": "t4", "text_md": "5"}, {"id": "t5", "text_md": "pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Después de reponer limones y vasos con las ganancias de ayer, ¡Liruf ya está listo para vender hoy! Necesita armar su letrero. Las palabras están revueltas. Ponlas en el orden correcto para que diga: **Limonada fría a 5 pesos**.", "difficulty": 1, "explanation_md": "¡Excelente! Liruf ya tiene su letrero: ''Limonada fría a 5 pesos''. El 5 es el precio del vaso.", "audio_segment_id": "s1-arma-letrero.prompt"}], "schema_version": 1}', '{"s1-arma-letrero": {"order": ["t1", "t2", "t3", "t4", "t5"]}}', '{"units": {"s1-arma-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/cf5d3eacc7dd306453339ea117ca860856f935a0a2db28a38dcfcc67bc03325f.mp3", "hash": "dde35886e911defbd0bcfbd71264732e7ba96180de824d2a4ce4148fb1bbd457", "bytes": 93024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cf5d3eacc7dd306453339ea117ca860856f935a0a2db28a38dcfcc67bc03325f.mp3", "duration_ms": 15440}, "s1-arma-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/258ce6b34f338fd46707ca7f60818e0381ad9e80fcd0dbf29b1703842be5e5ab.mp3", "hash": "ca269b852db38c1cf85d0b8c95caf231d06a30146e0e73fc1f0c7204d384a11f", "bytes": 46944, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/258ce6b34f338fd46707ca7f60818e0381ad9e80fcd0dbf29b1703842be5e5ab.mp3", "duration_ms": 7760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "build-sentence", "title": "Monte a placa do estande", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar palavras para formar uma placa de limonada com preço"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-arma-letrero", "xp": 0, "type": "build_sentence", "hints": ["Comece com o nome da bebida: ''Limonada''.", "Depois de ''a'' vem o número do preço."], "title": "Monte a placa do estande", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "Limonada"}, {"id": "t2", "text_md": "gelada"}, {"id": "t3", "text_md": "a"}, {"id": "t4", "text_md": "5"}, {"id": "t5", "text_md": "pesos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Depois de repor limões e copos com os lucros de ontem, Liruf já está pronto para vender hoje! Ele precisa montar sua placa. As palavras estão embaralhadas. Coloque-as na ordem correta para que diga: **Limonada gelada a 5 pesos**.", "difficulty": 1, "explanation_md": "Excelente! Liruf já tem sua placa: ''Limonada gelada a 5 pesos''. O 5 é o preço do copo.", "audio_segment_id": "s1-arma-letrero.prompt"}], "schema_version": 1}', '{"s1-arma-letrero": {"order": ["t1", "t2", "t3", "t4", "t5"]}}', '{"units": {"s1-arma-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/6aba871746ffa98e942099ef0bdf2d9ba3a4aac7a714e406cb36870511e1536e.mp3", "hash": "5c22d6187ca8eac588ede7d7ab629c84698c2540fc690ef56210b0c0aaa94548", "bytes": 96768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6aba871746ffa98e942099ef0bdf2d9ba3a4aac7a714e406cb36870511e1536e.mp3", "duration_ms": 16080}, "s1-arma-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/dab544010fb022188d17b4c37dbaf6c646cb360a6d0b1066d63b1221234e2628.mp3", "hash": "35d800775847d81e5f1028d6560093e98bacbc6b003ed9c4a3aab65454418d93", "bytes": 42048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dab544010fb022188d17b4c37dbaf6c646cb360a6d0b1066d63b1221234e2628.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Completing Liruf''s accounts", "locale": "en-US", "subject": "mixed", "objectives": ["Write exact numeric and text answers about the day''s sales (sums up to 80, counts up to 20)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 0, "type": "fill_blank", "hints": ["Remember: profit = selling price - cost of ingredients. You sold for 5 pesos, the ingredients cost 2 pesos."], "title": "The day''s profit", "payload": {"bank": [{"id": "b1-numero", "text_md": "3"}, {"id": "b2-palabra", "text_md": "three"}], "mode": "typed", "text_md": "Now that you know what saving is, let''s see how much you can save from your profits! Liruf sold a glass for 5 pesos, the ingredients cost 2, his profit is {{1}} pesos."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Complete the sentence with the correct number.", "difficulty": 1, "explanation_md": "Great job! 5 - 2 = 3, so your profit is 3 pesos.", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"gaps": [{"gap": 1, "accept": ["3", "tres"], "bank_id": "b1-numero"}]}}', '{"units": {"s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/fa948c022b38c030262e400dddf0989530ccb55c8dbbfb58b38138b7672df7c4.mp3", "hash": "d8f45f732163d0ff8455759548f7b19fab5be98c53fb5451081686b73e416f5e", "bytes": 11808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fa948c022b38c030262e400dddf0989530ccb55c8dbbfb58b38138b7672df7c4.mp3", "duration_ms": 1920}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/22d0794d3c1bfbd6409d6b7c648b403a8ac7db77a043c8e600dec41442ab6043.mp3", "hash": "b0a1f0a7e4fb382c2e3284a4cd59b91f7b9b919d5df0f7257b993772cee0de62", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/22d0794d3c1bfbd6409d6b7c648b403a8ac7db77a043c8e600dec41442ab6043.mp3", "duration_ms": 4480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Completando las cuentas de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Escribir respuestas numéricas y de texto exactas sobre las ventas del día (sumas hasta 80, conteos hasta 20)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 0, "type": "fill_blank", "hints": ["Recuerda: ganancia = precio de venta - costo de ingredientes. Vendiste en 5 pesos, los ingredientes costaron 2 pesos."], "title": "La ganancia del día", "payload": {"bank": [{"id": "b1-numero", "text_md": "3"}, {"id": "b2-palabra", "text_md": "tres"}], "mode": "typed", "text_md": "Ahora que sabes qué es el ahorro, ¡veamos cuánto puedes ahorrar de tus ganancias! Liruf vendió un vaso en 5 pesos, los ingredientes costaron 2, su ganancia es {{1}} pesos."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Completa la frase con el número correcto.", "difficulty": 1, "explanation_md": "¡Muy bien! 5 - 2 = 3, así que tu ganancia es de 3 pesos.", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"gaps": [{"gap": 1, "accept": ["3", "tres"], "bank_id": "b1-numero"}]}}', '{"units": {"s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/be7e8f815ba8cc00aeab081d560dcefa3dbcf8de659e934c18b41060402f8a6b.mp3", "hash": "ca4c77828f0c8d56a0a462366b0f7dfee38ceced4bf482db8877e6df2ad6bab1", "bytes": 15696, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/be7e8f815ba8cc00aeab081d560dcefa3dbcf8de659e934c18b41060402f8a6b.mp3", "duration_ms": 2560}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/cdf3d1625de372dac58d7d1f96af4b206edb83b59f45c3dab36c8e7e368fc100.mp3", "hash": "208955c569ad38e90627afd77bec15a64e888ac1715804335543ffd3c16852de", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cdf3d1625de372dac58d7d1f96af4b206edb83b59f45c3dab36c8e7e368fc100.mp3", "duration_ms": 5600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Completando as contas de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escrever respostas numéricas e de texto exatas sobre as vendas do dia (somas até 80, contagens até 20)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia", "xp": 0, "type": "fill_blank", "hints": ["Lembre-se: lucro = preço de venda - custo dos ingredientes. Você vendeu por 5 pesos, os ingredientes custaram 2 pesos."], "title": "O lucro do dia", "payload": {"bank": [{"id": "b1-numero", "text_md": "3"}, {"id": "b2-palabra", "text_md": "três"}], "mode": "typed", "text_md": "Agora que você sabe o que é poupança, vamos ver quanto você pode poupar dos seus lucros! Liruf vendeu um copo por 5 pesos, os ingredientes custaram 2, seu lucro é {{1}} pesos."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Complete a frase com o número correto.", "difficulty": 1, "explanation_md": "Muito bem! 5 - 2 = 3, então seu lucro é de 3 pesos.", "audio_segment_id": "s1-ganancia.prompt"}], "schema_version": 1}', '{"s1-ganancia": {"gaps": [{"gap": 1, "accept": ["3", "tres"], "bank_id": "b1-numero"}]}}', '{"units": {"s1-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/283990ae9bca31eb3c13868bd658978ae43e99e3080495944d4d387ad75bd966.mp3", "hash": "1ebb0097d3a9794346ec12955dda6d6e7d219f84011f1f9ecc85a0132558ad9b", "bytes": 15264, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/283990ae9bca31eb3c13868bd658978ae43e99e3080495944d4d387ad75bd966.mp3", "duration_ms": 2480}, "s1-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/6f1a2c0dbecf1420c99118f5eee6d0aebeb98756bbbe07313a138f4d12f6186d.mp3", "hash": "bdf3b7dfcf3f1d5f9d92d272de56ee18b70341c7af67cefc0a2f707daea56165", "bytes": 36288, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6f1a2c0dbecf1420c99118f5eee6d0aebeb98756bbbe07313a138f4d12f6186d.mp3", "duration_ms": 6000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
